INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('f6ffcc81-664c-515d-9fa5-8c735dfdc1cb'::uuid, '8908c144-8a4f-5da6-b251-50dff0115c0d'::uuid, 'gambhirananda', 'english', 'Dhṛtarāṣṭra said: O Sanjaya, what did my sons and the sons of Pandu do when they assembled on the sacred field of Kurukshetra, eager for battle?'),
('2dd454fd-c345-5362-bdf4-1dd9e46bd914'::uuid, '8908c144-8a4f-5da6-b251-50dff0115c0d'::uuid, 'sivananda', 'english', 'Dhritarashtra said, "What did my people and the sons of Pandu do when they had assembled together, eager for battle, on the holy plain of Kurukshetra, O Sanjaya?"'),
('ea6b425b-d859-5dd4-a385-b6d881b7ad07'::uuid, '39650053-34a7-522a-9ced-97f638529efc'::uuid, 'gambhirananda', 'english', 'Sanjaya said: But then, seeing the army of the Pandavas in battle array, King Duryodhana approached the teacher, Drona, and spoke.'),
('bc9d9fd0-f955-53bb-adf6-c01a7b8534ae'::uuid, '39650053-34a7-522a-9ced-97f638529efc'::uuid, 'sivananda', 'english', 'Sanjaya said: Having seen the army of the Pandavas drawn up in battle array, King Duryodhana approached his teacher, Drona, and spoke these words.'),
('27a55e2a-a6e8-57c3-87fd-a24e033f0c07'::uuid, '48576bc0-f366-5487-9fed-7a05c6319892'::uuid, 'gambhirananda', 'english', 'O teacher, behold this vast army of the sons of Pandu, arrayed for battle by the intelligent disciple of Drupada.'),
('c58bb286-2a37-5030-b112-3f9691c01c6f'::uuid, '48576bc0-f366-5487-9fed-7a05c6319892'::uuid, 'sivananda', 'english', 'Behold, O Teacher! This mighty army of the sons of Pandu, arrayed by the son of Drupada, thy wise disciple.'),
('34c289fd-954b-5b81-ae5a-c978982032c5'::uuid, 'be79d223-ef7f-5266-affb-9d69c3cdb9ed'::uuid, 'gambhirananda', 'english', 'Here are the heroes wielding great bows, who in battle are peers of Bhima and Arjuna: Yuyudhana (Satyaki) and Virata, and the maharatha (great chariot-rider) Drupada;'),
('572c9123-2723-5eb8-9f79-cabe1fbd48e6'::uuid, 'be79d223-ef7f-5266-affb-9d69c3cdb9ed'::uuid, 'sivananda', 'english', 'Here are heroes, mighty archers, equal in battle to Bhima and Arjuna, Yuyudhana (Satyaki), Virata, and Drupada—all mighty warriors.'),
('f2f61e08-24c4-5f8d-a623-d2bc8997db50'::uuid, '6c0143e3-a069-591b-b363-d4223275d69f'::uuid, 'gambhirananda', 'english', 'Dhrstaketu, Cekitana, and the valiant king of Kasi (Varanasi); Purujit, Kuntibhoja, and Saibya, the choicest of men;'),
('265ac8ba-db75-5fe7-8ae6-863afcf75d52'::uuid, '6c0143e3-a069-591b-b363-d4223275d69f'::uuid, 'sivananda', 'english', 'Dhrishtaketu, Chekitana, the valiant king of Kasi, Purujit, Kuntibhoja, and Saibya—the best of men.'),
('d8d835c9-5715-577f-aded-1a7365416108'::uuid, '521460fd-2273-5364-b2e1-c888e6f7fa2f'::uuid, 'gambhirananda', 'english', 'And the valiant Yudhamanyu, and the chivalrous Uttamaujas; the son of Subhadra (Abhimanyu) and the sons of Draupadi—all of them are, indeed, maharathas.'),
('78f113db-2edc-570d-8f42-b8d5c1d19b82'::uuid, '521460fd-2273-5364-b2e1-c888e6f7fa2f'::uuid, 'sivananda', 'english', 'The strong Yudhamanyu and the brave Uttamaujas, the son of Subhadra (Abhimanyu, the son of Subhadra and Arjuna), and the sons of Draupadi, all of them great charioteers (great heroes)."'),
('fea6a0e2-9f78-53d9-8467-2389f4872e86'::uuid, 'fa01897d-be77-5757-a521-f758ae4ff33e'::uuid, 'gambhirananda', 'english', 'But, O best among the Brahmanas, please be appraised of those who are foremost among us, the founders of my army. I speak of them to you by way of illustration.'),
('274b5be1-ebc8-5f56-8c63-803fdcf2a719'::uuid, 'fa01897d-be77-5757-a521-f758ae4ff33e'::uuid, 'sivananda', 'english', 'Know also, O best among the twice-born! the names of those who are the most distinguished amongst ourselves, the leaders of my army; these I name to you for your information.'),
('b6913d96-9fa3-5049-bec0-265304ad876e'::uuid, 'bed96014-9b78-5203-a88b-31adcd509694'::uuid, 'gambhirananda', 'english', '(They are): Your venerable self, Bhisma, Karna, and Krpa, who is ever victorious in battle; Asvatthama, Vikarna, Saumadatti, and Jayadratha.'),
('99daa238-6c63-5429-9fba-e7a93b44bf7f'::uuid, 'bed96014-9b78-5203-a88b-31adcd509694'::uuid, 'sivananda', 'english', '"Thou thyself, Bhishma, Karna, Kripa, the victorious in war, Asvatthama, Vikarna, and Bhurisrava, the son of Somadatta—all these are ready for battle."'),
('091f7be4-2e57-540e-a55e-4ef344ce1078'::uuid, '54ae0136-fbd5-55cf-be65-d290f409c47e'::uuid, 'gambhirananda', 'english', 'There are many heroes who have dedicated their lives to me, possessing various kinds of weapons and missiles, all of whom are skilled in battle.'),
('98dfd701-c483-5b4e-9fc9-651dbab20533'::uuid, '54ae0136-fbd5-55cf-be65-d290f409c47e'::uuid, 'sivananda', 'english', 'And also many other heroes, ready to give up their lives for my sake, armed with various weapons and missiles, all well-skilled in battle.'),
('f19c4c1e-52e2-5dba-b6d6-59813bb8ee0d'::uuid, '1addcdad-fc61-53ce-9566-fe7967dc78ac'::uuid, 'gambhirananda', 'english', 'Therefore, our army, under the complete protection of Bhisma and others, is limitless. But this army of the enemies, under the protection of Bhima and others, is limited.'),
('f1b24790-c68f-5d7a-b818-57777ee470f2'::uuid, '1addcdad-fc61-53ce-9566-fe7967dc78ac'::uuid, 'sivananda', 'english', 'Our army, marshalled by Bhishma, is insufficient, whereas theirs, marshalled by Bhima, is sufficient.'),
('653178a8-2628-5a9c-bc22-18d0ebd5889c'::uuid, '9463be70-e124-5030-a110-47b1c54f3638'::uuid, 'gambhirananda', 'english', 'However, venerable sirs, all of you without exception, while occupying all the positions in the different directions as allotted to you respectively, please protect Bhisma in particular.'),
('8f11be49-305d-5fc4-a13a-968240a6f2d9'::uuid, '9463be70-e124-5030-a110-47b1c54f3638'::uuid, 'sivananda', 'english', 'Therefore, do all of you, stationed in your respective positions in the several divisions of the army, protect Bhishma alone.'),
('1b186706-caf6-5ce7-8b05-8c5413861e1c'::uuid, 'cb447a08-1645-5d32-80cb-d298aa07d91a'::uuid, 'gambhirananda', 'english', 'The valiant grandfather, the eldest of the Kurus, loudly sounding a lion''s roar, blew the conch to raise his (Duryodhana''s) spirits.'),
('d02f71ca-579a-5cf2-b84d-1319a0ab98f9'::uuid, 'cb447a08-1645-5d32-80cb-d298aa07d91a'::uuid, 'sivananda', 'english', 'His glorious grandsire, the oldest of the Kauravas, roared like a lion to cheer Duryodhana and blew his conch.'),
('e97490ed-3e34-5502-8ff2-7229058350a5'::uuid, '0acbd4d6-a413-517e-8017-5d8d14ed599a'::uuid, 'gambhirananda', 'english', 'Just immediately afterward, conch shells, kettledrums, tabors, trumpets, and cow-horns blared forth, creating a tumultuous sound.'),
('bba426ef-d536-591b-83bc-2c51120690f9'::uuid, '0acbd4d6-a413-517e-8017-5d8d14ed599a'::uuid, 'sivananda', 'english', 'Then, suddenly, conches, kettledrums, tabors, drums, and cow horns blared forth from the Kaurava side, and the sound was tremendous.'),
('de8d67c2-5cca-5f81-8c82-475f37e38a14'::uuid, '81751ab9-f902-5dee-bad9-6267d9e1c66f'::uuid, 'gambhirananda', 'english', 'Then Madhava (Krishna) and the son of Pandu (Arjuna), stationed in their magnificent chariot with white horses yoked to it, blew their divine conchs loudly.'),
('5cda9ab2-0382-5041-8696-ceb3b4eec357'::uuid, '81751ab9-f902-5dee-bad9-6267d9e1c66f'::uuid, 'sivananda', 'english', 'Then, Madhava (Krishna) and the son of Pandu (Arjuna), seated in the magnificent chariot yoked with white horses, blew divine conches.'),
('bacb355c-c302-5968-aa41-308129ef1d55'::uuid, 'a20e47f4-e0c2-582d-841c-b9addbae304b'::uuid, 'gambhirananda', 'english', 'Hrsikesa (Krsna) blew the conch Pancajanya; Dhananjaya (Arjuna) blew the conch Devadatta; and Vrkodara (Bhima) of terrible deeds blew the great conch Paundra.'),
('d51b1560-1662-5f9c-9a81-171b085523fe'::uuid, 'a20e47f4-e0c2-582d-841c-b9addbae304b'::uuid, 'sivananda', 'english', 'Hrishikesha blew the Panchajanya, Arjuna blew the Devadatta, and Bhima, the wolf-bellied doer of terrible deeds, blew the great conch Paundra.'),
('8977ae9a-eb27-509b-8154-f9de17ef3291'::uuid, 'f85c985e-f0da-5880-8f00-998c8b738624'::uuid, 'gambhirananda', 'english', 'King Yudhisthira, son of Kunti, blew the Anantavijaya; Nakula and Sahadeva blew the Sughosa and the Manipuspaka, respectively.'),
('285978c6-38a9-5e10-88f0-35cf49f00553'::uuid, 'f85c985e-f0da-5880-8f00-998c8b738624'::uuid, 'sivananda', 'english', 'King Yudhishthira, the son of Kunti, blew the Anantavijaya; Nakula and Sahadeva blew the Sughosha and the Manipushpaka.'),
('16a840a3-e6c2-5b31-9e71-194f7ca40c6b'::uuid, 'f9244a40-9286-5b1b-b4b2-f2ab518f9ddc'::uuid, 'gambhirananda', 'english', 'And the King of Kashi, wielding a great bow, and the great chariot-rider Sikhandin, Dhrstadyumna, Virata, and Satyaki the unconquered;'),
('b9e4c47e-3b45-5c54-98e8-14977497e4d3'::uuid, 'f9244a40-9286-5b1b-b4b2-f2ab518f9ddc'::uuid, 'sivananda', 'english', 'The king of Kasi, an excellent archer, Sikhandi, the mighty car-warrior, Dhrishtadyumna, Virata, and Satyaki, the unconquered.'),
('7df4b143-5831-569b-bffb-8129b2d89a1a'::uuid, '234f9d7c-c49e-5335-8a06-208b22f9b156'::uuid, 'gambhirananda', 'english', 'Drupada and the sons of Draupadi, as well as the mighty-armed son of Subhadra, all of them together, O king, blew their respective conchs.'),
('d599ca84-6e4a-5330-8232-db723af30607'::uuid, '234f9d7c-c49e-5335-8a06-208b22f9b156'::uuid, 'sivananda', 'english', 'Drupada and the sons of Draupadi, O Lord of the Earth, and the son of Subhadra, the mighty-armed, blew their conches each separately.'),
('8b7d80af-2863-5296-95fb-8f3125530ecb'::uuid, '3bdd5706-9362-5eeb-a3a2-939ae47857b8'::uuid, 'gambhirananda', 'english', 'That tremendous sound pierced the hearts of the sons of Dhrtarastra as it reverberated through the sky and the earth.'),
('074f735d-d0df-5ed4-b21a-771bdc5e7efa'::uuid, '3bdd5706-9362-5eeb-a3a2-939ae47857b8'::uuid, 'sivananda', 'english', 'The tumultuous sound rent the hearts of Dhritarashtra''s party, reverberating through both heaven and earth.'),
('45c7689b-691c-52f3-8831-cf8db1142c40'::uuid, 'e0ee1743-eea8-5d6b-b0e2-116b2075c06e'::uuid, 'gambhirananda', 'english', 'O King, thereafter, seeing Dhrtarastra''s men standing in their positions, with all the weapons ready for action, the son of Pandu, Arjuna, who had the insignia of Hanuman on his chariot-flag, raised his bow and said the following to Hrsikesa.'),
('8f6d01f0-ea9d-5c31-9a64-a44a91b246b2'::uuid, 'e0ee1743-eea8-5d6b-b0e2-116b2075c06e'::uuid, 'sivananda', 'english', 'Then, seeing the people of Dhritarashtra''s party standing arrayed and the discharge of weapons about to begin, Arjuna, the son of Pandu whose ensign was a monkey, took up his bow and said the following to Krishna, O Lord of the Earth.'),
('c9109579-4e6e-5260-8859-5109df6db669'::uuid, '0dacaed8-ac46-54ac-96b3-2419fa05dac9'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Acyuta, please place my chariot between both the armies."'),
('9eb1cff4-0bd9-53ad-84ff-7072ca85a458'::uuid, '0dacaed8-ac46-54ac-96b3-2419fa05dac9'::uuid, 'sivananda', 'english', 'Arjuna said, "O Krishna, place my chariot in the middle between the two armies, so that I may behold those who stand here, desirous to fight, and know with whom I must fight when the battle is about to commence."'),
('ababff8e-b089-5945-9dd7-7ad437e950fb'::uuid, 'deaf76ac-eb32-5174-a19f-0452e6b8a6e0'::uuid, 'gambhirananda', 'english', 'Until I survey those who stand intent on fighting and those who are about to engage in battle with me in this impending war.'),
('44ece658-c3a7-5ea6-9875-674aefb0fc3d'::uuid, 'deaf76ac-eb32-5174-a19f-0452e6b8a6e0'::uuid, 'sivananda', 'english', 'Arjuna said, "O Krishna, place my chariot in the middle between the two armies, so that I may behold those who stand here, desirous to fight, and know with whom I must fight when the battle is about to commence."'),
('9c967c86-c1d9-596a-99ac-75bb0189ae2e'::uuid, '4acb1945-35fe-5330-8199-ecb8441a19b5'::uuid, 'gambhirananda', 'english', 'These who have assembled here and want to accomplish in the war what is dear to the perverted son of Dhrtarastra, I find them to be intent on fighting.'),
('9338ab55-e902-5a89-90c1-297e6bd2f4ab'::uuid, '4acb1945-35fe-5330-8199-ecb8441a19b5'::uuid, 'sivananda', 'english', 'For I desire to observe those who are assembled here to fight, wishing to please in battle the evil-minded Duryodhana—the son of Dhritarashtra.'),
('5db9c19f-c99e-5cee-aa65-4757c2f096fe'::uuid, 'f141f7b5-6dd9-56de-95c4-e6b02878d9c6'::uuid, 'gambhirananda', 'english', 'Sanjaya said, "O scion of the line of Bharata, Hrishikesa, being told so by Gudakesa (Arjuna), placed the excellent chariot between the two armies, in front of Bhishma and Drona as well as all the rulers of the earth, and said, ''O Partha, behold these assembled Kurus!''"'),
('4bd8327e-7ad6-52db-a58f-6906c1f3bcb7'::uuid, 'f141f7b5-6dd9-56de-95c4-e6b02878d9c6'::uuid, 'sivananda', 'english', 'Sanjaya said, Thus addressed by Arjuna, Krishna stationed the best of chariots, O Dhritarashtra, in the midst of the two armies.'),
('0b1c6f62-f2ac-5ca0-9769-8a1a34c29b86'::uuid, '0dd87316-617e-5142-acda-5a76e2614ee8'::uuid, 'gambhirananda', 'english', 'Sanjaya said, "O scion of the line of Bharata (Dhrtarashtra), Hrsikesa, being told so by Gudakesa (Arjuna), placed the excellent chariot between the two armies, in front of Bhisma and Drona as well as all the rulers of the earth, and said, ''O Partha (Arjuna), behold these assembled people of the Kuru dynasty.''"'),
('1eafdcd1-c197-5c86-b920-9afb4f5382fb'::uuid, '0dd87316-617e-5142-acda-5a76e2614ee8'::uuid, 'sivananda', 'english', 'In front of Bhishma and Drona, and all the rulers of the earth, he said: "O Arjuna, son of Pritha, behold these Kurus gathered together."'),
('d105fd39-fd16-5ba1-88be-cf67c156935c'::uuid, 'b7c1a0ad-06ca-535d-ac28-a10b21a9a695'::uuid, 'gambhirananda', 'english', 'Then Arjuna saw, marshalled among both the armies, his uncles, grandfathers, teachers, maternal uncles, brothers, cousins, sons, grandsons, comrades, fathers-in-law, and friends.'),
('2b69e1c6-0734-5cff-a961-f95f0a712cee'::uuid, 'b7c1a0ad-06ca-535d-ac28-a10b21a9a695'::uuid, 'sivananda', 'english', 'Then, Arjuna (son of Pritha) saw there (in the armies) stationed fathers, grandfathers, teachers, maternal uncles, brothers, sons, grandsons, and friends.'),
('5f3a0d70-1d22-5f08-a5bc-f605e9856c72'::uuid, '0e377d0d-745c-5f39-90fd-c3d9eaf95235'::uuid, 'gambhirananda', 'english', 'The son of Kunti, Arjuna, seeing all those relatives arrayed there, became overwhelmed by supreme compassion and sorrowfully said this:'),
('14bf28b0-245b-5d5d-8063-4625fac5e4f9'::uuid, '0e377d0d-745c-5f39-90fd-c3d9eaf95235'::uuid, 'sivananda', 'english', 'He saw fathers-in-law and friends in both the armies. The son of Kunti, Arjuna, seeing all those kinsmen thus standing arrayed, spoke sorrowfully, deeply filled with pity.'),
('ee730934-76ef-5c64-83de-a7c2906b5a1e'::uuid, 'c2f2bbdd-1a17-54eb-a64c-6d12016b7739'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Krsna, seeing these relatives and friends who have assembled here with the intention of fighting, my limbs become languid and my mouth becomes completely dry."'),
('723be34c-0c0a-593f-97ee-d13a657ecb09'::uuid, 'c2f2bbdd-1a17-54eb-a64c-6d12016b7739'::uuid, 'sivananda', 'english', 'Arjuna said, "O Krishna, seeing my kinsmen arrayed here, eager to fight,'),
('d95449fc-92e6-5066-b635-d2948272e3f8'::uuid, '84b2b286-799b-503b-99ff-fcd3bf2554a8'::uuid, 'gambhirananda', 'english', 'And there is trembling in my body, and my hair stands on end; the Gandiva (bow) slips from my hand and my skin burns intensely.'),
('730e752e-44ce-5b4d-8861-2f3414db9a03'::uuid, '84b2b286-799b-503b-99ff-fcd3bf2554a8'::uuid, 'sivananda', 'english', 'My limbs fail, my mouth is parched, my body quivers, and my hair stands on end.'),
('c768d71a-0eae-57fa-95e9-a6db5c0277d6'::uuid, 'dfc1e8d7-2475-5b28-8419-eaded33d850a'::uuid, 'gambhirananda', 'english', 'Moreover, O Kesava (Krishna), I am not able to stand firmly, and my mind seems to be whirling. And I observe the omens to be adverse.'),
('81b7b316-ee43-569d-8853-3a5382e23d07'::uuid, 'dfc1e8d7-2475-5b28-8419-eaded33d850a'::uuid, 'sivananda', 'english', 'The Gandiva slips from my hand, and my skin burns all over; I am unable to stand, and my mind is reeling, as it were.'),
('1a6c222a-0029-594c-ba43-a61dc5a8e67a'::uuid, 'e4a9e229-f38b-5f05-90f3-08a9771f13cf'::uuid, 'gambhirananda', 'english', 'Besides, I do not see any good to be derived from killing my own people in battle. O Krsna, I do not hanker after victory, nor even a kingdom, nor pleasures.'),
('0e3244c5-5fe1-5793-9a90-421fcbc53913'::uuid, 'e4a9e229-f38b-5f05-90f3-08a9771f13cf'::uuid, 'sivananda', 'english', 'And I see ill omens, O Kesava. I do not see any good in slaying my kinsmen in battle.'),
('68a09f62-fe35-5e17-82d4-58f908307879'::uuid, '08511b51-a3d1-531a-a59c-78284db5da1c'::uuid, 'gambhirananda', 'english', 'O Govinda! What need do we have of a kingdom, or what need of enjoyments and livelihood? Those for whom kingdom, enjoyments, and pleasures are desired by us—such as teachers, uncles, fathers-in-law, grandsons, brothers-in-law, as well as relatives—those very ones stand arrayed for battle, risking their lives and wealth.'),
('60e4a8e2-ae8f-5d0c-8968-f9ccda288c28'::uuid, '08511b51-a3d1-531a-a59c-78284db5da1c'::uuid, 'sivananda', 'english', 'I desire not victory, O Krishna, nor kingdom, nor pleasures.
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('af794df3-699d-5776-a2f7-236dc0396427'::uuid, 'f0490d06-ce14-5594-9ea7-ef36ca55e8e2'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Madhusudana, O destroyer of enemies, how can I fight with arrows in battle against Bhisma and Drona, who are worthy of adoration?"'),
('9ec7ffef-5b0a-5c97-9d98-c90d21792e40'::uuid, 'f0490d06-ce14-5594-9ea7-ef36ca55e8e2'::uuid, 'sivananda', 'english', 'Arjuna said, "O Madhusudana, how can I fight in battle with arrows against Bhishma and Drona, who are worthy of being worshipped, O destroyer of enemies?"'),
('c613c32f-a8fa-5a8b-99e6-cd16de7143ab'::uuid, 'eef450fc-9f59-5cef-bd4f-43577d81641d'::uuid, 'gambhirananda', 'english', 'Rather than killing the noble-minded elders, it is better in this world to live even on alms. But by killing them, we shall only be enjoying here the pleasures of wealth and desirable things drenched in blood.'),
('5afd64e7-cde5-54c3-8cef-b6f8edba6890'::uuid, 'eef450fc-9f59-5cef-bd4f-43577d81641d'::uuid, 'sivananda', 'english', 'Better it is, indeed, in this world to accept alms than to slay the most noble teachers. But if I were to kill them, even in this world, all my enjoyments of wealth and fulfilled desires would be stained with their blood.'),
('9aae7e74-d86c-50e8-a4d8-62c8895e5bc2'::uuid, '916fdaee-856b-5a0a-bf94-5f3859c1c581'::uuid, 'gambhirananda', 'english', 'We do not know which is better for us, whether we shall win or they shall conquer us. Those very sons of Dhrtarastra, whom we do not wish to kill, stand in confrontation.'),
('4bd32b8c-e1f7-5dd3-8dc2-c069701ac8cf'::uuid, '916fdaee-856b-5a0a-bf94-5f3859c1c581'::uuid, 'sivananda', 'english', 'I can hardly tell which would be better, that we should conquer them or that they should conquer us. Even the sons of Dhritarashtra, whom we do not wish to slay, stand facing us.'),
('66a4208b-38b7-5139-bc28-aef33d412f4e'::uuid, '81ce4613-6e7c-55b1-a344-8187e2487d59'::uuid, 'gambhirananda', 'english', 'With my nature overpowered by weak commiseration, my mind bewildered about duty, I supplicate You. Tell me for certain what is better; I am Your disciple, having taken refuge in You. Instruct me.'),
('23042640-8a2f-558e-9392-673fb0b77c82'::uuid, '81ce4613-6e7c-55b1-a344-8187e2487d59'::uuid, 'sivananda', 'english', 'My heart is overpowered by the taint of pity; my mind is confused as to my duty. I ask Thee: Tell me decisively what is good for me. I am Thy disciple; instruct me, who has taken refuge in Thee.'),
('cc28b0d8-f364-5c42-90ba-d537fc390ddb'::uuid, '3a3d2062-56d0-591e-9f19-9f851796f379'::uuid, 'gambhirananda', 'english', 'For I do not see anything that, even after acquiring on this earth a prosperous kingdom free from enemies and even sovereignty over the gods, can remove my sorrow that is blasting the senses.'),
('961a322c-4e78-59dc-92ec-1379f0e9e41a'::uuid, '3a3d2062-56d0-591e-9f19-9f851796f379'::uuid, 'sivananda', 'english', 'I do not see that this sorrow that burns up my senses would be removed, even if I were to attain prosperous and unrivaled dominion on earth or lordship over the gods.'),
('e152141a-040a-50fd-a085-fecc6417d1ee'::uuid, '3755d567-5ea4-5c64-a2da-0978ae8fd352'::uuid, 'gambhirananda', 'english', 'Sanjaya said: Having spoken thus to Hrsikesa (Krsna), Gudakesa (Arjuna), the afflictor of foes, verily became silent, telling Govinda, ''I shall not fight.'''),
('e26b5a71-72b9-5436-9696-3b55358f674a'::uuid, '3755d567-5ea4-5c64-a2da-0978ae8fd352'::uuid, 'sivananda', 'english', 'Sanjaya said: Having spoken thus to Hrishikesha, the Lord of the senses, Arjuna, the conqueror of sleep and destroyer of foes, said, "I will not fight," and became silent.'),
('a2a92557-5ad9-517c-a060-5c9e801d6b69'::uuid, '7ab3810b-a7d6-5180-b577-86f672f8aada'::uuid, 'gambhirananda', 'english', 'O descendant of Bharata, Hrsikesa, mocking as it were, said these words to him who was sorrowing between the two armies:'),
('31981693-9e57-5eba-836d-0e945bb4640c'::uuid, '7ab3810b-a7d6-5180-b577-86f672f8aada'::uuid, 'sivananda', 'english', 'To him who was despondent in the midst of the two armies, Krishna, smiling, O Bharata, spoke these words.'),
('31b0fd38-a9f5-5d81-affa-6f404de9ee5d'::uuid, '13597f0a-05bd-509e-9c11-d140bc70d763'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "You grieve for those who are not to be grieved for; and you speak words of wisdom! The learned do not grieve for the departed nor for those who have not departed.'),
('4aeae742-ee8f-53ce-af85-cded7468fdcb'::uuid, '13597f0a-05bd-509e-9c11-d140bc70d763'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "You have grieved for those who should not be grieved for; yet, you speak words of wisdom. The wise grieve neither for the living nor for the dead."'),
('f4d75451-039b-54b5-a33b-9f4467a0fdb5'::uuid, 'cc4f4cc6-529c-5f5a-8760-6e29f7051672'::uuid, 'gambhirananda', 'english', 'But certainly it is not a fact that I did not exist at any time; nor you, nor these rulers of men. And surely it is not that we all shall cease to exist after this.'),
('004ddf4f-45f1-5cad-a308-5f7083e82014'::uuid, 'cc4f4cc6-529c-5f5a-8760-6e29f7051672'::uuid, 'sivananda', 'english', 'Nor, at any time, was I not, nor thou, nor these rulers of men; nor, verily, shall we ever cease to be hereafter.'),
('43cf3f3b-978c-5a5e-a990-ad9ff6f83e6f'::uuid, 'ab6be0cb-4af4-5f9a-83da-c51c03f3f724'::uuid, 'gambhirananda', 'english', 'As boyhood, youth, and decrepitude are to an embodied being in this present body, so is the acquisition of another body. Therefore, an intelligent person does not get deluded.'),
('2f2d1855-2ec4-56f7-ae47-de3708d346a5'::uuid, 'ab6be0cb-4af4-5f9a-83da-c51c03f3f724'::uuid, 'sivananda', 'english', 'Just as the embodied soul passes through childhood, youth, and old age in this body, so too does it pass into another body; the steadfast one does not grieve over this.'),
('6902feed-d201-5493-9411-531fd5f429c7'::uuid, 'bfe8c250-40de-5d96-96e6-5a9ff9254bdb'::uuid, 'gambhirananda', 'english', 'But the contacts of the organs with the objects are the producers of cold and heat, happiness, and sorrow. They have a beginning and an end and are transient. Bear them, O descendant of Bharata.'),
('cf831dda-4c2b-5c88-a6a2-ebc6d59e9178'::uuid, 'bfe8c250-40de-5d96-96e6-5a9ff9254bdb'::uuid, 'sivananda', 'english', 'The contact of the senses with the objects, O son of Kunti, which causes heat and cold, pleasure and pain, has a beginning and an end; they are impermanent; endure them bravely, O Arjuna.'),
('343e7bed-c9c3-5e81-8273-fd10e5883a2f'::uuid, '1c4ad91c-c459-50a3-900b-19ee502de13a'::uuid, 'gambhirananda', 'english', 'O Arjuna, who is foremost among men, verily, the person whom these do not torment, the wise man to whom sorrow and happiness are the same—he is fit for immortality.'),
('660cb0f6-9223-59ee-8f5d-b89e621ff5ad'::uuid, '1c4ad91c-c459-50a3-900b-19ee502de13a'::uuid, 'sivananda', 'english', 'That firm man, whom surely these afflictions do not, O chief among men, to whom pleasure and pain are the same, is fit for attaining immortality.'),
('ae3bd5ed-0371-52b0-b437-d3850757f786'::uuid, '08510c75-32d1-55a0-b544-59c7ad4d044a'::uuid, 'gambhirananda', 'english', 'There is no being of the unreal; the real has no non-existence. Yet, the nature of both has been realized by the seers of Truth.'),
('d2ae57b2-0e61-5296-ae26-926ccd78cd4c'::uuid, '08510c75-32d1-55a0-b544-59c7ad4d044a'::uuid, 'sivananda', 'english', 'The unreal has no being; there is no non-being of the real; the truth about both has been seen by the knowers of the truth (or the seers of the essence).'),
('c2a09a43-1061-5346-982b-ac7757c17759'::uuid, '4a31496f-7694-5eab-9ddf-8e90f5875d77'::uuid, 'gambhirananda', 'english', 'But know that to be indestructible by which all this is pervaded. No one can bring about the destruction of this immutable.'),
('9ccbde5f-0084-5c74-8b0d-ea6816000eec'::uuid, '4a31496f-7694-5eab-9ddf-8e90f5875d77'::uuid, 'sivananda', 'english', 'Know that to be indestructible, by which all this is pervaded. No one can cause the destruction of that, the Imperishable.'),
('a89f94fb-584d-5739-afe8-57bfc902bc48'::uuid, '9d67746c-f135-5715-b502-8ac5e9e34105'::uuid, 'gambhirananda', 'english', 'These destructible bodies are said to belong to the everlasting, indestructible, and indeterminable embodied One. Therefore, O descendant of Bharata, join the battle.'),
('d880f1aa-54a1-531e-a55e-523e6d4ef171'::uuid, '9d67746c-f135-5715-b502-8ac5e9e34105'::uuid, 'sivananda', 'english', 'These bodies of the embodied Self, which are eternal, indestructible, and immeasurable, are said to have an end. Therefore, fight, O Arjuna.'),
('1ce58444-ee30-508f-8618-de60f77dabe7'::uuid, 'e9a90dec-e7b5-56ec-9462-d0f292246aef'::uuid, 'gambhirananda', 'english', 'He who thinks of this One as the killer, and he who thinks of this One as the one being killed, both of them do not know. This One neither kills nor is It killed.'),
('cb695bc0-7ecd-5b4d-8c75-b9b2d8449610'::uuid, 'e9a90dec-e7b5-56ec-9462-d0f292246aef'::uuid, 'sivananda', 'english', 'He who takes the Self to be the slayer and he who thinks it is slain, neither of them knows. It does not slay, nor is it slain.'),
('abda9250-8d46-5ad1-a220-a6f442285ad4'::uuid, '5fe9a354-b762-5b22-ae2c-adefa6126069'::uuid, 'gambhirananda', 'english', 'Never is this One born, nor does It ever die; nor, having come into existence, does It cease to be. This One is birthless, eternal, undecaying, and ancient; It is not killed when the body is killed.'),
('9682d945-5b47-5cbb-88ff-57b7e24760a4'::uuid, '5fe9a354-b762-5b22-ae2c-adefa6126069'::uuid, 'sivananda', 'english', 'It is not born, nor does it ever die; after having been, it again does not cease to be; unborn, eternal, changeless, and ancient, it is not killed when the body is killed.'),
('e873419d-32cb-5eed-884c-8feede0d4f13'::uuid, 'aa95bf09-a8d9-5dc1-9478-e941c36656cf'::uuid, 'gambhirananda', 'english', 'O Partha, he who knows this One as indestructible, eternal, birthless, and undecaying—how can that person kill, or cause to be killed, whom?'),
('82c14bdf-21f8-577d-bd85-a35dbca4a9fc'::uuid, 'aa95bf09-a8d9-5dc1-9478-e941c36656cf'::uuid, 'sivananda', 'english', 'Whoever knows it to be indestructible, eternal, unborn, and inexhaustible, how can that person slay, O Arjuna, or cause to be slain?'),
('fe5adfc6-8b3d-520d-99ba-17f528ea3d0f'::uuid, '4ffc5d3e-8c4c-5fa3-89b0-c4e7d71b6b43'::uuid, 'gambhirananda', 'english', 'As after rejecting worn-out clothes, a man takes up other new ones, likewise, after rejecting worn-out bodies, the embodied one unites with other new ones.'),
('c5a3a11e-2bbd-545a-aa13-d8b78c26d389'::uuid, '4ffc5d3e-8c4c-5fa3-89b0-c4e7d71b6b43'::uuid, 'sivananda', 'english', 'Just as a man casts off worn-out clothes and puts on new ones, so too the embodied Self casts off worn-out bodies and enters others that are new.'),
('fb2061ad-da62-5028-993b-0cc17b455408'::uuid, '0253ec8e-7e72-5e7c-aa1d-869d069a99b4'::uuid, 'gambhirananda', 'english', 'Weapons cannot cut It, fire cannot burn It, water cannot moisten It, and air cannot dry It.'),
('863c125b-43ef-5ae8-81a5-5ebbee98a56a'::uuid, '0253ec8e-7e72-5e7c-aa1d-869d069a99b4'::uuid, 'sivananda', 'english', 'Weapons cannot cut it, fire cannot burn it, water cannot wet it, wind cannot dry it.'),
('54497185-f9ef-5761-9d8e-5444b5624a4c'::uuid, '8ab6a31f-8e4c-5499-9d8b-67a78ceb8f8a'::uuid, 'gambhirananda', 'english', 'It cannot be cut, burned, moistened, or dried up; it is eternal, omnipresent, stationary, unmoving, and unchanging.'),
('c4f7e5cf-8de5-53ab-bbd2-cf33ef80d2e6'::uuid, '8ab6a31f-8e4c-5499-9d8b-67a78ceb8f8a'::uuid, 'sivananda', 'english', 'This Self cannot be cut, burned, wetted, nor dried up; it is eternal, all-pervasive, stable, immovable, and ancient.'),
('4b8e7755-0fb5-5cb5-b0e5-30724e4cdb11'::uuid, '4d9a74d3-12e7-5108-bb0a-2b00fc1293bc'::uuid, 'gambhirananda', 'english', 'It is said that This is unmanifest; This is inconceivable; This is unchangeable. Therefore, having known This thus, you ought not to grieve.'),
('006d1c01-9206-5d0e-9995-b69c934d8811'::uuid, '4d9a74d3-12e7-5108-bb0a-2b00fc1293bc'::uuid, 'sivananda', 'english', 'This Self is said to be unmanifested, unthinkable, and unchangeable. Therefore, knowing this to be so, you should not grieve.'),
('80825079-c0c1-5b44-b1fb-b44ae78b97e0'::uuid, 'f9c60e3d-cb6e-5d71-9d36-207f3906c2da'::uuid, 'gambhirananda', 'english', 'On the other hand, if you think this One is born continually or constantly dies, even then, O mighty-armed one, you should not grieve.'),
('41654fc1-9908-5ec6-bc43-48276b3d041c'::uuid, 'f9c60e3d-cb6e-5d71-9d36-207f3906c2da'::uuid, 'sivananda', 'english', 'But even if thou thinkest of It as constantly being born and constantly dying, even then, O mighty-armed one, thou shouldst not grieve.'),
('972d798b-455e-5f7b-9405-3593ef873bb6'::uuid, 'd5d967a2-295c-53cf-927e-62390ef3b10d'::uuid, 'gambhirananda', 'english', 'For the death of anyone born is certain, and the rebirth of the dead is certain. Therefore, you should not grieve over an inevitable fact.'),
('02762955-8d5a-53e8-b117-14e394d53edd'::uuid, 'd5d967a2-295c-53cf-927e-62390ef3b10d'::uuid, 'sivananda', 'english', 'For the born, death is certain, and for the dead, birth is certain; therefore, you should not grieve over the inevitable.'),
('f846273c-2477-5e61-a8aa-26e2055ab061'::uuid, '4310266d-3207-5b04-a7f8-31f0ae72c9ab'::uuid, 'gambhirananda', 'english', 'O descendant of Bharata, all beings remain unmanifested in the beginning; they become manifested in the middle. After death, they certainly become unmanifested. What lamentation can there be for them?'),
('719e2dc4-d645-585e-922a-7fed101be5e6'::uuid, '4310266d-3207-5b04-a7f8-31f0ae72c9ab'::uuid, 'sivananda', 'english', 'Beings are unmanifest in their beginning, manifest in their middle state, O Arjuna, and unmanifest again in their end. What is there to grieve about?'),
('b34754fd-6948-5417-b7c6-877db8d4cf1f'::uuid, 'ccfec810-54c0-5e1a-92e0-071aeb0ada0d'::uuid, 'gambhirananda', 'english', 'Someone visualizes it as a wonder; someone else talks of it as a wonder; someone else hears of it as a wonder; and yet someone else does not even realize it after hearing about it.'),
('46d878f1-b9c1-55ae-a288-92f3feff6ada'::uuid, 'ccfec810-54c0-5e1a-92e0-071aeb0ada0d'::uuid, 'sivananda', 'english', 'One sees this (the Self) as a wonder; another speaks of it as a wonder; another hears of it as a wonder; yet, having heard, none understands it at all.'),
('9d9b0073-fb90-5f7a-a00c-9aab8a2c67b7'::uuid, '7082d70a-857e-5855-be33-e2390c031f79'::uuid, 'gambhirananda', 'english', 'O descendant of Bharata, this embodied Self existing in everyone''s body can never be killed; therefore, you ought not to grieve for all these beings.'),
('610fcf8b-99f5-5613-ba7e-1ce2fa9d71f0'::uuid, '7082d70a-857e-5855-be33-e2390c031f79'::uuid, 'sivananda', 'english', 'This indweller in the body of everyone is ever indestructible, O Arjuna; therefore, you should not grieve for any creature.'),
('e65872a1-4acf-5147-8e4d-fe3dcb4797c8'::uuid, 'ec4c3d46-e1a6-577c-b22b-78c915abb994'::uuid, 'gambhirananda', 'english', 'Even considering your own duty, you should not waver, since there is nothing better for a Ksatriya than a righteous battle.'),
('c50bac5d-7ff3-52dc-906e-95f53de44b32'::uuid, 'ec4c3d46-e1a6-577c-b22b-78c915abb994'::uuid, 'sivananda', 'english', 'Further, having regard to your duty, you should not waver, for there is nothing higher for a Kshatriya than a righteous war.'),
('a0da7450-545d-59f6-98cd-050d19d7391c'::uuid, '3cc08a8f-422d-53bd-bdec-198a5c9e8612'::uuid, 'gambhirananda', 'english', 'O son of Partha, happy are the Kshatriyas who come across such a battle, which presents itself unsought and is an open gate to heaven.'),
('57cc9d39-a6fb-5c96-907e-61ad475e7b77'::uuid, '3cc08a8f-422d-53bd-bdec-198a5c9e8612'::uuid, 'sivananda', 'english', 'Happy are the Kshatriyas, O Arjuna! who are called to fight in such a battle that comes of its own accord as an open door to heaven.'),
('d9c9e1be-fadc-54cb-9f47-ffc95e1e1da2'::uuid, '83eef5a7-6c26-5154-ac48-42c2d61a3653'::uuid, 'gambhirananda', 'english', 'On the other hand, if you do not fight this righteous battle, then you will incur sin, forsaking your own duty and fame.'),
('ac5a107e-cad6-5995-8b12-a8f51b6106ff'::uuid, '83eef5a7-6c26-5154-ac48-42c2d61a3653'::uuid, 'sivananda', 'english', 'But if you will not fight this righteous war, then having abandoned your own duty and reputation, you will incur sin.'),
('1d04cc95-2826-5f92-bbcb-cda07b844404'::uuid, '4122cefe-1b37-5e9c-a1f5-a86584adb835'::uuid, 'gambhirananda', 'english', 'People also will speak of your unending infamy, and to an honored person, infamy is worse than death.'),
('c45b7af9-fd43-5088-bcc6-6348952fdaaf'::uuid, '4122cefe-1b37-5e9c-a1f5-a86584adb835'::uuid, 'sivananda', 'english', 'People will also recount your everlasting dishonor; and for one who has been honored, dishonor is worse than death.'),
('75f40086-d6e6-5998-92cd-e04a26de4208'::uuid, 'fae5c1bf-e1c7-5dda-bfef-ebef66f8a681'::uuid, 'gambhirananda', 'english', 'The great chariot-riders will think of you as having desisted from the fight out of fear, and you will fall into disgrace before them whom you had been estimable to.'),
('b0f1b827-d888-53c2-98d7-b35dac36e205'::uuid, 'fae5c1bf-e1c7-5dda-bfef-ebef66f8a681'::uuid, 'sivananda', 'english', 'The great chariot-warriors will think that you have withdrawn from the battle out of fear, and you will be held in low esteem by those who have held you in high regard.'),
('2f9a2699-c269-51a8-a1ae-a691baa930ab'::uuid, '22cae4a9-e3ac-57b6-a406-e9787335fbf9'::uuid, 'gambhirananda', 'english', 'And your enemies will speak many indecent words while denigrating your power. What can be more painful than that?'),
('01f33c40-5913-579d-9ff1-0e6ab0b9d034'::uuid, '22cae4a9-e3ac-57b6-a406-e9787335fbf9'::uuid, 'sivananda', 'english', 'Your enemies, scoffing at your power, will speak many abusive words—what could be more painful than this?'),
('8cdbab69-1f01-524e-940d-30dac3dd6eb3'::uuid, '674a2fd3-81ef-55fa-9e53-0579f267d756'::uuid, 'gambhirananda', 'english', 'Either by being killed, you will attain heaven, or by winning, you will enjoy the earth. Therefore, O Arjuna, rise up with determination to fight.'),
('694eb499-64a5-5d88-93ed-febf15825655'::uuid, '674a2fd3-81ef-55fa-9e53-0579f267d756'::uuid, 'sivananda', 'english', 'Slain, you will obtain heaven; victorious, you will enjoy the earth; therefore, stand up, O son of Kunti, resolved to fight.'),
('4fab0a0d-a57f-5c92-934c-a212d1fade61'::uuid, 'c71f94a0-4fe7-5e9b-9e77-8a23e49605f9'::uuid, 'gambhirananda', 'english', 'Treating happiness and sorrow, gain and loss, and conquest and defeat with equanimity, then engage in battle. Thus, you will not incur sin.'),
('8f2c0676-5945-5f56-a044-d938f54ba1f1'::uuid, 'c71f94a0-4fe7-5e9b-9e77-8a23e49605f9'::uuid, 'sivananda', 'english', 'Having made pleasure and pain, gain and loss, victory and defeat equal, engage in battle for the sake of battle; thus, you shall not incur sin.'),
('37c0a77a-54d4-5d11-a061-d91fbd1be3f1'::uuid, 'fb8f93f0-8242-5372-b2b5-5f3251423258'::uuid, 'gambhirananda', 'english', 'O Partha, this wisdom has been imparted to you from the standpoint of Self-realization. But listen to this wisdom from the standpoint of Yoga, endowed with which, you will get rid of the bondage of action.'),
('7653733c-df60-5802-9208-d538772f00ed'::uuid, 'fb8f93f0-8242-5372-b2b5-5f3251423258'::uuid, 'sivananda', 'english', 'This, which has been taught to you, is wisdom concerning Sankhya. Now listen to wisdom concerning Yoga, endowed with which, O Arjuna, you shall cast off the bonds of action.'),
('85c6f38b-1bd0-5ad6-9ee9-9499b4df5b06'::uuid, '438ed540-7e2e-529e-b534-fa076fe5cc87'::uuid, 'gambhirananda', 'english', 'Here, there is no waste of effort; nor is there any harm. Even a little of this righteousness saves one from great fear.'),
('821c3efe-8826-544b-a91d-e05b72430f9c'::uuid, '438ed540-7e2e-529e-b534-fa076fe5cc87'::uuid, 'sivananda', 'english', 'In this, there is no loss of effort, nor is there any harm produced, nor any transgression. Even a little of this knowledge protects one from great fear.'),
('5c50c3a0-a592-5fa4-b6ea-6ab076d1669c'::uuid, '0d68b441-418b-5d03-a0a0-c74927298c48'::uuid, 'gambhirananda', 'english', 'O scion of the Kuru dynasty, in this there is a single, one-pointed conviction. The thoughts of the irresolute ones, however, have many branches indeed and are innumerable.'),
('b2e41ad9-64bb-5dd6-a1cd-b0fe5f62706c'::uuid, '0d68b441-418b-5d03-a0a0-c74927298c48'::uuid, 'sivananda', 'english', 'Here, O joy of the Kurus, there is only one single-pointed determination; many-branched and endless are the thoughts of the indecisive.'),
('d3e5f250-02b1-5aac-9022-3208fd8769f6'::uuid, '54d98493-fbad-57f3-84ab-3ab4d8cad2ef'::uuid, 'gambhirananda', 'english', 'O son of Prtha, those undiscerning people who utter this flowery talk, which promises birth as a result of rites and duties, and is full of various special rites meant for the attainment of enjoyment and affluence, remain engrossed in the utterances of the Vedas and declare that nothing else exists; their minds are full of desires and they have heaven as their goal.'),
('a85f9492-c319-53ed-982f-cffc44e11ca4'::uuid, '54d98493-fbad-57f3-84ab-3ab4d8cad2ef'::uuid, 'sivananda', 'english', 'The unwise, taking pleasure in the eulogizing words of the Vedas, utter flowery speech, saying, "There is nothing else," O Arjuna.'),
('27e42cdb-ba36-5641-a628-58855a7cc4af'::uuid, '07c67223-61c4-5b7f-9170-2b794a5321bd'::uuid, 'gambhirananda', 'english', 'O son of Prtha, those undiscerning people who utter this flowery talk, which promises birth as a result of rites and duties, and is full of various special rites meant for the attainment of enjoyment and affluence, remain engrossed in the utterances of the Vedas and declare that nothing else exists; their minds are full of desires and they have heaven as their goal.'),
('03708083-451a-5d3c-8e2f-363adaafce0f'::uuid, '07c67223-61c4-5b7f-9170-2b794a5321bd'::uuid, 'sivananda', 'english', 'Full of desires, with heaven as their goal, (they speak words that are directed to ends) leading to new births as the result of their works, and prescribe various methods abounding in specific actions, for the attainment of pleasure and power.'),
('93c8f642-7f21-52ae-84da-12af199f9bad'::uuid, 'e56a4507-80c7-5726-8608-49750de85282'::uuid, 'gambhirananda', 'english', 'One-pointed conviction does not become established in the minds of those who delight in enjoyment and affluence, and whose intellects are carried away by it.'),
('54148f70-9791-5d7b-87bf-85a9096937f1'::uuid, 'e56a4507-80c7-5726-8608-49750de85282'::uuid, 'sivananda', 'english', 'For those who are attached to pleasure and power, whose minds are drawn away by such teachings, their determinate reason is not formed which is steadily bent on meditation and Samadhi (superconscious state).'),
('299cf1a9-f50a-5dd6-867c-80f324ef9fb1'::uuid, '728e922b-fecd-5162-8980-670240463820'::uuid, 'gambhirananda', 'english', 'O Arjuna, the Vedas [Meaning only the portion dealing with rites and duties (karma-kanda).] have the three qualities as their object. You become free from worldliness, free from the pairs of duality, ever-poised in the quality of sattva, without (desire for) acquisition and protection, and self-collected.'),
('11c5cd1b-90cb-5297-a98d-6b231087bfa3'::uuid, '728e922b-fecd-5162-8980-670240463820'::uuid, 'sivananda', 'english', 'The Vedas deal with the three attributes; be thou above these three attributes. O Arjuna, free yourself from the pairs of opposites and ever remain in the quality of Sattva, freed from acquisition and preservation, and be established in the Self.'),
('14d93a1c-16b0-5c5b-9b3f-47b4b8373a4b'::uuid, '67628f79-9ca9-576d-8f66-1e2dc4e33ae9'::uuid, 'gambhirananda', 'english', 'A Brahmana with realization has that much utility in all the Vedas as a person has in a well when there is a flood all around.'),
('9ea76fce-620b-51f6-952e-29beb610fc87'::uuid, '67628f79-9ca9-576d-8f66-1e2dc4e33ae9'::uuid, 'sivananda', 'english', 'To the Brahmana who has known the Self, all the Vedas are of as much use as a reservoir of water would be in a place where there is a flood.'),
('2c60db13-0c90-52ad-9155-f99fb6363cd6'::uuid, '171fcfe7-c27d-52d2-b6f0-399f559554a9'::uuid, 'gambhirananda', 'english', 'Your right is only to act, not to the results. Do not be the cause of the results of action. Do not have any inclination towards inaction.'),
('a35fad51-f010-5f53-86e8-1d21d6543eb3'::uuid, '171fcfe7-c27d-52d2-b6f0-399f559554a9'::uuid, 'sivananda', 'english', 'Your right is only to work, but not to its results; do not let the results of action be your motive, nor let your attachment be to inaction.'),
('ff8069d9-d46a-5778-aa45-b0057bc09274'::uuid, '0e0b1b2e-6a84-5712-a371-214ea1800637'::uuid, 'gambhirananda', 'english', 'By being established in Yoga, O Dhananjaya (Arjuna), undertake actions, casting off attachment and remaining equanimous in success and failure. Equanimity is called Yoga.'),
('831c0e0f-698d-52be-8099-8151d702a9df'::uuid, '0e0b1b2e-6a84-5712-a371-214ea1800637'::uuid, 'sivananda', 'english', 'Perform action, O Arjuna, being steadfast in Yoga, abandoning attachment and balanced in success and failure; evenness of mind is called Yoga.'),
('0d2caa0a-6b26-59c5-9046-e9d7a792db35'::uuid, 'b21f9548-9ec4-51c1-a594-5b328b45e15c'::uuid, 'gambhirananda', 'english', 'O Dhananjaya, indeed, action is inferior to the yoga of wisdom. Take refuge in wisdom. Those who thirst for rewards are pitiable.'),
('34a6f7b6-c718-55d7-9580-ce00ff9ce053'::uuid, 'b21f9548-9ec4-51c1-a594-5b328b45e15c'::uuid, 'sivananda', 'english', 'Far lower than the Yoga of wisdom is action, O Arjuna. Seek thou refuge in wisdom; wretched are those whose motive is the fruit.'),
('7c49270d-33ab-5a74-abc1-c416c79f776b'::uuid, 'a7ef20f0-8141-500e-947b-fc122959469d'::uuid, 'gambhirananda', 'english', 'Possessed of wisdom, one rejects here both virtue and vice. Therefore, devote yourself to (Karma-) yoga; for yoga is skilfulness in action.'),
('e2d8ca8f-28cb-55a8-918c-3348b1caba5f'::uuid, 'a7ef20f0-8141-500e-947b-fc122959469d'::uuid, 'sivananda', 'english', 'Endowed with wisdom and evenness of mind, one casts off in this life both good and evil deeds; therefore, devote yourself to Yoga; Yoga is skill in action.'),
('2c18320d-ab91-52b0-8e51-7e6b2f7eb696'::uuid, '83376527-d732-5ea5-b0bd-5951f95aeeea'::uuid, 'gambhirananda', 'english', 'For those devoted to wisdom, they become enlightened men by giving up the fruits of their actions, and thus they reach a state beyond evil, having been freed from the bondage of birth.'),
('4b786e1a-756d-5c47-ae24-ec542e95a1ef'::uuid, '83376527-d732-5ea5-b0bd-5951f95aeeea'::uuid, 'sivananda', 'english', 'The wise, possessing knowledge, having abandoned the fruits of their actions, and being freed from the bonds of birth, go to the place which is beyond all evil.'),
('2c1b8ede-5125-535e-8a3f-6d3d7c8343d9'::uuid, '204c7772-8eaf-5806-b490-e18d24631a17'::uuid, 'gambhirananda', 'english', 'When your mind goes beyond the turbidity of delusion, then you will acquire dispassion for what has to be heard and what has already been heard.'),
('719af0b6-02b2-5623-87f4-b59115f19753'::uuid, '204c7772-8eaf-5806-b490-e18d24631a17'::uuid, 'sivananda', 'english', 'When your intellect passes beyond the mire of delusion, then you will attain indifference to what has been heard and what has yet to be heard.'),
('06981477-33c1-583c-8271-55e12bfbfc3a'::uuid, 'f6ffb97a-9871-5c92-af83-c58d73e50beb'::uuid, 'gambhirananda', 'english', 'When your mind, which has become bewildered by hearing, becomes unshakable and steadfast in the Self, then you will attain Yoga that arises from discrimination.'),
('58f22202-5923-5b60-aaff-651a5a6597e2'::uuid, 'f6ffb97a-9871-5c92-af83-c58d73e50beb'::uuid, 'sivananda', 'english', 'When your intellect, which is perplexed by the Vedic texts you have read, stands immovable and steady in the Self, then you will attain Self-realization.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('05304b92-b47a-50cf-add5-222d4a553c88'::uuid, '48da304c-7d2f-59bf-9165-e8ef0a658aa0'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Kesava, what is the description of a man of steady wisdom who is self-absorbed? How does he speak, sit, and move about?"'),
('3a4005c6-f175-5a9d-9e82-7a1ad1635cb5'::uuid, '48da304c-7d2f-59bf-9165-e8ef0a658aa0'::uuid, 'sivananda', 'english', 'Arjuna said, "O Krishna, what is the description of one who has steady wisdom and is merged in the superconscious state? How does one of steady wisdom speak, how do they sit, and how do they walk?"'),
('606918ae-e576-53ec-b26b-ba1d572ba712'::uuid, 'ba58cbf1-a87f-595d-a200-942017edb805'::uuid, 'gambhirananda', 'english', 'The Blessed One said, "O Partha, when one fully renounces all the desires that have entered the mind and remains satisfied in the Self alone, then he is called a man of steady wisdom."'),
('3b06315b-db2d-5a97-8756-55629842acee'::uuid, 'ba58cbf1-a87f-595d-a200-942017edb805'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "When a man completely casts off, O Arjuna, all the desires of the mind and is satisfied in the Self by the Self, then he is said to be one of steady wisdom."'),
('babb77c2-97fe-55b9-a909-f2a4e9b22121'::uuid, 'a449720e-f078-52b6-8bc9-90e5a7ca665b'::uuid, 'gambhirananda', 'english', 'That monk is called a man of steady wisdom when his mind is unperturbed even in sorrow, he is free from longing for delights, and has gone beyond attachment, fear, and anger.'),
('3158e09e-d355-5b0f-9252-dd111cdf17b6'::uuid, 'a449720e-f078-52b6-8bc9-90e5a7ca665b'::uuid, 'sivananda', 'english', 'He whose mind is not shaken by adversity, who does not long for pleasures, and is free from attachment, fear, and anger, is called a sage of steady wisdom.'),
('0c48dd12-c380-5217-baf8-35f056cfbe0f'::uuid, 'f093da7c-c9dd-5059-b8cf-1f51d7f63464'::uuid, 'gambhirananda', 'english', 'The wisdom of that person remains established who has no attachment to anything anywhere, who neither welcomes nor rejects anything, whatever good or bad, when they come across it.'),
('b0c40fd0-723d-59bd-bebe-4772e86f15c4'::uuid, 'f093da7c-c9dd-5059-b8cf-1f51d7f63464'::uuid, 'sivananda', 'english', 'He who is everywhere without attachment, upon encountering anything good or bad, neither rejoices nor hastens; his wisdom is firm.'),
('db635d80-057d-5487-beed-81de59216ffa'::uuid, 'f6f6b1ba-77f8-5359-956d-1b13817da029'::uuid, 'gambhirananda', 'english', 'And when one fully withdraws their senses from the objects of the senses, just as a tortoise withdraws its limbs, then their wisdom remains established.'),
('98daa43a-a4d2-575a-9315-154e6ff924ee'::uuid, 'f6f6b1ba-77f8-5359-956d-1b13817da029'::uuid, 'sivananda', 'english', 'When, like the tortoise which withdraws all its limbs on all sides, he withdraws his senses from the sense-objects, then his wisdom becomes steady.'),
('030dbfaf-e782-52f4-bbf2-42bd83c3315e'::uuid, '8ba4b3c6-4719-5eba-b3b8-25d05d952d5b'::uuid, 'gambhirananda', 'english', 'The objects recede from an abstinent person, except for the taste for them. Even this taste falls away after realization of the Absolute.'),
('4e068ed4-06aa-54ca-9264-5176bb3614dd'::uuid, '8ba4b3c6-4719-5eba-b3b8-25d05d952d5b'::uuid, 'sivananda', 'english', 'The objects of the senses turn away from the abstinent man, leaving the longing behind; but his longing also turns away upon seeing the Supreme.'),
('d67fdd64-0929-5fa1-ab15-a65284623bac'::uuid, '82994df3-345e-54c7-8495-6eb8efae7a35'::uuid, 'gambhirananda', 'english', 'For, O son of Kunti, the turbulent senses can violently snatch away the mind of an intelligent person, even while they are striving diligently.'),
('d81128a6-3ec9-5658-83fa-1a59df6d6f43'::uuid, '82994df3-345e-54c7-8495-6eb8efae7a35'::uuid, 'sivananda', 'english', 'The turbulent senses, O Arjuna, can violently carry away the mind of a wise person, even though they are striving to control them.'),
('f47f7708-ac93-5c95-99e6-7285a0f0a919'::uuid, '4ab5cad6-0867-574b-b68b-e9db11d0a633'::uuid, 'gambhirananda', 'english', 'Controlling all of them, one should remain focused on Me as the supreme. For, the wisdom of one whose senses are under control becomes steadfast.'),
('7edf5379-c45d-590c-afd6-82693061dddd'::uuid, '4ab5cad6-0867-574b-b68b-e9db11d0a633'::uuid, 'sivananda', 'english', 'Having restrained them all, he should sit steadfast, intent on Me; his wisdom is steady whose senses are under control.'),
('07f7cc65-5558-514a-ac08-366e78a92890'::uuid, '6cde0a0c-ad48-5de1-8cea-c6158bf8708f'::uuid, 'gambhirananda', 'english', '- In the case of a person who dwells on objects, there arises attachment to them. From attachment grows hankering, and from hankering springs anger.'),
('6a502acd-2d99-59ce-a309-8c7bb1f417f0'::uuid, '6cde0a0c-ad48-5de1-8cea-c6158bf8708f'::uuid, 'sivananda', 'english', 'When one thinks of objects, attachment to them arises; from attachment, desire is born; from desire, anger arises.'),
('2c8bb1c3-3355-580f-ae34-dd84f5e56ab5'::uuid, '17e4dd97-7fef-5671-8a06-f261cc089cd6'::uuid, 'gambhirananda', 'english', 'From anger follows delusion; from delusion, a failure of memory; from the failure of memory, the loss of understanding; and from the loss of understanding, one perishes.'),
('0a6358ef-2858-5aa1-8270-b66903b55223'::uuid, '17e4dd97-7fef-5671-8a06-f261cc089cd6'::uuid, 'sivananda', 'english', 'Anger leads to delusion, which causes loss of memory; this, in turn, leads to the destruction of discrimination, resulting in destruction.'),
('fa4a7a0c-9dad-5402-90c0-5350d437f72e'::uuid, '51cb2cd0-9a71-54c9-ad94-c1c5b9671e3e'::uuid, 'gambhirananda', 'english', 'But by perceiving objects with the organs that are free from attraction and repulsion, and are under his own control, the self-controlled person attains serenity.'),
('210513cb-483b-57af-9d3f-8030960aba43'::uuid, '51cb2cd0-9a71-54c9-ad94-c1c5b9671e3e'::uuid, 'sivananda', 'english', 'But the self-controlled man, moving among objects with the senses restrained and free from attraction and repulsion, attains peace.'),
('0a7691bd-3c56-5bae-bc74-7ae70212f35c'::uuid, '16572170-4087-5539-a220-b91708ae1b68'::uuid, 'gambhirananda', 'english', 'When there is serenity, all his sorrows are eradicated, for the wisdom of one with a serene mind soon becomes firmly established.'),
('2044c97f-3777-5650-8147-7ac57766f33a'::uuid, '16572170-4087-5539-a220-b91708ae1b68'::uuid, 'sivananda', 'english', 'In that peace, all pains are destroyed; for the intellect of the tranquil-minded soon becomes steady.'),
('62639079-6913-5797-9f22-efe62112fb74'::uuid, '7cc34c3c-32d2-5834-9ff0-052dde4d971a'::uuid, 'gambhirananda', 'english', 'For the unsteady there is no wisdom, and there is no meditation for the unsteady person. And for an unmeditative person there is no peace. How can there be happiness for one without peace?'),
('d117cc34-b687-5ecb-9832-0e40a823587c'::uuid, '7cc34c3c-32d2-5834-9ff0-052dde4d971a'::uuid, 'sivananda', 'english', 'There is no knowledge of the Self for the unsteady, and no meditation is possible for the unsteady, and no peace for the unmeditative, and how can there be happiness for one who has no peace?'),
('763a09c3-b2f2-5ecc-b7cd-18ecec55fc19'::uuid, '772d15da-2bfc-5c9e-9b86-9b7a5afd91d7'::uuid, 'gambhirananda', 'english', 'For, the mind which follows in the wake of the wandering senses carries away his wisdom like a boat on the waters.'),
('e9dc2b34-2654-5984-9e79-23ce0aaf26fa'::uuid, '772d15da-2bfc-5c9e-9b86-9b7a5afd91d7'::uuid, 'sivananda', 'english', 'For the mind, which follows in the wake of the wandering senses, carries away his discrimination, as the wind carries away a boat on the waters.'),
('26159ee4-094e-5dbc-b678-68e3bd11e636'::uuid, 'ff3e1ded-4ed7-5227-af39-8120764eac46'::uuid, 'gambhirananda', 'english', 'Therefore, O mighty-armed one, this wisdom becomes established when all its senses are withdrawn from their objects.'),
('0db419b6-0a07-56f3-a7b0-e030d6a5cf3f'::uuid, 'ff3e1ded-4ed7-5227-af39-8120764eac46'::uuid, 'sivananda', 'english', 'Therefore, O mighty-armed Arjuna, his knowledge is steady whose senses are completely restrained from sense objects.'),
('03a02ec3-1222-5c76-8994-7952d83e87cb'::uuid, 'f7156de3-e067-532d-a977-e9b11a843925'::uuid, 'gambhirananda', 'english', 'The self-restrained man stays awake during what is night for all creatures. That which creatures stay awake for, it is night to the discerning sage.'),
('9be16e68-59d8-5ec1-bff9-632e76bf1a39'::uuid, 'f7156de3-e067-532d-a977-e9b11a843925'::uuid, 'sivananda', 'english', 'That which is night to all beings, in that the self-controlled man is awake; when all beings are awake, that is night for the sage who sees.'),
('c1663c3c-1706-540b-aadf-4f7a0201f8b6'::uuid, '4d95e69a-b998-5628-9eb2-f4885bd63d1a'::uuid, 'gambhirananda', 'english', 'That man attains peace into whom all desires enter, just as waters flow into the sea that remains unchanged even when filled from all sides. Not so one who is desirous of objects.'),
('119604b3-4ef7-5fb1-8707-a877e250540d'::uuid, '4d95e69a-b998-5628-9eb2-f4885bd63d1a'::uuid, 'sivananda', 'english', 'He attains peace into whom all desires enter, just as waters enter the ocean which, filled from all sides, remains unmoved; but not the man who is full of desires.'),
('ba1e533f-8ea2-583c-aa1b-abea76874306'::uuid, '84ce9535-31d1-511a-8a9c-f42ce6b49dd5'::uuid, 'gambhirananda', 'english', 'That man attains peace who, after rejecting all desires, moves about free from hankering, without the idea of ''me'' and ''mine'', and devoid of pride.'),
('b1ffe4e5-b498-5cf9-84b6-9d8d85cfb576'::uuid, '84ce9535-31d1-511a-8a9c-f42ce6b49dd5'::uuid, 'sivananda', 'english', 'That person attains peace who, abandoning all desires, moves about without longing, without the sense of ownership, and without egoism.'),
('e65b9d82-9d5d-5726-a2fb-d2d6f999f8d7'::uuid, '90350f08-a6d4-5dec-abc5-e67e0e307d43'::uuid, 'gambhirananda', 'english', 'O Partha, this is the state of being established in Brahman. One does not become deluded after attaining this; one attains identification with Brahman by being established in this state even in the closing years of one''s life.'),
('ea5d4ebf-bd90-5a53-94da-803fa8a97e9e'::uuid, '90350f08-a6d4-5dec-abc5-e67e0e307d43'::uuid, 'sivananda', 'english', 'O son of Pritha, this is the eternal state, the Brahmic seat. Attaining this, one is not deluded. Being established in it, one attains oneness with Brahman even at the end of life.'),
('a947543b-9382-5e9d-ba3d-9701a2a4b623'::uuid, '642345b9-6cd6-53fd-a745-898ff599b660'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Janardana (Krishna), if it is Your opinion that wisdom is superior to action, why do You urge me to take such horrible action, O Kesava?"'),
('61348838-e0a0-5771-a82f-f4eaf676ce76'::uuid, '642345b9-6cd6-53fd-a745-898ff599b660'::uuid, 'sivananda', 'english', 'Arjuna said: If Thou thinkest that knowledge is superior to action, O Krishna, why then, O Kesava, doest Thou ask me to engage in this terrible action?'),
('102cbeea-7742-562d-9242-7acbe6094174'::uuid, 'a05cd567-8f51-5734-a55e-cf88e2c8bb67'::uuid, 'gambhirananda', 'english', 'You bewilder my understanding, as it were, with a seemingly conflicting statement! Tell me for certain which one of these I may use to attain the highest Good.'),
('1afab160-152b-5629-a84a-fc5baa722d4a'::uuid, 'a05cd567-8f51-5734-a55e-cf88e2c8bb67'::uuid, 'sivananda', 'english', 'With this seemingly perplexing speech, you seem to be confusing my understanding; therefore, tell me one certain way by which I may attain bliss.'),
('2e2f0aef-b3e6-543f-8d32-ae3796098868'::uuid, '0fdee932-dce7-51d5-8585-e8abe7edcf99'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, O unblemished one, two kinds of steadfastness in this world were spoken of by Me in days gone by—through the Yoga of Knowledge for the men of realization; through the Yoga of Action for the yogis.'),
('c94460d8-dede-503c-b62f-4754e60b8b6f'::uuid, '0fdee932-dce7-51d5-8585-e8abe7edcf99'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "In this world, there is a twofold path, as I said before, O sinless one: the path of knowledge of the Sankhyas and the path of action of the Yogins."'),
('7c5d4560-09b3-50da-9851-ad03357ab148'::uuid, 'dc57ccd7-d9b7-537b-8c0c-5238994d6325'::uuid, 'gambhirananda', 'english', 'A person does not attain freedom from action by abstaining from action; nor does he attain fulfillment merely through renunciation.'),
('7da2df0e-db58-5bfa-90b8-10272946e256'::uuid, 'dc57ccd7-d9b7-537b-8c0c-5238994d6325'::uuid, 'sivananda', 'english', 'Man does not reach actionlessness by not performing actions; nor does he attain perfection by mere renunciation.'),
('0b2dd7aa-f261-5aa5-9d9e-5e58b8f26099'::uuid, '694b87d1-7dc9-55c3-8020-a358e1d8e014'::uuid, 'gambhirananda', 'english', 'For no one ever remains even for a moment without doing work, for all are made to work under compulsion by the gunas born of Nature.'),
('cb3e991d-c354-5206-9eb4-da86548be79c'::uuid, '694b87d1-7dc9-55c3-8020-a358e1d8e014'::uuid, 'sivananda', 'english', 'Verily, no one can remain for even a moment without performing action; for everyone is made to act helplessly, indeed, by the qualities born of Nature.'),
('eaa46271-7c2f-5970-a0f2-835b9c21b781'::uuid, 'c75a64bd-71b5-5e3f-892b-0ced0b633dd2'::uuid, 'gambhirananda', 'english', 'One who, after withdrawing the organs of action, sits mentally recollecting the objects of the senses, is called a hypocrite, for they have a deluded mind.'),
('b8b6318b-d021-598a-ab68-519481408337'::uuid, 'c75a64bd-71b5-5e3f-892b-0ced0b633dd2'::uuid, 'sivananda', 'english', 'He who, restraining the organs of action, sits thinking of the sense-objects in his mind, he of deluded understanding is called a hypocrite.'),
('d930cc03-c504-58dd-99c9-dc99e450871a'::uuid, 'bb8ff35c-911b-5e58-ab5b-780a9cd158a3'::uuid, 'gambhirananda', 'english', 'But, O Arjuna, one who engages in Karma-yoga, controlling the organs of action with the mind and becoming unattached, excels.'),
('d1230e3a-e1a1-5c6c-822c-5cbadd83114b'::uuid, 'bb8ff35c-911b-5e58-ab5b-780a9cd158a3'::uuid, 'sivananda', 'english', 'But whoever, controlling the senses by the mind, O Arjuna, engages himself in Karma Yoga with the organs of action, without attachment, he excels.'),
('469a0062-a65e-54eb-a1ba-b029fe8c897f'::uuid, 'da0afc0f-2bc2-5875-accb-5f40204e5bc7'::uuid, 'gambhirananda', 'english', 'You should perform your obligatory duties, for action is superior to inaction. Moreover, even the maintenance of your body will not be possible without action.'),
('c0604743-5a7a-53d2-ba22-a63282975dd4'::uuid, 'da0afc0f-2bc2-5875-accb-5f40204e5bc7'::uuid, 'sivananda', 'english', 'Perform your bounden duty, for action is superior to inaction, and even the maintenance of the body would not be possible for you through inaction.'),
('35ef3250-f333-58a1-9a60-7e314b3220b5'::uuid, '51171b67-ae21-551a-b660-a9234c980200'::uuid, 'gambhirananda', 'english', 'This man becomes bound by actions other than those intended for God. Without being attached, O son of Kunti, perform actions for Him.'),
('503eb597-cc35-5d69-9877-9dac1ba25cf8'::uuid, '51171b67-ae21-551a-b660-a9234c980200'::uuid, 'sivananda', 'english', 'The world is bound by actions other than those performed for the sake of sacrifice; do thou, therefore, O son of Kunti (Arjuna), perform actions for that sake alone, free from attachment.'),
('0e835aa8-ae17-5113-bdd5-1014e2e0b970'::uuid, 'b4d64f6f-10e9-594b-980c-c1fc6091425c'::uuid, 'gambhirananda', 'english', 'In days of yore, having created the beings together with the sacrifices, Prajapati said, "By this, you shall multiply. Let this be your yielder of coveted objects of desire."'),
('102161fa-0213-5eaf-b3e2-5ca198d5a284'::uuid, 'b4d64f6f-10e9-594b-980c-c1fc6091425c'::uuid, 'sivananda', 'english', 'The Creator, having in the beginning created mankind together with sacrifice, said, "By this shall you propagate; let this be the milch cow of your desires—the cow that yields all the desired objects."'),
('52f00df2-a57e-539e-b7c3-d08c188bcd1b'::uuid, '6535e4a9-946a-5236-8f88-6f5663fa44b3'::uuid, 'gambhirananda', 'english', '''You nourish the gods with this. Let those gods nourish you in return. By mutually nourishing each other, you shall attain the supreme Good.'''),
('76a6fb77-3b11-5a83-a73d-4021ca762f5a'::uuid, '6535e4a9-946a-5236-8f88-6f5663fa44b3'::uuid, 'sivananda', 'english', 'With this, nourish the gods, and may the gods nourish you; thus, nourishing each other, you shall attain the highest good.'),
('0d45cb49-e18e-5a9b-b1d2-a0fd5f0f7ddd'::uuid, 'd8648255-5bda-5733-876c-74994b2ec9cc'::uuid, 'gambhirananda', 'english', '''Being nourished by sacrifices, the gods will indeed give you the coveted enjoyments. He is certainly a thief who enjoys what has been given by them without offering it to them.'''),
('23c3ee84-bf39-50d9-b990-1cfe24e0c867'::uuid, 'd8648255-5bda-5733-876c-74994b2ec9cc'::uuid, 'sivananda', 'english', 'The gods, nourished by the sacrifice, will give you the desired objects. So, he who enjoys the objects given by the gods without offering anything in return is indeed a thief.'),
('cc01e4f0-0b32-5e08-bdbb-61d6c11ab673'::uuid, '30dcdf09-d955-5bc0-a1ec-00e65b42aac3'::uuid, 'gambhirananda', 'english', 'By partaking in the remnants of sacrifices, they become freed from all sins. But those who are unholy and cook for themselves incur sin.'),
('36618220-baef-5b48-ba68-c8f0810e94c6'::uuid, '30dcdf09-d955-5bc0-a1ec-00e65b42aac3'::uuid, 'sivananda', 'english', 'The righteous who eat the remnants of the sacrifice are freed from all sins; but those sinful ones who cook food solely for their own sake indeed consume sin.'),
('95c44eef-6653-5877-a41c-7230fe5ed642'::uuid, 'e70eda3d-179a-5302-8cc8-faf33f91be49'::uuid, 'gambhirananda', 'english', 'From food are born the creatures; the origin of food is from rain; rain originates from sacrifice; sacrifice has action as its source.'),
('ce01fb5a-dd94-5b08-b515-200dae5214bd'::uuid, 'e70eda3d-179a-5302-8cc8-faf33f91be49'::uuid, 'sivananda', 'english', 'From food come forth beings; from rain, food is produced; from sacrifice arises rain, and sacrifice is born of action.'),
('4fcf6606-c62e-5767-9f4c-18bc3310cd74'::uuid, '5c3ddb00-90a4-5c8c-ac9b-978fecca99e1'::uuid, 'gambhirananda', 'english', 'Know that action has the Vedas as its origin; the Vedas have the Immutable as their source. Hence, the all-pervading Vedas are forever based on sacrifice.'),
('a235e370-7039-573d-89d9-67a6244b82bc'::uuid, '5c3ddb00-90a4-5c8c-ac9b-978fecca99e1'::uuid, 'sivananda', 'english', 'Know that action comes from Brahma, and Brahma comes from the Imperishable. Therefore, the all-pervasive Brahma ever rests in sacrifice.'),
('220e8c79-e209-53fe-8c47-7eb4111e188e'::uuid, '6943c13a-442c-5fda-9280-1efde3c2789f'::uuid, 'gambhirananda', 'english', 'O Partha, he who does not follow the wheel thus set in motion lives in vain, their life is sinful, and they indulge in the senses.'),
('385ed5f6-a86d-50f3-8b4b-353517c4b31a'::uuid, '6943c13a-442c-5fda-9280-1efde3c2789f'::uuid, 'sivananda', 'english', 'He who does not follow the wheel thus set in motion, who is of sinful life, rejoicing in the senses, lives in vain, O Arjuna.'),
('a14b72d1-f89e-5c28-a75b-570fd84983b0'::uuid, 'bccb8135-facd-5266-8567-729951c1bfe8'::uuid, 'gambhirananda', 'english', 'But that man who rejoices only in the Self, is satisfied with the Self, and is content only in the Self—for him there is no duty to perform.'),
('ece3fb2f-ad57-5cbf-b85a-56d2a4273d09'::uuid, 'bccb8135-facd-5266-8567-729951c1bfe8'::uuid, 'sivananda', 'english', 'But for that man who rejoices only in the Self, who is satisfied with the Self and is content in the Self alone, indeed there is nothing to do.'),
('66c3d777-66e5-55a3-87a3-ad734cc4b147'::uuid, '51c4f40f-993e-5226-a4d2-d3beba3277e7'::uuid, 'gambhirananda', 'english', 'For him, there is no concern here at all with performing action, nor any with non-performance. Moreover, he has no dependence on any object to serve any purpose.'),
('0fe693ee-8fb2-51cb-94dc-fec06a3c8cb8'::uuid, '51c4f40f-993e-5226-a4d2-d3beba3277e7'::uuid, 'sivananda', 'english', 'For him, there is no interest whatsoever in what is done or not done; nor does he depend on any being for any purpose.'),
('49ca3b34-e027-54df-8379-da46724cd14d'::uuid, '06fd4067-6275-53e0-b76b-d63746b83f6c'::uuid, 'gambhirananda', 'english', 'Therefore, remaining unattached, always perform the obligatory duty; for, by performing one''s duty without attachment, a person attains the highest.'),
('4b798b40-488a-57c2-b0b5-ad886d2018a9'::uuid, '06fd4067-6275-53e0-b76b-d63746b83f6c'::uuid, 'sivananda', 'english', 'Therefore, without attachment, always perform the actions that should be done; for by performing actions without attachment, one reaches the Supreme.'),
('470798de-293e-57db-93b4-c39ad14cc482'::uuid, 'd2b07086-689c-5cab-9436-6428fc4eb543'::uuid, 'gambhirananda', 'english', 'For Janaka and others strove to attain liberation through action itself. You should perform your duties, keeping in view the prevention of mankind from going astray.'),
('02579cfa-f4ec-5b6d-a458-ceb926575afe'::uuid, 'd2b07086-689c-5cab-9436-6428fc4eb543'::uuid, 'sivananda', 'english', 'Janaka and others attained perfection indeed through action alone; even with the intention of protecting the masses, you should perform action.'),
('2234876d-b2d3-57bc-bc23-69f955c42945'::uuid, '487bbb4e-9745-5da9-a56f-30bdf521760a'::uuid, 'gambhirananda', 'english', 'Whatever a superior person does, another person does the same! Whatever they uphold as authority, an ordinary person follows that.'),
('c31c617b-c9fc-5205-88e8-9504f1d5213a'::uuid, '487bbb4e-9745-5da9-a56f-30bdf521760a'::uuid, 'sivananda', 'english', 'Whatever a great man does, others also do; whatever he establishes as the standard, the world follows.'),
('3c6d192d-a5f7-5804-a743-f6ddba04122d'::uuid, 'f8b9d024-8589-59d1-b5d5-b61c65cbb222'::uuid, 'gambhirananda', 'english', 'In all the three worlds, O Partha, there is no duty for Me to fulfill; nothing remains unachieved or to be achieved. (Still,) I continue in action.'),
('53506087-be84-53d9-aaf4-9f0f9af72dd3'::uuid, 'f8b9d024-8589-59d1-b5d5-b61c65cbb222'::uuid, 'sivananda', 'english', 'There is nothing in the three worlds, O Arjuna, that needs to be done by Me, nor is there anything unattained that needs to be attained; yet I engage Myself in action.'),
('2171f5e5-eb17-5c83-941c-24dc8d040b44'::uuid, '2f047970-ab62-50fb-8ec3-f956feea766b'::uuid, 'gambhirananda', 'english', 'For, O Partha, if at any time I do not continue vigilantly in action, people will follow My path in every way.'),
('a00e3dc0-ae01-5f72-a76f-75bcb3966aaa'::uuid, '2f047970-ab62-50fb-8ec3-f956feea766b'::uuid, 'sivananda', 'english', 'For, should I not ever engage myself in action, unwearied, people would in every way follow my path, O Arjuna.'),
('0428037c-3eee-5db0-b2b3-c6a69b016a78'::uuid, 'ce3f62ec-89d5-553f-9050-6e695bbec4c2'::uuid, 'gambhirananda', 'english', 'These worlds would be ruined if I did not perform action. And I shall become the agent of intermingling (of castes), and shall be destroying these beings.'),
('3e824797-7e55-5466-8032-7cf95c5460eb'::uuid, 'ce3f62ec-89d5-553f-9050-6e695bbec4c2'::uuid, 'sivananda', 'english', 'These worlds would perish if I did not perform action; I would be the author of confusion of castes and destruction of these beings.'),
('fc38a0d2-4f71-5eba-be89-3e62b8119292'::uuid, '1e24e90b-ece3-5e16-aeed-f6d687699003'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, as the unenlightened people act with attachment to work, so should the enlightened person act, without attachment, desiring to prevent people from going astray.'),
('22f5d206-261b-54d5-8d7a-0c70426a007c'::uuid, '1e24e90b-ece3-5e16-aeed-f6d687699003'::uuid, 'sivananda', 'english', 'As the ignorant act out of attachment to action, O Bharata, so should the wise act without attachment, wishing for the welfare of the world.'),
('e04cbdf0-9a01-555d-8303-a3a061754d12'::uuid, '9d743f97-ca3b-56f5-9dd5-71b39a53b737'::uuid, 'gambhirananda', 'english', 'The enlightened man should not disturb the beliefs of the ignorant, who are attached to work. He should remain diligent himself and make them perform all their duties.'),
('9bb3ae5d-b95d-5cf4-8f07-11ee881fdc93'::uuid, '9d743f97-ca3b-56f5-9dd5-71b39a53b737'::uuid, 'sivananda', 'english', 'Let no wise man unsettle the minds of ignorant people who are attached to action; he should engage them in all actions, himself fulfilling them with devotion.'),
('417a7832-bc3b-5305-b391-95dc6de16408'::uuid, '27a68d79-5e98-53c9-9d2b-1ffc15078dc1'::uuid, 'gambhirananda', 'english', 'While actions are being done in every way by the gunas (qualities) of Nature, one who is deluded by egoism thinks, "I am the doer."'),
('276e655d-445a-5a7f-94af-853166a16c92'::uuid, '27a68d79-5e98-53c9-9d2b-1ffc15078dc1'::uuid, 'sivananda', 'english', 'All actions are wrought in all cases by the qualities of Nature alone. He whose mind is deluded by egoism thinks, "I am the doer."'),
('92605a11-a22f-5146-98bc-c03c713e3bee'::uuid, '99499fef-d15b-5d8d-888d-60bd828020cc'::uuid, 'gambhirananda', 'english', 'But, O mighty-armed one, the one who is a knower of the facts about the varieties of the gunas and actions does not become attached, thinking thus: ''The organs act on the objects of the organs.'''),
('bc47be56-9370-505c-b173-e75c5b05057f'::uuid, '99499fef-d15b-5d8d-888d-60bd828020cc'::uuid, 'sivananda', 'english', 'But he who knows the Truth, O mighty-armed Arjuna, about the divisions of the qualities and their functions, knowing that the Gunas, as senses, move amidst the Gunas, as the sense-objects, is not attached.'),
('eedbf80c-d853-53c6-8f84-1ae99443bac6'::uuid, '71a43934-b14f-5993-9477-a132180f2d5e'::uuid, 'gambhirananda', 'english', 'Those who are completely deluded by the gunas of Nature become attached to the activities of the gunas. The one who knows the All should not disturb those of dull intellect, who do not know the All.'),
('b3bb9f54-2eb3-51ed-b504-8e19992fdbd0'::uuid, '71a43934-b14f-5993-9477-a132180f2d5e'::uuid, 'sivananda', 'english', 'Those deluded by the qualities of Nature are attached to the functions of the qualities. The man of perfect knowledge should not unsettle the foolish one who is of imperfect knowledge.'),
('e50b9eea-9818-5560-af61-f40a6838c88e'::uuid, '7a4eed63-0cc5-5860-afea-c9976b6dd369'::uuid, 'gambhirananda', 'english', 'Free from the fever of the soul, dedicate all actions to Me, with your mind intent on the Self, and become free from expectations and egoism, and engage in battle.'),
('2b92a7e0-ace9-5b83-83cf-0b15bec0f024'::uuid, '7a4eed63-0cc5-5860-afea-c9976b6dd369'::uuid, 'sivananda', 'english', 'Renouncing all actions in Me, with the mind centered on the Self, free from hope and egoism, and from mental fever, fight thou.'),
('a567239a-92b1-504a-950d-0d33c96b3b78'::uuid, '6fec3a2f-5ba3-5a6c-9b51-b9aab858c5a9'::uuid, 'gambhirananda', 'english', 'Those who faithfully follow this teaching of Mine without cavil, they too become freed from their actions.'),
('2b4cbd59-d384-54a4-b6cd-eadef0528a32'::uuid, '6fec3a2f-5ba3-5a6c-9b51-b9aab858c5a9'::uuid, 'sivananda', 'english', 'Those who constantly practice this teaching of Mine with faith and without caviling, they too are freed from actions.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('f2b51ad7-6680-5572-a098-891da8ef4b38'::uuid, '43030554-33cf-5162-9640-65a7baf17b2a'::uuid, 'gambhirananda', 'english', 'But those who, finding fault where there is none, do not follow My teaching, know them—who are deluded about all knowledge concerning the qualified and the unqualified Brahman and who are devoid of discrimination—to have gone to ruin.'),
('2ca37fa6-5e0a-5d25-9f0e-41561dd075e5'::uuid, '43030554-33cf-5162-9640-65a7baf17b2a'::uuid, 'sivananda', 'english', 'But those who criticize My teaching and do not practice it, deprived of all knowledge and lacking discernment, know them to be doomed to destruction.'),
('9eee2e87-517e-5b70-83fb-dbe5263ffd3b'::uuid, 'f8cd7d2c-d38e-5ffc-873d-e50ff9b5891e'::uuid, 'gambhirananda', 'english', 'Even a man of wisdom behaves according to his own nature. They follow their nature. What can restraint do?'),
('6770a302-cd58-5655-a5a4-fe0c8eaab333'::uuid, 'f8cd7d2c-d38e-5ffc-873d-e50ff9b5891e'::uuid, 'sivananda', 'english', 'Even a wise man acts in accordance with his own nature; beings will follow their nature; what can restraint do?'),
('ca5bde29-fca0-5032-bf8b-602fb8c7672a'::uuid, 'c203770a-c9c0-5c1b-bf34-7c48182df501'::uuid, 'gambhirananda', 'english', 'Attraction and repulsion are ordained with respect to the objects of all the organs. One should not be swayed by these two, as they are adversaries.'),
('beb70fc3-89f7-5fc8-af82-f503aa073b64'::uuid, 'c203770a-c9c0-5c1b-bf34-7c48182df501'::uuid, 'sivananda', 'english', 'Attachment and aversion for the objects of the senses abide in the senses; let no one come under their sway; for, they are his enemies.'),
('c0225fcb-6293-53e7-9adf-5af7f806fc0f'::uuid, '432ea4cf-676a-5296-9a2f-6df02ebe358c'::uuid, 'gambhirananda', 'english', 'One''s own duty, though defective, is superior to another''s duty well-performed. Death is better while engaged in one''s own duty; another''s duty is full of fear.'),
('995bf896-1e31-51f3-a6b7-86c1bfe03f4c'::uuid, '432ea4cf-676a-5296-9a2f-6df02ebe358c'::uuid, 'sivananda', 'english', 'Better is one''s own duty, though devoid of merit, than the duty of another well discharged. Better is death in one''s own duty; the duty of another is fraught with fear.'),
('f5a31b77-67de-523d-9f63-4d9612ccedec'::uuid, 'd7ec16ba-f4e9-5da1-8155-61b20bde7c85'::uuid, 'gambhirananda', 'english', 'Arjuna said, "Now then, O scion of the Vrsni dynasty (Krsna), what compels this man to commit sin even against his will, as if he were constrained by force?"'),
('8bf396d2-6a31-564e-bd21-89c7331f6c2a'::uuid, 'd7ec16ba-f4e9-5da1-8155-61b20bde7c85'::uuid, 'sivananda', 'english', 'Arjuna said, "But what compels man to commit sin, even against his wishes, O Varshneya (Krishna), as if constrained by force?"'),
('16f91714-41c3-5bbe-bc1f-8c46b46f8e9a'::uuid, '6251b0cf-367a-529c-a138-8b6cf7af8dcc'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "This desire, this anger, born of the quality of rajas, is a great devourer, a great source of sin. Know this to be the enemy here."'),
('aa4dcafd-fb0e-5b79-b02c-677da9d97afb'::uuid, '6251b0cf-367a-529c-a138-8b6cf7af8dcc'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "It is desire and it is anger, both of the quality of Rajas, all-devouring and all-sinful; know this as the foe here in this world."'),
('57580f20-9356-5555-87d2-f4b3f514a941'::uuid, '057a729b-56e7-52c4-9d1b-9248c2b16c52'::uuid, 'gambhirananda', 'english', 'As fire is enveloped by smoke, as a mirror is obscured by dirt, and as a fetus remains enclosed in the womb, so is this shrouded by that.'),
('2ccc118d-c131-5ba3-93c1-ec21c2366598'::uuid, '057a729b-56e7-52c4-9d1b-9248c2b16c52'::uuid, 'sivananda', 'english', 'As fire is enveloped by smoke, as a mirror is covered by dust, and as an embryo is surrounded by the amniotic sac, so is this enveloped by that.'),
('8f9d30df-28de-58e9-a6c6-de39234f8e0f'::uuid, '3c625eeb-bfe5-5fec-a08a-48eef5d22088'::uuid, 'gambhirananda', 'english', 'O son of Kunti, knowledge is covered by this constant enemy of the wise, in the form of desire, which is an insatiable fire.'),
('19554e7d-19b0-58fc-86f2-ebcbb029f52b'::uuid, '3c625eeb-bfe5-5fec-a08a-48eef5d22088'::uuid, 'sivananda', 'english', 'O Arjuna, wisdom is enveloped by this constant enemy of the wise, in the form of desire, which is insatiable like fire.'),
('de4cf0f1-ca4c-55da-ae9a-153f48eff2a3'::uuid, '79be0cb4-8de4-506f-9a4f-38d327b321de'::uuid, 'gambhirananda', 'english', 'The organs, mind, and intellect are said to be its abode. This one diversely deludes the embodied being, veiling Knowledge with the help of these.'),
('027533a8-e348-55e4-8273-3586e087fa51'::uuid, '79be0cb4-8de4-506f-9a4f-38d327b321de'::uuid, 'sivananda', 'english', 'The senses, the mind, and the intellect are said to be its seat; through these, it deludes the embodied one, veiling their wisdom.'),
('683e4248-1b41-5c50-94dd-512098222c13'::uuid, '69bf7957-a5d4-51ce-abcd-dcf34d852aff'::uuid, 'gambhirananda', 'english', 'Therefore, O scion of the Bharata dynasty, after first controlling the organs, completely renounce this one which is sinful and a destroyer of learning and wisdom.'),
('47b99885-e058-57f6-8496-6876639c0050'::uuid, '69bf7957-a5d4-51ce-abcd-dcf34d852aff'::uuid, 'sivananda', 'english', 'Therefore, O best of the Bharatas, control your senses first and then kill this sinful thing, which destroys knowledge and realization.'),
('e8ad8d8c-422d-55e3-a891-7a847c9a6042'::uuid, 'b6321639-cf22-543a-a757-f9c18509a2e8'::uuid, 'gambhirananda', 'english', 'They say that the organs are superior to the gross body; the mind is superior to the organs; and the intellect is superior to the mind. However, He is superior to the intellect.'),
('3e0f5f49-818e-5f2c-a8b8-b5c54d64e6ad'::uuid, 'b6321639-cf22-543a-a757-f9c18509a2e8'::uuid, 'sivananda', 'english', 'They say that the senses are superior to the body; the mind is superior to the senses; the intellect is superior to the mind; and He (the Self) is superior even to the intellect.'),
('cfb977e0-37bb-5a65-bf1b-a6a99318422f'::uuid, '6ee651c8-2e09-500c-8363-9edb89a9f914'::uuid, 'gambhirananda', 'english', '[The Ast, introduces this verse with, ''Tatah kim, what follows from that?''-Tr.] Understanding the Self thus as superior to the intellect, and completely establishing (the Self) through spiritual absorption with the (help of) the mind, O mighty-armed one, the enemy in the form of desire, which is difficult to subdue, vanishes.'),
('effd87c0-0ccc-5163-8718-a18cbf677870'::uuid, '6ee651c8-2e09-500c-8363-9edb89a9f914'::uuid, 'sivananda', 'english', 'Thus, knowing Him who is superior to the intellect and restraining the self by the Self, slay thou, O mighty-armed Arjuna, the enemy in the form of desire, hard to conquer.'),
('d57c1840-2335-535d-aee3-976ef0c62c31'::uuid, '58b673ae-10fe-5838-994e-4ca18a3a8254'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "I imparted this imperishable Yoga to Vivasvan, who then taught it to Manu, who in turn transmitted it to Iksavaku.'),
('ed1bb4c8-6330-5c8d-bcf9-53b7e774b16d'::uuid, '58b673ae-10fe-5838-994e-4ca18a3a8254'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "I taught this imperishable Yoga to Vivasvan; he then told it to Manu; Manu proclaimed it to Ikshvaku.'),
('dfe0d143-0d3f-53f8-9482-91c3c1c5a59c'::uuid, 'a6324ec2-34f0-50d8-96de-e96c15274f85'::uuid, 'gambhirananda', 'english', 'The king-sages knew this yoga, which was received in regular succession. That yoga, O destroyer of foes, is now lost due to a long lapse of time.'),
('fd29774c-3b72-5f79-9613-48af3e125f79'::uuid, 'a6324ec2-34f0-50d8-96de-e96c15274f85'::uuid, 'sivananda', 'english', 'This, handed down in regular succession by the royal sages, was known. This Yoga, however, has been lost here over time, O Parantapa (burner of the foes).'),
('6679b216-4506-5eb3-97ad-5d63892181f4'::uuid, 'cd822b2a-fdb6-582b-b06f-a0b134f1dda7'::uuid, 'gambhirananda', 'english', 'That ancient Yoga itself, which is this, has been taught to you by Me today, considering you to be My devotee and friend, for this Yoga is a profound secret.'),
('861af016-3e13-5ced-a345-c254cd1c6428'::uuid, 'cd822b2a-fdb6-582b-b06f-a0b134f1dda7'::uuid, 'sivananda', 'english', 'That same ancient yoga has been today taught to you by me, for you are my devotee and my friend; it is the supreme secret.'),
('e988f794-e376-5dc5-bab5-093e286336bb'::uuid, '0406722a-08cd-5cec-a0f5-9cba4e5aac9a'::uuid, 'gambhirananda', 'english', 'Arjuna said, "Your birth was later, whereas Vivasvan''s birth was earlier. How am I to understand that You instructed him in the beginning?"'),
('237b959e-5ce9-5f0d-b2e7-288d216c707c'::uuid, '0406722a-08cd-5cec-a0f5-9cba4e5aac9a'::uuid, 'sivananda', 'english', 'Arjuna said, "Later was Thy birth, and prior to it was the birth of Vivasvan (the Sun); how am I to understand that Thou hast taught this Yoga from the beginning?"'),
('22ac883e-0c3f-59ad-933c-d14813630c84'::uuid, '04f116d4-7eb9-58bd-97b6-7418ef1cf10d'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "O Arjuna, many lives of Mine have passed, and so have yours. I know them all, but you do not know, O scorcher of enemies!"'),
('72ebd547-d497-5c7c-87be-bbb4c987aec8'::uuid, '04f116d4-7eb9-58bd-97b6-7418ef1cf10d'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "Many births of Mine have passed, as well as of thine, O Arjuna; I know them all, but thou knowest not, O Parantapa (scorcher of foes)."'),
('d498dad2-5666-5bc4-b708-59f35d7b0e19'::uuid, 'cbc51231-994a-5664-83e0-3cecc2d04992'::uuid, 'gambhirananda', 'english', 'Though I am birthless and undecaying by nature, and the Lord of beings, yet by subjugating My Prakriti, I take birth through My own Maya.'),
('78dafbeb-d47c-513a-a869-24b73eb55f34'::uuid, 'cbc51231-994a-5664-83e0-3cecc2d04992'::uuid, 'sivananda', 'english', 'Though I am unborn and of imperishable nature, and though I am the Lord of all beings, yet, governing my own nature, I am born by my own Maya.'),
('03a6b8af-3597-569a-87e5-c8e3116a36ae'::uuid, 'a2d25b2f-d1e9-5927-8648-5ed81c80ef3a'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, whenever there is a decline in virtue and an increase in vice, then I manifest Myself.'),
('283550f1-6bd0-5b84-96ec-0405d7092c52'::uuid, 'a2d25b2f-d1e9-5927-8648-5ed81c80ef3a'::uuid, 'sivananda', 'english', 'Whenever there is a decline of righteousness and an increase of unrighteousness, O Arjuna, then I manifest Myself.'),
('95ca47a1-beec-523a-a29b-7406d0b83d48'::uuid, '7f287d89-3364-59e5-b82a-506f77271cd8'::uuid, 'gambhirananda', 'english', 'For the protection of the pious, the destruction of the evil-doers, and the establishment of virtue, I manifest myself in every age.'),
('0d09eb00-5e92-5a3f-bfae-fa123546e67f'::uuid, '7f287d89-3364-59e5-b82a-506f77271cd8'::uuid, 'sivananda', 'english', 'For the protection of the good, for the destruction of the wicked, and for the establishment of righteousness, I am born in every age.'),
('4cc042bd-eb7d-567d-98bf-5ebcb5f50691'::uuid, '3b25fea4-d31a-5046-800a-30555c85dfed'::uuid, 'gambhirananda', 'english', 'He who thus knows truly the divine birth and actions of Mine does not get rebirth after casting off the body. He attains Me, O Arjuna.'),
('68a934d4-0cc6-55b4-95bd-8ac961de038b'::uuid, '3b25fea4-d31a-5046-800a-30555c85dfed'::uuid, 'sivananda', 'english', 'He who thus knows, in their true light, My divine birth and actions, having abandoned the body, is not born again; he comes to Me, O Arjuna.'),
('2a6f5945-92f8-5042-8f97-1fbe2a0c8c74'::uuid, '649d2bb9-2a09-56da-8dcc-a2ea1aed3b40'::uuid, 'gambhirananda', 'english', 'Many who were devoid of attachment, fear, and anger, who were absorbed in Me, who had taken refuge in Me, and were purified by the austerity of knowledge, have attained My state.'),
('216031ad-e5d7-5024-aa56-5fd207200696'::uuid, '649d2bb9-2a09-56da-8dcc-a2ea1aed3b40'::uuid, 'sivananda', 'english', 'Freed from attachment, fear, and anger, absorbed in Me, taking refuge in Me, purified by the fire of knowledge, many have attained My Being.'),
('42e4ecea-2788-57e3-ae67-4fa58d4afc1a'::uuid, '0c21c7ba-8a37-5a2a-babd-8fa261b8d120'::uuid, 'gambhirananda', 'english', 'According to the manner in which they approach Me, I favor them in that same manner. O son of Partha, humans follow My path in every way.'),
('c32c9192-d375-5807-92f8-895ce575f95d'::uuid, '0c21c7ba-8a37-5a2a-babd-8fa261b8d120'::uuid, 'sivananda', 'english', 'In whatever way men approach Me, even so do I reward them; My path do men tread in all ways, O Arjuna.'),
('fdf6ab46-111b-5e58-909a-238d2f9a9404'::uuid, 'c1c95996-41f2-54ee-92c1-1964e0ff6c05'::uuid, 'gambhirananda', 'english', 'Longing for the fruition of their actions (of their rites and duties), they worship the gods here. For, in the human world, success from action comes quickly.'),
('e6130d12-601c-5839-a37c-26273b43ed29'::uuid, 'c1c95996-41f2-54ee-92c1-1964e0ff6c05'::uuid, 'sivananda', 'english', 'Those who long for success in action in this world sacrifice to the gods; for success is quickly attained by men through action.'),
('cc4602f8-7a7b-5068-80fb-f257287e5b5f'::uuid, '96c72b16-b8cd-51e8-b4b6-b49d277a2206'::uuid, 'gambhirananda', 'english', 'The four castes have been created by Me through a classification of the gunas and duties. Even though I am the agent of that (act of classification), still know Me to be non-agentive and changeless.'),
('c877988e-b50e-56a5-bf6b-d0586911faa8'::uuid, '96c72b16-b8cd-51e8-b4b6-b49d277a2206'::uuid, 'sivananda', 'english', 'The fourfold caste has been created by Me according to the differentiation of Guna and Karma; though I am the author of it, know Me as non-doer and immutable.'),
('0f1fba67-c450-57b8-ac79-27f93fa022d9'::uuid, '70f614a9-4c4d-5428-ab24-7f3d6778f704'::uuid, 'gambhirananda', 'english', 'Actions do not taint Me; for I have no hankering for the results of actions. One who knows Me thus, does not become bound by their actions.'),
('38a6932e-cced-5d02-9ec2-4b1d5273a18c'::uuid, '70f614a9-4c4d-5428-ab24-7f3d6778f704'::uuid, 'sivananda', 'english', 'Actions do not taint Me, nor do I have a desire for the fruit of actions. He who knows Me thus is not bound by actions.'),
('90175758-6786-5324-972a-3812a1636ae7'::uuid, '0498534f-e85a-5216-8c8b-146f6dbae8c3'::uuid, 'gambhirananda', 'english', 'Thus having known, even the ancient seekers of liberation performed their duties. Therefore, you should undertake action as was performed earlier by the ancients.'),
('6ccc3f97-61ad-5b20-abc5-99151c35649c'::uuid, '0498534f-e85a-5216-8c8b-146f6dbae8c3'::uuid, 'sivananda', 'english', 'Having known this, the ancient seekers of freedom also performed action; therefore, do thou also perform action, as the ancients did in days of yore.'),
('2aeadce6-ede9-59a5-a0db-6d21edf592a6'::uuid, '1f99e228-6b42-55d8-9e60-417f413927c6'::uuid, 'gambhirananda', 'english', 'Even the intelligent are confounded as to what is action and what is inaction. I shall tell you of that action, knowing which you will become free from evil.'),
('5f01e630-cec2-54c4-a803-5c453d561cdd'::uuid, '1f99e228-6b42-55d8-9e60-417f413927c6'::uuid, 'sivananda', 'english', 'What is action? What is inaction? Even the wise are confused about this. Therefore, I shall teach you the nature of action and inaction, by knowing which you will be liberated from the evil of Samsara, the wheel of birth and death.'),
('95029478-c4eb-5478-9e41-6b0b9da69b7f'::uuid, '9b46f2d0-d829-514d-85cf-068dc3ef5b02'::uuid, 'gambhirananda', 'english', 'For there is something to be known even about action, and something to be known about prohibited action; and something needs to be known about inaction. The true nature of action is inscrutable.'),
('8d77d56d-3147-5378-ae35-ac4cc7d63c2b'::uuid, '9b46f2d0-d829-514d-85cf-068dc3ef5b02'::uuid, 'sivananda', 'english', 'For verily, the true nature of action enjoined by the scriptures should be known, as well as that of forbidden or unlawful action, and of inaction; the nature of action is hard to understand.'),
('6edd17a0-86de-5b62-9f09-ae754796fc83'::uuid, 'b3848acf-7137-51c6-811d-417d0555f728'::uuid, 'gambhirananda', 'english', 'He who finds inaction in action, and action in inaction, is the wise one [possessed of the knowledge of Brahman] among men; they are engaged in yoga and are performers of all actions!'),
('3990a134-d49d-5f16-8d4e-92d761bf3a5a'::uuid, 'b3848acf-7137-51c6-811d-417d0555f728'::uuid, 'sivananda', 'english', 'He who sees inaction in action and action in inaction, he is wise among men; he is a yogi and performer of all actions.'),
('23b91f69-1975-5fef-8f0c-2c8a6df3479e'::uuid, 'eeff6e02-b5df-5085-9658-fb76a1ecbd70'::uuid, 'gambhirananda', 'english', 'The wise call him learned whose actions are all devoid of desires and their thoughts, and whose actions have been burned away by the fire of wisdom.'),
('2d41a823-fa27-5785-87e2-706467348b1b'::uuid, 'eeff6e02-b5df-5085-9658-fb76a1ecbd70'::uuid, 'sivananda', 'english', 'He whose undertakings are all devoid of desires and selfish purposes, and whose actions have been burned by the fire of knowledge, the wise call him a sage.'),
('c70c0e16-4aaa-5907-aa18-bb53b3fb9e63'::uuid, 'b969ae28-b184-5622-9dd6-d807b65459c0'::uuid, 'gambhirananda', 'english', 'Having given up attachment to the results of action, he who is ever-content, dependent on nothing, does not really do anything even though he is engaged in action.'),
('6dfde6e6-ffa3-56b5-b614-58465aa35290'::uuid, 'b969ae28-b184-5622-9dd6-d807b65459c0'::uuid, 'sivananda', 'english', 'Having abandoned attachment to the fruits of the action, ever content, depending on nothing, he does not do anything even while being engaged in activity.'),
('49c82d07-30d3-5118-9458-e6d31bee9c41'::uuid, 'd302664b-254b-5530-b3cf-053ba95ccf81'::uuid, 'gambhirananda', 'english', 'One who is without solicitation, who has the mind and senses under control, and is totally without possessions, incurs no sin by performing actions merely for the maintenance of the body.'),
('966df24b-6925-5ad7-bc5f-2dd3614e2720'::uuid, 'd302664b-254b-5530-b3cf-053ba95ccf81'::uuid, 'sivananda', 'english', 'Without hope, controlling the mind and the self, having abandoned all covetousness, and performing only bodily actions, one incurs no sin.'),
('b1c47c4f-6dc9-56e3-8738-868b28d7f0ba'::uuid, 'c73d34bb-3e4d-5522-ae02-b950ddfdfa47'::uuid, 'gambhirananda', 'english', 'Remaining satisfied with what comes unasked for, having transcended the dualities, being free from spite, and balanced under success and failure, he is not bound even by performing actions.'),
('1bf28669-341c-535a-a883-0a35e46bb31f'::uuid, 'c73d34bb-3e4d-5522-ae02-b950ddfdfa47'::uuid, 'sivananda', 'english', 'Content with what comes to him without effort, free from the pairs of opposites and envy, even-minded in success and failure, he acts yet is not bound.'),
('03d3a2f7-c2de-5d1f-8653-ddb96719bac6'::uuid, '5f306b8e-2fc6-5ea9-accc-5bf7fe5617f6'::uuid, 'gambhirananda', 'english', 'The liberated person, who has rid themselves of attachment and whose mind is fixed in knowledge, has their actions undertaken for a sacrifice completely destroyed.'),
('1d4c4e37-0622-577d-b99c-6e953d1800ce'::uuid, '5f306b8e-2fc6-5ea9-accc-5bf7fe5617f6'::uuid, 'sivananda', 'english', 'To one who is devoid of attachment, who is liberated, whose mind is established in knowledge, and who works for the sake of sacrifice (for the sake of God), the whole action is dissolved.'),
('b154f8d4-942e-5f09-8581-4690484db7cd'::uuid, 'e8ba1b49-91a4-5bf4-bc5b-b80444de40cb'::uuid, 'gambhirananda', 'english', 'The ladle is Brahman, the oblations are Brahman, and the offering is poured by Brahman into the fire of Brahman. He who has concentration on Brahman as the objective can only reach Brahman.'),
('2716e047-e575-5455-b38f-2b295218b34f'::uuid, 'e8ba1b49-91a4-5bf4-bc5b-b80444de40cb'::uuid, 'sivananda', 'english', 'Brahman is the oblation; Brahman is the melted butter (ghee); by Brahman is the oblation poured into the fire of Brahman; Brahman indeed shall be attained by one who always sees Brahman in action.'),
('ad9dfd43-2783-5a32-868b-c6860b489b38'::uuid, '104895bd-f569-5105-81b0-8d3e7cc84df1'::uuid, 'gambhirananda', 'english', 'Other yogis undertake sacrifice to gods alone, while others offer the Self as a sacrifice by themselves, in the fire of Brahman.'),
('64f8a3a8-c767-5710-8310-cca5b1ff8d35'::uuid, '104895bd-f569-5105-81b0-8d3e7cc84df1'::uuid, 'sivananda', 'english', 'Some yogis perform sacrifice to the gods alone; while others, who have realized the Self, offer the Self as sacrifice in the fire of Brahman alone.'),
('8f0bf5fd-ac02-5a79-8581-90ba78d19f8e'::uuid, '2b552f15-26f6-5644-920e-36342604c17d'::uuid, 'gambhirananda', 'english', 'Others offer their organs, such as their ears, etc., in the fires of self-control. Others offer the objects, such as sound, etc., in the fires of their organs.'),
('4f373da9-fcb3-5251-a98d-51e253dcb052'::uuid, '2b552f15-26f6-5644-920e-36342604c17d'::uuid, 'sivananda', 'english', 'Some again offer the organ of hearing and other senses as a sacrifice in the fire of restraint; others offer sound and other objects of the senses as a sacrifice in the fire of the senses.'),
('eec337f1-8540-50fc-9863-dde0456f627f'::uuid, '72692d8c-3f9a-5902-80b7-da86df99965c'::uuid, 'gambhirananda', 'english', 'Others offer all the activities of the organs and the activities of the vital force into the fire of the yoga of self-control, lit by Knowledge.'),
('2c7f6b79-0975-5b68-b479-162928aa22d2'::uuid, '72692d8c-3f9a-5902-80b7-da86df99965c'::uuid, 'sivananda', 'english', 'Others again sacrifice all the functions of the senses and those of the breath (vital energy, or Prana) in the fire of the Yoga of self-restraint, kindled by knowledge.'),
('710e2add-351b-59a8-9db9-1e6a2648d07c'::uuid, '9184e73e-fc34-5504-8f17-4873c2b4e7af'::uuid, 'gambhirananda', 'english', 'Similarly, others are performers of sacrifices through wealth, through austerity, through yoga, and through study and knowledge; others are ascetics with severe vows.'),
('e14eee81-c9e3-5963-8142-771fb13429d2'::uuid, '9184e73e-fc34-5504-8f17-4873c2b4e7af'::uuid, 'sivananda', 'english', 'Others again offer wealth, austerity, and Yoga as sacrifice, while ascetics of self-restraint and rigid vows offer the study of scriptures and knowledge as sacrifice.'),
('0024aef3-4722-5050-8f5f-8c28c7340a1c'::uuid, '7022a1c2-a13e-5e73-9993-43cbe12bbc39'::uuid, 'gambhirananda', 'english', 'Constantly practicing control of the vital forces by stopping the movements of the outgoing and incoming breaths, some offer as a sacrifice the outgoing breath into the incoming breath; while still others, the incoming breath into the outgoing breath.'),
('6d9addb6-d2c6-5e0d-a790-eb465860f7bd'::uuid, '7022a1c2-a13e-5e73-9993-43cbe12bbc39'::uuid, 'sivananda', 'english', 'Others offer as sacrifice the outgoing breath into the incoming, and the incoming into the outgoing, restraining the flow of the outgoing and the incoming breaths, solely absorbed in the restraint of the breath.'),
('b4576e4e-c635-576c-9172-5440a381cce2'::uuid, 'c2611989-3b6e-53c4-9989-f827000e5004'::uuid, 'gambhirananda', 'english', 'Others, having their food regulated, offer the vital forces in the vital forces. All of them are knowers of the sacrifice and have their sins destroyed by the sacrifice.'),
('6e55da20-c4b6-549c-b246-b044749dece3'::uuid, 'c2611989-3b6e-53c4-9989-f827000e5004'::uuid, 'sivananda', 'english', 'Others who regulate their diet offer life-breaths in each life-breath. All these are knowers of sacrifice, whose sins are destroyed through sacrifice.'),
('5033ccdf-a1ed-56a8-b026-708f6c7aec22'::uuid, '9f0fd21e-56a6-5418-8b24-da01d8de5f39'::uuid, 'gambhirananda', 'english', 'Those who partake of the nectar left over after a sacrifice reach the eternal Brahman. This world ceases to exist for one who does not perform sacrifices; what, then, to speak of the other world, O best among the Kurus (Arjuna)!'),
('44dffbeb-9e53-53e4-a531-c313890116bb'::uuid, '9f0fd21e-56a6-5418-8b24-da01d8de5f39'::uuid, 'sivananda', 'english', 'Those who eat the remnants of the sacrifice, which are like nectar, go to the eternal Brahman. This world is not for the one who does not perform sacrifice; how then can they have the other, O Arjuna?'),
('e7284d6a-9df0-5366-b7d8-902c993e0d43'::uuid, '06e9020f-ce3e-51b2-8c7c-712f40d199ad'::uuid, 'gambhirananda', 'english', 'Thus, various kinds of sacrifices are spread at the mouth of the Vedas. Know them all to be born of action. Knowing this, you will become liberated.'),
('30de610e-16c6-57f8-844e-6e5e2ce2d986'::uuid, '06e9020f-ce3e-51b2-8c7c-712f40d199ad'::uuid, 'sivananda', 'english', 'Thus, manifold sacrifices are spread out before Brahman at the face of Brahman. Know them all to be born of action, and thus knowing, you shall be liberated.'),
('9f8429c9-84a0-5c33-832c-3200ccf3ae3a'::uuid, 'ca89e9f8-4826-59b8-9d7c-6b7c24b0078e'::uuid, 'gambhirananda', 'english', 'O destroyer of enemies, knowledge considered as a sacrifice is greater than sacrifices requiring materials. O son of Prtha, all actions in their totality culminate in knowledge.'),
('3d1968eb-db7b-546e-b27d-c1398032f7ae'::uuid, 'ca89e9f8-4826-59b8-9d7c-6b7c24b0078e'::uuid, 'sivananda', 'english', 'Superior is wisdom-sacrifice to the sacrifice with objects, O Parantapa (scorcher of the foes). All actions in their entirety, O Arjuna, culminate in knowledge.'),
('29eb3ba6-7403-5626-baf7-8eaee09e456b'::uuid, '78099d40-23f3-5cc3-a699-9d0c715e5be9'::uuid, 'gambhirananda', 'english', 'Know that the wise ones who have realized the Truth will impart the Knowledge to you through prostration, inquiry, and service.'),
('07cc7b74-720d-5987-8bfe-3ccfd6d34860'::uuid, '78099d40-23f3-5cc3-a699-9d0c715e5be9'::uuid, 'sivananda', 'english', 'Know that the wise who have realized the truth will instruct thee in that knowledge through long prostration, supplication, and service.'),
('5c0792d7-a206-5b2f-8f8b-4801bddfa227'::uuid, '35475557-6f1f-52d3-bceb-e87eb3e21f08'::uuid, 'gambhirananda', 'english', 'Knowing this, O Pandava, you will not be deluded again in this way, and through it, you will see all beings, without exception, in the Self and also in Me.'),
('aae2dbe8-f1b7-5501-9017-51b89fa3ef32'::uuid, '35475557-6f1f-52d3-bceb-e87eb3e21f08'::uuid, 'sivananda', 'english', 'Knowing that thou shalt not, O Arjuna, again be deluded like this; and by that thou shalt see all beings in thyself and also in me.'),
('12aa4936-978f-52f8-b311-6cc9427cfe96'::uuid, '807330e6-c4f2-501e-95dd-7a8f16ceaa35'::uuid, 'gambhirananda', 'english', 'Even if you are the worst sinner among all sinners, you can still cross over all wickedness with the raft of Knowledge alone.'),
('c7d951f8-499a-5906-8f35-8109f212a6fe'::uuid, '807330e6-c4f2-501e-95dd-7a8f16ceaa35'::uuid, 'sivananda', 'english', 'Even if thou art the most sinful of all sinners, yet thou shalt surely cross over all sins by the raft of knowledge.'),
('201dcbf6-633a-5593-a063-ae33e2b7f2f4'::uuid, 'b007c082-879b-54b7-9e6e-837da9dd19f4'::uuid, 'gambhirananda', 'english', 'O Arjuna, just as a blazing fire reduces wood to ashes, similarly the fire of Knowledge reduces all actions to ashes.'),
('eb295f26-8d81-5386-8211-b03f5ab3abf2'::uuid, 'b007c082-879b-54b7-9e6e-837da9dd19f4'::uuid, 'sivananda', 'english', 'As the blazing fire reduces fuel to ashes, O Arjuna, so does the fire of knowledge reduce all actions to ash.'),
('abf66959-4f86-5e3d-b40f-c7c0bb444941'::uuid, '8bcec931-e765-587d-8aff-36369bd1b5d6'::uuid, 'gambhirananda', 'english', 'Indeed, there is nothing purifying here comparable to Knowledge. One who has become perfected over time through yoga, realizes That in their own heart.'),
('0735046e-df93-522d-a9f8-af1e3608f8cb'::uuid, '8bcec931-e765-587d-8aff-36369bd1b5d6'::uuid, 'sivananda', 'english', 'Verily, there is no purifier in this world like knowledge. He who is perfected in Yoga finds it within the Self in due time.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('66ce9286-b050-5d68-8cfc-2b08fb46ab94'::uuid, '929471c5-5cd7-554f-999c-3dd3cc1a041e'::uuid, 'gambhirananda', 'english', 'The one who has faith, is diligent, and has control over their organs, attains Knowledge. Achieving Knowledge, one soon attains supreme Peace.'),
('77cf05d1-43f1-57f4-9a3f-7fa779b58a40'::uuid, '929471c5-5cd7-554f-999c-3dd3cc1a041e'::uuid, 'sivananda', 'english', 'The one who is full of faith, devoted to it, and has subdued their senses obtains this knowledge; and upon obtaining the knowledge, they attain the supreme peace immediately.'),
('8a56e388-64bc-563d-94a6-393dbbf4fe60'::uuid, '939bac97-0ce4-51bb-a5e9-0b2a669eea51'::uuid, 'gambhirananda', 'english', 'One who is ignorant and faithless, and has a doubting mind, perishes. Neither this world nor the next, nor happiness, exists for one who has a doubting mind.'),
('ed0dc9d8-3559-5bfd-a3d3-8683c382bdbc'::uuid, '939bac97-0ce4-51bb-a5e9-0b2a669eea51'::uuid, 'sivananda', 'english', 'The ignorant, the faithless, and the doubting self go to destruction; there is neither this world nor the other, nor happiness for the doubting one.'),
('839a596a-98e6-5c5f-9b06-7843960ee7c0'::uuid, '1ddda8f6-3172-5749-83ed-9cf594fb9c4d'::uuid, 'gambhirananda', 'english', 'O Dhananjaya (Arjuna), actions do not bind one who has renounced actions through yoga, whose doubts have been fully dispelled by Knowledge, and who is not inattentive.'),
('c3e52ae6-67e5-54e2-845b-81a465501bf1'::uuid, '1ddda8f6-3172-5749-83ed-9cf594fb9c4d'::uuid, 'sivananda', 'english', 'He who has renounced actions through Yoga, whose doubts have been dispelled by knowledge, and who is self-possessed—such a one is not bound by actions, O Arjuna.'),
('28cfcbd5-1b6e-5d68-9ed5-a6c3879a651d'::uuid, '5678cecb-0ad5-592a-bce6-67ff1f34755b'::uuid, 'gambhirananda', 'english', 'Therefore, O scion of the Bharata dynasty, take recourse to yoga and rise up, cutting asunder with the sword of knowledge this doubt in your heart, arising from ignorance.'),
('4b703b6d-6475-5daa-ad89-5b86ee182ec1'::uuid, '5678cecb-0ad5-592a-bce6-67ff1f34755b'::uuid, 'sivananda', 'english', 'Therefore, with the sword of knowledge (of the Self), cut asunder the doubt of the self, born of ignorance, residing in your heart, and take refuge in Yoga. Arise, O Arjuna!'),
('38b1f921-fddf-548f-8115-732ed11566ed'::uuid, '88f4d63b-a852-5707-bc0b-f9c1ed0d7c0c'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Krsna, you praise renunciation of actions and, at the same time, Karma-yoga. Please tell me for certain which one is better between these two."'),
('4048154a-a81f-5af5-ac04-019a5e5e8a7e'::uuid, '88f4d63b-a852-5707-bc0b-f9c1ed0d7c0c'::uuid, 'sivananda', 'english', 'Arjuna said, "O Krishna, you praise renunciation of actions and also yoga. Please tell me conclusively which is better of the two."'),
('277d88da-acff-596e-86b3-df19cba5e24d'::uuid, '6d8df0dd-5159-5002-bf70-97e4fa98808d'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "Both renunciation of actions and Karma-yoga lead to liberation; however, Karma-yoga excels over renunciation of actions."'),
('462d4ab4-73e3-5590-a20a-e413436b014b'::uuid, '6d8df0dd-5159-5002-bf70-97e4fa98808d'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "Renunciation and the Yoga of action both lead to the highest bliss; but of the two, the Yoga of action is superior to the renunciation of action."'),
('7e7995dd-cf0e-5bf0-822a-d8043119b82d'::uuid, 'f655713a-0a3a-5cb5-aa91-07bc0a0b076f'::uuid, 'gambhirananda', 'english', 'He who neither hates nor craves should be known as a man of constant renunciation.'),
('6a079f2b-2f8d-5c6f-8c93-c22b63a58807'::uuid, 'f655713a-0a3a-5cb5-aa91-07bc0a0b076f'::uuid, 'sivananda', 'english', 'He should be known as a perpetual Sannyasi who neither hates nor desires; for, free from the pairs of opposites, O mighty-armed Arjuna, he is easily freed from bondage.'),
('1f463c61-25cf-51e6-aee5-9b3dd3029863'::uuid, '2931a370-49a7-5de0-a3e3-17427394a2b0'::uuid, 'gambhirananda', 'english', 'The fools, not the learned ones, speak of Sankhya and (Karma-) yoga as being different. Anyone who properly resorts to either one of them gets the results of both.'),
('92d0f85a-dda7-54d4-b4b2-8715acd94a54'::uuid, '2931a370-49a7-5de0-a3e3-17427394a2b0'::uuid, 'sivananda', 'english', 'Children, not the wise, speak of knowledge and the Yoga of action, or the performance of action, as though they are distinct and different; he who is truly established in one, obtains the fruits of both.'),
('36ea3465-6079-51a8-adb1-3828dddc0193'::uuid, '83bca8da-0437-5180-9274-1511fad6b9a2'::uuid, 'gambhirananda', 'english', 'The state that is reached by the Sankhyas, and that is also reached by the yogis, is seen by one who sees Sankhya and yoga as one.'),
('80cbc48a-9c33-565e-85d4-a9f60731e1d8'::uuid, '83bca8da-0437-5180-9274-1511fad6b9a2'::uuid, 'sivananda', 'english', 'That place which is reached by the Sankhyas or the Jnanis is also reached by the Yogis (Karma Yogis). He who sees knowledge and the performance of action (Karma Yoga) as one, sees truly.'),
('3d6f5e85-778f-5b8a-9c0c-1c81c5b8fbdb'::uuid, 'd606c05f-ad99-5ded-9efa-883cc09de097'::uuid, 'gambhirananda', 'english', 'But, O mighty-armed one, renunciation is hard to attain without (Karma-) yoga. The meditative man equipped with yoga attains Brahman without delay.'),
('bcca5516-10ea-573b-953c-769677f995ee'::uuid, 'd606c05f-ad99-5ded-9efa-883cc09de097'::uuid, 'sivananda', 'english', 'But, O mighty-armed Arjuna, renunciation is hard to attain without Yoga; the sage who is in harmony with Yoga quickly goes to Brahman.'),
('bee978a5-9389-5a3e-9107-25491e4eb1f4'::uuid, '106aff34-3def-560a-8582-65ef9fb1d2ca'::uuid, 'gambhirananda', 'english', 'Endowed with yoga, pure in mind, controlled in body, a conqueror of the organs, the Self of the selves of all beings—he does not become tainted even while performing actions. When this person resorts to nitya and naimittika rites and duties as a means to the achievement of full illumination, and thus becomes fully enlightened, then, even when he acts through the apparent functions of the mind, organs, etc., he does not become affected.'),
('20eb4dcd-a6ea-5160-9d64-117f058430ea'::uuid, '106aff34-3def-560a-8582-65ef9fb1d2ca'::uuid, 'sivananda', 'english', 'He who is devoted to the path of action, whose mind is pure, who has conquered the self, who has subdued his senses, and who realizes his Self as the Self in all beings, though acting, is not tainted.'),
('f29b930e-bdc6-5efd-98b4-c9905bc83d6d'::uuid, '12b34c1a-6b73-5d37-9344-a19d3850f08a'::uuid, 'gambhirananda', 'english', '- Remaining absorbed in the Self, the knower of Reality should think, ''I certainly do not do anything'', even while seeing, hearing, touching, smelling, eating, moving, sleeping, breathing, speaking, releasing, holding, opening, and closing the eyes—remembering that the organs function in relation to the objects of the organs.'),
('6b1ee5fe-85ff-5352-86f6-85bde4d4c837'::uuid, '12b34c1a-6b73-5d37-9344-a19d3850f08a'::uuid, 'sivananda', 'english', 'I do nothing at all," thus would the harmonized knower of Truth think, seeing, hearing, touching, smelling, eating, going, sleeping, and breathing.'),
('1acd9a82-97c2-53e7-a82d-21d500e78ff4'::uuid, '73bffac7-e17a-57aa-860d-7c08511d7b0c'::uuid, 'gambhirananda', 'english', '- Remaining absorbed in the Self, the knower of Reality should think, ''I certainly do not do anything'', even while seeing, hearing, touching, smelling, eating, moving, sleeping, breathing, speaking, releasing, holding, opening, and closing the eyes—remembering that the organs function in relation to the objects of the organs.'),
('e3011e74-8636-5367-9a4a-592071244eb6'::uuid, '73bffac7-e17a-57aa-860d-7c08511d7b0c'::uuid, 'sivananda', 'english', 'Speaking, letting go, seizing, opening, and closing the eyes, one should be convinced that the senses move among the sense-objects.'),
('20e18fbb-9244-50ed-9360-1d6a9e3a8226'::uuid, '9673c10a-f5d5-5191-9c94-5966c2bb7e43'::uuid, 'gambhirananda', 'english', 'One who acts by dedicating their actions to Brahman and by renouncing attachment, they do not become polluted by sin, just as a lotus leaf is not by water.'),
('a7f2583f-f6ca-5439-ad2b-724935eec68c'::uuid, '9673c10a-f5d5-5191-9c94-5966c2bb7e43'::uuid, 'sivananda', 'english', 'He who does actions, offering them to Brahman and abandoning attachment, is not tainted by sin, just as a lotus leaf is not tainted by water.'),
('a6bff09a-24a0-5c46-9b45-f1524d0690ab'::uuid, '74bd969b-e672-5bd7-b84d-3011028aa3e1'::uuid, 'gambhirananda', 'english', 'By giving up attachment, the yogis undertake work solely through the body, mind, intellect, and even the organs, for their own purification.'),
('346b330d-a053-549b-87f8-395813a8191d'::uuid, '74bd969b-e672-5bd7-b84d-3011028aa3e1'::uuid, 'sivananda', 'english', 'Yogis, having abandoned attachment, perform actions only through the body, mind, intellect, and even the senses, for the purification of the self.'),
('8d8263d8-1ca2-5d41-97e5-604aacb9843e'::uuid, 'aeecaaad-b559-5646-a1d3-223424f083c4'::uuid, 'gambhirananda', 'english', 'Giving up the results of work by becoming resolute in faith, one attains peace arising from steadfastness. One who is lacking in resolute faith, being attached to the results under the impulse of desire, becomes bound.'),
('b0408647-aafa-5f02-8d6a-7919d5db55ff'::uuid, 'aeecaaad-b559-5646-a1d3-223424f083c4'::uuid, 'sivananda', 'english', 'The one who is united (the well-poised or harmonized) having abandoned the fruit of action attains eternal peace; whereas the one who is not united (the unsteady or unbalanced), impelled by desire and attached to the fruit, is bound.'),
('cf3e934f-0521-5b10-a255-ca69c5834568'::uuid, 'e18dcd79-638e-5289-a871-cd53654cfd82'::uuid, 'gambhirananda', 'english', 'The embodied man of self-control, having given up all actions mentally, continues happily in the city of nine gates, without doing or causing anyone else to do anything.'),
('31379336-4461-58e1-ae0f-b4a47677b002'::uuid, 'e18dcd79-638e-5289-a871-cd53654cfd82'::uuid, 'sivananda', 'english', 'Mentally renouncing all actions and being self-controlled, the embodied one happily rests in the nine-gated city, neither acting nor causing others (body and senses) to act.'),
('a122547b-4380-5d8c-9fed-a052dfc89fac'::uuid, 'a0cd9f97-0972-5fd6-8e4b-08c0b8bfe688'::uuid, 'gambhirananda', 'english', 'The Self does not create agency or any objects of desire for anyone, nor does it associate with the results of actions; rather, it is Nature that acts.'),
('8f330b17-4714-5518-8be6-56d2ccb6ec56'::uuid, 'a0cd9f97-0972-5fd6-8e4b-08c0b8bfe688'::uuid, 'sivananda', 'english', 'Neither does the Lord create agency nor actions for the world, nor union with the fruits of actions; rather, it is Nature that acts.'),
('cd566b0f-7338-5139-beea-9d1ed801af36'::uuid, 'b1c614d1-62aa-56e0-a81a-49b8b7e9f6ab'::uuid, 'gambhirananda', 'english', 'The Omnipresent neither accepts anyone''s sin nor even virtue; knowledge remains covered by ignorance, thus the creatures become deluded.'),
('92dbde8e-dc56-5f82-86b9-f048c2de24cd'::uuid, 'b1c614d1-62aa-56e0-a81a-49b8b7e9f6ab'::uuid, 'sivananda', 'english', 'The Lord takes neither the demerit nor the merit of any; knowledge is enveloped by ignorance, and beings are deluded.'),
('27115819-3a1f-5105-a048-9d99e5f3bec3'::uuid, 'c43cb171-1e2c-54ae-b567-5f768543c49c'::uuid, 'gambhirananda', 'english', 'But in the case of those whose ignorance is destroyed by knowledge (of the Self), their knowledge, like the sun, reveals that supreme Reality.'),
('6a136809-1a9f-53da-85d5-71712133608c'::uuid, 'c43cb171-1e2c-54ae-b567-5f768543c49c'::uuid, 'sivananda', 'english', 'But to those whose ignorance is destroyed by knowledge of the Self, like the sun, knowledge reveals the Supreme Brahman.'),
('139c6775-63b3-5465-a282-e350544e5fa8'::uuid, '81460644-56a1-55ec-a4c7-1ef46e137b3c'::uuid, 'gambhirananda', 'english', 'Those whose intellect is absorbed in That, whose Self is That, who are steadfast in That, and who have That as their supreme Goal—they attain the state of non-returning, their impurities having been removed by Knowledge.'),
('0d8be277-1dac-5013-b150-cd384d7aaf25'::uuid, '81460644-56a1-55ec-a4c7-1ef46e137b3c'::uuid, 'sivananda', 'english', 'Their intellect absorbed in That, their self being That, established in That, with That as their supreme goal, they go whence there is no return, their sins dispelled by knowledge.'),
('12483298-616f-5996-8688-4391df85dd50'::uuid, '60d4f4f7-0f08-51e9-8c73-206e7ea48bfe'::uuid, 'gambhirananda', 'english', 'The learned ones look with equanimity on a Brahmana endowed with learning and humility, a cow, an elephant, and even a dog, as well as one who eats dog meat.'),
('de0f108d-4248-591e-87ab-262a00b9ace4'::uuid, '60d4f4f7-0f08-51e9-8c73-206e7ea48bfe'::uuid, 'sivananda', 'english', 'Sages look with an equal eye on a Brahmana endowed with learning and humility, on a cow, an elephant, a dog, and even an outcaste.'),
('af6e7db1-fde1-5697-80f0-75713691afcb'::uuid, 'c55d2e32-cfa3-508e-b624-eb3adea5d69f'::uuid, 'gambhirananda', 'english', 'Here itself is mirth attained by those whose minds are established in sameness. Since Brahman is the same in all and free from defects, they are established in Brahman.'),
('b3e40a5b-bc9c-52d7-9ded-158dc9cdef74'::uuid, 'c55d2e32-cfa3-508e-b624-eb3adea5d69f'::uuid, 'sivananda', 'english', 'Even here in this world, those whose minds rest in reality overcome birth; Brahman is indeed spotless and real; therefore they are established in Brahman.'),
('e56a11f5-4fa8-5074-ae56-7c57c226a46a'::uuid, '11d5bf6f-c012-5737-84fe-adadfc2a9841'::uuid, 'gambhirananda', 'english', 'A knower of Brahman, who is established in Brahman, should have their intellect steady and should not be deluded. They should not get delighted by getting what is desirable, nor become dejected by getting what is undesirable.'),
('2cab2fbf-63ea-5741-ba88-4eab4b8a8657'::uuid, '11d5bf6f-c012-5737-84fe-adadfc2a9841'::uuid, 'sivananda', 'english', 'Resting in Brahman, with a steady intellect and undeluded, the knower of Brahman neither rejoices upon obtaining what is pleasant nor grieves upon obtaining what is unpleasant.'),
('31930883-1041-5554-9bd0-ec6fafff0862'::uuid, '31b4cea4-4406-5adc-8790-6fd1e215b3d7'::uuid, 'gambhirananda', 'english', 'With his heart unattached to external objects, he gets the bliss that is in the Self. With his heart absorbed in meditation on Brahman, he acquires undying Bliss.'),
('07f11cc9-8c10-589e-9adb-5555c61cb63d'::uuid, '31b4cea4-4406-5adc-8790-6fd1e215b3d7'::uuid, 'sivananda', 'english', 'With the self unattached to external contacts, he finds happiness in the Self; with the self engaged in the meditation of Brahman, he attains endless happiness.'),
('10ed54f8-12df-5c53-8e91-cec3c9004da5'::uuid, '529b2022-6c47-5fa1-a58e-0cf3882b509d'::uuid, 'gambhirananda', 'english', 'Since enjoyments that result from contact with objects are indeed the sources of sorrow, having a beginning and an end, O son of Kunti, the wise one does not delight in them.'),
('c14f7ced-73b2-50ac-92b5-0ef5a6240a2c'::uuid, '529b2022-6c47-5fa1-a58e-0cf3882b509d'::uuid, 'sivananda', 'english', 'The enjoyments that arise from contact are only sources of pain, for they have a beginning and an end, O Arjuna; the wise do not rejoice in them.'),
('8cc04b48-8cd1-5cd3-8fea-7588096d4e5c'::uuid, '1f28dbbf-1d29-5042-bba7-93a4ac3bc8bc'::uuid, 'gambhirananda', 'english', 'One who can withstand here itself, before departing from the body, the impulse arising from desire and anger, that person is a yogi; they are happy.'),
('3e4b7b68-69df-55d3-bc8e-3d83ca26ef45'::uuid, '1f28dbbf-1d29-5042-bba7-93a4ac3bc8bc'::uuid, 'sivananda', 'english', 'He who is able, while still here in this world, to withstand the impulse born out of desire and anger before the liberation from the body, he is a Yogi, and he is a happy man.'),
('4f8c2e00-dc9c-5889-8763-0be3e61e646a'::uuid, 'b710e44d-77bd-5428-9bc3-0a376e233f3c'::uuid, 'gambhirananda', 'english', 'One who is content within, whose pleasure is within, and whose light is only within, that yogi, having become Brahman, attains absorption into Brahman.'),
('1eb54a2f-36b4-5cda-a9bd-e7517b07912a'::uuid, 'b710e44d-77bd-5428-9bc3-0a376e233f3c'::uuid, 'sivananda', 'english', 'He who is happy within, who rejoices within, and who is illuminated within, that Yogi attains absolute freedom, or Moksha, becoming Brahman himself.'),
('a8394b83-27ff-55be-a671-e6c3d4891193'::uuid, '7c8e84c8-a1d3-54cc-b52b-99fe9e0e2875'::uuid, 'gambhirananda', 'english', 'The seers whose sins have been attenuated, who are free from doubt, whose senses are under control, who are engaged in doing good to all beings, attain absorption in Brahman.'),
('dbe5528f-e6cb-5ba5-852c-0691f3827325'::uuid, '7c8e84c8-a1d3-54cc-b52b-99fe9e0e2875'::uuid, 'sivananda', 'english', 'The sages obtain absolute freedom or Moksha when their sins have been destroyed, their dualities have been torn asunder, they are self-controlled, and they are intent on the welfare of all beings.'),
('612cd232-b2f8-5a0f-86ba-1d93cab87276'::uuid, '8d38c1ba-87cf-567d-840a-f33720be0df7'::uuid, 'gambhirananda', 'english', 'To those monks who have control over their internal organs, who are free from desire and anger, who have known the Self, there is absorption into Brahman either way.'),
('dbe18808-d1dc-5440-baf0-fb057deecb6e'::uuid, '8d38c1ba-87cf-567d-840a-f33720be0df7'::uuid, 'sivananda', 'english', 'Absolute freedom exists on all sides for those self-controlled ascetics who are free from desire and anger, who have controlled their thoughts, and who have realized the Self.'),
('750045de-8cd2-590c-95a6-5dfca4c75561'::uuid, '1d69920b-0742-5f35-b0e8-4c22499d3ecd'::uuid, 'gambhirananda', 'english', '- Keeping external objects outside, fixing the eyes at the juncture of the eye-brows, and controlling the outgoing and incoming breaths that move through the nostrils, the contemplative who has mastery over his organs, mind, and intellect should be fully intent on Liberation and free from desire, fear, and anger. He who is ever thus is verily free.'),
('737548ab-7f26-5cb0-aabe-e0fcf2ba5b8a'::uuid, '1d69920b-0742-5f35-b0e8-4c22499d3ecd'::uuid, 'sivananda', 'english', 'Shutting out all external contacts and fixing the gaze between the eyebrows, realizing the outgoing and incoming breaths moving within the nostrils.'),
('e03b3bfa-329f-59ed-8f2c-aa11ab78d517'::uuid, 'e6ba17fb-83ba-58dc-a5ff-37987d0fd908'::uuid, 'gambhirananda', 'english', '- Keeping external objects outside, fixing the eyes at the juncture of the eye-brows, and controlling the outgoing and incoming breaths that move through the nostrils, the contemplative who has mastery over his organs, mind, and intellect should be fully intent on Liberation and free from desire, fear, and anger. He who is ever thus is verily free.'),
('0e553357-5f3f-5a13-88dc-1ec85015955f'::uuid, 'e6ba17fb-83ba-58dc-a5ff-37987d0fd908'::uuid, 'sivananda', 'english', 'With the senses, mind, and intellect ever controlled, having liberation as their supreme goal, free from desire, fear, and anger, the sage is truly liberated forever.'),
('83af78f2-62e3-5bcc-af87-0189a9c5a9c6'::uuid, '4d1ae98b-bc01-59fd-b45c-3243afdab166'::uuid, 'gambhirananda', 'english', 'One attains peace by knowing Me, who am the great Lord of all the worlds, the enjoyer of sacrifices and austerities, and the friend of all creatures.'),
('aadf5c99-e31a-5b85-80c5-d8608c3682e5'::uuid, '4d1ae98b-bc01-59fd-b45c-3243afdab166'::uuid, 'sivananda', 'english', 'He who knows Me as the enjoyer of sacrifices and austerities, the great Lord of all the worlds, and the friend of all beings, attains peace.'),
('21ca9a35-1543-5d63-a331-7fdc94da3a1f'::uuid, '864cc8d0-15d0-5a2a-8284-8b135cf8bcdd'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "He who performs an action which is his duty, without depending on the result of the action, is a monk and a yogi; not so in he who does not keep afire and is actionless."'),
('9e34f6e0-b854-5c9f-b1f2-fa8564722283'::uuid, '864cc8d0-15d0-5a2a-8284-8b135cf8bcdd'::uuid, 'sivananda', 'english', 'The Blessed Lord said: He who performs his bounden duty without depending on the fruits of his actions—he is a sannyasi and a yogi, not he who is without fire and without action.'),
('b61b9eeb-33cd-538e-b33f-9dad7b798f82'::uuid, '0e8ed7c9-b3af-5d30-92f2-0a53e163acf5'::uuid, 'gambhirananda', 'english', 'That which they call monasticism, know that to be Yoga, O Pandava, for nobody who has not given up expectations can be a yogi.'),
('67d8b5cf-0169-519e-88a6-40aa739e2aa9'::uuid, '0e8ed7c9-b3af-5d30-92f2-0a53e163acf5'::uuid, 'sivananda', 'english', 'Do you, O Arjuna, know that Yoga is what they call renunciation; no one indeed becomes a Yogi who has not renounced their thoughts.'),
('a2322c1b-19f3-5075-99f3-27d7f611f895'::uuid, 'f60c0376-e228-5e81-af7f-a5dddf436e75'::uuid, 'gambhirananda', 'english', 'For the sage who wishes to ascend to (Dhyana-) yoga, action is said to be the means. For that person, once he has ascended to (Dhyana-)yoga, inaction alone is said to be the means.'),
('ff1929f7-88d4-521e-b965-256c1ec51ce5'::uuid, 'f60c0376-e228-5e81-af7f-a5dddf436e75'::uuid, 'sivananda', 'english', 'For a sage who wishes to attain to Yoga, action is said to be the means; for the same sage who has attained Yoga, inaction is said to be the means.'),
('8256935e-9cc9-5d58-ae2a-fe3868f460c6'::uuid, '5f1c5aad-0792-5748-84c2-872edbe85785'::uuid, 'gambhirananda', 'english', 'Verily, when a man who has given up thought about everything does not get attached to sense-objects or actions, he is then said to be established in Yoga.'),
('a6f42e86-8d8c-58e3-9bd3-de249fdaec8c'::uuid, '5f1c5aad-0792-5748-84c2-872edbe85785'::uuid, 'sivananda', 'english', 'When a person is not attached to the sense-objects or to actions, having renounced all thoughts, then they are said to have attained Yoga.'),
('07ad0caa-8ac3-5a86-8cb6-83bd9b92ba48'::uuid, '8a32a1b6-0601-5909-bffc-40b00a4a12ec'::uuid, 'gambhirananda', 'english', 'One should save oneself by oneself; one should not degrade oneself. For oneself is indeed one''s own friend; oneself is indeed one''s own enemy.'),
('fea40994-3878-59a1-a247-9273ff243f43'::uuid, '8a32a1b6-0601-5909-bffc-40b00a4a12ec'::uuid, 'sivananda', 'english', 'One should raise oneself by one''s own self alone; let not one lower oneself; for the self alone is one''s own friend, and the self alone is one''s own enemy.'),
('971483e4-f9e4-5525-9785-521198a7a5e3'::uuid, '45aa7457-b6e9-5e06-a8c4-08222d237067'::uuid, 'gambhirananda', 'english', 'He who has conquered his own self by the self, his self is his own friend. But for one who has not conquered his own self, his self itself acts like an enemy.'),
('36d2ff49-d734-550a-b7c1-f5ec96e65783'::uuid, '45aa7457-b6e9-5e06-a8c4-08222d237067'::uuid, 'sivananda', 'english', 'The Self is the friend of the self of him by whom the Self has been conquered; but to the unconquered self, this Self stands in the position of an enemy, like an external foe.'),
('6acdd4a7-61b7-5d81-8173-b8b822ff1c50'::uuid, '317f9788-47c0-558d-91ab-cb75b8a47d34'::uuid, 'gambhirananda', 'english', 'The supreme Self of one who has control over the aggregate of his body and organs, and who is tranquil, becomes manifest. He should be poised in the midst of cold and heat, happiness and sorrow, as well as honor and dishonor.'),
('72ff038a-2b83-5aa8-8ae6-21a429fe28ee'::uuid, '317f9788-47c0-558d-91ab-cb75b8a47d34'::uuid, 'sivananda', 'english', 'The Supreme Self of him who is self-controlled and peaceful remains balanced in cold and heat, pleasure and pain, as well as in honor and dishonor.'),
('b12c2f7d-3092-5d3f-a2ad-7892699f3cb7'::uuid, 'ec9f2e90-33eb-548d-bea8-18ce2e9b5d10'::uuid, 'gambhirananda', 'english', 'One whose mind is satisfied with knowledge and realization, who is unmoved, who has his organs under control, is said to be Self-absorbed. The yogi treats all alike, a lump of earth, a stone, and gold.'),
('942835ad-6916-5f8e-8593-ce7999c59904'::uuid, 'ec9f2e90-33eb-548d-bea8-18ce2e9b5d10'::uuid, 'sivananda', 'english', 'The Yogi who is satisfied with the knowledge and wisdom of the Self, who has conquered the senses, and to whom a clod of earth, a piece of stone, and gold are all the same, is said to have attained Nirvikalpa Samadhi.'),
('d530cc33-20c0-5d3a-8c14-4006b7352cb0'::uuid, '2d87ad62-9496-5fe9-bd7f-1d54acc8dd10'::uuid, 'gambhirananda', 'english', 'He excels who has sameness of view with regard to a benefactor, a friend, an enemy, a neutral, an arbiter, the hateful, a relative, good people, and even sinners.'),
('84e1e133-d662-593a-9f11-0a869993b63a'::uuid, '2d87ad62-9496-5fe9-bd7f-1d54acc8dd10'::uuid, 'sivananda', 'english', 'He who is of the same mind towards the good-hearted, friends, enemies, the indifferent, the neutral, the hateful, the relatives, the righteous, and the unrighteous, excels.'),
('a3a298ff-d66d-5183-8a0d-c91223b89161'::uuid, 'b690b975-ea06-5027-b3af-7f6afbeba90f'::uuid, 'gambhirananda', 'english', 'A yogi should constantly concentrate his mind by staying in a solitary place, alone, with mind and body controlled, free from expectations, and free from acquisition.'),
('1dc071b8-e1a3-5e1c-8abd-e978b1cc4798'::uuid, 'b690b975-ea06-5027-b3af-7f6afbeba90f'::uuid, 'sivananda', 'english', 'Let the yogi constantly strive to keep the mind steady, remaining in solitude, alone, with the body and mind controlled, and free from hope and greed.'),
('c328c09e-4cd8-59d6-a591-27bdb171a6d5'::uuid, '4d9b3f97-da7a-5e71-a4d4-9d6263238e9f'::uuid, 'gambhirananda', 'english', 'Having firmly established in a clean place his seat, neither too high nor too low, composed of cloth, skin, and kusa-grass placed successively one below the other;'),
('edeaa1e0-5446-533c-9f55-4f0d479ccfc4'::uuid, '4d9b3f97-da7a-5e71-a4d4-9d6263238e9f'::uuid, 'sivananda', 'english', 'In a clean spot, having established a firm seat of his own, neither too high nor too low, made of cloth, skin, and kusha grass layered one over the other.'),
('60667865-a2a4-530b-8f8f-36d0d8eb7078'::uuid, 'ab1fa93d-b564-5961-9051-e807bdb7cdfe'::uuid, 'gambhirananda', 'english', 'Sitting on that seat, he should concentrate his mind for the purification of the internal organ, making the mind one-pointed and keeping the actions of the mind and senses under control.'),
('abb27be0-14d3-5f66-87a1-3a37604e8748'::uuid, 'ab1fa93d-b564-5961-9051-e807bdb7cdfe'::uuid, 'sivananda', 'english', 'There, having made the mind one-pointed, with the actions of the mind and senses controlled, let him, seated on the seat, practice Yoga for the purification of the self.'),
('f697ec23-c108-5d9b-a781-5dc9962ad560'::uuid, '8c40219d-a0c1-5019-8ab1-b65eb51e6af2'::uuid, 'gambhirananda', 'english', 'Holding the body, head, and neck erect and still, being steady, looking at the tip of his own nose and not looking around.'),
('7b375f63-9aa3-5e4b-bc71-f025654ff876'::uuid, '8c40219d-a0c1-5019-8ab1-b65eb51e6af2'::uuid, 'sivananda', 'english', 'Let him firmly hold his body, head, and neck erect and still, gazing at the tip of his nose without looking around.'),
('af658ae1-7779-5ccd-9260-8dd62925c6ca'::uuid, '899b7c59-072f-54dc-afdf-66ae22c9f133'::uuid, 'gambhirananda', 'english', 'He should remain seated with a placid mind, free from fear, firm in the vow of celibacy, and with the mind fixed on Me by controlling it through concentration, having Me as the supreme goal.'),
('e0e27b44-b321-5797-a196-1fcf7cc4b3d9'::uuid, '899b7c59-072f-54dc-afdf-66ae22c9f133'::uuid, 'sivananda', 'english', 'Serene-minded, fearless, firm in the vow of a Brahmachari, having controlled their mind, thinking of Me and balanced in mind, let them sit, having Me as their supreme goal.'),
('17660d26-3633-57e0-b762-5fc314a251c1'::uuid, '3f36ebe7-5494-5f14-8ec8-dfb10b391511'::uuid, 'gambhirananda', 'english', 'Concentrating the mind thus, forever, the yogi of a controlled mind achieves the peace that culminates in liberation and abides in Me.'),
('dadee704-9492-5077-9939-bc72d785daa7'::uuid, '3f36ebe7-5494-5f14-8ec8-dfb10b391511'::uuid, 'sivananda', 'english', 'Thus, always keeping the mind balanced, the yogi, with the mind controlled, attains the peace abiding in Me, culminating in liberation.'),
('bd7f56be-6834-56bc-beb4-521a077457c7'::uuid, '14a21db0-98ad-5fb8-87e2-03033a6b2ea7'::uuid, 'gambhirananda', 'english', 'But, O Arjuna, Yoga is not for one who eats excessively, nor for one who does not eat at all; neither for one who habitually sleeps too long, nor for one who stays awake.'),
('fa33d348-9669-5b08-bca0-2eea937ca510'::uuid, '14a21db0-98ad-5fb8-87e2-03033a6b2ea7'::uuid, 'sivananda', 'english', 'Verily, Yoga is not possible for him who eats too much, nor for him who does not eat at all, nor for him who sleeps too much, nor for him who is always awake, O Arjuna.'),
('c80e8991-2aa5-531b-a544-c708869ab346'::uuid, 'faf664c7-c7cf-5613-b51e-f61862db4266'::uuid, 'gambhirananda', 'english', 'Yoga becomes a destroyer of sorrow for one whose eating and movements are regulated, whose effort in works is moderate, and whose sleep and wakefulness are temperate.'),
('2a754869-eba1-5849-9397-c72a9b2384e2'::uuid, 'faf664c7-c7cf-5613-b51e-f61862db4266'::uuid, 'sivananda', 'english', 'Yoga becomes the destroyer of pain for him who is moderate in eating and recreation (such as walking, etc.), who exercises moderation in action, and who is moderate in sleep and wakefulness.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('6e826f30-82d1-5d15-b5fc-c8cd9b7954f8'::uuid, 'fadb8f4a-df29-5233-96e7-0c092e197e20'::uuid, 'gambhirananda', 'english', 'A person who has become free from hankering for all desirable objects is said to be Self-absorbed when the controlled mind rests solely in the Self.'),
('d2c9aced-79dd-549c-b330-0babd2ceaa83'::uuid, 'fadb8f4a-df29-5233-96e7-0c092e197e20'::uuid, 'sivananda', 'english', 'When the perfectly controlled mind rests in the Self alone, free from longing for any of the objects of desire, then it is said, ''He is united''.'),
('9156cc6e-eb83-587e-ba4a-987e9eeb6235'::uuid, '1d61291d-21ea-5ba9-a2f8-9436b7990adc'::uuid, 'gambhirananda', 'english', 'As a lamp kept in a windless place does not flicker, so is the simile for the yogi whose mind is under control and who is engaged in concentration on the Self.'),
('d0f0dcad-9044-5045-a36d-520202a7f81e'::uuid, '1d61291d-21ea-5ba9-a2f8-9436b7990adc'::uuid, 'sivananda', 'english', 'As a lamp placed in a windless spot does not flicker, so is the Yogi of a controlled mind, who practices Yoga in the Self, compared.'),
('65eeea53-6d51-583b-816f-0b3278fadef0'::uuid, '4883b50b-39dc-59ad-833f-71d2f1ce68e7'::uuid, 'gambhirananda', 'english', 'At the time when the mind, restrained through the practice of Yoga, is withdrawn, and just when one sees the Self by the self and remains contented in the Self alone;'),
('9ec4873a-c5c7-55d5-abc8-75dd054e0e7c'::uuid, '4883b50b-39dc-59ad-833f-71d2f1ce68e7'::uuid, 'sivananda', 'english', 'When the mind, restrained by the practice of yoga, attains quietude, and when one sees the Self by the Self, they are satisfied in their own Self.'),
('d419ef92-04b7-5244-80c1-0984d306b3c6'::uuid, 'fa6207f9-73d7-5fd2-b9c5-eee887d9169a'::uuid, 'gambhirananda', 'english', 'When one experiences that absolute Bliss, which can be intuited by the intellect and which is beyond the senses, and being thus established, this person surely does not swerve from Reality.'),
('eb221963-b557-5098-adb2-b7b6592d26bd'::uuid, 'fa6207f9-73d7-5fd2-b9c5-eee887d9169a'::uuid, 'sivananda', 'english', 'When he (the Yogi) feels that infinite bliss which can be grasped by the pure intellect and which transcends the senses, and is established therein, never moving away from the reality.'),
('0cf34862-3904-536e-981a-544cfa2c90f5'::uuid, 'c71e647a-a852-5f28-a03f-18af441e86e9'::uuid, 'gambhirananda', 'english', 'Obtaining which one does not consider any other acquisition to be superior, and being established in which one is not perturbed even by great sorrow;'),
('84e38ce5-d4ee-586d-b820-b6172e565ffe'::uuid, 'c71e647a-a852-5f28-a03f-18af441e86e9'::uuid, 'sivananda', 'english', 'Having obtained it, he thinks there is no other gain superior to it; established in it, he is not moved even by heavy sorrow.'),
('768fb23f-a6a5-5afd-8ee1-ef6e1205d04b'::uuid, 'd9c58c9f-f181-5d83-8f21-6b1498f7085d'::uuid, 'gambhirananda', 'english', 'One should know that severance of contact with sorrow to be what is called Yoga. That Yoga should be practiced with perseverance and with an undepressed heart.'),
('6a37cc8b-eb6b-549d-9aed-5a9026d9de66'::uuid, 'd9c58c9f-f181-5d83-8f21-6b1498f7085d'::uuid, 'sivananda', 'english', 'Let this be known by the name of Yoga, the severance from union with pain. This Yoga should be practiced with determination and with an undespairing mind.'),
('2437f8d3-9ee7-53f7-8acf-7cc96119c06f'::uuid, '87bc1125-fd57-58c5-a004-530fe0cafd4f'::uuid, 'gambhirananda', 'english', 'By totally eschewing all desires that arise from thoughts and restraining all the organs with the mind from every side;'),
('388e4759-3c73-5982-b475-d2b46dfabd3f'::uuid, '87bc1125-fd57-58c5-a004-530fe0cafd4f'::uuid, 'sivananda', 'english', 'Abandoning unreservedly all desires born of Sankalpa (thought and imagination) and completely restraining the whole group of senses by the mind from all sides.'),
('16065327-84c1-51e0-97fb-aa09af6b2d25'::uuid, '27a37edb-8993-5c61-9dbd-dfe32eee5327'::uuid, 'gambhirananda', 'english', 'One should gradually withdraw with the intellect, endowed with steadiness. Making the mind fixed in the Self, one should not think of anything at all.'),
('55f046f2-79fe-57eb-abdb-008fe98faea9'::uuid, '27a37edb-8993-5c61-9dbd-dfe32eee5327'::uuid, 'sivananda', 'english', 'Little by little, let him attain steadiness of the intellect by holding it firmly; having made the mind establish itself in the Self, let him not think of anything else.'),
('7c062315-43e9-503c-9f29-8484079d5f2a'::uuid, 'fe5b1f4b-1bbf-5e74-b441-b0037176a6cf'::uuid, 'gambhirananda', 'english', 'The yogi should bring this mind under the subjugation of the Self itself, restraining it from all those causes that cause the restless, unsteady mind to wander away.'),
('7568e1bb-1ab7-55a1-853d-f224bed0b339'::uuid, 'fe5b1f4b-1bbf-5e74-b441-b0037176a6cf'::uuid, 'sivananda', 'english', 'From whatever cause the restless and unsteady mind wanders away, let him restrain it from that and bring it under the control of the Self alone.'),
('12d07862-7c0a-5334-a59e-f99dd8ecea25'::uuid, '49493824-8eb5-5a77-8636-42c9da3db8e5'::uuid, 'gambhirananda', 'english', 'Supreme Bliss comes to this yogi alone whose mind has become perfectly tranquil, whose quality of rajas has been eliminated, who has become identified with Brahman, and is untainted.'),
('c70a9036-3d2c-5edb-9bce-6b95dfbb597a'::uuid, '49493824-8eb5-5a77-8636-42c9da3db8e5'::uuid, 'sivananda', 'english', 'Supreme Bliss indeed comes to this Yogi whose mind is made peaceful, whose passion is quelled, who has become Brahman, and who is free from sin.'),
('be93c025-2060-5cfa-9ae9-4f7925c7c23f'::uuid, '58fe1c3a-b266-5640-afae-a7cb73e106d7'::uuid, 'gambhirananda', 'english', 'By constantly concentrating his mind in this way, the taintless yogi easily attains the absolute bliss of contact with Brahman.'),
('47a25903-911a-5ec9-9dec-70e09aacbde9'::uuid, '58fe1c3a-b266-5640-afae-a7cb73e106d7'::uuid, 'sivananda', 'english', 'The yogi, always engaging the mind thus (in the practice of yoga), is freed from sins and easily enjoys the infinite bliss of contact with Brahman (the Eternal).'),
('94446ecf-7bbc-5ed6-b13a-05424e81bc8e'::uuid, '56c7b080-ae70-587a-b5be-aad478085982'::uuid, 'gambhirananda', 'english', 'One who has their mind Self-absorbed through Yoga, and who has the vision of sameness everywhere, sees this Self existing in everything, and everything in their Self.'),
('4c41e151-97f2-56ee-aaf4-791f2e2ad5ff'::uuid, '56c7b080-ae70-587a-b5be-aad478085982'::uuid, 'sivananda', 'english', 'With the mind harmonized by Yoga, he sees the Self abiding in all beings and all beings in the Self; he sees the same everywhere.'),
('f2cb6d7b-6112-551b-84a2-52562800742f'::uuid, '260fdbf3-65b5-5f44-9658-e75e8d88c87e'::uuid, 'gambhirananda', 'english', 'One who sees Me in everything and sees all things in Me—I do not lose sight of him, and he also is not lost to My vision.'),
('c894101e-c5b9-5f04-adaa-ff463d27406e'::uuid, '260fdbf3-65b5-5f44-9658-e75e8d88c87e'::uuid, 'sivananda', 'english', 'He who sees Me everywhere and sees everything in Me, never becomes separated from Me, nor do I from him.'),
('cb7c8d5b-3028-5f47-8278-708c5be385a7'::uuid, 'ee9bf745-feea-5bbb-acd0-8afe95af047e'::uuid, 'gambhirananda', 'english', 'That yogi, who, being established in unity, adores Me as existing in all things, exists in Me—in whatever condition he may be.'),
('e9b0bd68-6826-5384-8a64-2364d3985658'::uuid, 'ee9bf745-feea-5bbb-acd0-8afe95af047e'::uuid, 'sivananda', 'english', 'He who, being established in unity, worships Me, who dwells in all beings, that yogi abides in Me, whatever their mode of living may be.'),
('b00735f9-fb06-5c39-94ef-e8d281bf125e'::uuid, '031f5ada-08b1-51d9-afb6-1017e7fd850a'::uuid, 'gambhirananda', 'english', 'O Arjuna, that yogi is considered the best who judges what is happiness and sorrow in all beings by the same standard as they would apply to themselves.'),
('d138aab8-ffbe-5d68-a7e6-ed1c3f3d5edb'::uuid, '031f5ada-08b1-51d9-afb6-1017e7fd850a'::uuid, 'sivananda', 'english', 'He who, through the likeness of the Self, O Arjuna, sees reality everywhere, be it pleasure or pain, is regarded as the highest Yogi.'),
('538798d5-52b5-54a3-8049-3bd7c14fff45'::uuid, '7238b5af-337c-51c4-b370-3db2806e8f09'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Madhusudana (Krsna), this Yoga that You have spoken of as sameness, I do not see its steady continuance due to the restlessness of the mind."'),
('52d7d6b9-f0bb-5662-be2b-6f70d77d4b51'::uuid, '7238b5af-337c-51c4-b370-3db2806e8f09'::uuid, 'sivananda', 'english', 'Arjuna said, "O Krishna, I do not see how this Yoga of equanimity, which you have taught me, can be maintained steadily, due to the restlessness of the mind."'),
('941efcff-fe21-5b13-b7a5-7eb98fdb1a2e'::uuid, 'b04c045b-41f2-5e66-bd5b-f68952f3bf01'::uuid, 'gambhirananda', 'english', 'For, O Kṛṣṇa, the mind is unsteady, turbulent, strong, and obstinate; I consider its control to be as difficult as that of the wind.'),
('0d8cbb85-f583-56e8-bc98-c57e75beaa5a'::uuid, 'b04c045b-41f2-5e66-bd5b-f68952f3bf01'::uuid, 'sivananda', 'english', 'The mind is indeed restless, turbulent, strong, and unyielding, O Krishna; I consider it as difficult to control as controlling the wind.'),
('a0fa3539-5cb8-519d-871a-dffdac8e2a64'::uuid, '5f42b2da-ef86-5863-a7cf-d621adb0f4cf'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, O mighty-armed one, undoubtedly the mind is untamable and restless. But, O son of Kunti, it can be brought under control through practice and detachment.'),
('1aab28f6-7baa-5a5a-9565-8a17fb1f60fc'::uuid, '5f42b2da-ef86-5863-a7cf-d621adb0f4cf'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "Undoubtedly, O mighty-armed Arjuna, the mind is difficult to control and restless; but with practice and dispassion, it can be restrained."'),
('e2fff5fb-f18c-5ee2-9232-69680465f74f'::uuid, 'a489f5bc-cb32-598d-a09f-e43fb4b03902'::uuid, 'gambhirananda', 'english', 'My conviction is that Yoga is difficult to attain for one with an uncontrolled mind. But it is possible to attain through the aforementioned means for one who strives and has a controlled mind.'),
('52de793c-0a36-50a8-a59b-6ed8d410ccdd'::uuid, 'a489f5bc-cb32-598d-a09f-e43fb4b03902'::uuid, 'sivananda', 'english', 'I think Yoga is hard to be attained by one with an uncontrolled self, but the self-controlled and striving one can attain it by the appropriate means.'),
('c43f22a0-3282-5f56-9d7b-96539b4caf07'::uuid, 'ce61bf06-b5d5-52b4-ac03-d3a7ba994502'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Krsna, what goal does one attain who, despite having faith, fails to achieve perfection in Yoga due to lack of diligence, and whose mind becomes deflected from Yoga?"'),
('ff2f5bb6-df39-5bf4-9029-0faf5b1712df'::uuid, 'ce61bf06-b5d5-52b4-ac03-d3a7ba994502'::uuid, 'sivananda', 'english', 'Arjuna said, "He who is unable to control himself, even though he has faith, and whose mind wanders away from Yoga, what end does he meet, having failed to attain perfection in Yoga, O Krishna?"'),
('8230edb3-8296-55ff-ac18-13e71d35ee5c'::uuid, '302e1229-4854-50d2-a71b-4cf3ec09afc2'::uuid, 'gambhirananda', 'english', 'O Mighty-armed one, having fallen from both [paths], without support, deluded on the path to Brahman, does he not get ruined like a scattered cloud?'),
('dd249a09-fc83-5cd5-bca9-ca6179c5efba'::uuid, '302e1229-4854-50d2-a71b-4cf3ec09afc2'::uuid, 'sivananda', 'english', 'Fallen from both, does he not perish like a rent cloud, supportless, O mighty-armed one, deluded on the path of Brahman?'),
('9a60e850-1f5d-54fc-bd68-a915351d66f4'::uuid, 'ace846c5-c503-58d6-85f6-aff050afda32'::uuid, 'gambhirananda', 'english', 'O Krsna, you should totally eradicate this doubt of mine, for none other than yourself can be the dispeller of this doubt!'),
('fdaf352f-b4f5-59da-93b1-174396ff21cb'::uuid, 'ace846c5-c503-58d6-85f6-aff050afda32'::uuid, 'sivananda', 'english', 'O Krishna, please completely dispel this doubt of mine, for it is not possible for anyone but You to do so.'),
('1b5051bd-5989-5eb3-a73a-346851d15b36'::uuid, 'ca921481-2feb-532d-b50e-d9aa96359701'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "O Partha, there is certainly no ruin for him here or hereafter, for no one engaged in good meets with a deplorable end, my son!"'),
('e4291bbe-e486-503d-9195-733fa978535f'::uuid, 'ca921481-2feb-532d-b50e-d9aa96359701'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "O Arjuna, neither in this world nor in the next will there be destruction for him; none, indeed, who does good, O my son, ever comes to grief."'),
('d099a0a2-0343-5422-9b8e-b0291ed9abd3'::uuid, 'd6064d04-1043-5b8c-a002-06280cff8981'::uuid, 'gambhirananda', 'english', 'Attaining the worlds of the righteous and residing there for eternal years, the man who has fallen from Yoga is born in the house of the pious and prosperous.'),
('740b1b51-f09b-531e-a9f5-f5a72ae8f601'::uuid, 'd6064d04-1043-5b8c-a002-06280cff8981'::uuid, 'sivananda', 'english', 'Having attained to the worlds of the righteous and having dwelt there for everlasting years, he who fell from Yoga is born in a house of the pure and wealthy.'),
('9c3195df-b846-5b7f-8ab0-1b514b44195d'::uuid, '1a3077a1-7689-5741-b475-06fca087f1e0'::uuid, 'gambhirananda', 'english', 'Or, he is born in the family of wise yogis. Such a birth is indeed more difficult to come by in the world.'),
('f05c9935-fdc9-5e10-b46d-84ae114dbfba'::uuid, '1a3077a1-7689-5741-b475-06fca087f1e0'::uuid, 'sivananda', 'english', 'Or he is born in a family of even the wisest of yogis; verily, such a birth is very difficult to obtain in this world.'),
('dbc8ef45-9568-5c15-8501-9a8576a46fe9'::uuid, 'c6fba463-edde-5804-924c-a1d60b3ab5d1'::uuid, 'gambhirananda', 'english', 'There he becomes endowed with the wisdom acquired in the previous body, and he strives even more than before for perfection, O scion of the Kuru dynasty.'),
('6c7e44a3-edfd-50b0-91b2-34273e04675a'::uuid, 'c6fba463-edde-5804-924c-a1d60b3ab5d1'::uuid, 'sivananda', 'english', 'Then he comes into contact with the knowledge acquired in his former body and strives even more for perfection, O Arjuna.'),
('d26e7f2d-b110-553c-9cd7-63c8f87cb237'::uuid, 'eeb9ac72-6ad2-5b3e-ac46-27fc8da01508'::uuid, 'gambhirananda', 'english', 'For, by that very past practice, he is carried forward even in spite of himself! Even a seeker of Yoga transcends the results of the performance of Vedic rituals!'),
('03376e83-c20a-5654-988e-f14a3b185307'::uuid, 'eeb9ac72-6ad2-5b3e-ac46-27fc8da01508'::uuid, 'sivananda', 'english', 'By that same former practice, he is borne on in spite of himself. Even he who merely wishes to know Yoga goes beyond the Brahmanic word.'),
('a9dd7790-277b-51ad-bcd9-9bb5013cbe6b'::uuid, '0b0736fb-02cb-5b75-a22e-9a6e5c24154a'::uuid, 'gambhirananda', 'english', 'However, the yogi, applying himself assiduously, becoming purified from sin and attaining perfection through many births, they achieve the highest Goal.'),
('58d8413c-1122-5248-b30e-4fd8bf8df60b'::uuid, '0b0736fb-02cb-5b75-a22e-9a6e5c24154a'::uuid, 'sivananda', 'english', 'But the Yogi who strives assiduously, purified of sins and perfected gradually over many births, reaches the highest goal.'),
('2edbe1a0-a441-5c9c-9155-077176ae9aa1'::uuid, '911b439e-8d0f-544a-9272-0582dde7ff34'::uuid, 'gambhirananda', 'english', 'A yogi is higher than those of austerity; they are considered higher even than those of knowledge. The yogi is also higher than those of action. Therefore, O Arjuna, become a yogi.'),
('a0304b28-e3a8-5186-9d6c-b81f181f6d17'::uuid, '911b439e-8d0f-544a-9272-0582dde7ff34'::uuid, 'sivananda', 'english', 'The yogi is thought to be superior to the ascetics, even superior to those who have knowledge obtained through the study of scriptures; he is also superior to men of action; therefore, be thou a yogi, O Arjuna.'),
('4a8cd546-e183-56cd-b0ad-4018dd1b81ed'::uuid, '9ff91195-318c-582c-91a9-5dc720e1d8bc'::uuid, 'gambhirananda', 'english', 'Even among all the yogis, he who adores Me with his mind fixed on Me and with faith is considered by Me to be the best of the yogis.'),
('06a0ed48-0b88-5ca9-86d1-1902d9e81358'::uuid, '9ff91195-318c-582c-91a9-5dc720e1d8bc'::uuid, 'sivananda', 'english', 'And among all the Yogis, he who, full of faith and with his inner self merged in Me, worships Me is deemed by Me to be the most devoted.'),
('2946f3d8-c2ef-5fbf-986a-89c8bf6d9be3'::uuid, '3857fad2-c141-5c9b-8a2e-a9ea92bd6617'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "O Partha, hear how, with your mind fixed on Me, practicing the Yoga of Meditation and taking refuge in Me, you will certainly and fully know Me.'),
('831aa931-65cc-51c0-9aa4-e633f2d2f67d'::uuid, '3857fad2-c141-5c9b-8a2e-a9ea92bd6617'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "O Arjuna, hear how you shall, without doubt, know Me fully, with your mind intent on Me, practicing Yoga and taking refuge in Me."'),
('338a203b-7de8-5f13-af1c-d7bffec6a91a'::uuid, 'c59ebaaa-4cad-5a24-b61a-63b45113e007'::uuid, 'gambhirananda', 'english', 'I shall tell you in detail of this Knowledge, which is combined with realization, after experiencing which there remains nothing else here to be known.'),
('7c9fc79f-44af-58d2-a7f5-c63d3e97ae27'::uuid, 'c59ebaaa-4cad-5a24-b61a-63b45113e007'::uuid, 'sivananda', 'english', 'I will declare to you in full this knowledge combined with realization, after knowing which nothing else remains to be known here.'),
('bffadd69-f3b5-526a-accb-4c2b410c8fbe'::uuid, '8a7c9bb0-7762-5d86-b4ca-3bafe4883617'::uuid, 'gambhirananda', 'english', 'Among thousands of men, a rare one endeavors for perfection. Even among the perfected ones who are diligent, one perchance knows Me in truth.'),
('786c9d44-0a7f-5856-b855-cc5b8bd5829f'::uuid, '8a7c9bb0-7762-5d86-b4ca-3bafe4883617'::uuid, 'sivananda', 'english', 'Among thousands of men, one may perchance strive for perfection; even among those successful strivers, only one may perchance know Me in essence.'),
('422dec7c-bf86-5224-b049-dcbb5fd03fe4'::uuid, '8e33ba3b-74b3-5655-9413-3bdbf30af51d'::uuid, 'gambhirananda', 'english', 'This Prakrti of Mine is divided eightfold thus: earth, water, fire, air, space, mind, intellect, and egoism.'),
('d63a2faf-6279-5dd6-9ff0-2cc883bdf23d'::uuid, '8e33ba3b-74b3-5655-9413-3bdbf30af51d'::uuid, 'sivananda', 'english', 'Earth, water, fire, air, ether, mind, intellect, and egoism—thus is My Nature divided eightfold.'),
('8e0e5a0c-4212-5b7b-8985-e26b56706ce7'::uuid, '50cb55eb-fe26-5ff0-b8e9-05af6bd0eddb'::uuid, 'gambhirananda', 'english', 'O mighty-armed one, this is the inferior Prakrti. Know the other Prakrti of Mine, which is however higher than this, which has taken the form of individual souls, and by which this world is upheld.'),
('bfa3214b-2228-5131-96ac-3d2242a36952'::uuid, '50cb55eb-fe26-5ff0-b8e9-05af6bd0eddb'::uuid, 'sivananda', 'english', 'O mighty-armed Arjuna, this is the inferior Prakriti; know it as distinct from My higher Prakriti, the very life-element, by which this world is upheld.'),
('8a1327c8-f2cd-5541-9386-68bdfc8737be'::uuid, 'a1dcf370-e869-5adb-bf77-8e08bdee035c'::uuid, 'gambhirananda', 'english', 'Understand thus that all things—sentient and insentient—have these as their source. I am the origin as well as the end of the entire universe.'),
('f3e397bf-ff28-507e-ad63-30549f637ef6'::uuid, 'a1dcf370-e869-5adb-bf77-8e08bdee035c'::uuid, 'sivananda', 'english', 'Know that these two are the womb of all beings; thus, I am the source and dissolution of the whole universe.'),
('9b747a0e-c1a9-50c5-a6ca-63e31efc2d12'::uuid, '29bc17bd-599a-5c8a-8b06-942b190fe6c1'::uuid, 'gambhirananda', 'english', 'O Dhananjaya, there is nothing else higher than Myself. All this is strung on Me like pearls on a string.'),
('66fb6ff7-c7b3-54eb-8af2-a27b54d41ecf'::uuid, '29bc17bd-599a-5c8a-8b06-942b190fe6c1'::uuid, 'sivananda', 'english', 'There is nothing higher than Me, O Arjuna. All this is strung on Me, like clusters of gems on a string.'),
('64479917-ceaf-5a8c-9192-ac8937e12661'::uuid, '5a408a70-84dd-5a72-a746-528fac13942e'::uuid, 'gambhirananda', 'english', 'O son of Kunti, I am the taste of water, I am the effulgence of the moon and the sun; the letter ''Om'' in all the Vedas, the sound in space, and manhood in men.'),
('fb3c5689-20b9-550b-8ce2-5e2d3c0c987d'::uuid, '5a408a70-84dd-5a72-a746-528fac13942e'::uuid, 'sivananda', 'english', 'I am the flavor in water, O Arjuna; I am the light in the moon and the sun; I am the syllable Om in all the Vedas, sound in the ether and virility in men.'),
('ebbc096a-7e5e-560f-a46e-5c82e251c05d'::uuid, '85f39e76-284a-56a2-8104-0b6fbc08bf97'::uuid, 'gambhirananda', 'english', 'I am also the sweet fragrance in the earth; I am the brilliance in the fire, and the life in all beings; and I am the austerity of the ascetics.'),
('9e152211-2e88-5464-89a1-aad957733118'::uuid, '85f39e76-284a-56a2-8104-0b6fbc08bf97'::uuid, 'sivananda', 'english', 'I am the sweet fragrance in the earth and the brilliance in the fire, the life in all beings, and I am the austerity of ascetics.'),
('b08b4eac-d73b-54e1-8fea-37f55d28b5cf'::uuid, '1ec52b38-4a62-5228-836e-8228c38468a5'::uuid, 'gambhirananda', 'english', 'O Partha, know Me to be the eternal seed of all beings. I am the intellect of the intelligent, and I am the courage of the courageous.'),
('d3c179cb-bd66-5f05-b880-14cfd19a0ae5'::uuid, '1ec52b38-4a62-5228-836e-8228c38468a5'::uuid, 'sivananda', 'english', 'Know Me, O Arjuna, as the eternal seed of all beings; I am the intelligence of the intelligent, and the splendour of the splendid objects.'),
('b7ae704f-8863-5c8f-ba3f-65a9d6a56f91'::uuid, '0da6d08b-3273-5f28-bde6-f90f9177817b'::uuid, 'gambhirananda', 'english', 'And of the strong, I am the strength that is devoid of passion and attachment. Among creatures, I am desire that is not contrary to righteousness, O scion of the Bharata dynasty.'),
('d064bed6-5fe1-5404-9e2b-6c5946ab1b21'::uuid, '0da6d08b-3273-5f28-bde6-f90f9177817b'::uuid, 'sivananda', 'english', 'Of the strong, I am the strength devoid of desire and attachment, and in all beings, I am the desire in accordance with Dharma, O Arjuna.'),
('355ed874-618a-515e-ae17-076719341634'::uuid, '9f835ba3-7827-5cdc-b515-916bd5fbe546'::uuid, 'gambhirananda', 'english', 'Those things that are made of the quality of sattva, and those things that are made of the quality of rajas and tamas, know them to have sprung from Me alone. However, I am not in them; they are within Me!'),
('eef9beab-c122-5887-a514-a1f616250af9'::uuid, '9f835ba3-7827-5cdc-b515-916bd5fbe546'::uuid, 'sivananda', 'english', 'Whatever beings (and objects) that are pure, active, and inert, know that they proceed from Me. They are in Me, yet I am not in them.'),
('b12f9f66-694c-5caf-ada4-37f5787f8972'::uuid, '853bbd9d-e54a-558a-8767-4d2cc1f6d2d7'::uuid, 'gambhirananda', 'english', 'All this world, deluded as it is by these three qualities made of the gunas, does not know Me, who am transcendental to these and undecaying.'),
('626c8507-dfa7-50c9-b75a-7062441aae5e'::uuid, '853bbd9d-e54a-558a-8767-4d2cc1f6d2d7'::uuid, 'sivananda', 'english', 'Deluded by these Natures, composed of the three qualities of Nature, all this world does not know Me as distinct from them and immutable.'),
('d0e836af-1963-5056-866f-b316837477db'::uuid, 'b418621f-440b-5fdd-bde2-4698c1cde91d'::uuid, 'gambhirananda', 'english', 'Since this divine Maya of Mine, which is constituted by the gunas, is difficult to cross over, those who take refuge in Me alone can transcend this Maya.'),
('74f83ba9-5fb8-5536-a96c-0ee59cc85ce1'::uuid, 'b418621f-440b-5fdd-bde2-4698c1cde91d'::uuid, 'sivananda', 'english', 'Verily, this divine illusion of Mine, composed of the three qualities, is difficult to cross over; those who take refuge in Me alone, can cross over this illusion.'),
('af18c52d-127f-538f-910d-d4f2146618f8'::uuid, '32363d86-b2bb-5b43-a5be-27d4793dca46'::uuid, 'gambhirananda', 'english', 'The foolish evildoers, who are the most depraved among men, who are deprived of their wisdom by Maya, and who resort to demonic ways, do not take refuge in Me.'),
('687c0495-ebb8-5fd4-ac3e-130459c57bf9'::uuid, '32363d86-b2bb-5b43-a5be-27d4793dca46'::uuid, 'sivananda', 'english', 'The evil-doers and the deluded, who are the lowest of men, do not seek Me; those whose knowledge is destroyed by illusion follow the ways of demons.'),
('73770fd0-e9ac-57d3-aace-e69e57e099d2'::uuid, '4562982b-eb43-5eec-9758-5654fe1ed26a'::uuid, 'gambhirananda', 'english', 'O Arjuna, foremost of the Bharata dynasty, four classes of people of virtuous deeds adore Me: the afflicted, the seekers of Knowledge, the seekers of wealth, and the man of Knowledge.'),
('887ccb3b-9939-50bc-b91a-a7b5ef064ce7'::uuid, '4562982b-eb43-5eec-9758-5654fe1ed26a'::uuid, 'sivananda', 'english', 'Four kinds of virtuous men worship Me, O Arjuna, and they are the distressed, the seekers of knowledge, the seekers of wealth, and the wise, O Lord of the Bharatas.'),
('6b23b267-cadd-5ede-8543-752b0d4e1d1b'::uuid, 'cbdd8f03-c774-56cf-a43c-6941686fac3d'::uuid, 'gambhirananda', 'english', 'Of them, the man of knowledge, endowed with constant steadfastness and one-pointed devotion, excels. For I am very dear to the man of knowledge, and he too is dear to me.'),
('bc5f1a6f-aebd-5897-8beb-0cbeaf9f9da3'::uuid, 'cbdd8f03-c774-56cf-a43c-6941686fac3d'::uuid, 'sivananda', 'english', 'Of them, the wise who are ever steadfast and devoted to the One, excel; for I am exceedingly dear to the wise, and they are dear to Me.'),
('6716ec03-190f-5e95-801e-61a6d76c32b3'::uuid, 'a1f7ac7a-69f8-5d04-9988-2ef5c7f1c886'::uuid, 'gambhirananda', 'english', 'Indeed, all of these are noble, but the man of Knowledge is the Self itself. This is my opinion. For, with a steadfast mind, he is set on the path leading only to Me, who am the supreme Goal.'),
('7808cd01-7b15-58e6-97e5-68b6d08bdee4'::uuid, 'a1f7ac7a-69f8-5d04-9988-2ef5c7f1c886'::uuid, 'sivananda', 'english', 'Indeed, all these are noble; however, I consider the wise man as My very Self; for, he is steadfast in mind and established in Me alone as the supreme goal.'),
('405e00d8-008b-5f01-bab5-25c3fc7c8974'::uuid, '1da4ce04-8aad-515b-a48f-79b1d63fa868'::uuid, 'gambhirananda', 'english', 'At the end of many births, the man of knowledge attains Me, realizing that Vasudeva is all. Such a high-souled one is very rare.'),
('f31b9520-e8fa-5a63-972b-a15eeadfd512'::uuid, '1da4ce04-8aad-515b-a48f-79b1d63fa868'::uuid, 'sivananda', 'english', 'At the end of many births, the wise man comes to Me, realizing that all this is Vaasudeva (the innermost Self); such a great soul (Mahatma) is very hard to find.'),
('f1a6c0b1-95e3-5e2a-a5cc-492f03234715'::uuid, 'a2f515f5-e089-5d1e-a8c0-752632982add'::uuid, 'gambhirananda', 'english', 'People, deprived of their wisdom by desires for various objects and guided by their own nature, resort to other deities, following the relevant methods.'),
('648b965f-0c49-58f8-8dbd-1e11435951c4'::uuid, 'a2f515f5-e089-5d1e-a8c0-752632982add'::uuid, 'sivananda', 'english', 'Those whose wisdom has been taken away by this or that desire, go to other gods, following this or that rite, led by their own nature.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('c847f7d3-864f-5c95-a394-697fba434f71'::uuid, 'a44ddd08-c380-5af6-a5fb-1a2a516026f4'::uuid, 'gambhirananda', 'english', 'Whichever form of a deity any devotee wants to worship with faith, I strengthen that very firm faith of theirs.'),
('834aaa61-7356-5305-ab0c-5f73398e1e33'::uuid, 'a44ddd08-c380-5af6-a5fb-1a2a516026f4'::uuid, 'sivananda', 'english', 'Whatever form any devotee desires to worship with faith, I make that same faith of his firm and unflinching.'),
('f4aa0cb7-493e-558f-a65b-a29f3d7f4d4b'::uuid, '7537b9a0-5472-516c-9191-818afcab5983'::uuid, 'gambhirananda', 'english', 'Being imbued with that faith, that person engages in worshipping that form, and they get those very desired results as dispensed by Me alone.'),
('15c28e00-84de-559a-8219-487a87cf0c4e'::uuid, '7537b9a0-5472-516c-9191-818afcab5983'::uuid, 'sivananda', 'english', 'Endowed with that faith, he engages in the worship of that form and obtains his desired outcome, which is ordained by Me alone.'),
('174bb3ab-f77f-5d5c-b4a1-cf14e002a701'::uuid, '563bcb8f-dde1-5a35-b908-7430724dbce4'::uuid, 'gambhirananda', 'english', 'The result of those who are of poor intellect is indeed limited. The worshippers of gods go to the gods, while My devotees go to Me alone.'),
('327b7028-19e9-5960-8bef-da55bacba1d7'::uuid, '563bcb8f-dde1-5a35-b908-7430724dbce4'::uuid, 'sivananda', 'english', 'Verily, the reward (fruit) that accrues to those men of small intelligence is finite. The worshippers of the gods go to them, whereas My devotees come to Me.'),
('6c826731-1e0d-5fca-bdc2-d3cd90cf1ee9'::uuid, '322e38cb-afc4-5c75-8d95-23bbe3ebdc49'::uuid, 'gambhirananda', 'english', 'The unintelligent, unaware of My supreme state which is immutable and unsurpassable, think of Me as having become manifest from the unmanifest.'),
('4de8a944-2dc9-5f5c-9c6b-9399f8d8be59'::uuid, '322e38cb-afc4-5c75-8d95-23bbe3ebdc49'::uuid, 'sivananda', 'english', 'The foolish think of Me, the Unmanifest, as having manifestation, not knowing My higher, immutable, and most excellent nature.'),
('e7647384-005e-5f34-b55b-ad5480018f20'::uuid, '1a58b77f-d488-5c8b-ab98-485a7b163c4b'::uuid, 'gambhirananda', 'english', 'Being enveloped by yoga-maya, I do not become manifest to all. This deluded world does not know Me, who am birthless and undecaying.'),
('668ba0eb-8e37-5fde-8eae-bc88c1c90b79'::uuid, '1a58b77f-d488-5c8b-ab98-485a7b163c4b'::uuid, 'sivananda', 'english', 'I am not manifest to all, veiled as I am by the Yoga-Maya. This deluded world does not know Me, who am unborn and imperishable.'),
('4705abb7-8bc8-54f1-abea-eadac706895f'::uuid, '4f1502b6-26a5-5f34-84b9-0897905ec7b8'::uuid, 'gambhirananda', 'english', 'O Arjuna, I know the past, present, and future beings; but no one knows Me!'),
('a55248d1-6114-586d-a8d3-e74948c3a809'::uuid, '4f1502b6-26a5-5f34-84b9-0897905ec7b8'::uuid, 'sivananda', 'english', 'I know, O Arjuna, the beings of the past, the present, and the future; however, no one knows Me.'),
('01ad97c3-a782-5ad7-a2d7-722263568d9c'::uuid, 'c6cae0e3-531b-5a41-a1a3-bac10d5c6494'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, O destroyer of foes, due to the delusion of duality arising from likes and dislikes, all creatures become bewildered upon their birth.'),
('acb02ba2-e9f4-5a95-b601-e4146f68bcee'::uuid, 'c6cae0e3-531b-5a41-a1a3-bac10d5c6494'::uuid, 'sivananda', 'english', 'O Bharata, all beings are subject to delusion at birth due to the delusion of the pairs of opposites arising from desire and aversion, O Parantapa.'),
('49730651-500c-57a9-8038-0545ffec03d7'::uuid, 'e262c515-1c2d-52c5-b1f4-c51a91228025'::uuid, 'gambhirananda', 'english', 'On the other hand, those persons who have done virtuous deeds, whose sin has come to an end, they, being free from the delusion of duality and firm in their convictions, adore Me.'),
('f29e864f-8c59-502c-8f22-b12ae462bd4b'::uuid, 'e262c515-1c2d-52c5-b1f4-c51a91228025'::uuid, 'sivananda', 'english', 'But those men of virtuous deeds, whose sins have come to an end and who are freed from the delusion of the pairs of opposites, worship Me steadfastly, with their vows.'),
('43586cbd-bd7d-5bcb-9318-788285780243'::uuid, 'dd746d5b-2f47-50e2-b7f0-d021532a9d0e'::uuid, 'gambhirananda', 'english', 'Those who strive by resorting to Me for becoming free from old age and death, they know Brahman, the individual Self, and all about actions. [They know Brahman as being all the individual entities and all actions. This verse prescribes meditation on the qualified Brahman for aspirants of the middle class. Verses beginning with the 14th speak about the realization of the unqualified Brahman by aspirants of the highest class.]'),
('b6635b89-a13a-58b6-ada3-726a11694201'::uuid, 'dd746d5b-2f47-50e2-b7f0-d021532a9d0e'::uuid, 'sivananda', 'english', 'Those who strive for liberation from old age and death, taking refuge in Me, realize in full that Brahman, the whole knowledge of the Self, and all action.'),
('6a65441a-4a73-59bd-87aa-02b8ca8d6f5e'::uuid, '2cdfd895-fc01-596c-9bed-527b98b45f81'::uuid, 'gambhirananda', 'english', 'Those who know me as existing in both the physical and divine planes, and also in the context of the sacrifice, they with concentrated minds know me even at the time of death.'),
('5ba2f20d-79d1-5371-b22f-9d116a67c438'::uuid, '2cdfd895-fc01-596c-9bed-527b98b45f81'::uuid, 'sivananda', 'english', 'Those who know Me with the Adhibhuta (pertaining to the elements), Adhidaiva (pertaining to the gods), and the Adhiyajna (pertaining to the sacrifice) know Me even at the time of death, remaining steadfast in mind.'),
('01aff4bb-2393-50ce-8167-1877f10837d9'::uuid, '0a35738a-cd71-5d99-b5bd-2a6ea3e6b62b'::uuid, 'gambhirananda', 'english', 'Arjuna said, O Supreme Person, what is Brahman? What exists in the individual plane? What is action? What is said to exist in the physical plane? And what is said to exist in the divine plane?'),
('0167487f-937a-5149-bda8-2bef664881c4'::uuid, '0a35738a-cd71-5d99-b5bd-2a6ea3e6b62b'::uuid, 'sivananda', 'english', 'Arjuna said, "What is Brahman? What is Adhyatma? What is action, O best among men? What is Adhibhuta declared to be? And, what is Adhidaiva said to be?"'),
('89a9bd9f-be2d-5201-8c3f-f3f8e29fa5da'::uuid, 'b5da4e49-943b-5f61-8746-7ebc22843877'::uuid, 'gambhirananda', 'english', 'O Madhusudana, how is the entity existing in the sacrifice here in this body, and who is it? And how are You to be known by people of concentrated minds at the time of death?'),
('fd6f86f2-3265-589b-8def-fc560378f537'::uuid, 'b5da4e49-943b-5f61-8746-7ebc22843877'::uuid, 'sivananda', 'english', 'Who and how is Adhiyajna here in this body, O destroyer of Madhu? And how, at the time of death, are You to be known by the self-controlled?'),
('fb207dc1-7e7d-5a34-afda-dde0b3a12d11'::uuid, 'df6b6259-6e52-5246-b81f-d9c574b51cf5'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "The Immutable is the supreme Brahman; selfhood is said to be the entity present in the individual plane. By action is meant the offerings that bring about the origin of existence of things."'),
('868aa883-e1a5-5f0a-8c34-462579ca285d'::uuid, 'df6b6259-6e52-5246-b81f-d9c574b51cf5'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "Brahman is the Imperishable, the Supreme; its essential nature is called Self-knowledge; the offering (to the gods) that causes the existence and manifestation of beings and sustains them is called action."'),
('3e6ca295-6e6a-5b8c-8142-b2bcc83038b8'::uuid, 'bd07fb40-a7ad-5453-9035-2f99cd89feda'::uuid, 'gambhirananda', 'english', 'That which exists in the physical plane is the mutable entity, and what exists in the divine plane is the Person. O best among the embodied beings, I Myself am the entity that exists in the sacrifice within this body.'),
('b322f7cb-ebaf-5b5b-bcf4-ed2b9081a99e'::uuid, 'bd07fb40-a7ad-5453-9035-2f99cd89feda'::uuid, 'sivananda', 'english', 'Adhibhuta—knowledge of the elements—pertains to My perishable nature, and the Purusha, or the Soul, is the Adhidaiva; I alone am the Adhiyajna here in this body, O best among the embodied.'),
('db35ea17-af5c-57de-9a52-6f7967f959f3'::uuid, 'f7475c48-ff10-5405-9ddf-6eb01a443475'::uuid, 'gambhirananda', 'english', 'And at the time of death, anyone who departs, giving up the body while thinking of Me alone, attains My state; there is no doubt about this.'),
('59224065-c7d4-5ec9-828e-06292fbf291f'::uuid, 'f7475c48-ff10-5405-9ddf-6eb01a443475'::uuid, 'sivananda', 'english', 'And whoever, leaving their body, goes forth remembering Me alone at the time of death, they will attain My Being; there is no doubt about this.'),
('a306a757-eab7-5d48-aacd-4ce04affd7b2'::uuid, 'b6d958e4-76fa-58c1-b6a4-8b37a2de338c'::uuid, 'gambhirananda', 'english', 'O son of Kunti, thinking of any entity, whichever it may be, one gives up the body at the end; he attains that very one, having been always engrossed in its thought.'),
('9e4e6596-9f5f-50e9-b6a3-4702a7941da8'::uuid, 'b6d958e4-76fa-58c1-b6a4-8b37a2de338c'::uuid, 'sivananda', 'english', 'Whoever at the end leaves the body, thinking of any being, to that being only does he go, O son of Kunti (Arjuna), due to his constant thought of that being.'),
('20139b95-4699-5f5d-b78d-503628a03f16'::uuid, '89535827-771c-528c-8058-86e79f79934a'::uuid, 'gambhirananda', 'english', 'Therefore, think of Me at all times and fight; there is no doubt that by dedicating your mind and intellect to Me, you will attain only Me.'),
('f685d9ed-ab6b-5559-9616-74ab739d893a'::uuid, '89535827-771c-528c-8058-86e79f79934a'::uuid, 'sivananda', 'english', 'Therefore, at all times, remember Me only and fight. With your mind and intellect fixed on Me, you will undoubtedly come to Me alone.'),
('2f93de5b-91f7-5289-9a44-8e37aa3c3ef6'::uuid, 'a3b577af-5887-52ca-a522-601bc06ee0c3'::uuid, 'gambhirananda', 'english', 'O son of Prtha, by meditating with a mind engaged in the yoga of practice and not straying away to anything else, one reaches the supreme Person existing in the effulgent region.'),
('e31bec5c-4a8a-5fc3-a3fe-be13a9ef24ad'::uuid, 'a3b577af-5887-52ca-a522-601bc06ee0c3'::uuid, 'sivananda', 'english', 'With the mind not moving towards any other thing, made steadfast through the practice of habitual meditation, and constantly meditating, one goes to the Supreme Person, the Resplendent, O Arjuna.'),
('7c896585-7c40-51d0-8142-ab32d98aa1cb'::uuid, '024c5d09-14df-5802-8f77-980da8a78b4f'::uuid, 'gambhirananda', 'english', 'He who meditates on the Omniscient, the Ancient, the Ruler, subtler than the subtle, the Ordainer of everything, of inconceivable form, effulgent like the sun, and beyond darkness—he attains the Supreme Person.'),
('9f6b18db-48ce-5e09-83da-d032b6a900c5'::uuid, '024c5d09-14df-5802-8f77-980da8a78b4f'::uuid, 'sivananda', 'english', 'Whosoever meditates on the Omniscient, the Ancient, the Ruler of the whole world, minuter than an atom, the supporter of all, of inconceivable form, effulgent like the sun and beyond the darkness of ignorance.'),
('e70489ac-cd6b-5871-b413-7ad9762faa21'::uuid, '7740a559-0254-5e03-b5b0-0e24bb5099e1'::uuid, 'gambhirananda', 'english', 'At the time of death, having fully fixed the Prana (vital force) between the eyebrows with an unwavering mind, and being imbued with devotion as well as the strength of concentration, he reaches that resplendent Supreme Person.'),
('0c178ff0-81b4-5705-8b1a-565337a9f5ed'::uuid, '7740a559-0254-5e03-b5b0-0e24bb5099e1'::uuid, 'sivananda', 'english', 'At the time of death, with an unwavering mind, endowed with devotion, by the power of Yoga, fixing the whole life-breath in the middle of the two eyebrows, he reaches that resplendent Supreme Person.'),
('d34c8bcd-f84e-5f9f-9132-4a08fd15b28e'::uuid, '229f7af3-6bfa-5243-9fac-87d086cd898c'::uuid, 'gambhirananda', 'english', 'I will briefly tell you about that immutable Goal which the knowers of the Vedas declare; those who are diligent, free from attachment, and aspire for it, enter into it. People practice celibacy for it.'),
('b9f54a17-f232-5838-a168-8c4e33756d94'::uuid, '229f7af3-6bfa-5243-9fac-87d086cd898c'::uuid, 'sivananda', 'english', 'That which is declared to be Imperishable by those who know the Vedas, that which the self-controlled (ascetics or Sannyasins) and passion-free enter, that goal, desiring which celibacy is practised, I will declare to thee in brief.'),
('923e55d8-539a-5bc7-98e1-2e9964036823'::uuid, 'f2222c2c-776e-51cf-840f-47309970f4d2'::uuid, 'gambhirananda', 'english', 'Having controlled all the senses, confined the mind in the heart, and fixed his own vital force in the head, he should remain firm in yoga.'),
('efc18560-187d-5eec-9a6b-5888fec5afd5'::uuid, 'f2222c2c-776e-51cf-840f-47309970f4d2'::uuid, 'sivananda', 'english', 'Having closed all the gates, confined the mind in the heart, and fixed the life-breath in the head, engage in the practice of concentration.'),
('5cbf0c21-bc72-579b-868d-7cbd97b5f3fa'::uuid, '2c463b87-9b9e-517f-8805-2a457aebb10c'::uuid, 'gambhirananda', 'english', 'He who departs, leaving the body while uttering the single syllable, "Om," which is Brahman, and thinking of Me, attains the supreme Goal.'),
('7f5a3c9f-7277-5180-9d45-22483c4a4711'::uuid, '2c463b87-9b9e-517f-8805-2a457aebb10c'::uuid, 'sivananda', 'english', 'Uttering the one-syllabled Om, the Brahman, and remembering Me, he who departs, leaving the body, attains the Supreme Goal.'),
('6d139a35-bcdb-5d46-9de4-1b6a07d23596'::uuid, '36a57b78-8af1-5f62-ac68-67c2b3e81294'::uuid, 'gambhirananda', 'english', 'O son of Prtha, to that yogi of constant concentration and single-minded attention, who remembers Me uninterruptedly and for a long time, I am easily attained.'),
('c06ad2b7-81fa-53d5-b6bc-9a93061ed699'::uuid, '36a57b78-8af1-5f62-ac68-67c2b3e81294'::uuid, 'sivananda', 'english', 'I am easily attainable by that ever-steadfast yogi who constantly and daily remembers me for a long time, not thinking of anything else with a single-minded or one-pointed focus, O Partha.'),
('c360a701-0c51-50ae-ae61-ed4974215b60'::uuid, '079f240e-3b90-5584-a27a-4e75cfc546a2'::uuid, 'gambhirananda', 'english', 'As a result of reaching Me, the exalted ones who have attained the highest perfection do not get rebirth, which is an abode of sorrows and is impermanent.'),
('25351699-2e70-5c64-870b-96c86c2f3ce2'::uuid, '079f240e-3b90-5584-a27a-4e75cfc546a2'::uuid, 'sivananda', 'english', 'Having attained Me, these great souls do not take birth again here—a place of pain and impermanence—but have reached the highest perfection of liberation.'),
('37d57739-fa65-5c41-8900-fc91b8dac40d'::uuid, '2b8cb7cf-d821-519c-adaa-112bbecf09d2'::uuid, 'gambhirananda', 'english', 'O Arjuna, all the worlds together with the world of Brahma are subject to return. But, O son of Kunti, there is no return after reaching Me.'),
('3f8a6b51-271e-5103-bc94-d0c808b8f7da'::uuid, '2b8cb7cf-d821-519c-adaa-112bbecf09d2'::uuid, 'sivananda', 'english', 'All the worlds, including the world of Brahma, are subject to return again, O Arjuna; but he who reaches Me, O son of Kunti, has no rebirth.'),
('d22c6fa2-3ec2-5e8b-b994-97173fe86e7f'::uuid, 'e59761d3-66f8-540d-89bb-4ecb7fd44773'::uuid, 'gambhirananda', 'english', 'Those people who know what day and night are, know the day of Brahma which ends in a thousand yugas, and His night which also ends in a thousand yugas.'),
('d5247ab1-ad67-5e06-b7f2-66ae8e8c777f'::uuid, 'e59761d3-66f8-540d-89bb-4ecb7fd44773'::uuid, 'sivananda', 'english', 'Those who know the day of Brahma, which lasts a thousand Yugas, and the night, which also lasts a thousand Yugas, know day and night.'),
('2e5f6f85-1b69-5494-a9fd-54facd2747f1'::uuid, '8b2e2dff-85ef-5fb8-a057-118fd1e19f0c'::uuid, 'gambhirananda', 'english', 'With the coming of day, all manifested things emerge from the Unmanifest, and when night comes, they merge into that which is called the Unmanifested.'),
('37d5631b-575c-5aea-8b95-2d14b8f1a457'::uuid, '8b2e2dff-85ef-5fb8-a057-118fd1e19f0c'::uuid, 'sivananda', 'english', 'From the Unmanifested, all the manifested worlds proceed upon the arrival of the ''day''; upon the arrival of the ''night'', they dissolve indeed into that which is known as the Unmanifested.'),
('5a490cce-cc94-5bd4-aa31-23a55bf5df6b'::uuid, 'd82bcfff-8d2c-53b9-8e56-cacfd5830a74'::uuid, 'gambhirananda', 'english', 'O son of Prtha, after being born again and again, that very multitude of beings disappears of its own accord at the approach of night. It comes to life again at the approach of day.'),
('559aa2f2-ac62-59d7-a105-44159de7e3d5'::uuid, 'd82bcfff-8d2c-53b9-8e56-cacfd5830a74'::uuid, 'sivananda', 'english', 'This same multitude of beings, being born again and again, helplessly dissolves, O Arjuna, into the Unmanifested at the coming of the night and comes forth at the coming of the day.'),
('c6f89c7a-58c1-5407-877d-63bff536a325'::uuid, 'a5f52f99-5d8e-540f-99e9-727da5167afc'::uuid, 'gambhirananda', 'english', 'But distinct from that Unmanifested is the other eternal, unmanifest Reality, who does not get destroyed when all beings are destroyed.'),
('9563d821-6b6a-51e3-9852-fe3642999895'::uuid, 'a5f52f99-5d8e-540f-99e9-727da5167afc'::uuid, 'sivananda', 'english', 'But verily, there exists higher than this Unmanifested, another Unmanifested Eternal, which is not destroyed even when all beings are destroyed.'),
('e07bd4d2-2618-542f-a6d3-d7d42da2d89f'::uuid, '4dc2b0b4-46c9-5af9-a6e8-ed3a53020ce0'::uuid, 'gambhirananda', 'english', 'They call Him who has been mentioned as the Unmanifested, the Immutable, the supreme Goal. That is the supreme abode of Mine, from which they do not return once they reach it.'),
('76635250-e40b-579d-8dc2-8769ce0e4eae'::uuid, '4dc2b0b4-46c9-5af9-a6e8-ed3a53020ce0'::uuid, 'sivananda', 'english', 'What is known as the Unmanifested and the Imperishable, That is said to be the highest goal. Those who reach It do not return (to this Samsara). That is My supreme abode (place or state).'),
('43ae425a-de0f-5691-ab66-31ada6c63d8b'::uuid, '9b80e195-8bd7-5ba2-a1bd-888f218a3ae8'::uuid, 'gambhirananda', 'english', 'O son of Prtha, that supreme Person—in whom all beings are included and by whom all this is pervaded—is, indeed, reached through one-pointed devotion.'),
('d87574ad-bf79-59d9-b15c-814190455a6e'::uuid, '9b80e195-8bd7-5ba2-a1bd-888f218a3ae8'::uuid, 'sivananda', 'english', 'That highest Purusha, O Arjuna, is attainable by unswerving devotion to Him alone, within Whom all beings dwell and by Whom all this is pervaded.'),
('8d3b0c55-0ceb-5c8e-8a04-a7ad2b3f66a2'::uuid, 'a15d2915-ab75-5147-b69e-83ffb90778de'::uuid, 'gambhirananda', 'english', 'O best of the Bharata dynasty, I shall now speak of that time by which the yogis depart and attain the State of Non-return, and also the State of Return.'),
('30ce69a1-eb30-52b7-893a-dcb38858a3d4'::uuid, 'a15d2915-ab75-5147-b69e-83ffb90778de'::uuid, 'sivananda', 'english', 'Now I will tell you, O chief of the Bharatas, the times of departure at which the Yogis will return or not return.'),
('7c859f21-b0cf-5953-aa67-097ef3e73730'::uuid, '46e0ee3c-ed51-5493-9e72-24f889d6ad5e'::uuid, 'gambhirananda', 'english', 'Fire, light, daytime, the bright fortnight, the six months of the northern solstice—by following this path, persons who are knowers of Brahman attain Brahman when they die.'),
('6bc5100a-5b36-50cd-9553-32cf22d4a442'::uuid, '46e0ee3c-ed51-5493-9e72-24f889d6ad5e'::uuid, 'sivananda', 'english', 'Fire, light, daytime, the bright fortnight, the six months of the northern path of the sun (the northern solstice) departing, then men who know Brahman go to Brahman.'),
('c92aba39-8a2e-53d6-afed-d4c976aaf7cd'::uuid, 'c1a256da-a274-55bd-9628-73e55c1d39ca'::uuid, 'gambhirananda', 'english', 'Following this Path, the yogi, having reached the lunar light, returns, smoke, night, as also the dark fortnight and the six months of the Southern solstice.'),
('cc3b7566-ae91-5f46-95f7-09da36c7c71a'::uuid, 'c1a256da-a274-55bd-9628-73e55c1d39ca'::uuid, 'sivananda', 'english', 'Attaining the lunar light through smoke, night time, the dark fortnight, and the six months of the southern path of the sun (the southern solstice), the yogi returns.'),
('40850a01-c2cb-510b-af11-1fe77f9cc49c'::uuid, '82d794a7-e2da-5c17-bc6b-87f6850ef802'::uuid, 'gambhirananda', 'english', 'These two paths of the world, which are white and black, are indeed considered eternal. Through one, a person goes to the state of non-return; through the other, they return again.'),
('edb16472-48f5-5196-a675-c3b575db3f79'::uuid, '82d794a7-e2da-5c17-bc6b-87f6850ef802'::uuid, 'sivananda', 'english', 'The bright and dark paths of the world are thought to be eternal; one leads to no return, and the other leads to return.'),
('2a85518c-55ca-5101-86a5-cf3e8b3846c8'::uuid, '64ecf1da-d332-5de6-9cc6-29542ebcdbd3'::uuid, 'gambhirananda', 'english', 'O son of Prtha, no yogi—one steadfast in meditation—whosoever has known these two courses becomes deluded. Therefore, O Arjuna, be steadfast in yoga at all times.'),
('2547011b-abf0-5b42-8c8b-aa0055e65ade'::uuid, '64ecf1da-d332-5de6-9cc6-29542ebcdbd3'::uuid, 'sivananda', 'english', 'Knowing these paths, O Arjuna, no yogi is deluded; therefore, at all times, be steadfast in yoga.'),
('de06ebde-af51-53eb-a00c-1eda7ec0e774'::uuid, '6ed58d47-8424-5726-a484-f983fe7f90e4'::uuid, 'gambhirananda', 'english', 'Having known this, the yogi transcends all the results of righteous deeds declared in the Vedas, sacrifices, austerities, and charities, and reaches the primordial, supreme state.'),
('c5d8e7d6-f430-5c5e-a32a-8a9f36adac01'::uuid, '6ed58d47-8424-5726-a484-f983fe7f90e4'::uuid, 'sivananda', 'english', 'Whatever fruit of merit is declared (in the scriptures) to accrue from (the study of) the Vedas, (the performance of) sacrifices, (the practice of) austerities, and gifts, beyond all this goes the Yogi, having known this; and he attains to the Supreme, Primeval (first or ancient) Abode.'),
('8c84d208-7b95-5cbc-918a-1ff47802f12a'::uuid, '5cb6ec4b-1ec9-534d-9dfd-ab24b0b469ec'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said: However, to you who are not given to cavilling, I shall speak of this highest secret itself, which is knowledge combined with experience, by realizing which you shall be free from evil.'),
('bef8e998-ac0d-5181-b7f8-4ed017c9a197'::uuid, '5cb6ec4b-1ec9-534d-9dfd-ab24b0b469ec'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "I shall now declare to thee, who does not cavil, the greatest secret—the knowledge combined with experience (Self-realisation). Having known this, thou shalt be free from evil."'),
('a0e0cc3c-e3c8-5e26-a121-6d963428c09c'::uuid, '2a712fc2-43bf-57b0-9256-6951f09756f7'::uuid, 'gambhirananda', 'english', 'This is the sovereign knowledge, the sovereign profundity, the best sanctifier; directly realizable, righteous, very easy to practice, and imperishable.'),
('a708fc97-c785-5559-8fe4-72132ddf6fa3'::uuid, '2a712fc2-43bf-57b0-9256-6951f09756f7'::uuid, 'sivananda', 'english', 'This is the royal science, the royal secret, the supreme purifier, realizable by direct intuitive knowledge, according to righteousness, very easy to perform and imperishable.'),
('f5337c95-0633-50b7-adc0-f37896baf158'::uuid, 'e37da1cd-b33e-5a8a-929b-6273dfa406de'::uuid, 'gambhirananda', 'english', 'O destroyer of foes, those who are disregarding this Dharma (knowledge of the Self) certainly go round and round, without reaching Me, along the path of transmigration which is fraught with death.'),
('09e918e8-e12a-51b5-b984-8a4029f87a16'::uuid, 'e37da1cd-b33e-5a8a-929b-6273dfa406de'::uuid, 'sivananda', 'english', 'Those who have no faith in this Dharma, O Parantapa, return to the path of this world without attaining Me.'),
('ea569df0-b613-5862-9801-0f2c94d43c33'::uuid, '09a9275c-8aed-53ec-8d58-3dfb46927cc6'::uuid, 'gambhirananda', 'english', 'This whole world is pervaded by Me in My unmanifest form. All beings exist in Me, but I am not contained within them!'),
('53c86fc4-fde5-5c34-b219-832176d06e4c'::uuid, '09a9275c-8aed-53ec-8d58-3dfb46927cc6'::uuid, 'sivananda', 'english', 'All of this world is pervaded by Me in My unmanifest aspect; all beings exist within Me, but I do not dwell within them.'),
('f928b4eb-9ac5-5e41-8baf-09fa2d8ab019'::uuid, '506a222e-9e68-55cb-aee2-53e4a265d737'::uuid, 'gambhirananda', 'english', 'Neither do the beings dwell in Me. Behold My divine Yoga! I am the sustainer and originator of beings, but My Self is not contained within the beings.'),
('f5dc2764-dc3d-5669-8b84-4ea4a9016950'::uuid, '506a222e-9e68-55cb-aee2-53e4a265d737'::uuid, 'sivananda', 'english', 'Nor do beings exist in Me (in reality); behold, My divine Yoga, which supports all beings, but does not dwell in them, is My Self, the efficient cause of beings.'),
('c72e1bc1-0aca-5954-a81a-2fd2a4443ee0'::uuid, 'b4c94307-c261-526e-8e49-c014d748788a'::uuid, 'gambhirananda', 'english', 'Understand thus that just as the voluminous wind, moving everywhere, is ever present in space, similarly all beings abide in Me.'),
('d459b155-ff18-5676-92d7-110292e992b8'::uuid, 'b4c94307-c261-526e-8e49-c014d748788a'::uuid, 'sivananda', 'english', 'As the mighty wind, moving everywhere, always rests in the ether, so too, know that all beings rest in Me.'),
('01c7f107-27e7-5361-9b0f-8a52cfb4fd7f'::uuid, 'b1bfddf1-d293-5863-83b3-520157d7d7ba'::uuid, 'gambhirananda', 'english', 'O son of Kunti, all the beings at the end of a cycle go back to My Prakrti. At the beginning of a cycle, I project them forth again.'),
('fabd4ad9-3c5f-58c3-adde-b5e8f43eab8b'::uuid, 'b1bfddf1-d293-5863-83b3-520157d7d7ba'::uuid, 'sivananda', 'english', 'All beings, O Arjuna, go into My Nature at the end of a Kalpa; I send them forth again at the beginning of the next Kalpa.'),
('731a01cc-41d8-5ece-982a-f408822313c7'::uuid, '3dd3f0fa-a064-5bbe-93d4-c827b38c0501'::uuid, 'gambhirananda', 'english', 'Keeping My own prakṛti under control, I project forth again and again this multitude of beings, which are powerless due to the influence of their own nature.'),
('9b9373b2-719b-55d6-9f5a-63a13e92dbde'::uuid, '3dd3f0fa-a064-5bbe-93d4-c827b38c0501'::uuid, 'sivananda', 'english', 'Animating My Nature, I again and again send forth all this multitude of beings, helpless under the force of Nature.'),
('643a65a9-8246-5527-9305-2177ee210293'::uuid, '8da766e6-e15a-5b0d-a402-f53cbb73d6fd'::uuid, 'gambhirananda', 'english', 'O Dhananjaya, those actions do not bind Me, for I remain unconcerned and unattached to them.'),
('be5b1478-77db-5c3c-be70-212e733afcb9'::uuid, '8da766e6-e15a-5b0d-a402-f53cbb73d6fd'::uuid, 'sivananda', 'english', 'These acts do not bind Me, O Arjuna, sitting as one indifferent, unattached to those acts.'),
('70595bc2-39b9-5cc8-8564-f6248cc42f52'::uuid, '4b08a8c8-fd3f-5a51-908e-d8d7816f818c'::uuid, 'gambhirananda', 'english', 'Under Me as the supervisor, the Prakrti produces the world of the moving and the non-moving things. Owing to this, O son of Kunti, the world revolves.'),
('525d0733-842f-5520-a9e4-fccd03fde0f6'::uuid, '4b08a8c8-fd3f-5a51-908e-d8d7816f818c'::uuid, 'sivananda', 'english', 'Under Me, as supervisor, Nature produces the moving and the unmoving; therefore, O Arjuna, the world revolves.'),
('7f7f7ff4-e1d5-56d5-8802-71c3e4877fe6'::uuid, '05961472-12d9-5efc-b8ea-4e6fc1735f34'::uuid, 'gambhirananda', 'english', 'Not knowing My supreme nature as the Lord of all beings, foolish people disregard Me, who have taken a human form.'),
('aa997eba-ebce-5c21-94ce-63af08c08613'::uuid, '05961472-12d9-5efc-b8ea-4e6fc1735f34'::uuid, 'sivananda', 'english', 'Fools disregard Me, clad in human form, not knowing My higher Being as the great Lord of all beings.'),
('4902fe9a-aece-5f61-be79-5a8bef07f491'::uuid, 'de6eced8-c049-535b-bc8a-31a89afa832e'::uuid, 'gambhirananda', 'english', 'Possessed of vain hopes, vain actions, vain knowledge, and senselessness, they become verily possessed of the deceptive disposition of fiends and demons.'),
('b7cb7e33-c58e-58bc-b72a-6a3bb3e78f86'::uuid, 'de6eced8-c049-535b-bc8a-31a89afa832e'::uuid, 'sivananda', 'english', 'They are possessed of the deceitful nature of demons and undivine beings, filled with vain hopes, vain actions, and vain knowledge that is senseless.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('3be5f741-998d-5692-8148-df6adfe3bc92'::uuid, '47b344ec-b43e-5fde-85d8-7dee4b90fe88'::uuid, 'gambhirananda', 'english', 'O son of Prtha, the noble ones, being possessed of divine nature, surely adore Me with single-mindedness, knowing Me to be the immutable source of all objects.'),
('8a90b6e8-2a1e-5e96-957b-90b0deefdcd5'::uuid, '47b344ec-b43e-5fde-85d8-7dee4b90fe88'::uuid, 'sivananda', 'english', 'But the great souls, O Arjuna, partaking of My divine nature, worship Me with a single-minded devotion, knowing Me as the imperishable source of all beings.'),
('a1199997-6e92-5b01-b4f6-e2c3c49c2983'::uuid, 'db488ea7-8b3f-5c9a-ad38-9b161f25d24a'::uuid, 'gambhirananda', 'english', 'Always glorifying Me and striving, the men of firm vows worship Me by paying obeisance to Me and being ever endowed with devotion.'),
('ae9f03ed-aeb4-58d1-b77e-1b8c5929f7aa'::uuid, 'db488ea7-8b3f-5c9a-ad38-9b161f25d24a'::uuid, 'sivananda', 'english', 'Always glorifying Me, striving, firm in their vows, prostrating themselves before Me, they worship Me with steadfast devotion.'),
('f043db68-4a11-50e9-b3ab-79109b3a5911'::uuid, '2b102cad-2dba-5c60-ae6a-aab71303d17d'::uuid, 'gambhirananda', 'english', 'Others indeed worship Me by exclusively adoring through the sacrifice of the knowledge of oneness; (others worship Me) in many ways, and (others) as the multiform existing in various forms.'),
('88573517-6e9b-5a2b-90b5-928ae4c61c34'::uuid, '2b102cad-2dba-5c60-ae6a-aab71303d17d'::uuid, 'sivananda', 'english', 'Others also, sacrificing with the wisdom-sacrifice, worship Me, the All-Faced, as one, distinct, and manifold.'),
('6a416782-90dd-5a41-9749-786586df8324'::uuid, 'f8f0861e-e2ba-599d-84da-238dd603e697'::uuid, 'gambhirananda', 'english', 'I am the ritual, I am the sacrifice, I am the oblation, I am the medicinal herb, I am the mantra, I am the clarified butter, I am the fire, and I am the act of offering.'),
('74cb1703-49b0-52aa-9597-82a193ecc6e8'::uuid, 'f8f0861e-e2ba-599d-84da-238dd603e697'::uuid, 'sivananda', 'english', 'I am Kratu; I am Yajna; I am the offering to the manes; I am the medicinal herbs and all plants; I am the Mantra; I am also the ghee or melted butter; I am the fire; I am the oblation.'),
('0a8669af-d8bb-5014-85fe-83498b918ce1'::uuid, 'cdcebaf2-b698-5af0-b875-90b9e0b044f5'::uuid, 'gambhirananda', 'english', 'Of this world, I am the father, mother, ordainer, and grandfather; I am the knowable, the sanctifier, the syllable Om, as well as the Rk, Sama, and Yajus.'),
('c54f0653-7636-5168-8bab-2b6a3295f0b4'::uuid, 'cdcebaf2-b698-5af0-b875-90b9e0b044f5'::uuid, 'sivananda', 'english', 'I am the father of this world, the mother, the dispenser of the fruits of actions, and the grandfather; the one thing to be known, the purifier, the sacred monosyllable (Om), and also the Rik, Sama, and Yajur Vedas.'),
('08f3a160-e713-5ee0-b360-b6ae828d4632'::uuid, '74f0ea7d-9ca6-5dba-8c1d-be323042c711'::uuid, 'gambhirananda', 'english', 'I am the fruit of actions, the nourisher, the Lord, witness, abode, refuge, friend, origin, end, foundation, store, and the imperishable seed.'),
('64456c08-5fa9-5b34-8018-162876c3c132'::uuid, '74f0ea7d-9ca6-5dba-8c1d-be323042c711'::uuid, 'sivananda', 'english', 'I am the goal, the supporter, the Lord, the witness, the abode, the shelter, the friend, the origin, the dissolution, the foundation, the treasure-house, and the imperishable seed.'),
('16db5c07-9bf4-5eee-959c-2de39fc772ea'::uuid, 'e1578302-c768-5fc4-91d1-1ec996faf21e'::uuid, 'gambhirananda', 'english', 'O Arjuna, I give heat, I withhold and pour down rain; I am verily the nectar, and also death, existence, and non-existence.'),
('4b33c82a-7cd6-586e-b2b0-9ba19955aa67'::uuid, 'e1578302-c768-5fc4-91d1-1ec996faf21e'::uuid, 'sivananda', 'english', 'As the sun, I give heat; I withhold and send forth the rain; I am immortality and also death, existence and non-existence, O Arjuna.'),
('0ef04c83-7a44-50f0-aa2b-961ad33d2d5b'::uuid, '766677ca-b236-58ac-ac79-b5b6b503dafd'::uuid, 'gambhirananda', 'english', 'Those who are versed in the Vedas, who drink Soma and are purified of sin, pray for the heavenly goal by worshipping Me through sacrifices. Having reached the place (world) of the king of gods, which is the result of righteousness, they enjoy the divine pleasure of the gods in heaven.'),
('6cd5b0fd-b82f-5356-8dac-2de3961e5c0a'::uuid, '766677ca-b236-58ac-ac79-b5b6b503dafd'::uuid, 'sivananda', 'english', 'The knowers of the three Vedas, the drinkers of Soma, purified of all sins, worshipping Me through sacrifices, pray for the way to heaven; they reach the holy world of the Lord of the gods and enjoy the divine pleasures of the gods in heaven.'),
('b439b742-5c03-5114-8663-cea648300866'::uuid, '23080adf-dde2-5fb1-acee-43185708e0c7'::uuid, 'gambhirananda', 'english', 'After having enjoyed that vast heavenly world, they enter into the human world upon the exhaustion of their merit. Thus, those who follow the rites and duties prescribed in the three Vedas, and are desirous of pleasures, attain the state of coming and going.'),
('80812a10-a9c1-555d-a92e-ad49b359411a'::uuid, '23080adf-dde2-5fb1-acee-43185708e0c7'::uuid, 'sivananda', 'english', 'They, having enjoyed the vast heaven, enter the world of mortals when their merit is exhausted; thus abiding by the injunctions of the three (Vedas) and desiring objects of desires, they attain to the state of coming and going.'),
('0fc96f28-1947-5834-9126-baea0a72ba67'::uuid, 'b40d8e98-4a3a-542f-8a71-28686d959b51'::uuid, 'gambhirananda', 'english', 'Those persons who, becoming non-different from Me and meditating, worship Me everywhere, for them, who are ever attached to Me, I arrange for securing what they lack and preserving what they have.'),
('a848abf0-3f9a-52a0-861f-5306c3aca440'::uuid, 'b40d8e98-4a3a-542f-8a71-28686d959b51'::uuid, 'sivananda', 'english', 'For those men who worship Me alone, thinking of no one else, for those ever-united, I secure what they have not already possessed and preserve what they already possess.'),
('d1f7ca67-14d3-5b8f-9e11-2b918c9c16d0'::uuid, '5f5fc0f4-0c6e-53af-8067-1f7f7f4efb04'::uuid, 'gambhirananda', 'english', 'Even those who, being devoted to other deities and endowed with faith, worship them, they also, O son of Kunti, worship Me alone, though following the wrong method.'),
('acfc4b28-5ffe-5080-85b7-ec99ee9c145a'::uuid, '5f5fc0f4-0c6e-53af-8067-1f7f7f4efb04'::uuid, 'sivananda', 'english', 'Even those devotees who, endowed with faith, worship other gods, worship Me alone, O Arjuna, but by the wrong method.'),
('4a4486c5-7b2c-5227-943c-8dae0671b5de'::uuid, '885a493f-d466-549b-9d95-13be09dc8f6a'::uuid, 'gambhirananda', 'english', 'Indeed, I am the enjoyer and the Lord of all sacrifices, but they do not know Me truly. Therefore, they fall.'),
('0d0fa3f7-9778-5b97-b4b0-0e6733643dac'::uuid, '885a493f-d466-549b-9d95-13be09dc8f6a'::uuid, 'sivananda', 'english', 'For I alone am the enjoyer and Lord of all sacrifices; but they do not know Me in reality, and thus they return to this mortal world.'),
('257ae4fb-2564-583f-9a21-d2c3bcb389bf'::uuid, '6c482ef0-2212-57e6-a15c-73d2e50b963b'::uuid, 'gambhirananda', 'english', 'Those who worship the gods reach the gods; the worshippers of the manes go to the manes; the devotees of the Beings reach the Beings; and those who worship Me come to Me.'),
('d0dfd9fb-a238-50b1-953a-fd025bcf4e02'::uuid, '6c482ef0-2212-57e6-a15c-73d2e50b963b'::uuid, 'sivananda', 'english', 'The worshippers of the gods go to them; the ancestor-worshippers go to the manes; the worshippers of the deities who preside over the elements go to them; but My devotees come to Me.'),
('633672c4-21be-51c8-a134-9e34e8c13825'::uuid, '98246330-d83a-5901-85db-65a623a260f0'::uuid, 'gambhirananda', 'english', 'Whoever offers Me with devotion—a leaf, a flower, a fruit, or water—I accept that gift of the pure-hearted man which has been presented devotionally.'),
('8d12f7ce-3f75-53fc-b7af-192e816591ae'::uuid, '98246330-d83a-5901-85db-65a623a260f0'::uuid, 'sivananda', 'english', 'Whoever offers Me with devotion a leaf, a flower, a fruit, or a little water, that, so offered devotedly by the pure-minded, I accept.'),
('457f5be7-fc90-5ffd-b3e2-6eacd4697e87'::uuid, '2c8bb0fc-cc1c-58b0-b2c9-13d158b269d5'::uuid, 'gambhirananda', 'english', 'O son of Kunti, whatever you do, whatever you eat, whatever you offer as a sacrifice, whatever you give, and whatever austerities you undertake—all of that you offer to Me.'),
('89e367c2-dfa2-5ea1-a21b-71961cf74a1a'::uuid, '2c8bb0fc-cc1c-58b0-b2c9-13d158b269d5'::uuid, 'sivananda', 'english', 'Whatever you do, whatever you eat, whatever you offer in sacrifice, whatever you give, whatever austerity you practice, O Arjuna, do it as an offering to Me.'),
('a9607df6-6396-54d7-a029-b826687dd5e5'::uuid, '425c0695-0058-54d2-b717-00f501597a7c'::uuid, 'gambhirananda', 'english', 'Thus, you will become free from bondage in the form of actions which are productive of good and bad results. Having your mind imbued with the yoga of renunciation and becoming free, you will attain Me.'),
('9a462420-6029-595e-a53e-aa5718e9de33'::uuid, '425c0695-0058-54d2-b717-00f501597a7c'::uuid, 'sivananda', 'english', 'Thus, you shall be freed from the bonds of actions yielding good and evil fruits; with the mind steadfast in the Yoga of renunciation, and liberated, you shall come to Me.'),
('1e017c3c-faf5-5cdc-926b-26d6699efc7b'::uuid, 'ebddad50-4e48-5c8b-94f7-5680a8fe296a'::uuid, 'gambhirananda', 'english', 'I am impartial towards all beings; to Me there is none detestable or none dear. But those who worship Me with devotion, they exist in Me, and I too exist in them.'),
('ae808cc7-dc73-5a3b-a7f4-30995fcae8e9'::uuid, 'ebddad50-4e48-5c8b-94f7-5680a8fe296a'::uuid, 'sivananda', 'english', 'I am the same to all beings; there is none hateful or dear to Me; but those who worship Me with devotion are in Me, and I am also in them.'),
('3dba2184-41d6-50e5-8a5f-e09e2bae6889'::uuid, '1bc6778c-5496-57e7-ad98-579f9a69de9f'::uuid, 'gambhirananda', 'english', 'Even if a man of very bad conduct worships Me with single-minded devotion, he is to be considered truly good; for he has rightly resolved.'),
('714ff8fb-d163-5f17-93d9-c3efdfd550c5'::uuid, '1bc6778c-5496-57e7-ad98-579f9a69de9f'::uuid, 'sivananda', 'english', 'Even if the most sinful worships Me, with devotion to no one else, he should indeed be regarded as righteous, for he has rightly resolved.'),
('e29dc8cc-50a5-5922-b9fc-6d604a1f89cd'::uuid, '3cd49e7d-5d58-512f-a200-84057d3a356e'::uuid, 'gambhirananda', 'english', 'He soon becomes possessed of a virtuous mind; he attains everlasting peace. Do you proclaim boldly, O son of Kunti, that My devotee will not be ruined.'),
('51604e68-6fe7-5dcc-960a-e44b581d7a12'::uuid, '3cd49e7d-5d58-512f-a200-84057d3a356e'::uuid, 'sivananda', 'english', 'Soon he becomes righteous and attains eternal peace; O Arjuna, proclaim thou for certain that My devotee never perishes.'),
('2723ab17-cf62-5776-9e4d-d0bb636f6b5b'::uuid, '740bbc20-32f0-5666-a7f3-d3f03d5d9bde'::uuid, 'gambhirananda', 'english', 'For, O son of Prtha, even those who are born of sin-women, Vaisyas, as well as Sudras—[S.''s construction of this portion is: women, Vaisyas as well as Sudras, and even others who are born of sin (i.e., those who are born low and are of vile deeds, viz Mlecchas, Pukkasas and others). M.S. also takes papa-yonayah (born of sin) as a separate phrase, and classifies women and others only as those darred from Vedic study, etc.-Tr.]—even they reach the highest Goal by taking shelter under Me.'),
('5c7590ad-b34f-55b7-b5da-14738d3f97dc'::uuid, '740bbc20-32f0-5666-a7f3-d3f03d5d9bde'::uuid, 'sivananda', 'english', 'For, taking refuge in Me, they who, O Arjuna, may be of a sinful birth—women, Vaisyas, and Sudras—attain the Supreme Goal.'),
('ce10aa14-ab7e-5f42-be46-1de2449533ae'::uuid, 'ee1f230f-d590-5c9a-b999-43eeb29b9230'::uuid, 'gambhirananda', 'english', 'What of the holy Brahmanas and devoted, wise sages? Having come to this fleeting, miserable world, worship Me.'),
('eb8e9f84-fa76-571d-bc36-0c7eddf0a19a'::uuid, 'ee1f230f-d590-5c9a-b999-43eeb29b9230'::uuid, 'sivananda', 'english', 'How much more easily, then, do Brahmins and devoted royal saints attain the goal? Having come to this impermanent and unhappy world, do thou worship Me.'),
('9fe3f478-8ab2-5df9-9af6-5cac577eee35'::uuid, 'ed0a1204-c94b-5828-800a-7abfd1772b21'::uuid, 'gambhirananda', 'english', 'Having your mind fixed on Me, be devoted to Me, sacrifice to Me, and bow down to Me. By concentrating your mind and accepting Me as the supreme goal, you shall surely attain Me, who am thus the Self.'),
('f0f4928f-9a33-5a52-8834-e895cbdca1b2'::uuid, 'ed0a1204-c94b-5828-800a-7abfd1772b21'::uuid, 'sivananda', 'english', 'Fix your mind on Me; be devoted to Me; sacrifice to Me; bow down to Me; having thus united your whole self to Me, taking Me as the supreme goal, you will come to Me.'),
('e7040868-71c3-567a-b53f-8fdc9177e2c1'::uuid, '10f6398d-c4dc-5da9-b592-8ba3dca1afdf'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, O mighty-armed one, listen once more to My supreme utterance, which I, wishing for your welfare, shall speak to you who take delight in it.'),
('a6c95bcf-c74a-52d8-8ac4-ddadeb09ea65'::uuid, '10f6398d-c4dc-5da9-b592-8ba3dca1afdf'::uuid, 'sivananda', 'english', 'The Blessed Lord said, Again, O mighty-armed Arjuna, listen to my supreme word which I will declare to you, who are beloved, for your welfare.'),
('757e1eae-82be-5fee-b0f5-fc0730606b07'::uuid, '034c4f59-c649-5d7a-bfc6-0c5e6523576e'::uuid, 'gambhirananda', 'english', 'Neither the gods nor the great sages know My majesty, for I am the source of them all in all respects.'),
('a61da6e2-cf08-5a0d-9cfb-9d3d03ac06fe'::uuid, '034c4f59-c649-5d7a-bfc6-0c5e6523576e'::uuid, 'sivananda', 'english', 'Neither the hosts of the gods nor the great sages know My origin; for I am the source of all the gods and the great sages in every way.'),
('bfe151c5-e18f-57c1-808f-271eaa399c16'::uuid, 'ad968164-2c65-5857-a67a-532cc4fa231c'::uuid, 'gambhirananda', 'english', 'He who knows Me—the birthless, beginningless, and great Lord of the worlds—he, the undeluded one among mortals, becomes freed from all sins.'),
('c047d6c3-47c9-5cda-bd29-c729ff2c1d85'::uuid, 'ad968164-2c65-5857-a67a-532cc4fa231c'::uuid, 'sivananda', 'english', 'He who knows Me as unborn and beginningless, as the great Lord of the worlds, he among mortals is undeluded and is liberated from all sins.'),
('33bcd8b0-7fb1-5171-a1ec-d8e005336423'::uuid, '5ed9ce8d-5da8-5a65-b6e1-5ae4baaa07ca'::uuid, 'gambhirananda', 'english', 'Intelligence, wisdom, non-delusion, forgiveness, truth, control of the external organs, control of the internal organs, happiness, sorrow, birth, death, and fearlessness;'),
('7855b3ba-ffc7-539b-84f1-a89fd00b4754'::uuid, '5ed9ce8d-5da8-5a65-b6e1-5ae4baaa07ca'::uuid, 'sivananda', 'english', 'Intellect, wisdom, non-delusion, forgiveness, truth, self-restraint, calmness, happiness, pain, existence or birth, non-existence or death, fear, and also fearlessness.'),
('8ec7f675-685d-57a3-8164-c3e2a2f44cb5'::uuid, '13ca1067-53c0-578b-a7fd-8c8d1eab20aa'::uuid, 'gambhirananda', 'english', 'Non-injury, equanimity, satisfaction, austerity, charity, fame, and infamy—these different dispositions of beings spring from Me alone.'),
('6625e814-7c5d-560e-a621-c4bfb58b9a4e'::uuid, '13ca1067-53c0-578b-a7fd-8c8d1eab20aa'::uuid, 'sivananda', 'english', 'Non-injury, equanimity, contentment, austerity, beneficence, fame, and ill-fame—these different qualities of beings arise from Me alone.'),
('3c380c06-6b62-5175-9591-9e123ffb6407'::uuid, '08e901be-ad05-5cad-a38f-b24dd44d7d25'::uuid, 'gambhirananda', 'english', 'The seven great sages, as well as the four Manus of ancient days, from whom all these creatures in the world have descended, had their thoughts fixed on Me, and they were born from My mind.'),
('c147534e-5df8-5013-b1e6-f1fde346d068'::uuid, '08e901be-ad05-5cad-a38f-b24dd44d7d25'::uuid, 'sivananda', 'english', 'The seven great sages, the ancient four, and the Manus, possessing powers like Mine (due to their minds being fixed on Me), were born from My mind; from them, these creatures have been born in this world.'),
('993415b1-5b62-5b54-9bd5-5a39e70c27a6'::uuid, '64279be0-d27f-5ad6-9319-246653e6c66d'::uuid, 'gambhirananda', 'english', 'One who knows truly this majesty and yoga of Mine, he becomes imbued with unwavering yoga. There is no doubt about it.'),
('451fb134-b84c-523d-ad7c-720482f3b3a2'::uuid, '64279be0-d27f-5ad6-9319-246653e6c66d'::uuid, 'sivananda', 'english', 'He who truly knows these manifold manifestations of My Being and this Yoga-power of Mine, becomes established in unshakable Yoga; there is no doubt about it.'),
('29b93b3e-3bb2-5cdb-aa18-296877228e20'::uuid, '4869a956-b4ea-5734-bcf8-62320e674dc6'::uuid, 'gambhirananda', 'english', 'I am the origin of all; everything moves on due to Me. Realizing this, the wise ones, filled with fervor, adore Me.'),
('828cc8ff-3d75-51f7-b5e1-23d7bace444e'::uuid, '4869a956-b4ea-5734-bcf8-62320e674dc6'::uuid, 'sivananda', 'english', 'I am the source of all; from me everything evolves; Understanding this, the wise, endowed with meditation, worship me.'),
('812d556b-8a21-5d80-903f-b58b3234bd0c'::uuid, '0f2ba58c-f684-5bd5-9040-87d1f64c85b7'::uuid, 'gambhirananda', 'english', 'With their minds fixed on Me, dedicating their lives to Me, enlightening one another, and always speaking of Me, they derive satisfaction and rejoice.'),
('ada7e597-8c42-5a81-bbbc-38fa89462ebf'::uuid, '0f2ba58c-f684-5bd5-9040-87d1f64c85b7'::uuid, 'sivananda', 'english', 'With their minds and lives wholly absorbed in Me, they enlighten each other and ever speak of Me, being satisfied and delighted.'),
('9d16c4ff-8c9c-5265-b7c2-8545191c1e44'::uuid, '7f6ea195-976c-5024-a29c-6245f8dba5fd'::uuid, 'gambhirananda', 'english', 'To those who are ever devoted and worship Me with love, I grant the possession of wisdom that leads them to Me.'),
('fbf6bee2-741e-5c43-a26f-eb0bb76c83d1'::uuid, '7f6ea195-976c-5024-a29c-6245f8dba5fd'::uuid, 'sivananda', 'english', 'To those who are ever steadfast, worshipping me with love, I give the yoga of discrimination, by which they come to me.'),
('692e5f91-14d2-500b-9fe0-6a882764ccfb'::uuid, '0bec73d2-b93d-5aff-a187-b5bd459758ad'::uuid, 'gambhirananda', 'english', 'Out of compassion for them alone, I, residing in their hearts, destroy the darkness born of ignorance with the luminous lamp of knowledge.'),
('ab76fd60-9fa7-59cc-8526-7ebc35e8b7cf'::uuid, '0bec73d2-b93d-5aff-a187-b5bd459758ad'::uuid, 'sivananda', 'english', 'Out of mere compassion for them, I, dwelling within their selves, destroy the darkness born of ignorance with the luminous lamp of knowledge.'),
('f62e5ed2-b57e-54f8-8c59-c904a270657b'::uuid, '5cb8a5d5-415c-535a-b218-ff85e7ac02e1'::uuid, 'gambhirananda', 'english', 'Arjuna said, "You are the supreme Brahman, the supreme Light, the supreme Sanctifier. All the sages, as well as the divine sage Narada, Asita, Devala, and Vyasa [Although Narada and the other sages are already mentioned by the words ''all the sages'', they are still named separately due to their eminence. Asita is the father of Devala.] call You the eternal divine Person, the Primal God, the Birthless, the Omnipresent; and You Yourself indeed tell me this."'),
('6dfc0f1e-a2be-51e3-91b9-2046938ce8d9'::uuid, '5cb8a5d5-415c-535a-b218-ff85e7ac02e1'::uuid, 'sivananda', 'english', 'Arjuna said, "You are the Supreme Brahman, the supreme abode, the supreme purifier, eternal, divine Person, the primeval God, unborn, and omnipresent."'),
('8db498ed-521f-539b-bcc2-a2970aff3dbd'::uuid, '7d5e5da9-7ea0-5746-a68e-0b9b66127198'::uuid, 'gambhirananda', 'english', 'Arjuna said, "You are the supreme Brahman, the supreme Light, the supreme Sanctifier. All the sages, as well as the divine sage Narada, Asita, Devala, and Vyasa [Although Narada and the other sages are already mentioned by the words ''all the sages'', they are still named separately due to their eminence. Asita is the father of Devala.] call You the eternal divine Person, the Primal God, the Birthless, the Omnipresent; and You Yourself indeed tell me this."'),
('d60be4d1-248c-55c3-acaa-e1161643c593'::uuid, '7d5e5da9-7ea0-5746-a68e-0b9b66127198'::uuid, 'sivananda', 'english', 'All the sages have thus declared Thee, as also the divine sage Narada; so also Asita, Devala, and Vyasa; and now Thou Thyself dost say so to me.'),
('3c5ffcfa-d737-5f03-b37a-fc49822fa12b'::uuid, 'fe918ed7-1928-5440-989d-d37ff9a912e4'::uuid, 'gambhirananda', 'english', 'O Kesava, I accept as true all that You have told me. Certainly, O Lord, neither the gods nor the demons can comprehend Your glory.'),
('c32a2d44-855e-59b9-ba13-fbc1bdd74bc8'::uuid, 'fe918ed7-1928-5440-989d-d37ff9a912e4'::uuid, 'sivananda', 'english', 'I believe all that You have said to me to be true, O Krishna; indeed, O blessed Lord! Neither the gods nor the demons know Your manifestation (origin).'),
('04d31f48-5027-52c7-b4ad-a6b1af8ab0bb'::uuid, '94df8fad-9c4a-5eb1-a40a-0314766bdfa4'::uuid, 'gambhirananda', 'english', 'O Supreme Person, Creator of beings, Lord of beings, God of gods, Lord of the worlds, You alone know Yourself by Yourself.'),
('47abafd2-ff41-5ec3-af90-6013afb6e433'::uuid, '94df8fad-9c4a-5eb1-a40a-0314766bdfa4'::uuid, 'sivananda', 'english', 'Verily, Thou Thyself knowest Thyself by Thyself, O Supreme Person, O source and Lord of all beings, O God of gods, O ruler of the world!'),
('d913e710-c2f7-58fe-873a-8276e84f287f'::uuid, '3eff04d5-6ded-56cc-86bb-7627961bbb80'::uuid, 'gambhirananda', 'english', 'Be pleased to speak in full of Your own divine manifestations, through which You exist pervading these worlds.'),
('fe74fc80-2fc3-5207-8ab8-370431d99ffa'::uuid, '3eff04d5-6ded-56cc-86bb-7627961bbb80'::uuid, 'sivananda', 'english', 'You should indeed tell, without reserve, of your divine glories by which you exist, pervading all these worlds. (No one else can do so.)'),
('59f4495a-afaf-5648-a24c-2a9ce8d9c370'::uuid, 'd99a8d0d-9ee8-550d-905b-0c430d76d324'::uuid, 'gambhirananda', 'english', 'O Yogi, how shall I know You by remaining ever-engaged in meditation? And through what objects, O Lord, should I meditate on You?'),
('978ce39f-577d-5276-b42a-f04ae65a3176'::uuid, 'd99a8d0d-9ee8-550d-905b-0c430d76d324'::uuid, 'sivananda', 'english', 'How shall I, ever meditating, know you, O Yogin? In what aspects or things, O blessed Lord, should I think of you?'),
('b212e283-8b14-53fd-a9ed-f9ba694b1ae4'::uuid, 'c0e24b69-4f43-5b6b-97a8-f1958b29ff77'::uuid, 'gambhirananda', 'english', 'O Janardana, please narrate to me again in detail Your own yoga and divine manifestations. For, while hearing Your nectar-like words, I am not satiated.'),
('b4ceed59-172c-5802-af8a-6f2d416ac2ca'::uuid, 'c0e24b69-4f43-5b6b-97a8-f1958b29ff77'::uuid, 'sivananda', 'english', 'Tell me again in detail, O Krishna, of your yogic power and glory; for I am not satiated with what I have heard of your life-giving and nectar-like speech.'),
('117cdffa-6dc8-5b24-8728-0c510b05b56c'::uuid, 'ac86f39a-d934-52a4-9a78-01584eb356de'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, O best of the Kurus, now, according to their importance, I shall describe to you My own glories, which are indeed divine. There is no end to My manifestations.'),
('33ff3f8e-0d3a-5243-b1cc-cf1e4726ec6a'::uuid, 'ac86f39a-d934-52a4-9a78-01584eb356de'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "Very well! Now I will declare to you My divine glories in their prominence, O Arjuna; there is no end to their detailed description."'),
('0888ae1d-8330-5b52-a336-207d5e5b3bef'::uuid, 'd48b04da-0136-5391-9f61-f1b7e57c64ad'::uuid, 'gambhirananda', 'english', 'O Gudakesa, I am the Self residing in the hearts of all beings, and I am the beginning, middle, and end of all beings.'),
('468dcefb-7589-56d8-856d-06e071a19d65'::uuid, 'd48b04da-0136-5391-9f61-f1b7e57c64ad'::uuid, 'sivananda', 'english', 'I am the Self, O Gudakesa, seated in the hearts of all beings; I am the beginning, the middle, and the end of all beings.'),
('34ede7d4-6c10-519b-9df8-5345617033e1'::uuid, 'c94ff7b3-0d58-5f35-b461-1ddf45ab658d'::uuid, 'gambhirananda', 'english', 'Among the Adityas [viz Dhata, Mitra, Aryama, Rudra, Varuna, Surya, Bhaga, Vivasvan, Pusa, Savita, Tvasta, and Visnu.-Tr.], I am Visnu; among the luminaries, the radiant sun; among the (forty-nine) Maruts [The seven groups of Maruts are Avaha, Pravaha, Vivaha, Paravaha, Udvaha, Samvaha, and Parivaha.-Tr.], I am Marici; among the stars, I am the moon.'),
('85cc0dc1-d37f-5b58-bfad-712743af1284'::uuid, 'c94ff7b3-0d58-5f35-b461-1ddf45ab658d'::uuid, 'sivananda', 'english', 'Among the twelve Adityas, I am Vishnu; among luminaries, the radiant sun; among the seven or forty-nine Maruts, I am Marichi; among stars, I am the moon.'),
('a9e32bc7-c775-5890-aad5-4c1bb5d16eb8'::uuid, 'fd590e67-76bc-5168-8839-6e1cb6827149'::uuid, 'gambhirananda', 'english', 'Among the Vedas, I am the Sama-Veda; among the gods, I am Indra. Among the organs, I am the mind, and I am the intelligence in creatures.'),
('6a954a68-217d-5ac1-a398-cff388c32e64'::uuid, 'fd590e67-76bc-5168-8839-6e1cb6827149'::uuid, 'sivananda', 'english', 'Among the Vedas, I am the Sama-Veda; among the gods, I am Vasava; among the senses, I am the mind; and among living beings, I am intelligence.'),
('562c5dc6-f406-5f95-bd35-e7e5b86da374'::uuid, 'be2f4a9b-7770-5dcd-b3e7-a1bc3ea9a177'::uuid, 'gambhirananda', 'english', 'Among the Rudras, I am Aja, Ekapada, Ahirbudhnya, Pinaki, Aparajita, Tryam-baka, Mahesvara, Vrsakapi, Sambhu, Harana, and Isvara; among the Yaksas and goblins, I am Kubera; among the Vasus, I am Fire; and among the mountains, I am Meru.'),
('41f253c1-8ef8-5ac8-8016-491ec07dfa80'::uuid, 'be2f4a9b-7770-5dcd-b3e7-a1bc3ea9a177'::uuid, 'sivananda', 'english', 'And among the Rudras, I am Sankara; among the Yakshas and Rakshasas, the Lord of Wealth (Kubera); among the Vasus, I am Pavaka (Fire); and among the seven mountains, I am Meru.'),
('5b9e429e-ce64-511d-a792-b049832c68f1'::uuid, '4de15e78-5046-5443-be56-c9e3410befa9'::uuid, 'gambhirananda', 'english', 'O son of Prtha, know me to be Brhaspati, the foremost among the priests of kings. Among commanders of armies, I am Skanda; among large expanses of water, I am the sea.'),
('83bcc8ec-3d45-5634-bdf3-10c6136fdb8f'::uuid, '4de15e78-5046-5443-be56-c9e3410befa9'::uuid, 'sivananda', 'english', 'And, among the household priests of kings, O Arjuna, know Me to be the chief, Brihaspati; among the army generals, I am Skanda; among lakes, I am the ocean.'),
('e20658c3-a550-5557-8265-a4dea08058c7'::uuid, 'ae14ee0d-3b7d-5baa-86f3-a27f464ddaa0'::uuid, 'gambhirananda', 'english', 'Among the great sages, I am Bhrgu; of words, I am the single syllable (Om). Among rituals, I am the ritual of Japa of the immovables, the Himalayas.'),
('1765282e-c98f-5695-8ba0-e2d676299a3f'::uuid, 'ae14ee0d-3b7d-5baa-86f3-a27f464ddaa0'::uuid, 'sivananda', 'english', 'Among the great sages, I am Bhrigu; among words, I am the one syllable (Om); among sacrifices, I am the sacrifice of silent repetition; among the immovable things, I am the Himalayas.'),
('b215ecf2-85c6-53c3-9bef-042d74a44836'::uuid, 'df67bdd9-00b7-5846-b2f0-3f1ad923d4b8'::uuid, 'gambhirananda', 'english', 'Among all trees, I am the Ashvattha tree, and among divine sages, Narada. Among the Gandharvas, I am Citraratha; among the perfected ones, I am the sage Kapila.'),
('e079c0a1-e388-57ac-9230-29afbd52c4c3'::uuid, 'df67bdd9-00b7-5846-b2f0-3f1ad923d4b8'::uuid, 'sivananda', 'english', 'Among all the trees, I am the Peepul; among the divine sages, I am Narada; among the Gandharvas, I am Chitraratha; among the perfected, I am the sage Kapila.'),
('dc592cd9-bf75-59dd-a3b7-a6b502055c2c'::uuid, '58c335af-6a9f-52bb-8a45-2ac5c1f1635a'::uuid, 'gambhirananda', 'english', 'Among horses, know Me to be Uccaihsravas, born from nectar; Airavata among the lordly elephants; and among men, the King of men. [Uccaihsravas and Airavata are respectively the divine horse and elephant of Indra.]'),
('0909e123-d01f-5b36-bb32-9d4bc8d23012'::uuid, '58c335af-6a9f-52bb-8a45-2ac5c1f1635a'::uuid, 'sivananda', 'english', 'Know Me as Ucchaisravas, born of nectar, among horses; Airavata among lordly elephants; and the king among men.'),
('a0a483ae-6d76-5510-b794-356bb7646ef2'::uuid, '23b7055f-24f3-509d-b448-330bdd266df7'::uuid, 'gambhirananda', 'english', 'Among weapons I am the thunderbolt; among cows I am Kamadhenu. I am Kandarpa, the Progenitor, and among serpents I am Vasuki.'),
('50feacb2-bf01-543c-9891-7bfb4e870d31'::uuid, '23b7055f-24f3-509d-b448-330bdd266df7'::uuid, 'sivananda', 'english', 'Among weapons, I am the thunderbolt; among cows, I am the wish-fulfilling cow called Kamadhenu; I am the progenitor, the god of love; among serpents, I am Vasuki.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('8d519060-0fcd-54c5-b6f5-21c0d992a6fe'::uuid, '6bdfac75-31de-5c07-90b5-8c3ce0b1fd02'::uuid, 'gambhirananda', 'english', 'Among snakes, I am Ananta; among gods of the waters, Varuna; among the manes, Aryama; and among the maintainers of law and order, I am Yama (King of death).'),
('c9ef45df-f285-52f7-8d36-3be9704b4735'::uuid, '6bdfac75-31de-5c07-90b5-8c3ce0b1fd02'::uuid, 'sivananda', 'english', 'I am Ananta among the Nagas; I am Varuna among water-deities; Aryaman among the Manes; I am Yama among the governors.'),
('d13139b1-7bf1-5bc0-9f25-14cb432f9b0e'::uuid, '8bd37472-41bd-5c14-933a-cbebce43a454'::uuid, 'gambhirananda', 'english', 'Among demons, I am Prahlada, and among reckoners of time, I am Time. Among animals, I am the lion, and among birds, I am Garuda.'),
('fb9a6fd1-b828-58df-a1be-8a12aee742d3'::uuid, '8bd37472-41bd-5c14-933a-cbebce43a454'::uuid, 'sivananda', 'english', 'And I am Prahlada among the demons, I am Time among reckoners, I am the lion among beasts, and Vainateya (Garuda) among birds.'),
('ba7c5378-bf47-53c2-b07e-7d7ad9822e8d'::uuid, 'f40375a9-c9f5-5c6a-9a66-010ba15cc86e'::uuid, 'gambhirananda', 'english', 'Of the purifiers, I am the air; among the wielders of weapons, I am Rama. Among fishes, I am the shark; among rivers, I am Ganga.'),
('217edb0f-ccc8-548f-aa8a-db9bd7cdc140'::uuid, 'f40375a9-c9f5-5c6a-9a66-010ba15cc86e'::uuid, 'sivananda', 'english', 'Among the purifiers, I am the wind; among the warriors, I am Rama; among the fishes, I am the shark; among the streams, I am the Ganga.'),
('f8c94f96-d1eb-5928-8588-0689276a64b3'::uuid, '12953804-97f5-598a-88cc-cd9b22fd31f6'::uuid, 'gambhirananda', 'english', 'O Arjuna, of creations I am the beginning, the middle, and the end; I am the knowledge of the Self among knowledge; of those who debate, I am vada.'),
('363ccc03-4edc-50fd-b24c-2d2dce3e615c'::uuid, '12953804-97f5-598a-88cc-cd9b22fd31f6'::uuid, 'sivananda', 'english', 'Among creations I am the beginning, the middle, and the end, O Arjuna; among the sciences, I am the science of the Self; and I am the logic among controversialists.'),
('93494fe4-f59f-5f7e-a12f-a0a25c70f42d'::uuid, '5c3d7487-717a-56fb-8db4-f9ecc1d7b01c'::uuid, 'gambhirananda', 'english', 'Of the letters, I am the letter A, and of the group of compound words, I am the compound called Dvandva. I am Myself the infinite time; I am the Dispenser with faces everywhere.'),
('b618dac4-8674-5594-951f-1afdcbe26cff'::uuid, '5c3d7487-717a-56fb-8db4-f9ecc1d7b01c'::uuid, 'sivananda', 'english', 'Among the letters of the alphabet, I am the letter ''A'' and the dual among compounds. I am verily the inexhaustible and everlasting time; I am the dispenser of the fruits of actions, having faces in all directions.'),
('f1f582ed-094f-593b-8562-c22cf8d547eb'::uuid, 'b57a7f41-b0d5-5605-91ae-956e0f0666d9'::uuid, 'gambhirananda', 'english', 'And I am Death, the destroyer of all; and the bestower of prosperity to those destined to be prosperous. Of the feminine [Narinam may mean ''of the feminine qualities''. According to Sridhara Swami and S., the words fame etc. signify the goddesses of the respective qualities. According to M.S. these seven goddesses are the wives of the god Dharma.-Tr.] (I am) fame, beauty, speech, memory, intelligence, fortitude, and forbearance.'),
('62f6c987-971b-5c13-badd-cdbe9d9f4e7e'::uuid, 'b57a7f41-b0d5-5605-91ae-956e0f0666d9'::uuid, 'sivananda', 'english', 'And I am the all-devouring Death, and the source of prosperity for those who are to be prosperous; among the feminine qualities, I am fame, prosperity, speech, memory, intelligence, firmness, and forgiveness.'),
('177f8a00-8d82-5fc1-ba6a-ce4a4edb0b0d'::uuid, '6e3af952-af6a-5e4d-9a10-bc856eca2039'::uuid, 'gambhirananda', 'english', 'I am also the Brhat-sama of the Sama-mantras; of the meters, Gayatri. Of the months, I am Marga-sirsa, and of the seasons, spring.'),
('79c5af9c-0ab9-51ad-bba4-669d1c707960'::uuid, '6e3af952-af6a-5e4d-9a10-bc856eca2039'::uuid, 'sivananda', 'english', 'Among the hymns, I am the Brihatsaman; among meters, I am Gayatri; among months, I am Margasirsha; among seasons, I am the flowery season.'),
('dbed9db7-ece5-573d-a3a5-4c86bb3e8438'::uuid, 'fe70e8c1-a538-568d-af01-b03669e4ea9a'::uuid, 'gambhirananda', 'english', 'Of the fraudulent, I am the gambling; I am the irresistible end of the mighty. I am excellence, I am effort, I am the sattva quality of those possessed of sattva.'),
('865b8254-1b4b-5e7e-b3da-08010ad3daf9'::uuid, 'fe70e8c1-a538-568d-af01-b03669e4ea9a'::uuid, 'sivananda', 'english', 'I am the gambling of the deceitful; I am the splendor of the splendid; I am victory; I am the resolve of the resolute; I am the goodness of the good.'),
('2e68aa9a-f99a-55bf-a22e-7df3b24e3416'::uuid, '9c5da1f5-2d56-50dc-95e1-529f6974ec17'::uuid, 'gambhirananda', 'english', 'Of the Vrsnis, I am Vasudeva; of the Pandavas, Dhananjaya (Arjuna). Of the wise, I am Vyasa; of the omniscient, the omniscient Usanas.'),
('419bccf1-0b22-503b-8e3f-a635d733d1e2'::uuid, '9c5da1f5-2d56-50dc-95e1-529f6974ec17'::uuid, 'sivananda', 'english', 'Among the Vrishnis, I am Vaasudeva; among the Pandavas, I am Arjuna; among the sages, I am Vyasa; among the poets, I am Usanas, the poet.'),
('f1e703f4-a003-5cb0-b5f0-b1c972319898'::uuid, '76abbd73-3126-5417-8148-67094f760fe8'::uuid, 'gambhirananda', 'english', 'Of the punishers, I am the rod; I am the righteous policy of those who desire to conquer. And of things secret, I am verily silence; I am the knowledge of the wise.'),
('72bfe70a-6076-5a64-bf08-77db2ea24c43'::uuid, '76abbd73-3126-5417-8148-67094f760fe8'::uuid, 'sivananda', 'english', 'Of those who punish, I am the scepter; among those who seek victory, I am statesmanship; and among secrets, I am silence; I am knowledge among knowers.'),
('3f46fbbf-47d4-5514-afe9-f64657b183b2'::uuid, '22f05195-d61f-5fae-a530-c6fbeef36198'::uuid, 'gambhirananda', 'english', 'Moreover, O Arjuna, I am the seed of all beings. There is nothing, moving or non-moving, that can exist without Me.'),
('b92f273f-8276-5562-989d-0097327e9b8c'::uuid, '22f05195-d61f-5fae-a530-c6fbeef36198'::uuid, 'sivananda', 'english', 'And whatever is the seed of all beings, that too am I, O Arjuna; there is no being, be it moving or unmoving, that can exist without Me.'),
('c81a8448-60b8-551c-a106-bafc4d36b672'::uuid, 'e4da816e-b9e0-5b44-ab42-4ed2171ac57a'::uuid, 'gambhirananda', 'english', 'O destroyer of enemies, there is no limit to My divine manifestations. This description of My manifestations, however, has been stated by Me as an illustration.'),
('5807ebc3-100f-5d86-b6f5-5d3050a95120'::uuid, 'e4da816e-b9e0-5b44-ab42-4ed2171ac57a'::uuid, 'sivananda', 'english', 'There is no end to My divine glories, O Arjuna, but this is a brief statement by Me of the particulars of My divine glory.'),
('6bcbc80c-f27a-5a60-89ba-2a8b212cb4b9'::uuid, '5eac06b9-a790-5427-9d94-84be18f94cb8'::uuid, 'gambhirananda', 'english', 'Whatever object [all living beings] is verily endowed with majesty, possessed of prosperity, or is energetic, you know for certain each of them as having a part of My power as its source.'),
('3a3b2bcd-a718-5a22-ad83-dc00928acc32'::uuid, '5eac06b9-a790-5427-9d94-84be18f94cb8'::uuid, 'sivananda', 'english', 'Whatever being there is glorious, prosperous, or powerful, know that to be a manifestation of a part of My splendor.'),
('79effaaa-8e33-54e4-8239-daacef7819d4'::uuid, 'f41b38d6-776c-5e3e-978d-48b6244fc84d'::uuid, 'gambhirananda', 'english', 'Or, on the other hand, what is the need for you to know this extensively, O Arjuna? I remain sustaining this whole creation in a special way with a part of Myself.'),
('2d3075c8-2964-5a18-864c-e751b6ab7193'::uuid, 'f41b38d6-776c-5e3e-978d-48b6244fc84d'::uuid, 'sivananda', 'english', 'But, of what avail is the knowledge of all these details to you, O Arjuna? I exist, supporting this whole world with one part of Myself.'),
('bf7b4ea5-c9d4-5344-bc47-bbd84bc43c5c'::uuid, 'cf203c24-9c69-5343-9489-c4ac32571b7f'::uuid, 'gambhirananda', 'english', 'Arjuna said, "This delusion of mine has departed as a result of that speech which is most secret and pertains to the Self, uttered by You for my benefit."'),
('dc8f5488-4bd8-5c95-9913-8b5d31c80f7d'::uuid, 'cf203c24-9c69-5343-9489-c4ac32571b7f'::uuid, 'sivananda', 'english', 'Arjuna said, By this explanation of the highest secret concerning the Self which Thou hast spoken, for the sake of blessing me, my delusion has been dispelled.'),
('e987498d-93f2-52e9-81b7-7671c079e957'::uuid, 'c1ed36ef-229d-5b48-abab-e6735afccec2'::uuid, 'gambhirananda', 'english', 'O you with eyes like lotus leaves, I have heard in detail from You the origin and dissolution of beings, as well as Your undecaying glory.'),
('f89dfbb0-a6e1-5591-81d2-ad0ded56c5c7'::uuid, 'c1ed36ef-229d-5b48-abab-e6735afccec2'::uuid, 'sivananda', 'english', 'The origin and destruction of beings have been heard in detail from You, O lotus-eyed Lord, and also Your inexhaustible greatness.'),
('fe159ff1-6c4e-512f-812e-79d72f7a5b6e'::uuid, 'acab8c6a-5263-5235-af04-51f695a380f3'::uuid, 'gambhirananda', 'english', 'O Supreme Lord, so it is, as You have spoken of Yourself. O Supreme Person, I wish to behold Your divine form.'),
('ce67fc7f-172f-5ea9-a412-71dda2475b32'::uuid, 'acab8c6a-5263-5235-af04-51f695a380f3'::uuid, 'sivananda', 'english', 'Now, O Supreme Lord, as Thou hast thus described Thyself, O Supreme Person, I wish to behold Thy divine form.'),
('8fb926b7-d1a4-5245-9492-b270736bdc15'::uuid, 'bd2015b9-2baa-5c92-ad72-9c58419acc14'::uuid, 'gambhirananda', 'english', 'O Lord, if You deem it possible for me to behold You, then, O Lord of Yoga, show me Your eternal Self.'),
('20a33ba6-0269-554b-b31a-1fd1f1a148a8'::uuid, 'bd2015b9-2baa-5c92-ad72-9c58419acc14'::uuid, 'sivananda', 'english', 'If Thou, O Lord, thinkest it possible for me to see it, do Thou, then, O Lord of the Yogis, show me Thy imperishable Self.'),
('d06a4893-c302-5e87-b709-14a8a3220e52'::uuid, '2904542e-48ff-5375-883c-808e320c0a18'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "O son of Prtha, behold My forms in their hundreds and thousands, of different kinds, celestial, and of various colors and shapes."'),
('5c4edee4-0662-5be6-a14c-679b42afd813'::uuid, '2904542e-48ff-5375-883c-808e320c0a18'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "Behold, O Arjuna, forms of Mine, by the hundreds and thousands, of different sorts, divine, and of various colors and shapes."'),
('8e6f36bc-67ee-5e62-8574-a78edc7c4994'::uuid, '3bffd301-09a9-5ada-9b40-6ad89a9a09da'::uuid, 'gambhirananda', 'english', 'Behold the Adityas, the Vasus, the Rudras, the two Ashvins, and the Maruts. O scion of the Bharata dynasty, also behold the many wonders that have never been seen before.'),
('c66681d8-3d5b-5a26-8443-9fdc14a1a752'::uuid, '3bffd301-09a9-5ada-9b40-6ad89a9a09da'::uuid, 'sivananda', 'english', 'Behold the Adityas, the Vasus, the Rudras, the two Asvins, and the Maruts; behold many wonders never before seen, O Arjuna.'),
('7fe82d47-58ee-53ff-87e4-0585719aa2ca'::uuid, '7dcaec60-206b-5a52-a562-a2d3b8a11392'::uuid, 'gambhirananda', 'english', 'See now, O Gudakesa, the entire Universe together with the moving and the non-moving, concentrated in the same place here in My body, as also whatever else you would like to see.'),
('c39c9943-344e-5b93-b607-24ae27539a3c'::uuid, '7dcaec60-206b-5a52-a562-a2d3b8a11392'::uuid, 'sivananda', 'english', 'Now, behold, O Arjuna, in this My body, the entire universe centered in one, including the moving and the unmoving, and whatever else you desire to see.'),
('3fe51097-4cfb-5585-9f18-86a001e888ef'::uuid, 'dd14f713-8c54-5162-b144-06f6ac0cb41a'::uuid, 'gambhirananda', 'english', 'But you are not able to see Me with just this eye of yours. I grant you the divine eye; behold My divine Yoga.'),
('3645ff32-4529-50e7-b3bd-b3b51ae15d9f'::uuid, 'dd14f713-8c54-5162-b144-06f6ac0cb41a'::uuid, 'sivananda', 'english', 'But you are not able to behold Me with these your own eyes; I give you the divine eye; behold My lordly Yoga.'),
('d801c681-cb72-59b5-8aea-6fd6a264dea3'::uuid, '2876e97a-c26f-5e5d-9ab2-9a06c893416d'::uuid, 'gambhirananda', 'english', 'Sanjaya said, "O King, having spoken thus, thereafter, Hari, the great Master of Yoga, showed to the son of Prtha the supreme divine form."'),
('2ae9b83f-7360-5b00-b4e4-bc3ed1d09df6'::uuid, '2876e97a-c26f-5e5d-9ab2-9a06c893416d'::uuid, 'sivananda', 'english', 'Sanjaya said, Having thus spoken, O king, the great Lord of Yoga, Hari (Krishna), showed Arjuna His supreme form as the Lord.'),
('f1601b74-64b7-51a7-b1e4-07646caef13f'::uuid, '835f9e7c-3884-555e-8f6a-f5d90f30d6e8'::uuid, 'gambhirananda', 'english', 'Having many faces and eyes, possessing many wondrous sights, adorned with numerous celestial ornaments, and holding many uplifted heavenly weapons;'),
('19119e5a-e7fe-5f51-92fe-8b517c8e301e'::uuid, '835f9e7c-3884-555e-8f6a-f5d90f30d6e8'::uuid, 'sivananda', 'english', 'With numerous mouths and eyes, with numerous wondrous sights, with numerous divine adornments, with numerous divine weapons uplifted, such a form He showed.'),
('e8853ee8-c795-5996-a47e-62ca7b0192ce'::uuid, 'b3fc7603-7a71-5357-9c8a-480993340bb8'::uuid, 'gambhirananda', 'english', 'Wearing heavenly garlands and apparel, anointed with heavenly scents, abounding in all kinds of wonders, resplendent, infinite, and with faces on all sides.'),
('5d4be4e7-d01a-5fd3-9330-44ef860c7ac0'::uuid, 'b3fc7603-7a71-5357-9c8a-480993340bb8'::uuid, 'sivananda', 'english', 'Wearing divine garlands and apparel, anointed with divine unguents, the all-wonderful, resplendent Being is endless with faces on all sides.'),
('ead79f12-3506-52da-a13b-2c22ff67488e'::uuid, '5a4c12fa-9b87-5270-8480-4b171e2aa560'::uuid, 'gambhirananda', 'english', 'Should the effulgence of a thousand suns blaze forth simultaneously in the sky, that might be akin to the radiance of that exalted One.'),
('23a9a317-7131-54ad-9abc-79a8ca94e6a2'::uuid, '5a4c12fa-9b87-5270-8480-4b171e2aa560'::uuid, 'sivananda', 'english', 'If the splendour of a thousand suns were to blaze out simultaneously in the sky, that would be the splendour of that mighty being.'),
('8c8fe362-48ac-5e21-a5cf-a9ff1747ea62'::uuid, '6447375e-f3ed-5c01-9d7e-a672fe5eea72'::uuid, 'gambhirananda', 'english', 'At that time, the Pandava saw, in the body of the God of gods, the whole diversely differentiated universe united in one.'),
('198b0708-db62-59bd-80ea-d1de3446dc56'::uuid, '6447375e-f3ed-5c01-9d7e-a672fe5eea72'::uuid, 'sivananda', 'english', 'There, in the body of the God of gods, Arjuna then saw the entire universe resting in one, with its myriad of divisions.'),
('d2854b19-7a59-5fa2-8e86-cdfa6a72b4ec'::uuid, '26c79fd3-5b59-5a01-8706-7854cfc2a811'::uuid, 'gambhirananda', 'english', 'Then, filled with wonder and with hairs standing on end, Arjuna, bowing down with his head to the Lord, said with folded hands:'),
('839177f6-5e96-58c4-bdd3-fae99e9f2da8'::uuid, '26c79fd3-5b59-5a01-8706-7854cfc2a811'::uuid, 'sivananda', 'english', 'Then, Arjuna, filled with wonder and his hair standing on end, bowed his head to the God and spoke with palms joined.'),
('4c850506-0b71-5996-9244-9516baf8e738'::uuid, 'cb32a00d-21bd-5882-baab-c0e88089b2b8'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O God, I see in Your body all the gods, as well as hosts of various classes of beings; Brahma the ruler, sitting on a lotus seat, and all the heavenly sages and serpents.'),
('f3733cba-dcaa-565a-b3ac-dcdeeb0b7ac9'::uuid, 'cb32a00d-21bd-5882-baab-c0e88089b2b8'::uuid, 'sivananda', 'english', 'Arjuna said, "O God, I see all the gods in Your body, as well as hosts of various classes of beings, Brahma the Lord seated on the lotus, all the sages, and the celestial serpents."'),
('3d185a1d-fd3b-5f63-a521-cde83585bb73'::uuid, '192a9daa-4cc3-5093-9c30-4e93c9bdd135'::uuid, 'gambhirananda', 'english', 'I see You with numerous arms, bellies, mouths, and eyes; with infinite forms all around. O Lord of the Universe, O Cosmic Person, I see no limit, no middle, nor beginning!'),
('b4da0bdf-641c-527a-89bc-e5423410c29d'::uuid, '192a9daa-4cc3-5093-9c30-4e93c9bdd135'::uuid, 'sivananda', 'english', 'I see You with boundless form on every side, with many arms, stomachs, mouths, and eyes; neither the end nor the middle nor the beginning do I see, O Lord of the Universe, O Cosmic Form.'),
('2d4b654f-104f-576d-897e-4c8261938b42'::uuid, '42caf673-7f83-5e1a-8837-00f15d2dc7b3'::uuid, 'gambhirananda', 'english', 'I see You wearing a diadem, wielding a mace, and holding a disc; a mass of brilliance glowing all around, difficult to look at from all sides, possessing the radiance of the blazing fire and sun, and immeasurable.'),
('54956c6e-9369-5aa6-9ee4-4406d5f402ac'::uuid, '42caf673-7f83-5e1a-8837-00f15d2dc7b3'::uuid, 'sivananda', 'english', 'I see You with the diadem, club, and discus, a mass of radiance shining everywhere, very hard to look at, blazing all around like a burning fire and the sun, and immeasurable.'),
('51414107-7bf5-576b-89e1-868b03b68673'::uuid, '070e78e0-b554-562b-bbbe-e46dcb51accb'::uuid, 'gambhirananda', 'english', 'You are the Unchanging, the supreme One to be known; You are the most perfect repository of this Universe. You are the Imperishable, the Protector of the ever-existing religion; You are the eternal Person. This is my belief.'),
('28fb8171-d6bd-5d96-b332-b77e35348f46'::uuid, '070e78e0-b554-562b-bbbe-e46dcb51accb'::uuid, 'sivananda', 'english', 'You are the Imperishable, the Supreme Being, worthy of being known. You are the great treasure-house of this universe; You are the imperishable protector of the eternal Dharma; You are the Primal Person, I believe.'),
('dfe84ca1-aa93-5c88-b627-67339a973cc1'::uuid, '55b5f6b4-10c3-5df6-9721-6e2c9e2280c7'::uuid, 'gambhirananda', 'english', 'I see You as having no beginning, middle, or end, possessing infinite valor, with innumerable arms, the sun and moon as eyes, a mouth like a blazing fire, and heating up this universe with Your own brilliance.'),
('8a61b424-e11f-555e-80c0-3a1d3f33c88b'::uuid, '55b5f6b4-10c3-5df6-9721-6e2c9e2280c7'::uuid, 'sivananda', 'english', 'I see You without beginning, middle, or end, infinite in power, with endless arms, the sun and moon as Your eyes, the burning fire Your mouth, heating the entire universe with Your radiance.'),
('e4939fda-ad40-5f2c-812a-2dbe5512d23f'::uuid, 'd8d870a5-a336-5f00-acd7-5642effcd875'::uuid, 'gambhirananda', 'english', 'Indeed, this intermediate space between heaven and earth, as well as all the directions, are pervaded by You alone. O exalted One, the three worlds are struck with fear upon seeing this strange and fearful form of Yours.'),
('57c0c338-e0e9-5c73-8bfc-87a3b20558c1'::uuid, 'd8d870a5-a336-5f00-acd7-5642effcd875'::uuid, 'sivananda', 'english', 'This space between the earth and the heavens, and all the quarters, is filled by You alone; having seen this, Your wonderful and terrible form, the three worlds are trembling with fear, O great-souled Being.'),
('e7f3cc86-c61c-5ef8-8081-74b35e9aa3d1'::uuid, '32157bf6-f2a9-5a7f-9f6c-957f98976d68'::uuid, 'gambhirananda', 'english', 'Those very groups of gods enter into You; struck with fear, some extol You with joined palms. Groups of great sages and perfected beings praise You with elaborate hymns, saying, ''May it be well!'''),
('43636452-7f4c-526a-816f-d0056a776e27'::uuid, '32157bf6-f2a9-5a7f-9f6c-957f98976d68'::uuid, 'sivananda', 'english', 'Verily, these hosts of gods enter into Thee; some extol Thee with joined palms in fear, saying, ''May it be well!'' Bands of great sages and perfected ones praise Thee with complete hymns.'),
('0e1e509a-968e-500c-ad2c-a5cb01ddfcd1'::uuid, '5ee66cf5-a09d-574a-9827-f74b97fc56a1'::uuid, 'gambhirananda', 'english', 'Those who are the Rudras, the Adityas, the Vasus, and the Sadhyas, the Visvedevas, the two Asvins, the Maruts, and the Usmapas, and hosts of Gandharvas, Yaksas, demons, and Siddhas—all of those very ones gaze at You, being indeed struck with wonder.'),
('b7c25157-09f1-5217-9bd5-4c1101ee4645'::uuid, '5ee66cf5-a09d-574a-9827-f74b97fc56a1'::uuid, 'sivananda', 'english', 'The Rudras, Adityas, Vasus, Sadhyas, Visvedevas, the two Asvins, Maruts, the Manus, and the hosts of celestial singers, Yakshas, demons, and the perfected ones, all look upon Thee with great amazement.'),
('0b2cd4ae-21dd-54c6-b0bc-79acd69a38b7'::uuid, '8346db69-7987-5a30-9c6b-2a23cdf3373d'::uuid, 'gambhirananda', 'english', 'O Mighty-Armed One, seeing Your immense form with many mouths, eyes, arms, thighs, feet, bellies, and teeth, the creatures are struck with terror, and so am I.'),
('2b4377c9-08df-5237-88c6-a014c03ada4b'::uuid, '8346db69-7987-5a30-9c6b-2a23cdf3373d'::uuid, 'sivananda', 'english', 'Having seen Your immeasurable form with many mouths and eyes, O mighty-armed one, with many arms, thighs, and feet, with many stomachs and fearsome with many teeth, the worlds are terrified, and so am I.'),
('8b6bf088-6702-5fae-937c-4cc6a896ea95'::uuid, '6b7a3dda-850f-54d4-b6da-6e45ed45c8d5'::uuid, 'gambhirananda', 'english', 'O Vishnu, indeed, upon seeing Your form touching the heavens, blazing with many colors, open-mouthed, with fiery, large eyes, I become terrified in my mind and do not find steadiness and peace.'),
('287315c9-e665-5e08-891d-3870683cdb54'::uuid, '6b7a3dda-850f-54d4-b6da-6e45ed45c8d5'::uuid, 'sivananda', 'english', 'On seeing Thee, touching the sky, shining in many colors, with mouths wide open, with large fiery eyes, I am terrified at heart and find neither courage nor peace, O Vishnu.'),
('579bd9c7-459d-50fb-8a5c-8c265fe198e2'::uuid, '70b1db7f-c918-5dc0-8e6c-d8efc52501f0'::uuid, 'gambhirananda', 'english', 'Having merely seen Your mouths made terrible with their teeth and resembling the fire of Dissolution, I have lost my sense of direction and find no comfort. Be gracious, O Lord of gods, O Abode of the Universe.'),
('711eceaf-ad3b-54ec-8387-43c44bffece3'::uuid, '70b1db7f-c918-5dc0-8e6c-d8efc52501f0'::uuid, 'sivananda', 'english', 'Having seen Thy mouths fearful with teeth blazing like the fires of cosmic dissolution, I know not the four quarters, nor do I find peace. Have mercy, O Lord of the gods, O abode of the universe.'),
('2f4b1455-bc8f-55f6-934d-1328723f4413'::uuid, '3360d1ad-4fd3-5795-b636-d4fb72e05a49'::uuid, 'gambhirananda', 'english', 'And into You enter all those sons of Dhrtarastra, along with multitudes of the rulers of the earth, Bhisma, Drona, and that son of a Suta, Karna, together with our prominent warriors.'),
('08ceecdb-d10a-58f1-b016-e78377b9775e'::uuid, '3360d1ad-4fd3-5795-b636-d4fb72e05a49'::uuid, 'sivananda', 'english', 'All the sons of Dhritarashtra, along with the hosts of kings of the earth, Bhishma, Drona, and Karna, as well as the chief among our warriors.'),
('06bb8491-d694-5f6b-95f3-44e46d728b13'::uuid, '662847cf-2d99-5e79-9022-b3a15c40d737'::uuid, 'gambhirananda', 'english', 'They rapidly enter into Your terrible mouths with cruel teeth! Some are seen sticking in the gaps between the teeth, with their heads crushed!'),
('a224be29-76e7-5801-a7e4-cda807447f06'::uuid, '662847cf-2d99-5e79-9022-b3a15c40d737'::uuid, 'sivananda', 'english', 'Some hurry into Your mouths with their terrible teeth, fearful to behold. Some are found stuck in the gaps between the teeth, their heads crushed to powder.'),
('30186ce4-0255-5996-a361-0ac79948e0a4'::uuid, '8db8138e-ae14-5c0d-a9af-0a1e2250ab0b'::uuid, 'gambhirananda', 'english', 'As the numerous currents of the waters of rivers rush towards the sea alone, so too do those heroes of the human world enter into Your blazing mouths.'),
('826484c1-13a5-55e7-bc17-092debfd148d'::uuid, '8db8138e-ae14-5c0d-a9af-0a1e2250ab0b'::uuid, 'sivananda', 'english', 'Verily, just as many torrents of rivers flow towards the ocean, so too these heroes in the world of men enter Thy flaming mouths.'),
('5733b493-ea3c-5f9d-b28b-47d91e5d0e28'::uuid, 'ba65e7f4-4e6d-585e-94c4-af0daeb1ce9b'::uuid, 'gambhirananda', 'english', 'As moths hasten with increased speed into a blazing fire for destruction, so too do creatures hasten into Your mouths with increased speed for destruction.'),
('365a145d-8e35-58ca-8602-25abebfea106'::uuid, 'ba65e7f4-4e6d-585e-94c4-af0daeb1ce9b'::uuid, 'sivananda', 'english', 'As moths hurriedly rush into a blazing fire, leading to their own destruction, so too these creatures hurry into Your mouths, leading to their own destruction.'),
('60a9e567-cee6-5a4d-91e0-888c78cdefc8'::uuid, 'ed305a07-251d-5880-b621-348554f03d19'::uuid, 'gambhirananda', 'english', 'You lick Your lips as You devour all creatures from every side with flaming mouths that fill the entire world with heat.'),
('9e3c4a7e-6821-5198-8ecd-913fefa4e74e'::uuid, 'ed305a07-251d-5880-b621-348554f03d19'::uuid, 'sivananda', 'english', 'Thou lickest up, devouring all the worlds on every side with Thy flaming mouths. Thy fierce rays, filling the whole world with radiance, burn, O Vishnu!'),
('10ef382d-6f95-5e9d-8609-514386c1cb3c'::uuid, 'bd507b77-94f3-5d16-9fef-e72b2813779c'::uuid, 'gambhirananda', 'english', 'Tell me who You are, fierce in form. Salutations to You, O Supreme God; be gracious. I desire to fully know You, who are the Prime One. For I do not understand Your actions!'),
('b315e5af-cd50-544a-b7f4-0faa6e15b5cc'::uuid, 'bd507b77-94f3-5d16-9fef-e72b2813779c'::uuid, 'sivananda', 'english', 'Tell me, who you are, so fierce of form. I offer my salutations to you, O God Supreme; have mercy on me. I desire to know you, the original Being. I do not indeed know your workings.'),
('b745e34d-f50a-54f5-9885-f354c87af1bb'::uuid, 'd8c52c70-7894-5309-a0f0-2faff73ab55c'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "I am the world-destroying Time, grown in stature and now engaged in annihilating the creatures. Even without you, all the warriors arrayed in the confronting armies will cease to exist!"'),
('187beeeb-4c43-5a19-8229-08292759b2b5'::uuid, 'd8c52c70-7894-5309-a0f0-2faff73ab55c'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "I am the full-grown, world-destroying Time, now engaged in destroying the worlds. Even without you, none of the warriors arrayed in the hostile armies will live."'),
('e17c662e-cec3-5c28-bea3-57c901dcd883'::uuid, 'e10174ad-ae31-5050-9a65-15009b027d89'::uuid, 'gambhirananda', 'english', 'Therefore, rise up and gain fame; and, defeating the enemies, enjoy a prosperous kingdom. These have been killed by Me even earlier; be you merely an instrument, O Savyasacin (Arjuna).'),
('101769a5-7076-5b1d-a0cc-8d54d6c0ebb4'::uuid, 'e10174ad-ae31-5050-9a65-15009b027d89'::uuid, 'sivananda', 'english', 'Therefore, stand up and obtain fame. Conquer the enemies and enjoy the unparalleled kingdom. Verily, by Me they have already been slain; be thou a mere instrument, O Arjuna.'),
('78155ecc-e2e6-5de9-b6c9-af5f0f607fe4'::uuid, '2c556b1c-9a2f-5d48-8447-5d30303b5a45'::uuid, 'gambhirananda', 'english', 'You destroy Drona, Bhisma, Jayadratha, Karna, and the other heroic warriors who have been killed by Me. Do not be afraid. Fight! You will conquer the enemies in battle.'),
('d63acf06-5b1d-5fd5-a289-a4ab1b2fa5b5'::uuid, '2c556b1c-9a2f-5d48-8447-5d30303b5a45'::uuid, 'sivananda', 'english', 'Drona, Bhishma, Jayadratha, Karna, and other brave warriors have already been slain by Me; do not be distressed with fear; fight and you shall conquer your enemies in battle.'),
('aeea126c-2f42-5b9d-a267-6edc2050736f'::uuid, 'c17ed87f-a313-5e74-a6c9-4c3cd47c17a2'::uuid, 'gambhirananda', 'english', 'Sanjaya said: Hearing this utterance of Kesava, Kiriti (Arjuna), with joined palms and trembling, prostrated himself, and then, with a faltering voice, bowed down and overcome by fits of fear, said again to Krsna:'),
('8a45cb0d-44bd-55cc-9e04-1a839b061c10'::uuid, 'c17ed87f-a313-5e74-a6c9-4c3cd47c17a2'::uuid, 'sivananda', 'english', 'Sanjaya said, Having heard that speech of Lord Krishna, Arjuna, with joined palms, trembling, prostrated himself, again addressing Krishna in a choked voice, bowing down, overwhelmed with fear.'),
('442e30fb-4ee9-5c19-be9c-7c9de00f4339'::uuid, '9fbce802-01b7-5c77-8058-daa347063130'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Hrsikesa, it is proper that the world be delighted and attracted by Your praise; that the Raksasas, stricken with fear, run in all directions; and that all the groups of the Siddhas bow down to You."'),
('467268ec-f7fc-5798-8575-64b71d489314'::uuid, '9fbce802-01b7-5c77-8058-daa347063130'::uuid, 'sivananda', 'english', 'Arjuna said, "It is fitting, O Krishna, that the world delights and rejoices in Your praise; demons fly in fear in all directions and the hosts of the perfected ones bow to You."')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('4caf5f19-d7d6-5113-a93b-a4d04230ea38'::uuid, '36fb947c-3533-5367-82f2-df0bc24358c1'::uuid, 'gambhirananda', 'english', 'And why should they not bow down to You, O exalted One, who are greater than all and who are the first Creator even of Brahma! O infinite One, supreme God, Abode of the Universe, You are the Immutable, being and non-being, and that which is Transcendental.'),
('bfefe368-2b69-5b57-81d4-c8501015b92b'::uuid, '36fb947c-3533-5367-82f2-df0bc24358c1'::uuid, 'sivananda', 'english', 'And why should they not, O great Soul, bow to Thee Who art greater than all else, the primal cause even of the Creator (Brahma), O Infinite Being, O Lord of the gods, O Abode of the universe; Thou art the imperishable, the Being, the non-being, and That which is supreme—that which is beyond the Being and the non-being.'),
('80269bc7-d409-58e1-9dd9-6a874ccc2667'::uuid, '3c57efa3-e4b2-5a85-a51c-fab9ebaa3a16'::uuid, 'gambhirananda', 'english', 'You are the primal Deity, the ancient Person; You are the supreme Refuge of this world. You are the knower and the object of knowledge, and the supreme Abode. O You of infinite forms, You pervade the Universe!'),
('95e52ca4-acb1-5e24-8855-4b1f0aeed81e'::uuid, '3c57efa3-e4b2-5a85-a51c-fab9ebaa3a16'::uuid, 'sivananda', 'english', 'You are the primal God, the ancient Purusha, the supreme refuge of this universe, the knower, the knowable, and the supreme Abode. Through You, the universe is pervaded, O Being of infinite forms.'),
('79247e2f-1b58-506c-a185-d7236d2b3ec7'::uuid, '72ece883-3e44-5692-95b5-c801e9590684'::uuid, 'gambhirananda', 'english', 'You are air, death, fire, the god of the waters, the moon, the Lord of creatures, and the great-grandfather. Salutations to you a thousand times! Salutations to you again and again! Salutations!'),
('94302e96-df87-5dd6-9d98-0b55d836071e'::uuid, '72ece883-3e44-5692-95b5-c801e9590684'::uuid, 'sivananda', 'english', 'You are Vayu, Yama, Agni, Varuna, the moon, the Creator, and the great-grandfather. I offer my salutations to You a thousand times, and again I offer my salutations to You.'),
('18b4d254-ab37-562b-b4b1-001c6a33f251'::uuid, '5183d7fc-6a36-584c-840f-dec8ab821965'::uuid, 'gambhirananda', 'english', 'Salutations to You in the East and behind. Salutations to You on all sides indeed, O All! You possess infinite strength and infinite heroism. You pervade everything; thus You are all!'),
('9b4d608b-f855-53ff-98d5-3c9871a1410b'::uuid, '5183d7fc-6a36-584c-840f-dec8ab821965'::uuid, 'sivananda', 'english', 'Salutations to You in front and behind! Salutations to You on every side! O All! You, infinite in power and prowess, pervade all; therefore You are all.'),
('7761c089-a8e9-524b-a90d-ba1ab7518c20'::uuid, '507b156b-d4b6-5d84-9ab9-7b50ae3bbdbf'::uuid, 'gambhirananda', 'english', 'Without knowing Your greatness, whatever I said rashly, inadvertently, or even out of familiarity, thinking You to be a friend, addressing You as ''O Krsna,'' ''O Yadava,'' ''O friend,'' etc.'),
('9ccbcf86-8dcf-5e83-b9e9-eaeb015888c9'::uuid, '507b156b-d4b6-5d84-9ab9-7b50ae3bbdbf'::uuid, 'sivananda', 'english', 'Whatever I have presumptuously said from carelessness or love, addressing You as O Krishna! O Yadava! O Friend! regarding You merely as a friend, unknowing of Your greatness.'),
('46280242-647c-5bc4-95e1-aec508a3f85e'::uuid, 'a9beb7a3-faee-52fd-b68c-f425a866141a'::uuid, 'gambhirananda', 'english', 'And that You have been discourteously treated out of fun—while walking, while on a bed, while on a seat, while eating, in privacy, or, O Acyuta, even in public—for that, I beg pardon of You, the incomprehensible One.'),
('75eca3a6-4ddf-51b8-9684-54b42b02d15b'::uuid, 'a9beb7a3-faee-52fd-b68c-f425a866141a'::uuid, 'sivananda', 'english', 'In whatever way I may have insulted You for the sake of fun, while at play, reposing, sitting, or at meals, when alone (with You), O Krishna, or in company, that I implore You, immeasurable one, to forgive.'),
('65f57392-3133-5145-995d-160df7b65c19'::uuid, '70f5118b-e116-5215-95a3-9d8cfeace4c9'::uuid, 'gambhirananda', 'english', 'You are the Father of all beings, both moving and non-moving; to You, the Teacher, are they worthy of worship, and You are greater than a teacher. There is none equal to You; how can there be anyone greater even in all the three worlds, O You of unrivaled power?'),
('a8e610f2-0338-5ff1-9cd6-a823233ab693'::uuid, '70f5118b-e116-5215-95a3-9d8cfeace4c9'::uuid, 'sivananda', 'english', 'Thou art the Father of this world, both moving and unmoving. Thou art to be adored by this world; Thou, the greatest Guru; for none exists who is equal to Thee; how then could there be another superior to Thee in the three worlds, O Being of unrivaled power?'),
('0282ccd5-d1c3-5d27-b7fe-72933679f5df'::uuid, '419ca3cb-346d-5899-8862-253260a9d64d'::uuid, 'gambhirananda', 'english', 'Therefore, by bowing down and prostrating my body, I seek to propitiate You who are God and are adorable. O Lord, You should forgive my faults as a father would forgive the faults of a son, as a friend would forgive the faults of a friend, and as a lover would forgive the faults of a beloved.'),
('7286b422-2924-5671-9237-1242d173cf98'::uuid, '419ca3cb-346d-5899-8862-253260a9d64d'::uuid, 'sivananda', 'english', 'Therefore, bowing down and prostrating my body, I crave Thy forgiveness, O adorable Lord. As a father forgives his son, a friend his dear friend, a lover his beloved, even so may Thou forgive me, O God.'),
('a65b11d4-6f10-5bdf-bc38-16c408e52965'::uuid, '0b1622f1-1deb-5c1f-a72d-cd6f7baa924e'::uuid, 'gambhirananda', 'english', 'I am delighted by seeing something I have not seen before, and my mind is stricken with fear. O Lord, show me that very form; O Supreme God, O Abode of the Universe, be gracious!'),
('b78f1458-d257-5886-9f2c-56149353131a'::uuid, '0b1622f1-1deb-5c1f-a72d-cd6f7baa924e'::uuid, 'sivananda', 'english', 'I am delighted, having seen something never seen before; yet my mind is distressed with fear. Show me that form only, O God; have mercy, O God of gods, O Abode of the universe.'),
('6cde1d15-3049-509e-95df-dd7d70bc19cd'::uuid, 'b9169044-c90a-53d0-ad81-c69e3826f833'::uuid, 'gambhirananda', 'english', 'I want to see You just as before, wearing a crown, wielding a mace, and holding a disc in hand. O You with a thousand arms, O You of Cosmic form, appear with that very form with four hands.'),
('e361ae7b-1da2-5699-91fc-29a41f4faad6'::uuid, 'b9169044-c90a-53d0-ad81-c69e3826f833'::uuid, 'sivananda', 'english', 'I desire to see You as before, crowned, bearing a mace, with the discus in hand, in Your former form only, having four arms, O thousand-armed, Cosmic Being.'),
('a46d6acc-7708-5932-9c7e-a32951235c5c'::uuid, '6ed28195-eb9d-5603-a951-8dfb26a5614d'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, Out of grace, O Arjuna, this supreme, radiant, cosmic, infinite, primeval form—which no one other than you has seen before—has been shown to you by Me through the power of My own Yoga.'),
('4472f210-fe0a-509e-96d1-6c7ffbe7a993'::uuid, '6ed28195-eb9d-5603-a951-8dfb26a5614d'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "O Arjuna, this Cosmic Form has graciously been shown to you by Me through My own Yogic power. It is full of splendour, primeval, and infinite; this Cosmic Form of Mine has never been seen before by anyone other than you."'),
('f185b772-1b1a-5e10-8ee2-efa0716c2588'::uuid, 'f7f2490b-e367-5eb8-8ca1-9cc7433265a5'::uuid, 'gambhirananda', 'english', 'Not by the study of the Vedas and sacrifices, not by gifts, not even by rituals, nor by severe austerities, can I, in this form, be perceived in the human world by anyone other than you, O most valiant among the Kurus, who has not received My grace.'),
('cdac6c16-fd62-5fec-b754-f6e83a55fb41'::uuid, 'f7f2490b-e367-5eb8-8ca1-9cc7433265a5'::uuid, 'sivananda', 'english', 'Neither by the study of the Vedas, nor by gifts, nor by sacrifices, nor by severe austerities, can I be seen in this form in the world of men by any other than yourself, O great hero of the Kurus (Arjuna).'),
('f1e803b2-bf29-52b5-9562-b721f1673a85'::uuid, 'b4c8a0ce-7c71-5d0b-a6dd-75af2230647b'::uuid, 'gambhirananda', 'english', 'May you have no fear, and may there be no bewilderment upon seeing this form of Mine so terrible. Becoming free from fear and gladdened in mind once again, behold this earlier form of Mine.'),
('913f530c-42b1-5988-a875-6485def3b99e'::uuid, 'b4c8a0ce-7c71-5d0b-a6dd-75af2230647b'::uuid, 'sivananda', 'english', 'Do not be afraid, nor be bewildered on seeing such a terrible form of Mine; with your fear dispelled and with a gladdened heart, now behold again this former form of Mine.'),
('24b95b48-94c9-5735-83e7-58bb706142f5'::uuid, '95c8c7b8-4512-54b0-9268-961973d087b0'::uuid, 'gambhirananda', 'english', 'Sanjaya said, Thus, having spoken to Arjuna in that manner, Vasudeva showed His own form again. And He, the exalted One, reassured this terrified one by again becoming serene in his form.'),
('5540d05b-b5d8-5ee4-8b40-1860d4fbe2a6'::uuid, '95c8c7b8-4512-54b0-9268-961973d087b0'::uuid, 'sivananda', 'english', 'Sanjaya said, Having thus spoken to Arjuna, Krishna again showed His own form. The great Soul, assuming His gentle form, then consoled Arjuna, who was terrified.'),
('0be4da01-a5bf-5b79-8715-1400e780964d'::uuid, 'd14e4c70-7b12-54d7-a3e4-727e0ef42eb0'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Janardana, having seen this serene human form of Yours, I have now become calm in mind and restored to my own nature."'),
('cdb793d3-b692-5512-89bc-f05d546ea4cf'::uuid, 'd14e4c70-7b12-54d7-a3e4-727e0ef42eb0'::uuid, 'sivananda', 'english', 'Arjuna said, "Having seen this Thy gentle human form, O Krishna, now I am composed and have been restored to my own nature."'),
('536b2099-6c4d-5f76-86f2-895c928c12d7'::uuid, '99d77227-ae68-5f59-87c1-7ef93bf4248f'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "This form of Mine, which you have seen, is very difficult to behold; even the gods are ever desirous of a vision of this form."'),
('5bee1b0c-fd4e-5315-804f-2a6a63253774'::uuid, '99d77227-ae68-5f59-87c1-7ef93bf4248f'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "It is very hard indeed to see this form of Mine which thou hast seen; even the gods are ever longing to behold it."'),
('3df157f2-10f1-561d-ae27-af864f72be6a'::uuid, '0ead38a2-056d-5f6c-b74a-f868d9da38b2'::uuid, 'gambhirananda', 'english', 'Not through the Vedas, nor by austerity, nor by gifts, nor even by sacrifice can I be seen in this form as you have seen Me.'),
('929fa18e-015a-5348-8c1a-578598daba8a'::uuid, '0ead38a2-056d-5f6c-b74a-f868d9da38b2'::uuid, 'sivananda', 'english', 'Neither by the Vedas, nor by austerity, nor by gift, nor by sacrifice can I be seen in this form as thou hast seen Me so easily.'),
('050d969b-b2c9-54df-a46d-33de6c521b22'::uuid, '50560950-f300-5572-8bee-8f9b55023a5b'::uuid, 'gambhirananda', 'english', 'But, O Arjuna, by single-minded devotion am I, in this form, able to be known and seen in reality, and also entered into, O destroyer of foes.'),
('58f914ca-7368-5f52-a17b-145a56d0ba08'::uuid, '50560950-f300-5572-8bee-8f9b55023a5b'::uuid, 'sivananda', 'english', 'But by single-minded devotion, I can be known, seen, and entered into in reality, O Arjuna.'),
('441a8ae8-2701-5827-a1ab-64ad9bc7d0aa'::uuid, '1a17483b-4df1-5687-9a7b-f16b81db02d6'::uuid, 'gambhirananda', 'english', 'O son of Pandu, he who works for Me, accepts Me as the supreme goal, is devoted to Me, is devoid of attachment and free from enmity towards all beings—he attains Me.'),
('7514e7be-be97-50e9-89af-ce94416241bc'::uuid, '1a17483b-4df1-5687-9a7b-f16b81db02d6'::uuid, 'sivananda', 'english', 'He who does all actions for Me, who regards Me as the Supreme, who is devoted to Me, who is free from attachment, who bears no enmity towards any creature, he comes to Me, O Arjuna.'),
('cde0119d-e9ed-5348-81e7-7c39c461bf8d'::uuid, '5cb373d4-b326-597d-9896-4f3368ed11bc'::uuid, 'gambhirananda', 'english', 'Arjuna said: "Which of these devotees, who are ever dedicated and meditate on You, and those who meditate on the Unmanifested and Immutable, are the best experiencers of yoga [here, yoga means samadhi, spiritual absorption]?"'),
('d73e5537-4c57-5250-8d32-73f5c36f88b9'::uuid, '5cb373d4-b326-597d-9896-4f3368ed11bc'::uuid, 'sivananda', 'english', 'Arjuna said, "Which of them are better versed in Yoga—those who steadfastly worship You, or those who worship the imperishable and the unmanifested?"'),
('9d714ad1-5277-5dac-aeb6-45cd12afaeb3'::uuid, '8209192a-dbcf-591b-b9e0-2877f6c6ed92'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "Those who meditate on Me, fixing their minds on Me with steadfast devotion, endowed with supreme faith—they are considered to be the most perfect yogis according to Me."'),
('174cf08b-392d-58e9-bff1-1228e48de205'::uuid, '8209192a-dbcf-591b-b9e0-2877f6c6ed92'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "In My opinion, those who fix their minds on Me, worship Me ever steadfastly, and are endowed with supreme faith, are the best in Yoga."'),
('dd56799a-2970-55a6-9bb9-22756465c8f2'::uuid, '686c7422-99fa-5a8c-920d-d775fda753d3'::uuid, 'gambhirananda', 'english', 'Those, however, who meditate in every way on the immutable, the indefinable, the unmanifest, which is all-pervasive, incomprehensible, unchanging, immovable, and constant.'),
('d92c7777-fa15-5da4-8214-b2ea4a6fa39d'::uuid, '686c7422-99fa-5a8c-920d-d775fda753d3'::uuid, 'sivananda', 'english', 'Those who worship the imperishable, the indefinable, the unmanifest, the omnipresent, the unthinkable, the immovable, and the eternal.'),
('0aaa38f6-fccb-563c-864a-35443cd3df14'::uuid, 'd6a36d9f-78dc-5610-97be-4c0756c3c0b2'::uuid, 'gambhirananda', 'english', 'By fully controlling all the organs and remaining even-minded at all times, they, engaged in the welfare of all beings, attain Me alone.'),
('0c622752-d74e-54f0-96f9-9678ed40578e'::uuid, 'd6a36d9f-78dc-5610-97be-4c0756c3c0b2'::uuid, 'sivananda', 'english', 'Having restrained all the senses, being even-minded everywhere, and intent on the welfare of all beings, they verily come unto Me.'),
('1fa3c3ee-cb7b-5744-b802-ba299ed5bd7d'::uuid, '579f4b38-2ad4-5f54-b09d-78a3ab3550d2'::uuid, 'gambhirananda', 'english', 'For those whose minds are attached to the Unmanifested, the struggle is greater; for the Goal, which is the Unmanifest, is attained with difficulty by the embodied ones.'),
('fc08b5e9-4fe8-5fa3-b8cb-1921d89a2c4c'::uuid, '579f4b38-2ad4-5f54-b09d-78a3ab3550d2'::uuid, 'sivananda', 'english', 'Greater is their trouble whose minds are set on the unmanifested, for the goal of the unmanifested is very hard for the embodied to reach.'),
('1c2275d7-80f4-59ea-8fb9-0db85fd2678f'::uuid, '0a2b22d9-aecb-5774-9032-a79648cafb3b'::uuid, 'gambhirananda', 'english', 'As for those who, having dedicated all actions to Me and accepted Me as the supreme, meditate on Me with single-minded concentration only-.'),
('896d5c0e-4a9e-5e63-b3f1-75b5e8f51efe'::uuid, '0a2b22d9-aecb-5774-9032-a79648cafb3b'::uuid, 'sivananda', 'english', 'But to those who worship Me, renouncing all actions in Me, regarding Me as the supreme goal, meditating on Me with single-minded yoga.'),
('24ebf95f-599b-595e-af82-c79266247ea1'::uuid, '67e5f4ad-737f-5979-8ef3-64014b903963'::uuid, 'gambhirananda', 'english', 'O son of Prtha, for those who have their minds absorbed in Me, I become, without delay, the deliverer from the sea of the world, which is fraught with death.'),
('20a69019-cdde-5286-a849-76c88aae331c'::uuid, '67e5f4ad-737f-5979-8ef3-64014b903963'::uuid, 'sivananda', 'english', 'To those whose minds are set on Me, O Arjuna, verily I soon become the savior out of the ocean of Samsara.'),
('57625035-5baf-5558-ba44-f2c1d6506545'::uuid, '18a70a01-bf31-5b20-974d-9eb9a2551d2d'::uuid, 'gambhirananda', 'english', 'Fix the mind on Me alone; in Me alone let the intellect rest. There is no doubt that hereafter you will dwell in Me alone.'),
('0fecf2e5-9d56-5b91-b38f-9de2c5a30289'::uuid, '18a70a01-bf31-5b20-974d-9eb9a2551d2d'::uuid, 'sivananda', 'english', 'Fix your mind on Me, and your intellect in Me. Then you will certainly live in Me alone hereafter.'),
('5c564eaf-5999-5476-b37f-761882b90eec'::uuid, '6ef0f631-b1c8-5809-96f3-33ee56f47a55'::uuid, 'gambhirananda', 'english', 'If, however, you are unable to establish the mind steadily on Me, then, O Dhananjaya, seek to attain Me through the yoga of practice.'),
('48fa0dcb-4728-5a56-a071-8557f7fac734'::uuid, '6ef0f631-b1c8-5809-96f3-33ee56f47a55'::uuid, 'sivananda', 'english', 'If you are unable to fix your mind steadily on Me, then seek to reach Me through the yoga of constant practice, O Arjuna.'),
('a35d6ef3-93e9-59ff-a793-6cd2be039f5b'::uuid, '5deb16c4-4ee5-5bf4-a8b0-ba44108c0633'::uuid, 'gambhirananda', 'english', 'If you are unable even to practice, be intent on works for Me. By undertaking works for Me as well, you will attain perfection. [Identify with Brahman.]'),
('445863c2-e162-5155-8662-175b605fe95f'::uuid, '5deb16c4-4ee5-5bf4-a8b0-ba44108c0633'::uuid, 'sivananda', 'english', 'If you are unable to practice even this Abhyasa Yoga, be intent on doing actions for My sake; even by doing actions for My sake, you will attain perfection.'),
('77c47ed0-4698-5b0c-a3f6-ad24966ba6fd'::uuid, 'da0bd3d1-5dbb-553e-a45e-8d1fd05111c3'::uuid, 'gambhirananda', 'english', 'If you are unable to do even this, then resort to the Yoga for Me and afterwards, control your mind and renounce the results of all your works.'),
('6f4b1d2f-a64f-515b-8e47-4da379d9b8e0'::uuid, 'da0bd3d1-5dbb-553e-a45e-8d1fd05111c3'::uuid, 'sivananda', 'english', 'If you are unable to do even this, then, resort to union with Me and renounce the fruits of all actions with self-control.'),
('e0ec4d7c-fdbe-524f-addb-e1eef904da32'::uuid, 'bf12ad55-b500-5f2c-932d-ade38a585961'::uuid, 'gambhirananda', 'english', 'Knowledge is certainly superior to practice; meditation surpasses knowledge. The renunciation of the results of works surpasses meditation. From renunciation, peace follows immediately.'),
('19c5458e-f850-5bcc-af65-5ebf2e8100d1'::uuid, 'bf12ad55-b500-5f2c-932d-ade38a585961'::uuid, 'sivananda', 'english', 'Better indeed is knowledge than practice; better than knowledge is meditation; better than meditation is the renunciation of the fruits of actions: peace immediately follows renunciation.'),
('376cde24-36c9-5c01-bef0-31eb84972262'::uuid, 'f436e2e9-c483-579a-aa80-ca9bf18c84e0'::uuid, 'gambhirananda', 'english', 'He who is not hateful towards any creature, who is friendly and compassionate, who has no concept of ''mine'' and no sense of egoism, who remains the same in sorrow and happiness, and who is forgiving;'),
('4a0e251b-541f-595f-a672-333cb45c5159'::uuid, 'f436e2e9-c483-579a-aa80-ca9bf18c84e0'::uuid, 'sivananda', 'english', 'He who hates no creature, is friendly and compassionate to all, is free from attachment and egoism, is balanced in pleasure and pain, and is forgiving.'),
('c56a73db-831c-51dd-9b94-6a87e69f2d3d'::uuid, '8348abef-4e59-5cf9-893d-de6e33e3aef7'::uuid, 'gambhirananda', 'english', 'He who is ever content, who is a yogi, who has self-control, who has firm conviction, and who has dedicated his mind and intellect to Me—he who is such a devotee of Mine is dear to Me.'),
('c9073128-cfc8-518b-9387-1e6010c9b72d'::uuid, '8348abef-4e59-5cf9-893d-de6e33e3aef7'::uuid, 'sivananda', 'english', 'Ever content, steady in meditation, self-controlled, possessing firm conviction, with the mind and intellect dedicated to Me, he, My devotee, is dear to Me.'),
('31acc67d-5f6e-5a3a-888d-a37073077e17'::uuid, '89c6ed3c-4eb2-53a3-b770-cf9debcfc3b2'::uuid, 'gambhirananda', 'english', 'He, too, owing to whom the world is not disturbed, and who is not disturbed by the world, who is free from joy, impatience, fear, and anxiety, is dear to me.'),
('f2a61708-bbfb-5d78-be22-017d40a0c9b9'::uuid, '89c6ed3c-4eb2-53a3-b770-cf9debcfc3b2'::uuid, 'sivananda', 'english', 'He whom the world does not agitate, and who cannot be agitated by the world, and who is freed from joy, anger, fear, and anxiety—he is dear to Me.'),
('4042e71b-43db-5767-a63c-61ddd973ea83'::uuid, '0290ea0a-4d78-5d22-9394-d5a449123cdc'::uuid, 'gambhirananda', 'english', 'He who has no desires, who is pure, dexterous, impartial, free from fear, and who has renounced every undertaking—such a devotee of Mine is dear to Me.'),
('ffbe5930-6e72-5f24-a333-c9d8dc0d8bb7'::uuid, '0290ea0a-4d78-5d22-9394-d5a449123cdc'::uuid, 'sivananda', 'english', 'He who is free from wants, pure, expert, unconcerned, and free from pain, renouncing all undertakings and commencements, he who is devoted to Me is dear to Me.'),
('16dbcf94-53e9-5872-8e9f-2de725d57690'::uuid, '7d5546bd-b4f0-53e6-be61-9de2239d80a6'::uuid, 'gambhirananda', 'english', 'He who does not rejoice, nor fret, nor lament, nor hanker; who gives up both good and bad, and is filled with devotion—he is dear to Me.'),
('e67ebc12-c58c-516d-8389-b3362fde15f8'::uuid, '7d5546bd-b4f0-53e6-be61-9de2239d80a6'::uuid, 'sivananda', 'english', 'He who neither rejoices nor hates, nor grieves nor desires, renouncing both good and evil, and who is full of devotion, is dear to Me.'),
('925f94c8-6103-51fb-a643-e46b66155ef2'::uuid, 'c8be94c2-6220-5c29-9ebf-3adf9ddd4e58'::uuid, 'gambhirananda', 'english', 'He who is the same towards friend and foe, and in honor and dishonor; who is the same under cold, heat, happiness, and sorrow; who is free from attachment to all.'),
('ba266993-78ed-53a3-adc4-adf6f3a0ddfb'::uuid, 'c8be94c2-6220-5c29-9ebf-3adf9ddd4e58'::uuid, 'sivananda', 'english', 'He who is the same to foe and friend, and also in honor and dishonor, who is the same in cold and heat, in pleasure and pain, and who is free from attachment.'),
('bb39dfb9-14f0-5746-b75b-e6df683e18f7'::uuid, 'ef8ab183-dc1a-5bbb-8a67-8718aa926bb8'::uuid, 'gambhirananda', 'english', 'The person to whom denunciation and praise are the same, who is silent, content with anything, homeless, steadfast-minded, and full of devotion is dear to me.'),
('4ac93e88-5087-5e06-a8a5-1f96f54162d3'::uuid, 'ef8ab183-dc1a-5bbb-8a67-8718aa926bb8'::uuid, 'sivananda', 'english', 'He to whom censure and praise are equal, who is silent, content with anything, homeless, of a steady mind, and full of devotion; that man is dear to me.'),
('a06f2ff6-6af9-5604-863b-a0926d33d8cd'::uuid, 'd71b5192-1e47-5691-88ae-e3302bcb212b'::uuid, 'gambhirananda', 'english', 'But those devotees who accept Me as the supreme Goal, and with faith seek for this ambrosia—nectar in the form of virtue—which is indistinguishable from the virtues as stated above, they are very dear to Me.'),
('802f6e65-1a72-5953-87b9-5e25987379b7'::uuid, 'd71b5192-1e47-5691-88ae-e3302bcb212b'::uuid, 'sivananda', 'english', 'They who follow this immortal Dharma, endowed with faith and regarding Me as their supreme goal, are exceedingly dear to Me.'),
('b39367cb-5963-55d0-882f-2e3fb45d3e38'::uuid, '28eb3377-5a81-5458-9ec1-ba0c094e42e5'::uuid, 'gambhirananda', 'english', 'Swami Gambhirananda has not translated this verse. Many editions of the Bhagavad Gita do not contain this verse, including the commentary by Shankaracharya. If this verse is included, the total number of verses in the Bhagavad Gita is 701.'),
('e38fecd0-f2e9-55fd-aac5-42a1d42b9d59'::uuid, '28eb3377-5a81-5458-9ec1-ba0c094e42e5'::uuid, 'sivananda', 'english', 'Arjuna said, "I wish to learn about Nature and the Spirit, the field and the knower of the field, knowledge and that which ought to be known, O Kesava."'),
('a9006a87-8223-5871-8fca-3f650161e41b'::uuid, 'ab165159-e56e-56f5-b5d7-eb0ac14c988d'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "O son of Kunti, this body is referred to as the ''field''. Those who are versed in this call him who is conscious of it the ''knower of the field''."'),
('d22e7762-6eaf-5cd1-b807-7bd308e13d12'::uuid, 'ab165159-e56e-56f5-b5d7-eb0ac14c988d'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "O Arjuna, this body is called the field; he who knows it is called the knower of the field by those who know them."'),
('8d260354-a9d0-59fa-9b95-5563d3b2b65e'::uuid, '75849c61-1df7-5e2f-8b9e-5da603950fcb'::uuid, 'gambhirananda', 'english', 'And, O scion of the Bharata dynasty, understand Me to be the ''Knower of the field'' in all the fields. In My opinion, that is Knowledge which is the knowledge of the field and the knower of the field.'),
('4af0dbaa-68bb-5517-81d4-8e4c93c9255e'::uuid, '75849c61-1df7-5e2f-8b9e-5da603950fcb'::uuid, 'sivananda', 'english', 'Do thou also know Me as the knower of the field in all fields, O Arjuna. Knowledge of both the field and the knower of the field is considered by Me to be the knowledge.'),
('02498cca-f9c5-5221-bd2e-86c3cc534291'::uuid, '67663178-cb87-5b18-aac6-1316d1fa8d35'::uuid, 'gambhirananda', 'english', 'Hear from Me in brief about all that, what that field is and how it is; what its changes are, and what causes what effect; and who He is, and what His powers are.'),
('061b26eb-0463-5404-be9d-0a2ca2116c47'::uuid, '67663178-cb87-5b18-aac6-1316d1fa8d35'::uuid, 'sivananda', 'english', 'Hear from Me in brief what the field is, of what nature it is, what its modifications are, whence it is, who He is, and what His powers are.'),
('db5282db-3a5f-505b-b0d2-faf1346750f9'::uuid, 'eab8c5c8-95d1-5393-89be-4a92466c8c38'::uuid, 'gambhirananda', 'english', 'It has been sung of in various ways by the Rsis, separately by the different branches of Vedic texts, and also by the rational and convincing sentences themselves which are indicative of and lead to Brahman.'),
('260d46a9-19bb-56a8-92ea-37498199224c'::uuid, 'eab8c5c8-95d1-5393-89be-4a92466c8c38'::uuid, 'sivananda', 'english', 'Sages have sung in many ways, with various distinctive chants and also with suggestive words indicative of the Absolute, full of reasoning and decisive.'),
('c3200ff6-786c-5308-a4a9-f0074fe38ee3'::uuid, 'd221307c-21bb-53a0-8bb8-a778d9c65ea1'::uuid, 'gambhirananda', 'english', 'The great elements, egoism, intellect, and the Unmanifest itself; the ten organs and the one, and the five objects of the senses;'),
('068986fc-2b30-5c0e-9d04-048521f0906b'::uuid, 'd221307c-21bb-53a0-8bb8-a778d9c65ea1'::uuid, 'sivananda', 'english', 'The great elements, egoism, intellect, and also the Unmanifested Nature, the ten senses, and one mind, and the five objects of the senses.'),
('f22399a7-8474-5962-8a68-18b6a3e4390a'::uuid, '4fecdcdf-f181-564d-862e-094778c09383'::uuid, 'gambhirananda', 'english', 'Desire, repulsion, happiness, sorrow, the aggregate (of body and organs), sentience, fortitude—this field, together with its modifications, has been spoken of briefly.'),
('c9521b0a-c4a4-5303-9c6d-2c57aae65962'::uuid, '4fecdcdf-f181-564d-862e-094778c09383'::uuid, 'sivananda', 'english', 'Desire, hatred, pleasure, pain, the aggregate (body), intelligence, and fortitude—the field has thus been briefly described with its modifications.'),
('e13dcba0-5fad-50d0-b4a8-4d5a1620a2c8'::uuid, '0a6aaad4-176e-5534-b4ad-a5bc7fce3ae1'::uuid, 'gambhirananda', 'english', 'Humility, unpretentiousness, non-injury, forbearance, sincerity, service to the teacher, cleanliness, steadiness, and control of the body and its organs;'),
('a673152c-7c70-5aac-bf00-45a8ec747bca'::uuid, '0a6aaad4-176e-5534-b4ad-a5bc7fce3ae1'::uuid, 'sivananda', 'english', 'Humility, unpretentiousness, non-injury, forgiveness, uprightness, service to the teacher, purity, steadfastness, and self-control.'),
('c614f31c-332b-506d-a311-fe3fe55f36bb'::uuid, '8651ec69-3512-5cdb-9f4e-4be93fa3a48a'::uuid, 'gambhirananda', 'english', 'Non-attachment to objects of the senses, and also the absence of egotism; seeing the evil in birth, death, aging, diseases, and miseries;'),
('b5df7f86-efa6-5809-b5b3-5628ab77fe98'::uuid, '8651ec69-3512-5cdb-9f4e-4be93fa3a48a'::uuid, 'sivananda', 'english', 'Indifference to the objects of the senses and also absence of egoism; perceiving the evil in birth, death, old age, sickness, and pain.'),
('4d323969-9324-55bc-945a-6fa3adc0b8bf'::uuid, '8867c1ab-4570-5743-8323-4249d8e4a7ae'::uuid, 'gambhirananda', 'english', 'Non-attachment and absence of fondness with regard to sons, wives, homes, etc., and constant equanimity of the mind with regard to the attainment of both the desirable and the undesirable;'),
('f8862f3a-0541-57bf-a70c-c6309a7e4532'::uuid, '8867c1ab-4570-5743-8323-4249d8e4a7ae'::uuid, 'sivananda', 'english', 'Non-attachment, non-identification of the Self with son, wife, home, and the rest, and constant even-mindedness in the face of the attainment of both desirable and undesirable.'),
('ea5bafcc-dc79-52da-8fec-38e913e9e169'::uuid, '7d239131-6022-5a71-8e31-90a0b90e6157'::uuid, 'gambhirananda', 'english', 'And unwavering devotion to Me with single-minded concentration; inclination to retreat to a clean place; lack of delight in a crowd of people;'),
('b298e065-40fc-5dbc-b2fd-b32a741b23e6'::uuid, '7d239131-6022-5a71-8e31-90a0b90e6157'::uuid, 'sivananda', 'english', 'Unswerving devotion to Me through the Yoga of non-separation, resorting to solitary places, and a distaste for the company of people.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('016efed5-75cb-59d0-8cd8-8643c6ccd4f7'::uuid, '412cce2c-fc8f-57e9-b337-558b69c0de45'::uuid, 'gambhirananda', 'english', 'Steadfastness in the knowledge of the Self, contemplation on the Goal of the knowledge of Reality—this is spoken of as Knowledge. Ignorance is that which is other than this.'),
('01aa89b6-487b-5fa8-80a1-da7796beffaa'::uuid, '412cce2c-fc8f-57e9-b337-558b69c0de45'::uuid, 'sivananda', 'english', 'Constancy in Self-knowledge, the perception of the end of true knowledge—this is declared to be knowledge, and what is opposed to it is ignorance.'),
('81dab809-01e1-57c1-9a80-08208286578e'::uuid, '7a07da7b-b4bc-5365-b580-4bd91064e91f'::uuid, 'gambhirananda', 'english', 'I shall speak of that which is to be known, by realizing which one attains immortality. The supreme Brahman is without any beginning; that is called neither being nor non-being.'),
('a39e8ab3-26a1-5814-b648-4b4f315af2a9'::uuid, '7a07da7b-b4bc-5365-b580-4bd91064e91f'::uuid, 'sivananda', 'english', 'I will declare that which is to be known, knowing which one attains immortality; the beginningless Supreme Brahman, which is neither being nor non-being.'),
('877e8c98-8181-5531-a5cd-80c002b38b0e'::uuid, 'eb20a4db-bd61-5525-b49c-cf2581122a7a'::uuid, 'gambhirananda', 'english', 'That Knowable, which has hands and feet everywhere, which has eyes, heads, and mouths everywhere, which has ears everywhere, exists in creatures by pervading them all.'),
('bdd03ddb-f227-5050-b4a7-3389388ba444'::uuid, 'eb20a4db-bd61-5525-b49c-cf2581122a7a'::uuid, 'sivananda', 'english', 'With hands and feet everywhere, with eyes, heads, and mouths everywhere, with ears everywhere, He exists in the worlds, enveloping all.'),
('403568dd-ea57-5d78-98b9-9f7326d93533'::uuid, '93799091-8a25-5dd0-9999-5d123c5d3225'::uuid, 'gambhirananda', 'english', 'Shining through the functions of all the organs, yet devoid of all the organs; unattached, and verily the supporter of all; without quality, and the perceiver of qualities.'),
('61ec1b27-b4c1-5549-b416-ae10dd3cf822'::uuid, '93799091-8a25-5dd0-9999-5d123c5d3225'::uuid, 'sivananda', 'english', 'Shining by the functions of all the senses, yet without being attached to them; unattached, yet supporting all; devoid of qualities, yet the experiencer of them.'),
('7b64c80e-8dd3-5ba4-8a63-64ed98f9c4f0'::uuid, '75629797-0700-5fa5-af78-1c500f574f36'::uuid, 'gambhirananda', 'english', 'Existing both outside and inside all beings, moving and non-moving, It is incomprehensible due to Its subtlety. It is far away, yet near.'),
('dc7975c0-0aec-5c0f-873a-33b6751a59ec'::uuid, '75629797-0700-5fa5-af78-1c500f574f36'::uuid, 'sivananda', 'english', 'It is within and without all beings, both the unmoving and the moving; It is subtle and unknowable, and It is near and far away.'),
('b7ebb6ff-2b3a-57b4-9787-002dbc18eb43'::uuid, '99134278-0eff-5b1e-9164-17abb1ab74b2'::uuid, 'gambhirananda', 'english', 'The Knowable, though undivided, appears to exist as divided in all beings, and It is the sustainer, devourer, and originator of all beings.'),
('4f6b3b85-310c-5897-9511-a8921fd88348'::uuid, '99134278-0eff-5b1e-9164-17abb1ab74b2'::uuid, 'sivananda', 'english', 'Undivided yet, It exists as if divided in beings; It is to be known as the supporter of beings; It devours and It generates.'),
('a99fe750-2db5-5f5a-aa8d-696e9b4d4082'::uuid, 'd2804118-d15b-5286-8f42-34f32a338726'::uuid, 'gambhirananda', 'english', 'That is the Light of all lights; It is spoken of as beyond darkness. It is Knowledge, the Knowable, and the Known. It is specially situated in the hearts of all.'),
('86a2b3dd-71a3-51d2-be2f-a04b06c5c3dc'::uuid, 'd2804118-d15b-5286-8f42-34f32a338726'::uuid, 'sivananda', 'english', 'That Light of all lights is said to be beyond darkness: knowledge, the knowable, and the goal of knowledge, seated in the hearts of all.'),
('2fa3c300-653a-5bb3-9aa9-4bf61aca1adf'::uuid, '2dc1b5da-fa89-54d4-a7c0-a67ef381e075'::uuid, 'gambhirananda', 'english', 'Thus, in brief, the field, Knowledge, and the Knowable have been spoken of. By understanding this, My devotee becomes qualified for My state.'),
('5dc51a79-5aad-5860-ae05-7c18ad6156fd'::uuid, '2dc1b5da-fa89-54d4-a7c0-a67ef381e075'::uuid, 'sivananda', 'english', 'Thus, the field, as well as knowledge and the knowable, have been briefly stated. My devotee, knowing this, enters into My being.'),
('dfd497e3-1bfd-5b1d-9db7-75bffdafdeb8'::uuid, '7e8bf466-cc54-5a57-826a-fe9d24787dc6'::uuid, 'gambhirananda', 'english', 'Know both Nature and the individual soul to be verily without beginning; know the modifications as well as the qualities to be born of Nature.'),
('ba728d01-7b0f-5b75-a4ea-58060984efcb'::uuid, '7e8bf466-cc54-5a57-826a-fe9d24787dc6'::uuid, 'sivananda', 'english', 'Know that Nature (matter) and the Spirit are both beginningless, and know also that all modifications and qualities are born from Nature.'),
('d2873f5a-ad2c-59b9-bee8-4735c647fdd8'::uuid, 'bd572132-785c-58ce-930e-491ac888b364'::uuid, 'gambhirananda', 'english', 'With regard to the source of the body and its organs, Nature is said to be the cause; the soul is the cause so far as the enjoyment of happiness and sorrow is concerned.'),
('c8323156-818c-57c1-90c1-712ab54174e0'::uuid, 'bd572132-785c-58ce-930e-491ac888b364'::uuid, 'sivananda', 'english', 'In the production of the effect and the cause, Nature (matter) is said to be the cause; in the experience of pleasure and pain, the soul is said to be the one responsible.'),
('9c71f8e7-7285-562d-b1f8-c03838aac071'::uuid, '1ffbd5ac-37a8-5a4e-8d62-e031d04ab246'::uuid, 'gambhirananda', 'english', 'Since the soul is seated in Nature, therefore it experiences the qualities born of Nature. Contact with the qualities is the cause of its births in good and evil wombs.'),
('e73f112b-47a0-5ffd-9acd-3ebfde00cb10'::uuid, '1ffbd5ac-37a8-5a4e-8d62-e031d04ab246'::uuid, 'sivananda', 'english', 'The soul seated in Nature experiences the qualities born of Nature; attachment to the qualities is the cause of its birth in good and evil wombs.'),
('ba5bb795-9050-5eec-9550-0da814aaa42a'::uuid, '1d11b633-697d-5909-a138-628b16c65a1b'::uuid, 'gambhirananda', 'english', 'He who is the Witness, the Permitter, the Sustainer, the Experiencer, the great Lord, and who is also spoken of as the transcendental Self, is the supreme Person in this body.'),
('d5a1931d-1c79-5916-81da-658561bd8b1b'::uuid, '1d11b633-697d-5909-a138-628b16c65a1b'::uuid, 'sivananda', 'english', 'The Supreme Soul in this body is also called the observer, the permitter, the sustainer, the enjoyer, the great Lord, and the Supreme Self.'),
('571be353-5d54-50cb-94cf-6951a62c2884'::uuid, 'bef08c94-dfab-5a45-bc24-1d290efc6994'::uuid, 'gambhirananda', 'english', 'He who knows thus the Person, Nature, and Qualities will not be born again, no matter how he may live.'),
('6068afd3-94a6-5d77-b66b-6cfa7c717e6e'::uuid, 'bef08c94-dfab-5a45-bc24-1d290efc6994'::uuid, 'sivananda', 'english', 'He who thus knows the Spirit and Matter together with their qualities, in whatever condition he may be, he is not reborn.'),
('10b26b6e-df78-5b73-a255-3245e2df61a5'::uuid, '8ffe367b-2ca1-5f59-a5d5-475c965e3fad'::uuid, 'gambhirananda', 'english', 'Some realize the Self in their intellect through meditation, others through Sankhya-Yoga, and still others through Karma-Yoga, with the help of the internal organ.'),
('0c1ea169-9433-5760-99d3-13e22e7f6268'::uuid, '8ffe367b-2ca1-5f59-a5d5-475c965e3fad'::uuid, 'sivananda', 'english', 'Some behold the Self within themselves through meditation, others through the Yoga of knowledge, and still others through the Yoga of action.'),
('fda78d1a-060e-5f75-a371-31ac83614b0c'::uuid, 'a705be51-2e65-5c78-b7bf-8e8882eaec04'::uuid, 'gambhirananda', 'english', 'Others, again, who do not know thus, take to thinking after hearing from others; they too, who are devoted to hearing, certainly overcome death.'),
('497af600-282c-568d-a4a1-3d2a23c719f5'::uuid, 'a705be51-2e65-5c78-b7bf-8e8882eaec04'::uuid, 'sivananda', 'english', 'Others, too, who do not know thus, worship, having heard of It from others; they, too, cross beyond death, regarding what they have heard as the supreme refuge.'),
('456bed8b-8134-54b1-a2f8-5c7ea7dbcef3'::uuid, 'ced1d908-d1ba-5d43-abea-848734015dfb'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, whatever object, moving or non-moving, comes into existence, know that to be from the combination of the field and the Knower of the field!'),
('bef5b7c9-3105-581e-97cf-93e95ef1b686'::uuid, 'ced1d908-d1ba-5d43-abea-848734015dfb'::uuid, 'sivananda', 'english', 'Wherever a being is born, whether unmoving or moving, know thou, O best of the Bharatas (Arjuna), that it is from the union of the field and its knower.'),
('628b1c8a-f745-509d-bb16-5a87893afd76'::uuid, '28c174d8-82db-5d82-a562-b7b32e4e905a'::uuid, 'gambhirananda', 'english', 'He who sees the Supreme Lord existing truly in all beings, and the Imperishable among the perishable, sees indeed.'),
('3423e996-71f8-5a5e-9e2c-6bfb06f11671'::uuid, '28c174d8-82db-5d82-a562-b7b32e4e905a'::uuid, 'sivananda', 'english', 'He who sees the Supreme Lord existing truly in all beings, the imperishable within the perishable, sees indeed.'),
('ed35f467-6709-5f6c-8ca7-7716425bd50d'::uuid, 'abd8d324-d849-5a46-8676-c8e9c7ef53f2'::uuid, 'gambhirananda', 'english', 'Since, by truly seeing God, who is present everywhere alike, he does not injure the Self by the Self, he therefore attains the supreme Goal.'),
('5e6e00f2-623d-5d0e-9976-b0b062858259'::uuid, 'abd8d324-d849-5a46-8676-c8e9c7ef53f2'::uuid, 'sivananda', 'english', 'For he who truly sees the same Lord dwelling everywhere does not destroy the Self by the self; rather, he attains the highest goal.'),
('2219ad9c-2b29-53fe-901f-8bc313cf3e6b'::uuid, '3bcb6772-fe6f-5355-acaf-232cc201ca42'::uuid, 'gambhirananda', 'english', 'And he who sees actions being done in various ways by Nature itself, and also the Self as the non-agent, he sees.'),
('42f3b450-406f-531d-89b1-ec501afb3347'::uuid, '3bcb6772-fe6f-5355-acaf-232cc201ca42'::uuid, 'sivananda', 'english', 'He sees, who sees that all actions are performed solely by Nature and that the Self is without action.'),
('877f6176-c6f5-502b-9275-ae91d605094a'::uuid, 'b36737b3-0163-5e9a-8040-f5b562cc4238'::uuid, 'gambhirananda', 'english', 'When one realizes that the state of diversity of living things is rooted in the One, and that their manifestation also comes from That, then one becomes identified with Brahman.'),
('fd852be9-fade-5fb5-af75-4cbc1493796c'::uuid, 'b36737b3-0163-5e9a-8040-f5b562cc4238'::uuid, 'sivananda', 'english', 'When a person sees all beings as resting in the One and emanating from the One alone, they then become Brahman.'),
('01ff95ca-5270-5894-94bf-9b66d90be07d'::uuid, 'b2441b8d-92e6-5b6d-ac07-d8382329474f'::uuid, 'gambhirananda', 'english', 'Being without beginning and without end, O son of Kunti, this immutable, supreme Self does not act, nor is It affected [Also translated as tainted.-Tr.], although It exists in the body.'),
('812371e5-be2f-502c-959c-46b531a2008e'::uuid, 'b2441b8d-92e6-5b6d-ac07-d8382329474f'::uuid, 'sivananda', 'english', 'Being without beginning, devoid of any qualities, the Supreme Self, imperishable, though dwelling in the body, O Arjuna, neither acts nor is tainted.'),
('d57bd51c-6849-5258-9549-6cd309f4f82c'::uuid, '4c6e64a9-14d5-5690-b9f3-68f6c6ba3028'::uuid, 'gambhirananda', 'english', 'As the all-pervading space is not defiled, due to its subtlety, similarly the Self, present everywhere in bodies, is not defiled.'),
('267dea65-4dc7-5ee2-9bb1-5cf70d331e19'::uuid, '4c6e64a9-14d5-5690-b9f3-68f6c6ba3028'::uuid, 'sivananda', 'english', 'As the all-pervading ether is not tainted, due to its subtlety, so the Self seated everywhere in the body is not tainted either.'),
('4ccd82e9-e056-56c1-ae61-472bede9ef42'::uuid, '83904f5e-00c8-5f1e-b461-91f6e7852940'::uuid, 'gambhirananda', 'english', 'As the single sun illuminates this entire world, similarly, O descendant of the Bharata dynasty, the Knower of the field illuminates the entire field.'),
('927302d2-b9f6-527f-bc55-65b4a910f847'::uuid, '83904f5e-00c8-5f1e-b461-91f6e7852940'::uuid, 'sivananda', 'english', 'Just as the one sun illuminates the entire world, so too does the Lord of the field (Supreme Self) illuminate the entire field, O Arjuna.'),
('1d931008-8c92-5ab0-ba20-8f90f7b02ca9'::uuid, '2ca4e792-b204-5c58-a965-56e2e57eeeff'::uuid, 'gambhirananda', 'english', 'Those who, through the eye of wisdom, know the distinction between the field and the Knower of the field, and the annihilation of the Matrix of beings, reach the Supreme.'),
('75a6a62d-9484-5417-961f-cca2e7fbf875'::uuid, '2ca4e792-b204-5c58-a965-56e2e57eeeff'::uuid, 'sivananda', 'english', 'They who, by the eye of knowledge, perceive the distinction between the field and its knower, as well as the liberation from the Nature of being, go to the Supreme.'),
('990dc932-c136-5d8b-9f95-a1bd634ec993'::uuid, '86f46b0a-84f8-5a26-8818-5b6824479173'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "I shall speak again of the supreme knowledge, the best of all knowledge, by realizing which all the contemplatives have reached the highest perfection from here."'),
('31411bf8-026a-5f5c-bf50-3d69a41e39f6'::uuid, '86f46b0a-84f8-5a26-8818-5b6824479173'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "I will again declare to thee that supreme knowledge, the best of all knowledge, having known which all the sages have gone to supreme perfection after this life."'),
('5b3c7fb0-ac32-5fe9-9460-a6891d7182f7'::uuid, '830be355-3c87-5597-9686-3ed01f7a69fb'::uuid, 'gambhirananda', 'english', 'Those who attain identity with Me by resorting to this Knowledge are not born even during creation, nor do they suffer pain during dissolution.'),
('c47bb15a-3c77-566e-9ed6-5b2772b3a590'::uuid, '830be355-3c87-5597-9686-3ed01f7a69fb'::uuid, 'sivananda', 'english', 'Those who, having taken refuge in this knowledge, have attained unity with Me, are neither born at the time of creation nor disturbed at the time of dissolution.'),
('4dd9c4a2-feeb-5f69-aae1-afa59b3c9591'::uuid, 'd92d986f-4c0a-5b0e-a430-bd6259c567a8'::uuid, 'gambhirananda', 'english', 'My womb is the great sustainer. In it, I place the seed. From that, O scion of the Bharata dynasty, all things are born.'),
('b45fab5b-b2bf-539f-a56f-297c8ff74088'::uuid, 'd92d986f-4c0a-5b0e-a430-bd6259c567a8'::uuid, 'sivananda', 'english', 'My womb is the great Brahma; in it I place the germ; thence, O Arjuna, is the birth of all beings.'),
('05448e36-3a43-5138-b091-0cb4f75635ad'::uuid, '06c1ae51-a800-5185-88f4-c4423ebafa69'::uuid, 'gambhirananda', 'english', 'O son of Kunti, whatever forms are born from all the wombs, of them the great sustainer is the womb; I am the father who deposits the seed.'),
('6d0fef65-2fe3-5523-a48e-c7b54bf58229'::uuid, '06c1ae51-a800-5185-88f4-c4423ebafa69'::uuid, 'sivananda', 'english', 'Whatever forms are produced, O Arjuna, in any womb whatsoever, the great Brahma is their womb, and I am the seed-giving father.'),
('48f42b21-4bd3-59b4-9f8b-bb4c6e0cb55f'::uuid, '06858a54-f524-5fb7-90f3-04ae7950bba1'::uuid, 'gambhirananda', 'english', 'O mighty-armed one, the qualities, viz. sattva, rajas, and tamas, born of Nature, are the immutable embodiments belonging to the body.'),
('6160145d-52ac-57d9-b650-e325b6aa2dc9'::uuid, '06858a54-f524-5fb7-90f3-04ae7950bba1'::uuid, 'sivananda', 'english', 'These qualities, O Arjuna, born of Nature, bind fast in the body of the embodied, the indestructible: purity, passion, and inertia.'),
('3bfa8dd9-8685-5f41-8df2-7185bb7b1f80'::uuid, '595f34ef-b382-54d9-a630-1deb1b6cf316'::uuid, 'gambhirananda', 'english', 'Among them, sattva, being pure and nirmala (pure-transparent, i.e., capable of resisting any form of ignorance, and hence an illuminator, i.e. a revealer of Consciousness), is harmless. O sinless one, it binds through attachment to happiness and attachment to knowledge.'),
('3d1a0d36-2011-5cd6-b349-7c67cc936f0a'::uuid, '595f34ef-b382-54d9-a630-1deb1b6cf316'::uuid, 'sivananda', 'english', 'Of these, sattva, which is luminous and healthy due to its stainlessness, binds one by attachment to happiness and knowledge, O sinless one.'),
('17c569e0-e0c6-5903-a2ca-75248afb7b20'::uuid, 'e855623e-3365-5e49-9caa-782558de5a99'::uuid, 'gambhirananda', 'english', 'Know rajas to be of the nature of passion, born of hankering and attachment. O son of Kunti, it binds the embodied one through attachment to action.'),
('1d5bed51-1cf4-52a8-bc7c-43f09c95b23a'::uuid, 'e855623e-3365-5e49-9caa-782558de5a99'::uuid, 'sivananda', 'english', 'Know, O Arjuna, that Rajas is of the nature of passion, the source of thirst and attachment; it binds fast the embodied one by attachment to action.'),
('910af461-36d8-55e0-bd83-fc75fef1d6f0'::uuid, 'b629dcf6-0352-58d3-848c-87c9e55a1a28'::uuid, 'gambhirananda', 'english', 'On the other hand, know tamas, which deludes all embodied beings, to be born of ignorance. O scion of the Bharata dynasty, it binds through inadvertence, laziness, and sleep.'),
('88bfe381-173f-5b80-8d59-bf7878a346ab'::uuid, 'b629dcf6-0352-58d3-848c-87c9e55a1a28'::uuid, 'sivananda', 'english', 'But know thou Tamas to be born of ignorance, deluding all embodied beings; it binds fast, O Arjuna, through heedlessness, indolence, and sleep.'),
('5d56e353-db60-5231-8b07-58cf7cf93480'::uuid, 'a1a11f9b-78df-590a-b785-080e0fd6a982'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, sattva attaches one to happiness, rajas to action, while tamas, obscuring knowledge, leads to inadvertence as well.'),
('70937e3f-6888-539e-9203-a58efa51f41d'::uuid, 'a1a11f9b-78df-590a-b785-080e0fd6a982'::uuid, 'sivananda', 'english', 'Sattva attaches to happiness, Rajas to action, O Arjuna, while Tamas, verily shrouding knowledge, attaches to heedlessness.'),
('97f86e99-c109-57df-a731-c2eaf0e948c3'::uuid, '704e6bd1-354d-58f9-beeb-fd502170b917'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, sattva increases by subduing rajas and tamas; rajas increases by overpowering sattva and tamas; and tamas increases by dominating over sattva and rajas.'),
('fa201d44-8e6f-5990-8221-a6ffd085ff1f'::uuid, '704e6bd1-354d-58f9-beeb-fd502170b917'::uuid, 'sivananda', 'english', 'Now, O Arjuna, Sattva prevails, having overpowered Rajas and Tamas; then Rajas, having overpowered Sattva and Tamas; and then Tamas, having overpowered Sattva and Rajas.'),
('30b3e785-ea1e-5984-b44d-739cea9d09de'::uuid, '5e260453-9835-5d7f-98b6-e9ba5e6f5d3f'::uuid, 'gambhirananda', 'english', 'When the illumination of knowledge radiates through all the doors of the senses in this body, then one should know that sattva has greatly increased.'),
('41045880-48ea-5fa8-8be4-06a17fbce96d'::uuid, '5e260453-9835-5d7f-98b6-e9ba5e6f5d3f'::uuid, 'sivananda', 'english', 'When the wisdom-light shines through every gate of this body, then it may be known that Sattva is predominant.'),
('ad350e06-1a47-5177-b1bc-84063212c874'::uuid, '15b065a1-af85-5564-938c-52c64c667ccf'::uuid, 'gambhirananda', 'english', 'O best of the Bharata dynasty, when rajas becomes predominant, these come into being: avarice, restlessness, undertaking of actions, agitation, and craving.'),
('3cf282be-5656-5341-a39c-66ed01d536e3'::uuid, '15b065a1-af85-5564-938c-52c64c667ccf'::uuid, 'sivananda', 'english', 'Greed, activity, the undertaking of actions, restlessness, and longing—these arise when Rajas is predominant, O Arjuna.'),
('73cd7d90-15a8-53ff-89cd-da12d354886f'::uuid, '6bb07e5f-6b70-5e92-8f9d-fe02e4dcb0d3'::uuid, 'gambhirananda', 'english', 'O descendant of the Kuru dynasty, when tamas predominates, these come into being without exception: non-discrimination, inactivity, inadvertence, and delusion.'),
('28c81084-51ce-5418-86af-ca551f3ddb90'::uuid, '6bb07e5f-6b70-5e92-8f9d-fe02e4dcb0d3'::uuid, 'sivananda', 'english', 'Darkness, inertia, carelessness, and delusion—these arise when Tamas is predominant, O Arjuna.'),
('cbee7d41-cc8f-5b8a-b9eb-61227c29eb41'::uuid, 'b291ca93-dd01-52b0-95c2-44dc8992a08d'::uuid, 'gambhirananda', 'english', 'When an embodied one undergoes death while sattva is exclusively predominant, then he attains the untainted worlds of those who know the highest (entities).'),
('93adf391-5b3c-55e3-917c-cf5d7134cbe9'::uuid, 'b291ca93-dd01-52b0-95c2-44dc8992a08d'::uuid, 'sivananda', 'english', 'If the embodied one meets death when Sattva is predominant, then they attain the spotless worlds of the knowers of the Highest.'),
('00d3775d-59a2-5392-b7f6-67dd9af372b1'::uuid, '4b519ef7-1365-55e0-bfc2-32365e90b85d'::uuid, 'gambhirananda', 'english', 'When one dies while rajas predominates, they are born among people attached to activity. Similarly, when one dies while tamas predominates, they take birth among the stupid species.'),
('664ce3e2-ee18-525a-a90a-8f0b362ff153'::uuid, '4b519ef7-1365-55e0-bfc2-32365e90b85d'::uuid, 'sivananda', 'english', 'Meeting death in Rajas, he is born among those who are attached to action; and dying in Tamas, he is born in the womb of the thoughtless.'),
('20472c41-9aa8-5d12-8d83-db6c7bb34f61'::uuid, '4003b52a-9f9e-5fe3-b673-d0801139a377'::uuid, 'gambhirananda', 'english', 'They say that the result of good work is pure and is born of Sattva. But the result of Rajas is sorrow; the result of Tamas is ignorance.'),
('93ac5cb2-e578-560f-9882-52fd0ec1f772'::uuid, '4003b52a-9f9e-5fe3-b673-d0801139a377'::uuid, 'sivananda', 'english', 'They say that the fruit of good action is Sattvic and pure; indeed, the fruit of Rajas is pain, and the fruit of Tamas is ignorance.'),
('aac606cb-c3a5-53c1-b020-43a0f55ab4f6'::uuid, '2440892d-75fe-5a6f-85f5-699df601d4a1'::uuid, 'gambhirananda', 'english', 'From sattva is born knowledge, and from rajas, avarice indeed. From tamas are born inadvertence, delusion, and ignorance, to be sure.'),
('bbce9aa1-fddf-5cda-a828-4cd6163c2669'::uuid, '2440892d-75fe-5a6f-85f5-699df601d4a1'::uuid, 'sivananda', 'english', 'From Sattva arises knowledge, and greed from Rajas; heedlessness and delusion arise from Tamas, and also ignorance.'),
('288ba580-cce1-5466-8387-6c50b6172e93'::uuid, '01baba3e-ee6a-5950-8000-da5f7ac59528'::uuid, 'gambhirananda', 'english', 'People who conform to sattva go higher up; those who conform to rajas stay in the middle; those who conform to tamas, who conform to the actions of the lowest quality, go down.'),
('cafdba41-30a3-53f5-9302-b7ca21140e94'::uuid, '01baba3e-ee6a-5950-8000-da5f7ac59528'::uuid, 'sivananda', 'english', 'Those seated in Sattva ascend; those of Rajasic nature dwell in the middle; and those of Tamasic nature, abiding in the function of the lowest Guna, descend.'),
('464c6a2a-0a0c-51a8-b452-08a88b2faca2'::uuid, 'aaddc709-5c25-51a5-9be1-a3d3613de255'::uuid, 'gambhirananda', 'english', 'When the witness sees none other than the qualities as the agent, and knows that which is superior to the qualities, he attains My nature.'),
('6677a07f-9313-5e64-a20e-7126953c3625'::uuid, 'aaddc709-5c25-51a5-9be1-a3d3613de255'::uuid, 'sivananda', 'english', 'When the seer beholds no agent other than the Gunas and knows that which is higher than them, he attains to My Being.'),
('99c0c835-f8c5-540b-b09b-f55c36eaa7a6'::uuid, '02666ffc-fd3a-5a68-91f5-d081a6c139fa'::uuid, 'gambhirananda', 'english', 'Having transcended these three qualities, which are the origin of the body, the embodied one becomes free from birth, death, old age, and sorrows, and experiences Immortality.'),
('75f5d759-be88-53c7-946f-ab5cab021482'::uuid, '02666ffc-fd3a-5a68-91f5-d081a6c139fa'::uuid, 'sivananda', 'english', 'The embodied one, having crossed beyond these three Gunas from which the body is evolved, is freed from birth, death, decay, and pain, and attains immortality.'),
('68269903-2337-520c-aa2e-82e15a98e437'::uuid, 'f09ea791-acd2-5c87-851f-f1ae61bcdf06'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Lord, by what signs is one known who has gone beyond these three qualities? What is their behavior, and how do they transcend these three qualities?"'),
('d03faa98-3f44-5278-813d-bb4ae1c70b42'::uuid, 'f09ea791-acd2-5c87-851f-f1ae61bcdf06'::uuid, 'sivananda', 'english', 'Arjuna said, "What are the marks of one who has transcended the three qualities, O Lord? What is their conduct, and how do they go beyond these three qualities?"'),
('bda04ebf-e945-564e-a0b4-0f9cbb451580'::uuid, 'd7a56820-f559-55e6-9fab-c81af6ecb67c'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "O son of Pandu, he neither dislikes illumination (knowledge), activity, nor delusion when they appear, nor does he long for them when they disappear."'),
('9c1d4ef5-ff71-5b2a-9496-9e66e914a24f'::uuid, 'd7a56820-f559-55e6-9fab-c81af6ecb67c'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "When light, activity, and delusion are present, he does not hate them, nor does he long for them when they are absent.'),
('04771d39-a63c-5ba8-b1b3-08f0321cd93b'::uuid, 'dda9481c-23c6-5565-9055-ce989eb04602'::uuid, 'gambhirananda', 'english', 'He who, sitting like one indifferent, is not distracted by the three qualities; he who, thinking that the qualities alone act, remains firm and does not move surely;'),
('d4e6bcd4-97ff-54db-8f3e-86f64e044f46'::uuid, 'dda9481c-23c6-5565-9055-ce989eb04602'::uuid, 'sivananda', 'english', 'He who, seated like one unconcerned, is not moved by the dualities, and who, knowing that the dualities are active, is self-centered and does not move.'),
('80585508-2437-5dfb-8071-b299fdacd1a7'::uuid, '88ea8075-7b23-562f-b6f1-0738aeac2288'::uuid, 'gambhirananda', 'english', 'He to whom sorrow and happiness are alike, who is established in his own Self, to whom a lump of earth, iron, and gold are the same, to whom the agreeable and the disagreeable are the same, who is wise, to whom censure and his own praise are the same;'),
('5bac46f6-09c2-56ae-8d27-f7fa296387c6'::uuid, '88ea8075-7b23-562f-b6f1-0738aeac2288'::uuid, 'sivananda', 'english', 'Who is the same in pleasure and pain, who dwells in the Self, to whom a clod of earth, a stone, and gold are all alike, who is the same to the dear and the unfriendly, who is firm, and to whom censure and praise are one and the same.'),
('e4cd89ec-2980-52e3-be6c-d0e82570ee52'::uuid, '37a7ef21-7fac-58ad-a378-013ac979c7f0'::uuid, 'gambhirananda', 'english', 'He who is the same under honor and dishonor, who is equitably disposed towards both friends and foes, who has renounced all undertakings—he is said to have gone beyond dualities.'),
('3039b2b8-7377-5b55-ae6c-affd53f5e194'::uuid, '37a7ef21-7fac-58ad-a378-013ac979c7f0'::uuid, 'sivananda', 'english', 'Who is the same in honor and dishonor, the same to friend and foe, abandoning all undertakings, he is said to have transcended the dualities.'),
('fe96d0ea-36ae-5a24-944d-0b1840d9659c'::uuid, 'aec73186-508a-58d8-8e7b-6bc113dbde2a'::uuid, 'gambhirananda', 'english', 'And he who serves Me through the unswerving Yoga of Devotion, he, having gone beyond these qualities, qualifies for becoming Brahman.'),
('aab2a22e-4b3f-599f-853e-fff711afe896'::uuid, 'aec73186-508a-58d8-8e7b-6bc113dbde2a'::uuid, 'sivananda', 'english', 'And he who serves Me with unwavering devotion, he, crossing beyond the dualities, is fit for becoming Brahman.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('c221f41e-2df7-5776-b29f-1bee4ec3117f'::uuid, '1cc99c2a-fc51-50f4-9034-20eca6cbcd11'::uuid, 'gambhirananda', 'english', 'For I am the Abode of Brahman—the indestructible, immutable, eternal, Dharma, and absolute Bliss.'),
('65041853-44dc-523a-b524-f75347c386a8'::uuid, '1cc99c2a-fc51-50f4-9034-20eca6cbcd11'::uuid, 'sivananda', 'english', 'For I am the abode of Brahman, the immortal, immutable, and everlasting Dharma, and absolute bliss.'),
('0d0486f7-6014-5cdc-a380-454769517d30'::uuid, '059071bd-9b23-5fc6-96f6-eb1941b58f87'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "They say that the peepul tree, which has its roots upward and its branches downward, and of which the Vedas are the leaves, is imperishable. He who realizes it is a knower of the Vedas."'),
('6812a84c-a9d1-546f-8d1d-b208bbd43278'::uuid, '059071bd-9b23-5fc6-96f6-eb1941b58f87'::uuid, 'sivananda', 'english', 'The Blessed Lord said: They (the wise) speak of the indestructible peepul tree, with its roots above and branches below, whose leaves are the meters or hymns; he who knows it is a knower of the Vedas.'),
('5578cee4-0511-522c-89d7-6473f0c7a2e7'::uuid, '14c305d9-7774-5e86-8987-49b3f7621ae9'::uuid, 'gambhirananda', 'english', 'The branches of that Tree, extending downwards and upwards, are strengthened by the qualities and have sense-objects as their shoots. And the roots, which are followed by actions, spread downwards in the human world [According to A.G. and M.S. manusya-loke means a body distinguished by Brahminhood etc.].'),
('3b49a39d-ab8f-55f2-b3ae-fd595c5fdd07'::uuid, '14c305d9-7774-5e86-8987-49b3f7621ae9'::uuid, 'sivananda', 'english', 'Its branches spread below and above, nourished by the Gunas; its buds are sense-objects, and its roots stretch forth below in the world of men, originating action.'),
('2c6d00d3-39aa-5e34-9bc5-ce8f43ac06e2'::uuid, '813c4de4-1839-50ea-a4d7-e9b27d2eca78'::uuid, 'gambhirananda', 'english', 'Its form is not perceived here in that way; nor its end, nor beginning, nor its continuance. After felling this Peepul tree whose roots are well developed, with the strong sword of detachment.'),
('3c3fd685-a83e-58c7-a55c-207782e89fbc'::uuid, '813c4de4-1839-50ea-a4d7-e9b27d2eca78'::uuid, 'sivananda', 'english', 'Its form is not perceived here as such, nor its end, origin, foundation, or resting place; having cut asunder this firmly rooted peepul tree with the strong axe of non-attachment.'),
('20577d10-8b24-5469-b0b4-862ad261df00'::uuid, '764cf22a-e5ad-521c-8cb3-c44ebf950199'::uuid, 'gambhirananda', 'english', 'Thereafter, that state must be sought, going where they do not return again: I take refuge in that Primeval Person Himself, from whom the eternal Manifestation has ensued.'),
('838d1307-ef64-5182-9f73-ef7893d48864'::uuid, '764cf22a-e5ad-521c-8cb3-c44ebf950199'::uuid, 'sivananda', 'english', 'Then, that goal should be sought for, to which, having gone, none returns again. I seek refuge in that Primeval Purusha, from whence streamed forth the ancient activity or energy.'),
('dcd07f7e-79c0-56d7-bc41-2d5e6cda077a'::uuid, 'be2ee297-c202-521e-bc70-043c2518d84e'::uuid, 'gambhirananda', 'english', 'The wise ones, free from pride and non-discrimination, who have conquered the evil of association [hatred and love arising from association with foes and friends], who are ever devoted to spirituality, completely free from desires, and free from the dualities of happiness and sorrow, reach that undecaying state.'),
('b9f6ad7a-c222-56b4-80d3-da354ebc83ef'::uuid, 'be2ee297-c202-521e-bc70-043c2518d84e'::uuid, 'sivananda', 'english', 'Free from pride and delusion, victorious over the evil of attachment, dwelling constantly in the Self, their desires having completely turned away, freed from the pairs of opposites known as pleasure and pain, they, the undeluded, reach the eternal goal.'),
('e6b56d6a-8ddd-54f5-b9e5-9ac954f50e79'::uuid, 'c4e32aa4-aa7a-5864-b885-241797e1731e'::uuid, 'gambhirananda', 'english', 'Neither the sun nor the moon nor fire illuminates That. That is My supreme Abode, to which they do not return.'),
('de2dc399-2574-501b-8550-2c239a28321f'::uuid, 'c4e32aa4-aa7a-5864-b885-241797e1731e'::uuid, 'sivananda', 'english', 'Neither does the sun illuminate there, nor the moon, nor the fire; having gone there, they do not return; that is My supreme abode.'),
('9fa5bb32-340a-595b-9f1c-837a25088e5c'::uuid, '3bd6ce47-4542-526b-9f6a-69c1ec7030de'::uuid, 'gambhirananda', 'english', 'It is indeed a part of Mine that, becoming the eternal individual soul in the region of living beings, draws the organs, which have the mind as their sixth, and which abide in Nature.'),
('69750bbc-a231-5d4e-a80e-10a77c685e1f'::uuid, '3bd6ce47-4542-526b-9f6a-69c1ec7030de'::uuid, 'sivananda', 'english', 'An eternal portion of Myself having become a living soul in the world of life, draws to itself the five senses, with the mind as the sixth, abiding in Nature.'),
('2ffec9c2-9175-576c-a759-48c94d9fd01f'::uuid, '21979f1f-586b-5b1c-9d9b-029c8e4bcd2d'::uuid, 'gambhirananda', 'english', 'When the master leaves it and even when he assumes a body, he departs taking these with him, just as the wind carries away odours from their receptacles.'),
('30216a34-4783-5276-ba71-31890c0e7eaf'::uuid, '21979f1f-586b-5b1c-9d9b-029c8e4bcd2d'::uuid, 'sivananda', 'english', 'When the Lord, as the individual soul, obtains a body and when He leaves it, He takes these with Him, just as the wind takes the scents from their seats (flowers, etc.).'),
('320daac7-9653-5607-989b-1aa07e4965c4'::uuid, 'b89fde4b-3c2a-53a1-9928-dd76c8c005f5'::uuid, 'gambhirananda', 'english', 'This one enjoys the objects by presiding over the ears, eyes, skin, tongue, nose, and mind.'),
('be54afe2-e0e0-58ed-92a3-d30c20b63cb2'::uuid, 'b89fde4b-3c2a-53a1-9928-dd76c8c005f5'::uuid, 'sivananda', 'english', 'Presiding over the ears, eyes, touch, taste, smell, and mind, it enjoys the objects of the senses.'),
('1af6686c-0a6f-59b3-ad3d-3033c4ef5e65'::uuid, 'e47d00bb-f01e-5493-ab08-1b87ae3a6641'::uuid, 'gambhirananda', 'english', 'Persons who are diversely deluded do not see it even when it is leaving, residing, experiencing, or in association with the qualities; those with the eye of knowledge see.'),
('90147879-b910-5aa3-832a-e3201a7b0527'::uuid, 'e47d00bb-f01e-5493-ab08-1b87ae3a6641'::uuid, 'sivananda', 'english', 'The deluded do not see Him who departs, stays, and enjoys; but those who possess the eye of knowledge behold Him.'),
('127621cd-b16e-5315-a240-e050a184341f'::uuid, '4e415eee-9fa6-55d8-bc7d-31c83e48d5af'::uuid, 'gambhirananda', 'english', 'And the diligent yogis see this one existing within themselves. The non-discriminating ones who lack self-control, however, do not see this one, even though they are diligent.'),
('35c83970-010d-5fa6-9bb2-aea577510db2'::uuid, '4e415eee-9fa6-55d8-bc7d-31c83e48d5af'::uuid, 'sivananda', 'english', 'The yogis striving for perfection behold Him dwelling in the Self; but, the unrefined and unintelligent, even though striving, do not see Him.'),
('ac014775-a751-50a7-9719-b77ee964dd42'::uuid, '7268f639-de20-58c2-b2ef-056e4ab843b9'::uuid, 'gambhirananda', 'english', 'That light in the sun which illuminates the whole world, that which is in the moon, and that which is in fire—know that light to be Mine.'),
('e808c2f4-8097-5425-8e77-277e6aabc9f2'::uuid, '7268f639-de20-58c2-b2ef-056e4ab843b9'::uuid, 'sivananda', 'english', 'That light which resides in the sun, illuminating the whole world; that which is in the moon and in the fire—know that light to be Mine.'),
('7ec4524d-645e-5f38-8cf5-743700ca578c'::uuid, '48729d23-58a3-57fd-9366-210980550377'::uuid, 'gambhirananda', 'english', 'And entering the Earth, I sustain the beings through My power; and nourish all the plants by becoming Soma, which is of the nature of sap.'),
('5bc1db5b-3ade-5a2f-8d3a-e29c5c6de829'::uuid, '48729d23-58a3-57fd-9366-210980550377'::uuid, 'sivananda', 'english', 'Permeating the earth, I support all beings with My energy; and having become the watery moon, I nourish all herbs.'),
('b604ff82-ef2f-577a-bd9c-8f5c7471265a'::uuid, 'bc26eedd-b0f9-5f9b-8b93-5052da2e1b9a'::uuid, 'gambhirananda', 'english', 'Taking the form of Vaisvanara, and residing in the bodies of creatures, I, in association with Prana and Apana, digest the four kinds of food.'),
('c1ba6ddd-3765-5ad4-8ec6-8711bed605e4'::uuid, 'bc26eedd-b0f9-5f9b-8b93-5052da2e1b9a'::uuid, 'sivananda', 'english', 'Having become the fire Vaisvanara, I abide in the bodies of living beings and, associated with the Prana and the Apana, digest the fourfold food.'),
('56b1a4e3-c9b9-5bd2-8838-cd883165dff8'::uuid, 'afd2c905-bfb8-59c7-98ec-b3610a68d578'::uuid, 'gambhirananda', 'english', 'And I am seated in the hearts of all. From Me come memory, knowledge, and their loss. I alone am the object to be known through all the Vedas; I am also the originator of the Vedanta, and I Myself am the knower of the Vedas.'),
('33cfe986-70f5-5430-b559-f42cd228ef8b'::uuid, 'afd2c905-bfb8-59c7-98ec-b3610a68d578'::uuid, 'sivananda', 'english', 'And I am seated in the hearts of all; from Me come memory and knowledge, as well as their absence. I am verily That which has to be known by all the Vedas; I am indeed the author of the Vedanta and the knower of the Vedas.'),
('6b7399ba-0054-58c7-84ba-6a4e6c099c55'::uuid, '8ccb610e-cb9c-51d0-b3d4-df36ca437d44'::uuid, 'gambhirananda', 'english', 'There are two kinds of people in the world: the mutable and the immutable. The mutable consists of all things; the one existing as Maya is referred to as the immutable.'),
('72e4a2ec-87eb-55ad-b135-6d19951045c1'::uuid, '8ccb610e-cb9c-51d0-b3d4-df36ca437d44'::uuid, 'sivananda', 'english', 'Two Purushas there are in this world: the perishable and the imperishable. All beings are perishable, and the Kutastha—the unchanging—is called the imperishable.'),
('a16aac8e-5daf-57f2-84ed-1b41c7608795'::uuid, 'a14ae631-ea7b-5780-96a5-950f6eb537c8'::uuid, 'gambhirananda', 'english', 'But the Supreme Person is different; He is spoken of as the transcendental Self, permeating the three worlds and upholding them, and He is the imperishable God.'),
('72afbf18-9450-509b-bb31-a1afa556bd5f'::uuid, 'a14ae631-ea7b-5780-96a5-950f6eb537c8'::uuid, 'sivananda', 'english', 'But distinct is the Supreme Purusha, called the highest Self, indestructible and Lord, who pervades the three worlds and sustains them.'),
('ef915417-b49d-508d-a513-6dbca471ada1'::uuid, '2c2ab205-1342-5db2-b2bd-e6856e426d11'::uuid, 'gambhirananda', 'english', 'Since I am transcendental to the mutable and above even the immutable, therefore I am well known in the world and in the Vedas as the supreme Person.'),
('565a1d5b-9ef3-5b7d-b484-0e9cab674613'::uuid, '2c2ab205-1342-5db2-b2bd-e6856e426d11'::uuid, 'sivananda', 'english', 'As I transcend the perishable and am even higher than the imperishable, I am declared to be the highest Purusha in the world and in the Vedas.'),
('5e918c05-2bd6-5f59-aec0-c5caf2ad6f24'::uuid, '81905a09-cba3-5b8a-bce8-a43f0f1ceb77'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, he who, being free from delusion, knows Me, the supreme Person, thus, is all-knowing and adores Me with his whole being.'),
('b40149a9-12d7-5fbf-ad2d-806e6931eee1'::uuid, '81905a09-cba3-5b8a-bce8-a43f0f1ceb77'::uuid, 'sivananda', 'english', 'He who, undeluded, knows Me as the highest Purusha, he, knowing all, worships Me with his whole being (heart), O Arjuna.'),
('096888ec-bec1-54b9-9155-3b9c3cdd1036'::uuid, '868d3fea-ae92-5bd4-876e-8d49669892b8'::uuid, 'gambhirananda', 'english', 'O sinless one, I have thus uttered this most secret scripture. Understanding this, one becomes wise and fulfills their duties, O scion of the Bharata dynasty.'),
('cc2b6ba3-c8f1-5b77-894d-9e1784ef347c'::uuid, '868d3fea-ae92-5bd4-876e-8d49669892b8'::uuid, 'sivananda', 'english', 'Thus, I have imparted to you this most secret science, O sinless one; by knowing this, one becomes wise, and all their duties are accomplished, O Arjuna.'),
('c96bb566-775d-5320-9d6b-d6fba449b976'::uuid, 'edc758e4-b03b-5d3e-b77d-6119d6788ea5'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said: Fearlessness, purity of mind, persistence in knowledge and yoga, charity, control of the external organs, sacrifice, scriptural study, austerity, and rectitude.'),
('057676ae-4020-5c01-be9a-30025db09b02'::uuid, 'edc758e4-b03b-5d3e-b77d-6119d6788ea5'::uuid, 'sivananda', 'english', 'The Blessed Lord said: Fearlessness, purity of heart, steadfastness in knowledge and yoga, almsgiving, control of the senses, sacrifice, study of scriptures, austerity, and straightforwardness.'),
('60223f98-9b3f-55f8-9ec1-c791499d5bca'::uuid, '0b69a6af-0b16-5a43-b214-2afd1081bb3f'::uuid, 'gambhirananda', 'english', 'Non-injury, truthfulness, absence of anger, renunciation, control of the inner self, absence of vilification, kindness to creatures, non-covetousness, gentleness, modesty, and freedom from restlessness;'),
('f6b9001e-ab27-59c1-86d0-f333ac9f1b30'::uuid, '0b69a6af-0b16-5a43-b214-2afd1081bb3f'::uuid, 'sivananda', 'english', 'Harmlessness, truth, absence of anger, renunciation, peacefulness, absence of crookedness, compassion for beings, non-covetousness, gentleness, modesty, and absence of fickleness.'),
('d328dd83-c001-55a2-ae8d-e4ff46bbe02c'::uuid, '33f7758d-ed19-5061-b841-ccca81125358'::uuid, 'gambhirananda', 'english', 'Vigour, forgiveness, fortitude, purity, freedom from malice, absence of haughtiness—these, O scion of the Bharata dynasty, are the qualities of one born destined to have the divine nature.'),
('cfd0de55-82d5-5a9c-a1ce-522e7e7e5fbc'::uuid, '33f7758d-ed19-5061-b841-ccca81125358'::uuid, 'sivananda', 'english', 'Vigor, forgiveness, fortitude, purity, absence of hatred, absence of pride—these belong to one born for a divine state, O Arjuna.'),
('8a085ce1-a710-53e1-b691-bd957f1a8f0b'::uuid, '8920b850-00f8-52fd-91a7-a444ad0cca0d'::uuid, 'gambhirananda', 'english', 'O son of Prtha, the attributes of one destined to have the demoniacal nature are religious ostentation, pride, haughtiness, self-conceit, anger, rudeness, and ignorance.'),
('0b1e6813-a514-54f4-89ad-45f5f9fe31c8'::uuid, '8920b850-00f8-52fd-91a7-a444ad0cca0d'::uuid, 'sivananda', 'english', 'Hypocrisy, arrogance, and self-conceit, anger, harshness, and ignorance—these belong to one who is born for a demoniacal state, O Partha.'),
('bfe3c6ed-0f65-5555-9b87-b3a3ad468362'::uuid, '35fbbcca-a025-5c87-81fc-78796730a723'::uuid, 'gambhirananda', 'english', 'The divine nature is Liberation, while the demoniacal is considered to be an inevitable bondage. Do not grieve, O son of Pandu! You are destined to possess the divine nature.'),
('0dd71a22-ec3c-5733-947b-3f8d8c8b6b2f'::uuid, '35fbbcca-a025-5c87-81fc-78796730a723'::uuid, 'sivananda', 'english', 'The divine nature is deemed conducive to liberation, and the demonic to bondage. Grieve not, O Arjuna, for you are born with divine endowments.'),
('753db831-89b3-592c-85fd-fb3ddbb7db5d'::uuid, '07096359-2da5-5e15-83a8-fd2d6e801fde'::uuid, 'gambhirananda', 'english', 'In this world, there are two kinds of creation of beings: the divine and the demoniacal. The divine has been spoken of elaborately. Hear about the demoniacal from Me, O son of Prtha.'),
('6d137dde-f442-5cbe-8eee-e3cde7135345'::uuid, '07096359-2da5-5e15-83a8-fd2d6e801fde'::uuid, 'sivananda', 'english', 'There are two types of beings in this world: the divine and the demoniacal. The divine has been described at length; hear from Me, O Arjuna, about the demoniacal.'),
('cb51155d-9105-50c7-aa14-4bbeff6a54fb'::uuid, 'a2629eb4-66d9-5b6b-be63-e4a198d20cec'::uuid, 'gambhirananda', 'english', 'Neither do the demoniacal persons understand what should be done and what should not be done; nor do they possess purity, good conduct, or truthfulness.'),
('c188c4d0-ba9f-59ee-b65e-149ca2301e31'::uuid, 'a2629eb4-66d9-5b6b-be63-e4a198d20cec'::uuid, 'sivananda', 'english', 'The demoniacal do not know what to do and what to refrain from; they have neither purity, nor right conduct, nor truth.'),
('7f5a58be-fb64-555e-a0d6-503043c97292'::uuid, '38e94d6d-2816-5e1d-b72f-5913911805f8'::uuid, 'gambhirananda', 'english', 'They say that the world is unreal, having no basis, and without a God. It is born of mutual union brought about by passion! What other cause could there be?'),
('fb87084b-dd48-5971-83d8-fa122391797f'::uuid, '38e94d6d-2816-5e1d-b72f-5913911805f8'::uuid, 'sivananda', 'english', 'They say, "This universe is without truth, without a moral basis, without a God, brought about by mutual union, with lust as its cause; what else?"'),
('0ec3b681-8b4c-56db-a074-d618395c9a37'::uuid, 'f3652837-8d14-57ee-86e3-4d4cc027e172'::uuid, 'gambhirananda', 'english', 'Holding onto this view, those of depraved character, poor intellect, and given to fearful and harmful actions, wax strong and bring ruin to the world.'),
('55efbf66-d65a-5486-b998-f2d0b0e22145'::uuid, 'f3652837-8d14-57ee-86e3-4d4cc027e172'::uuid, 'sivananda', 'english', 'Holding this view, these ruined souls of small intellect and fierce deeds come forth as enemies of the world, intent on its destruction.'),
('1c867c70-dc62-5f32-84c4-4706dc29c31d'::uuid, '135218ed-a0df-5d01-9548-71a06f1aebe6'::uuid, 'gambhirananda', 'english', 'Giving themselves up to insatiable passion, filled with vanity, pride, and arrogance, adopting bad adjectives due to delusion, and having impure resolves, they engage in actions.'),
('fe97fa78-c0a9-5f19-86db-d020708051fe'::uuid, '135218ed-a0df-5d01-9548-71a06f1aebe6'::uuid, 'sivananda', 'english', 'Filled with insatiable desires, full of hypocrisy, pride, and arrogance, holding evil ideas due to delusion, they work with impure intentions.'),
('b0338bbc-0802-50f8-9725-a0f22f4afefc'::uuid, '630a4963-e675-5e8e-92df-1cd64fdc2d11'::uuid, 'gambhirananda', 'english', 'Beset with innumerable cares that end only with death, holding that the enjoyment of desirable objects is the highest goal, they feel sure that this is all.'),
('c7a8f6fd-2563-59da-85a9-76616491ff48'::uuid, '630a4963-e675-5e8e-92df-1cd64fdc2d11'::uuid, 'sivananda', 'english', 'Giving themselves over to immeasurable cares that end only with death, regarding the gratification of lust as their highest aim, and feeling sure that that is all.'),
('52d95cd6-36dd-5677-9e40-ca21f1d6a203'::uuid, '6d1c1cab-de17-53a8-adb4-6671cb8f917d'::uuid, 'gambhirananda', 'english', 'Bound by hundreds of shackles in the form of hope, giving themselves wholly to passion and anger, they endeavor to amass wealth through foul means for the enjoyment of desirable objects.'),
('16d0a5c4-2bcb-587b-b8ab-b32bc7580bab'::uuid, '6d1c1cab-de17-53a8-adb4-6671cb8f917d'::uuid, 'sivananda', 'english', 'Bound by a hundred ties of hope, given over to lust and anger, they strive to obtain hoards of wealth by unlawful means for sensual enjoyment.'),
('98d7a06b-f7d1-5b33-95ac-7df38c3a1ac9'::uuid, '3b837f4e-d9c7-5645-8d85-65ef9c65d77d'::uuid, 'gambhirananda', 'english', '''I have gained this today; I will acquire this desired object. This is in hand; and this wealth will also come to me.'''),
('157574cb-ca2e-53e0-9b98-db43fc3d7308'::uuid, '3b837f4e-d9c7-5645-8d85-65ef9c65d77d'::uuid, 'sivananda', 'english', '"I have gained this today; I will fulfill this desire of mine; this is mine, and this wealth will be mine in the future."'),
('eabd10cf-c97f-56c8-ad2e-d2cfda652e7c'::uuid, '3b90b65c-2e4a-5885-9821-b731ce22368b'::uuid, 'gambhirananda', 'english', '''I have slain that enemy, and I shall slay others too. I am the Lord, the Enjoyer, firmly established, powerful and joyous.'''),
('8c8faa20-6ef3-52aa-bd80-ae095d7a8816'::uuid, '3b90b65c-2e4a-5885-9821-b731ce22368b'::uuid, 'sivananda', 'english', '"I have slain that enemy, and I shall slay others too. I am the Lord; I enjoy, I am perfect, powerful, and happy."'),
('ea532ca9-5f02-564b-a1b8-867ab2be6ec6'::uuid, 'b1fee6d7-70be-518d-9910-d2646df559e5'::uuid, 'gambhirananda', 'english', '''I am wealthy and of noble birth; who else is like me? I shall perform sacrifices; I shall give, I shall rejoice''- thus, they are deluded by a lack of discernment in diverse ways.'),
('4c790396-5c3a-57e5-aa1c-9d55feb42cd1'::uuid, 'b1fee6d7-70be-518d-9910-d2646df559e5'::uuid, 'sivananda', 'english', '"I am wealthy and born into a noble family. Who is my equal? I shall perform sacrifices, give charity, and rejoice," thus deluded by ignorance.'),
('395d601d-4c88-550c-872d-ee41aad05c9f'::uuid, 'b62b25cc-b33f-593b-8ff2-e248488632d8'::uuid, 'gambhirananda', 'english', 'Bewildered by numerous thoughts, ensnared in the net of delusion, and engrossed in the enjoyment of desirable objects, they fall into a foul hell.'),
('6ca131a4-2b8f-56dc-b29c-b173145d3c73'::uuid, 'b62b25cc-b33f-593b-8ff2-e248488632d8'::uuid, 'sivananda', 'english', 'Bewildered by many fancies, entangled in the snare of delusion, addicted to the gratification of lust, they fall into a foul hell.'),
('d5489730-13be-594a-a37a-f9b9416e6407'::uuid, '12d161b9-7f05-5f33-a315-187ac5d27ad8'::uuid, 'gambhirananda', 'english', 'Self-conceited, haughty, filled with pride and intoxicated by wealth, they perform sacrifices that are only in name, ostentatiously and without regard for the injunctions.'),
('75698870-6f3c-5e9d-b344-c202166c24ac'::uuid, '12d161b9-7f05-5f33-a315-187ac5d27ad8'::uuid, 'sivananda', 'english', 'Self-conceited, stubborn, filled with pride and intoxication of wealth, they perform sacrifices in name only for ostentation, contrary to scriptural ordinances.'),
('c14b3937-2300-5a81-9da8-4c90abd93834'::uuid, 'd5908165-abd1-5a9c-b49b-0312b99f6920'::uuid, 'gambhirananda', 'english', 'Resorting to egotism, power, arrogance, passion, and anger, hating Me in their own and others'' bodies, they become envious by nature.'),
('7bc09df1-0afd-56e7-92b5-f64998ceda46'::uuid, 'd5908165-abd1-5a9c-b49b-0312b99f6920'::uuid, 'sivananda', 'english', 'Given over to egoism, power, haughtiness, lust, and anger, these malicious people hate Me in their own bodies and in the bodies of others.'),
('219d95a2-ab36-5b1b-ae58-ff925e379850'::uuid, '59929e2a-a87e-555c-9f52-094f46f8b609'::uuid, 'gambhirananda', 'english', 'I cast forever those hateful, cruel, evil-doers in the worlds, the vilest of human beings, verily into the demonic classes.'),
('55bc4739-f80f-504d-bf44-cce344d3f43d'::uuid, '59929e2a-a87e-555c-9f52-094f46f8b609'::uuid, 'sivananda', 'english', 'Those cruel haters, the worst among men in the world, I hurl those evil-doers into the wombs of demons only.'),
('3372c781-4b36-504c-966f-0ba445c64ce9'::uuid, 'cc1ddb45-35f4-5ea9-aaf2-b2146d586e86'::uuid, 'gambhirananda', 'english', 'Being born among the demoniacal species in birth after birth, the souls, without ever reaching Me, O son of Kunti, attain conditions lower than that.'),
('7c722861-7220-56ce-b857-3a6f33eab293'::uuid, 'cc1ddb45-35f4-5ea9-aaf2-b2146d586e86'::uuid, 'sivananda', 'english', 'Entering into demoniacal wombs and deluded, birth after birth, they do not attain Me, thus falling, O Arjuna, into a condition still lower than that.'),
('00ca8c1d-c5af-5839-9a78-19e18cd5c576'::uuid, '3436d539-f84f-5486-be7b-9b4495716ad9'::uuid, 'gambhirananda', 'english', 'This door to hell, which destroys the soul, is of three kinds—passion, anger, and greed. Therefore, one should forsake these three.'),
('cab455c8-ac56-5eda-947f-f95c97158fed'::uuid, '3436d539-f84f-5486-be7b-9b4495716ad9'::uuid, 'sivananda', 'english', 'There are three gates to this hell, destructive of the self: lust, anger, and greed; therefore, one should abandon these three.'),
('ad6dfd06-0b13-55c8-b9ca-e6ab311762ec'::uuid, '998b9008-9af7-5818-a276-3b817f8ce93c'::uuid, 'gambhirananda', 'english', 'O son of Kunti, a person who is free from these three doors to darkness strives for the good of the soul; thereby, they attain the highest Goal.'),
('b9c30a6d-6569-51b2-a6b3-7f9c2193f8a7'::uuid, '998b9008-9af7-5818-a276-3b817f8ce93c'::uuid, 'sivananda', 'english', 'A person who is liberated from these three gates of darkness, O Arjuna, practices what is beneficial for them and thus goes to the Supreme Goal.'),
('bf11a11b-845c-58dd-ac8d-5cd0fd8a8e43'::uuid, 'e0fcd722-65cd-5701-9b23-698b7e4ee232'::uuid, 'gambhirananda', 'english', 'Ignoring the precepts of the scriptures, he who acts under the impulse of passion does not attain perfection, nor happiness, nor the supreme goal.'),
('bb1369fe-aade-55c9-9d8b-4bb2cc4c6c95'::uuid, 'e0fcd722-65cd-5701-9b23-698b7e4ee232'::uuid, 'sivananda', 'english', 'He who, having cast aside the ordinances of the scriptures, acts under the impulse of desire, does not attain perfection, nor happiness, nor the Supreme Goal.'),
('d18643bb-5589-547e-95d2-2a2c4dd15025'::uuid, 'a925fa88-a53c-5743-947c-f2b138c56f66'::uuid, 'gambhirananda', 'english', 'Therefore, the scripture is your authority as regards determining what should be done and what should not be done. After understanding your duty as presented by scriptural injunction, you ought to perform it here.'),
('c651b411-3934-5ada-9f8e-ef9e6d4a5b91'::uuid, 'a925fa88-a53c-5743-947c-f2b138c56f66'::uuid, 'sivananda', 'english', 'Therefore, let the scripture be thy authority in determining what ought to be done and what ought not to be done. Having known what is said in the ordinance of the scriptures, thou shouldst act in this world.'),
('5af5058e-9d52-5cb7-abce-f2e9d68aa5ef'::uuid, '7b0a4903-1a30-5580-bbbc-9c48ed82ad71'::uuid, 'gambhirananda', 'english', 'Arjuna said, But, O Krsna, what is the state of those who, endued with faith, perform sacrifices, distribute wealth, etc. in honour of gods and others, while ignoring the injunctions of the scriptures? Is it sattva, rajas, or tamas?'),
('8c869d54-2acd-53c3-b422-8e5ce853fcd0'::uuid, '7b0a4903-1a30-5580-bbbc-9c48ed82ad71'::uuid, 'sivananda', 'english', 'Arjuna said, "What is the condition of those who, disregarding the injunctions of the scriptures, perform sacrifice with faith—is it Sattva, Rajas, or Tamas, O Krishna?"'),
('4c1c96ee-6ad6-5640-8772-6470cf35269a'::uuid, '0d90172a-27f2-5682-83ec-f7c9c39230f7'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "That faith of the embodied beings, born of their own nature, is threefold—born of sattva, rajas, and tamas. Hear about it."'),
('d18f8e88-ecdd-5434-94f8-0557ccd51be1'::uuid, '0d90172a-27f2-5682-83ec-f7c9c39230f7'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "There are threefold faiths inherent in the nature of the embodied: the sattvic (pure), the rajasic (passionate), and the tamasic (dark). Hear of them."'),
('d3bc4370-034b-563c-89f9-dcbdb51153d6'::uuid, '2b285c7c-cb2f-516f-aa2b-1f5543ad6b62'::uuid, 'gambhirananda', 'english', 'O scion of the Bharata dynasty, the faith of all beings is in accordance with their minds. This person is composed of faith as the dominant factor. He is indeed what his faith is.'),
('27a96114-fab1-505e-88c2-084df8d54361'::uuid, '2b285c7c-cb2f-516f-aa2b-1f5543ad6b62'::uuid, 'sivananda', 'english', 'The faith of each is in accordance with their nature, O Arjuna. People consist of their faith; as a person''s faith is, so are they.'),
('c8e2c8c3-6914-58f0-92f3-638447575254'::uuid, '1e55bf10-c62e-519a-b980-62fa7c774ef8'::uuid, 'gambhirananda', 'english', 'Those with sattva quality worship the gods; those with rajas, the demigods and demons; and those with tamas, ghosts and hosts of spirits.'),
('931f4195-86cb-58c6-bc79-e6cb846b9098'::uuid, '1e55bf10-c62e-519a-b980-62fa7c774ef8'::uuid, 'sivananda', 'english', 'The sattvic, or pure, men worship the gods; the rajasic, or passionate, worship the yakshas and rakshasas; the others, the tamasic or deluded people, worship ghosts and hosts of nature-spirits.'),
('78a924e3-e4f5-566c-bac3-61fc6795b628'::uuid, '035821de-6113-5553-ad55-c8a3c280dda2'::uuid, 'gambhirananda', 'english', 'Those persons who, given to ostentation and pride, and possessed of passion, attachment, and strength, undertake severe austerities not sanctioned by the scriptures;'),
('5927c999-004e-533a-93ed-0f57a6f3e2e4'::uuid, '035821de-6113-5553-ad55-c8a3c280dda2'::uuid, 'sivananda', 'english', 'Those men who practice terrific austerities not prescribed by the scriptures, given to hypocrisy and egoism, driven by the force of lust and attachment.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('249da3a2-4299-553d-b021-11df3ab53bb8'::uuid, 'a05fd1d0-d6a1-5e67-8a15-4d7f96560484'::uuid, 'gambhirananda', 'english', '(And those who,) being non-discriminating, torture all the organs in the body as well as even Me who reside in the body—know them to be possessed of demoniacal conviction.'),
('18fe8a00-cdcd-55be-bc7f-55de3da8d9ce'::uuid, 'a05fd1d0-d6a1-5e67-8a15-4d7f96560484'::uuid, 'sivananda', 'english', 'Know thou these to be of demonical resolves, senselessly torturing all the elements in the body and Me who dwell in the body.'),
('e9822787-38b8-55cd-9f51-0a39140c4349'::uuid, 'a889f697-d314-5b0d-8669-0d135b72ef5e'::uuid, 'gambhirananda', 'english', 'Food, which is dear to all, is of three kinds; likewise, sacrifices, austerity, and charity are also of three kinds. Listen to this classification of them.'),
('5d345ed2-ca0f-545c-aceb-b2d33b9bbf02'::uuid, 'a889f697-d314-5b0d-8669-0d135b72ef5e'::uuid, 'sivananda', 'english', 'The food that is dear to each is threefold, as well as sacrifice, austerity, and almsgiving. Hear the distinction of these.'),
('dfd654a0-ffcd-5451-be73-438b694a736b'::uuid, '09d55fa8-2f6a-58c3-90d7-4572ab1cf98d'::uuid, 'gambhirananda', 'english', 'Foods that augment life, firmness of mind, strength, health, happiness, and delight, and which are succulent, oleaginous, substantial, and agreeable, are dear to one endowed with sattva.'),
('3b1f311d-0922-5876-8853-7d715abf8fb8'::uuid, '09d55fa8-2f6a-58c3-90d7-4572ab1cf98d'::uuid, 'sivananda', 'english', 'The foods that increase life, purity, strength, health, joy, and cheerfulness (good appetite), which are savory, oily, substantial, and agreeable, are dear to the Sattvic (pure) people.'),
('744ca2ad-e2fd-5b68-b3b9-0c386ef58dc2'::uuid, 'd4155bb2-6f67-5465-8c29-70fc5140226a'::uuid, 'gambhirananda', 'english', 'Foods that are bitter, sour, salty, very hot, pungent, dry, and burning, producing pain, sorrow, and disease, are dear to one who has rajas.'),
('7722526d-0b07-5d64-a684-c29d31cf92ce'::uuid, 'd4155bb2-6f67-5465-8c29-70fc5140226a'::uuid, 'sivananda', 'english', 'The foods that are bitter, sour, salty, overly hot, pungent, dry, and burning are liked by the Rajasic and are productive of pain, grief, and disease.'),
('256b98fc-cb7b-53b0-af77-ea1f1f85e1fd'::uuid, '00a06d6b-74b1-5eb4-8913-196b68f88f30'::uuid, 'gambhirananda', 'english', 'Food that is not properly cooked, lacking in essence, putrid and stale, as well as that which is unfit for sacrifice, is dear to one possessed of tamas.'),
('42b07b6a-bebf-515a-b53c-1fee70f4f748'::uuid, '00a06d6b-74b1-5eb4-8913-196b68f88f30'::uuid, 'sivananda', 'english', 'That which is stale, tasteless, putrid, rotten, rejected, and impure is the food liked by the Tamasic.'),
('c4b39d4e-c51d-5c0d-a455-cbc68f0aeb0e'::uuid, 'eb394f9c-4032-5958-acc1-41201a5febca'::uuid, 'gambhirananda', 'english', 'That sacrifice which is in accordance with the injunctions, performed by persons who do not hanker after results, and with the mental conviction that it is surely obligatory, is done through sattva.'),
('1aeabff3-e86b-5add-8576-cd4a10fdc170'::uuid, 'eb394f9c-4032-5958-acc1-41201a5febca'::uuid, 'sivananda', 'english', 'That sacrifice which is offered by men without desire for reward, as enjoined by the ordinance (scripture), with a firm faith that doing so is their duty, is Sattvic or pure.'),
('386dc687-ee4d-5136-8fe4-d567592c43d2'::uuid, '45754dc4-f635-5074-8257-6aa2925cfea8'::uuid, 'gambhirananda', 'english', 'But that sacrifice which is performed with an aim for a result, as well as for show—know that sacrifice to be done through rajas, O greatest among the descendants of Bharata.'),
('169fcebc-de7b-5bff-ac52-eb9771945455'::uuid, '45754dc4-f635-5074-8257-6aa2925cfea8'::uuid, 'sivananda', 'english', 'The sacrifice that is offered, O Arjuna, seeking a reward and for show, know that to be a Rajasic Yajna.'),
('66052b4e-713c-5b50-82f5-4c334cd596ec'::uuid, '8dc98c4e-573d-5d37-8f89-6531f07bfba2'::uuid, 'gambhirananda', 'english', 'They declare that sacrifice as ''done through tamas'' which is contrary to injunction, in which no food is distributed, in which no mantras are used, in which no offerings are made to priests, and which is devoid of faith.'),
('627716b9-c267-5e2d-ae57-1ba9b523c31b'::uuid, '8dc98c4e-573d-5d37-8f89-6531f07bfba2'::uuid, 'sivananda', 'english', 'They declare that sacrifice to be Tamasic which is contrary to the ordinances of the scriptures, in which no food is distributed, and which is devoid of mantras, gifts, and faith.'),
('94d1764d-00d5-5e25-afb0-1a600fe1507b'::uuid, '276d6a1c-42d9-5b10-82c8-76e653545806'::uuid, 'gambhirananda', 'english', 'The worship of gods, twice-borns, venerable persons, and the wise; purity, straightforwardness, celibacy, and non-injury—these are said to be bodily austerities.'),
('3deb52ca-556a-5c9d-a5d4-0ed1eaefe93d'::uuid, '276d6a1c-42d9-5b10-82c8-76e653545806'::uuid, 'sivananda', 'english', 'Worship of the gods, the twice-born, the teachers, and the wise; purity, straightforwardness, celibacy, and non-injury are all called the austerities of the body.'),
('b584f5f7-e5da-54c9-8fee-819005bd842c'::uuid, '4ff32e91-069f-5953-ad5a-80137e5482f9'::uuid, 'gambhirananda', 'english', 'That speech which causes no pain, which is true, agreeable, and beneficial; as well as the practice of studying the scriptures—is said to be the austerity of speech.'),
('3e2a52ad-0e78-5c68-884b-0656fedae03c'::uuid, '4ff32e91-069f-5953-ad5a-80137e5482f9'::uuid, 'sivananda', 'english', 'Speech that causes no excitement, is truthful, pleasant, and beneficial; the practice of studying the Vedas is called austerity of speech.'),
('94db6bb1-b086-5bd6-90b0-61c6cb5ef3ca'::uuid, '839b9d26-22fc-5a62-9e35-75d702d3d96a'::uuid, 'gambhirananda', 'english', 'Tranquility of mind, gentleness, reticence, withdrawal of the mind, purity of heart—these are what are called mental austerities.'),
('2dc50764-c41f-57bc-8089-ce4659ab4c98'::uuid, '839b9d26-22fc-5a62-9e35-75d702d3d96a'::uuid, 'sivananda', 'english', 'Serenity of mind, good-heartedness, self-control, and purity of nature—this is called mental austerity.'),
('95902eaf-4fd5-5708-a67e-c9c3fe377010'::uuid, '1e1e3777-8805-5623-b91c-d1288b4b194b'::uuid, 'gambhirananda', 'english', 'When that threefold austerity is undertaken with supreme faith by people who do not hanker after results and are self-controlled, they speak of it as being born of sattva.'),
('7d821783-9e1f-5015-bed0-7b6c1dcb6f7a'::uuid, '1e1e3777-8805-5623-b91c-d1288b4b194b'::uuid, 'sivananda', 'english', 'This threefold austerity, practiced by steadfast men, with the utmost faith, desiring no reward, is called Sattvic.'),
('3651ca84-608f-5a69-b48b-2e13f1eddccd'::uuid, 'd07e58a2-ddb7-50e3-9c55-c68d726cc030'::uuid, 'gambhirananda', 'english', 'That austerity which is undertaken for earning a name, being honored and worshipped, and also ostentatiously—that is spoken of as born of rajas, belonging to this world, uncertain, and transitory.'),
('66a7f328-097b-5504-a5ab-d68264562296'::uuid, 'd07e58a2-ddb7-50e3-9c55-c68d726cc030'::uuid, 'sivananda', 'english', 'The austerity that is practiced with the aim of gaining good reception, honor, and worship, and with hypocrisy, is said to be Rajasic, unstable, and transient.'),
('e44426fa-27e5-5263-b8dd-dbe8480d1913'::uuid, '634af24e-63fa-5d21-9327-99169fcbe7fa'::uuid, 'gambhirananda', 'english', 'That austerity which is undertaken with a foolish intent, causing pain to oneself or for the destruction of others, is said to be born of tamas.'),
('5233f198-0c10-560b-bc91-500248117718'::uuid, '634af24e-63fa-5d21-9327-99169fcbe7fa'::uuid, 'sivananda', 'english', 'That austerity which is practised out of a foolish notion, with self-torture, or for the purpose of destroying another, is declared to be of the Tamasic nature.'),
('34d395d2-8f99-5c4f-be36-3962432bb3db'::uuid, '397b935e-bd4c-5672-9423-7368cc3669b1'::uuid, 'gambhirananda', 'english', 'That gift is referred to as born of sattva which is given with the idea that it should be given, to one who will not serve in return, at the right place, right time, and to the right person.'),
('8ba4ac32-1c5a-5a06-b134-e19e692fdb15'::uuid, '397b935e-bd4c-5672-9423-7368cc3669b1'::uuid, 'sivananda', 'english', 'That gift which is given to one who does nothing in return, knowing it to be a duty to give in a suitable place and time to a worthy person, is held to be Sattvic.'),
('566fe2c9-7e35-5ecd-9b2c-c399a674814e'::uuid, 'e199f4e2-13c0-5399-b6d0-ac86f626ccde'::uuid, 'gambhirananda', 'english', 'But the gift which is given expecting reciprocation, or with a desire for its result, and grudgingly, is considered to be born of rajas.'),
('03d709dd-63bc-56ac-85e2-dfa21cf6a6b9'::uuid, 'e199f4e2-13c0-5399-b6d0-ac86f626ccde'::uuid, 'sivananda', 'english', 'And, that gift which is given with the intention of receiving something in return, or expecting a reward, or begrudgingly, is considered to be Rajasic.'),
('f535a889-7123-57bf-a8d7-95476d982d4a'::uuid, '0b3acaa9-6269-5369-8585-3e38c74f25f2'::uuid, 'gambhirananda', 'english', 'The gift which is made at an inappropriate place and time, and to undeserving persons, without proper respect and with disdain, is declared to be born of tamas.'),
('61c295ae-ad89-59fb-99f9-02d45977ebb5'::uuid, '0b3acaa9-6269-5369-8585-3e38c74f25f2'::uuid, 'sivananda', 'english', 'The gift that is given in the wrong place and at the wrong time, to unworthy persons, without respect or with insult, is declared to be of a Tamasic nature.'),
('c0829012-6d57-5cf5-a49f-9d1cce859aaf'::uuid, '160e8f79-4c4a-573b-b109-8808feac3fbf'::uuid, 'gambhirananda', 'english', '"Om-tat-sat" - this is considered to be the threefold designation of Brahman. The Brahmanas, Vedas, and sacrifices were ordained by that in days of yore.'),
('0ace03a8-a4b1-524b-9cae-7dad16b74716'::uuid, '160e8f79-4c4a-573b-b109-8808feac3fbf'::uuid, 'sivananda', 'english', '"Om Tat Sat": This has been declared to be the triple designation of Brahman. By that, the Brahmanas, the Vedas, and the sacrifices were created formerly.'),
('00246d26-6681-52db-a20d-d35d38d5dad6'::uuid, '39d056e3-384c-5356-977e-b985314f70e6'::uuid, 'gambhirananda', 'english', 'Therefore, acts of sacrifice, charity, and austerity, as prescribed through injunctions, of those who study and expound the Vedas, always commence after uttering the syllable ‘Om’.'),
('2d1b972f-f263-5a32-bf8a-714c2e0f83e5'::uuid, '39d056e3-384c-5356-977e-b985314f70e6'::uuid, 'sivananda', 'english', 'Therefore, with the utterance of "Om," the acts of sacrifice, gift, and austerity, as enjoined in the scriptures, are always begun by the students of Brahman.'),
('a88f30c2-b0eb-5d07-b68f-bdf719cb3bbb'::uuid, '3141c2b6-ede0-5f64-a82a-af37566159f2'::uuid, 'gambhirananda', 'english', 'After uttering the word "tat," acts of sacrifice and austerity, as well as various acts of charity, are performed without regard for results by persons aspiring for liberation.'),
('557a4530-849e-5417-b97b-18a42216895e'::uuid, '3141c2b6-ede0-5f64-a82a-af37566159f2'::uuid, 'sivananda', 'english', 'Uttering "Tat," without aiming for the fruits, are the acts of sacrifice, austerity, and the various acts of gifts performed by those seeking liberation.'),
('941983b0-cadf-5f6f-bf20-2adef53d0c30'::uuid, 'c4a794c6-841c-5852-bb68-9287d189bfd6'::uuid, 'gambhirananda', 'english', 'This word "sat" is used with regard to something coming into being and someone becoming good. Likewise, O son of Prtha, the word "sat" is used with regard to an auspicious rite.'),
('03b3baad-b4db-54d7-b444-2cffdcacd4b2'::uuid, 'c4a794c6-841c-5852-bb68-9287d189bfd6'::uuid, 'sivananda', 'english', 'The word "Sat" is used to refer to reality and goodness; likewise, O Arjuna, the word "Sat" is used to refer to an auspicious act.'),
('522e3b7a-59da-5fe8-9d91-6a49fe07b1e2'::uuid, '1c3be0f6-4a71-5f97-88b8-076799da3144'::uuid, 'gambhirananda', 'english', 'And the steadfastness in sacrifice, austerity, and charity is spoken of as sat (good). And even the action meant for these is, indeed, called as sat.'),
('065c5594-6d3a-5270-b2e6-cce11813c76c'::uuid, '1c3be0f6-4a71-5f97-88b8-076799da3144'::uuid, 'sivananda', 'english', 'Steadfastness in sacrifice, austerity, and gift is also called ''Sat'', and action in connection with these, or for the sake of the Supreme, is also called ''Sat''.'),
('9408ca27-96eb-5990-a94b-42942edc3e17'::uuid, 'c571d489-334e-5c82-b77e-6b2985ecc4c8'::uuid, 'gambhirananda', 'english', 'O son of Prtha, whatever is offered in sacrifice and given in charity, as also whatever austerity is undertaken or whatever is done without faith, is said to be of no avail. And it is of no consequence after death, nor here.'),
('a9fc0ad9-0950-5e52-8f4e-3a81741e1303'::uuid, 'c571d489-334e-5c82-b77e-6b2985ecc4c8'::uuid, 'sivananda', 'english', 'Whatever is sacrificed, given, or performed, and whatever austerity is practiced without faith, it is called ''Asat'', O Arjuna; it is of no value here or hereafter (after death).'),
('964ab649-661c-53b8-b0df-c2eb5a037761'::uuid, '3dade9d2-6936-5e26-adad-826a86bd486d'::uuid, 'gambhirananda', 'english', 'Arjuna said, O mighty-armed Hrsikesa, O slayer of Kesi, I want to know separately the truth about sannyasa as well as about tyaga.'),
('71b80cd7-27c7-5987-bcbb-623c065d3abd'::uuid, '3dade9d2-6936-5e26-adad-826a86bd486d'::uuid, 'sivananda', 'english', 'Arjuna said, "O mighty-armed Hrishikesa, I desire to know the essence or truth of renunciation and abandonment severally, O slayer of Kesi."'),
('a8449ac3-855a-54a4-b053-39574219df35'::uuid, '98cf4cf4-b04a-5273-a9ea-89cb94cf68dd'::uuid, 'gambhirananda', 'english', 'The Blessed Lord said, "The learned ones know sannyasa to be the giving up of actions done with a desire for reward. The adepts call the abandonment of the results of all works ''tyaga''."'),
('cb85c4db-dfc4-5114-83c8-050f88822501'::uuid, '98cf4cf4-b04a-5273-a9ea-89cb94cf68dd'::uuid, 'sivananda', 'english', 'The Blessed Lord said, "The sages understand sannyasa to be the renunciation of action with desire; the wise declare the abandonment of the fruits of all actions to be tyaga."'),
('7193db5f-245a-51e1-a24b-6607111b5329'::uuid, 'e203772f-3263-560f-8d1b-5c4c4cfd6a55'::uuid, 'gambhirananda', 'english', 'Some learned persons say that action, beset with evil as it is, should be abandoned, and others say that the practice of sacrifice, charity, and austerity should not be abandoned.'),
('b32c03b3-f7fd-5e1b-acaa-133f5751248a'::uuid, 'e203772f-3263-560f-8d1b-5c4c4cfd6a55'::uuid, 'sivananda', 'english', 'Some philosophers declare that actions should be abandoned as evil; while others declare that acts of sacrifice, gift, and austerity should not be relinquished.'),
('a99695b9-0fdd-5ce1-af71-05d3a5e96ea2'::uuid, 'ecca47ab-8c80-5a6f-92a6-6f10c58ed360'::uuid, 'gambhirananda', 'english', 'O the most excellent among the descendants of Bharata, hear from Me the firm conclusion regarding that tyaga. For, O greatest among men, tyaga has been clearly declared to be of three kinds.'),
('516142a9-5f16-5c0a-9210-650aa8f74543'::uuid, 'ecca47ab-8c80-5a6f-92a6-6f10c58ed360'::uuid, 'sivananda', 'english', 'Hear from Me the conclusion or the final truth about this abandonment, O best of the Bharatas; abandonment, indeed, O best of men, has been declared to be of three kinds.'),
('a7882dd4-f3f3-586d-87ae-2cf15071691a'::uuid, '394c6d50-d63b-50ef-9312-99f3207fa8f9'::uuid, 'gambhirananda', 'english', 'The practice of sacrifice, charity, and austerity should not be abandoned; it should certainly be undertaken. Sacrifice, charity, and austerity are indeed the purifiers of the wise.'),
('316aeece-9dd1-5ac7-8494-c90fffdcb1ee'::uuid, '394c6d50-d63b-50ef-9312-99f3207fa8f9'::uuid, 'sivananda', 'english', 'Acts of sacrifice, gift, and austerity should not be abandoned, but should be performed; for sacrifice, gift, and austerity are the purifiers of the wise.'),
('3551f1b9-0090-5365-b12a-ca4e58e7ee4b'::uuid, 'a3d35297-4872-5d9f-a9ff-d05a3c588d42'::uuid, 'gambhirananda', 'english', 'But even these actions must be undertaken by renouncing attachment and hankering for results. This is My firm and definitive conclusion, O Partha.'),
('fd5132be-3024-5083-ba72-18e09b0d8920'::uuid, 'a3d35297-4872-5d9f-a9ff-d05a3c588d42'::uuid, 'sivananda', 'english', 'But even these actions should be performed, leaving aside attachment and the desire for rewards, O Arjuna; this is my certain and most assured conviction.'),
('c0fd2961-f3c1-54c2-aab1-3e3e863f43f5'::uuid, 'bef97c55-b3a0-557b-8ca1-c56a1f645874'::uuid, 'gambhirananda', 'english', 'Abandoning one''s daily obligatory acts is not justifiable; giving up those through delusion is said to be rooted in tamas.'),
('142a9dba-68e4-5d91-bd8f-6bbc0e11d3de'::uuid, 'bef97c55-b3a0-557b-8ca1-c56a1f645874'::uuid, 'sivananda', 'english', 'Verily, the renunciation of obligatory action is not proper; the abandonment of the same out of delusion is declared to be Tamasic.'),
('5e902abb-025d-5821-b7a8-15a81f5a11be'::uuid, '00dda16d-0a0a-55a5-bed0-31d8fc49aa79'::uuid, 'gambhirananda', 'english', 'Whatever action one may relinquish merely as being painful, out of fear of physical suffering, he, having resorted to renunciation based on rajas, will surely not acquire the fruits of renunciation.'),
('d6f8665d-e281-53e4-963d-937abb828e18'::uuid, '00dda16d-0a0a-55a5-bed0-31d8fc49aa79'::uuid, 'sivananda', 'english', 'He who abandons action out of fear of bodily trouble (because it is painful), does not obtain the merit of renunciation by performing such Rajasic renunciation.'),
('ee7aafb3-6b16-5013-953e-d0a2f678a4f0'::uuid, '0dab7010-6386-5352-a26f-85d3cdfedec9'::uuid, 'gambhirananda', 'english', 'Whatever obligatory duty is performed just because it is a bounden duty, O Arjuna, by giving up attachment and the results as well—that renunciation is considered to be based on sattva.'),
('bd323572-2e8e-5902-9351-a7f30a9a3400'::uuid, '0dab7010-6386-5352-a26f-85d3cdfedec9'::uuid, 'sivananda', 'english', 'Whatever obligatory action is done, O Arjuna, merely because it ought to be done, abandoning attachment and also the desire for reward, that renunciation is regarded as sattvic (pure).'),
('3567f3e0-bbc5-577a-bd09-0769fc1d7e2a'::uuid, 'c19fb4e5-ee91-5d2d-8d12-021f7730144d'::uuid, 'gambhirananda', 'english', 'The man of renunciation, imbued with sattva, wise and free from doubts, does not hate unbecoming action, nor does he become attached to becoming activity.'),
('9537a5be-1a40-51f1-9589-ac5edb0010c1'::uuid, 'c19fb4e5-ee91-5d2d-8d12-021f7730144d'::uuid, 'sivananda', 'english', 'The man of renunciation, pervaded by purity, intelligent, and with his doubts cut asunder, does not hate an unpleasant task nor is he attached to a pleasant one.'),
('987be911-38a8-5c2d-99d0-1ff5b5c80bff'::uuid, '87530d37-5128-50a9-9d75-80dd2c17c60e'::uuid, 'gambhirananda', 'english', 'Since it is not possible for one who holds onto a body to give up actions entirely, therefore he who renounces the results of his actions is called a man of renunciation.'),
('7e6dfe8c-7e4e-5f1d-8ff7-2f7e2148e3b3'::uuid, '87530d37-5128-50a9-9d75-80dd2c17c60e'::uuid, 'sivananda', 'english', 'Indeed, it is not possible for an embodied being to completely abandon actions; however, he who relinquishes the rewards of actions is truly called a man of renunciation.'),
('a53030e5-7c9a-518f-9cfb-1172c727f2ac'::uuid, 'a6b8a6be-5260-581b-b382-8233967cb345'::uuid, 'gambhirananda', 'english', 'The threefold results of actions—the undesirable, the desirable, and the mixed—accrue after death to those who do not resort to renunciation, but never to those who resort to renunciation.'),
('ec5821c7-7ee7-5d7d-a2b9-b50fd4479690'::uuid, 'a6b8a6be-5260-581b-b382-8233967cb345'::uuid, 'sivananda', 'english', 'The threefold fruit of action (evil, good, and mixed) accrues after death to those who do not abandon it, but never to those who do.'),
('2d3177a3-90e0-5f1f-9647-af14c6455ae2'::uuid, '057e74a9-628b-591a-914f-931622ab954f'::uuid, 'gambhirananda', 'english', 'O mighty-armed one, learn from Me these five factors for the accomplishment of all actions, which have been spoken of in the Vedanta, in which actions terminate.'),
('be82c9f8-a33a-5ca1-82e5-084691cb1840'::uuid, '057e74a9-628b-591a-914f-931622ab954f'::uuid, 'sivananda', 'english', 'Learn from Me, O mighty-armed Arjuna, these five causes, as declared in the Sankhya system, for the accomplishment of all actions.'),
('fd10c924-3c34-532c-abe6-1ab9a86313c7'::uuid, '569b7b00-6c15-51a6-b80f-5ccbcf0ce9f6'::uuid, 'gambhirananda', 'english', 'The locus, the agent, the different kinds of organs, the many and varied activities, and the divine are the fifth here.'),
('82c1f8bd-0e44-5b36-ad4c-2832bf732dbd'::uuid, '569b7b00-6c15-51a6-b80f-5ccbcf0ce9f6'::uuid, 'sivananda', 'english', 'The body, the doer, the various senses, the different functions of various kinds, and the presiding deity—the fifth.'),
('debfb0df-9c6c-59f7-b555-265906c7faac'::uuid, '32784664-f60c-5a79-abd2-771c23737f01'::uuid, 'gambhirananda', 'english', 'Whatever action a person performs with their body, speech, and mind, whether it be just or its opposite, these five are the causes of it.'),
('fb48938e-7e67-5421-883b-cd827bf2992f'::uuid, '32784664-f60c-5a79-abd2-771c23737f01'::uuid, 'sivananda', 'english', 'Whatever action a person performs with their body, speech, and mind, whether right or wrong, these five are its causes.'),
('8fe36fff-e654-58b0-a226-0958f024ccf9'::uuid, 'd56525d3-ac85-505f-8154-90a4d647c6df'::uuid, 'gambhirananda', 'english', 'Therefore, anyone whose intellect is imperfect and perceives the Absolute Self as the agent, does not perceive properly and has a distorted intellect.'),
('94d62415-dc0d-5f29-883c-0d56617dfff1'::uuid, 'd56525d3-ac85-505f-8154-90a4d647c6df'::uuid, 'sivananda', 'english', 'Now, such being the case, verily he who, owing to an untrained understanding, looks upon his Self, which is isolated, as the agent, he of perverted intelligence does not see.'),
('5df1cbd6-37e6-53ae-8b0f-b609d7c1ec3d'::uuid, 'cf4fdad2-5cd2-5efe-b75c-9b6409503be9'::uuid, 'gambhirananda', 'english', 'He who has no feeling of egoism, whose intellect is untainted, he does not kill, nor does he become bound—even by killing these creatures!'),
('b61bb595-35c3-50fa-abeb-8edf2c7c06f2'::uuid, 'cf4fdad2-5cd2-5efe-b75c-9b6409503be9'::uuid, 'sivananda', 'english', 'He who is free from the egoistic notion, whose intelligence is not tainted by good or evil, though he slays these people, he does not slay, nor is he bound by the action.'),
('8d84c135-3056-5376-bc2d-210f44431058'::uuid, '675f4942-fc02-503e-9ac0-e11f572ca437'::uuid, 'gambhirananda', 'english', 'Knowledge, the object of knowledge, and the knower—these are the threefold inducements to action. The comprehension of actions comes under three heads: the instruments, the object, and the subject.'),
('84009e76-f053-5df3-b3b9-b61f8bcb77ee'::uuid, '675f4942-fc02-503e-9ac0-e11f572ca437'::uuid, 'sivananda', 'english', 'Knowledge, the knowable, and the knower form the threefold impulse for action; the organ, the action, and the agent form the threefold basis of action.'),
('f927f8c1-c34f-5fec-a9dd-dc44bd80b39a'::uuid, 'ed8e02d5-6f43-53ec-9e33-955efec41b03'::uuid, 'gambhirananda', 'english', 'Knowledge, action, and agent are stated in the teaching about the gunas to be only of three kinds, according to the differences of the gunas. Hear about them also as they are.'),
('d10ea24a-6c16-5e22-8b71-eeb5a34bbf97'::uuid, 'ed8e02d5-6f43-53ec-9e33-955efec41b03'::uuid, 'sivananda', 'english', 'Knowledge, action, and actor are declared in the science of the Gunas (Sankhya philosophy) to be of three kinds only, according to the distinction of the Gunas. Of these, hear duly.'),
('c1d2e76a-8563-52c7-b1fd-ac362055895c'::uuid, '44fdf1b5-adfe-5ddb-ba9e-ae9ed9798e6f'::uuid, 'gambhirananda', 'english', 'Know that knowledge to originate from sattva, through which one sees a single, undecaying, undivided entity in all the diversified things.'),
('777d3351-446b-5e72-8bb4-dc4a9911d3a1'::uuid, '44fdf1b5-adfe-5ddb-ba9e-ae9ed9798e6f'::uuid, 'sivananda', 'english', 'That by which one sees the indestructible Reality in all beings, not separate in any of them—know that knowledge to be Sattvic.'),
('207e04c2-e860-56ee-8aed-9eec22241fc7'::uuid, '96794bb1-7e05-560e-937f-663d63ad25ff'::uuid, 'gambhirananda', 'english', 'But know that knowledge to originate from rajas, which amidst all things apprehends the different entities of various kinds as distinct [as possessing distinct selves].'),
('a402e4fe-b713-5a1a-9ef2-fe93b3c20c12'::uuid, '96794bb1-7e05-560e-937f-663d63ad25ff'::uuid, 'sivananda', 'english', 'But that knowledge which sees in all beings various entities of distinct kinds as being distinct from one another, know thou that knowledge to be Rajasic.'),
('069affc6-4a87-5d00-9f8b-5d0e75cd48a5'::uuid, '98f97988-126e-557d-944c-0c0b8af6bd70'::uuid, 'gambhirananda', 'english', 'But that (knowledge) is said to be born of tamas which is confined to one form as if it were all, which is irrational, unconcerned with truth, and trivial.'),
('40097a27-4a81-59df-84a9-92f8a75596e6'::uuid, '98f97988-126e-557d-944c-0c0b8af6bd70'::uuid, 'sivananda', 'english', 'But that which clings to one single effect as if it were the whole, without reason, without any foundation in Truth, and is trivial—that is declared to be Tamasic.'),
('3837aeae-ab8f-58cb-852d-2d17ac5a3d29'::uuid, '2faf8ad1-5093-5d8a-a7b2-05f31d7615a7'::uuid, 'gambhirananda', 'english', 'The daily obligatory action which is performed without attachment and without likes or dislikes, by one who does not hanker for rewards, is said to be born of sattva.'),
('7c431261-4720-5f8f-beb5-3f6ce474b50b'::uuid, '2faf8ad1-5093-5d8a-a7b2-05f31d7615a7'::uuid, 'sivananda', 'english', 'An action that is ordained, free from attachment, done without love or hatred, and without desire for reward is declared to be Sattvic.'),
('0b0bc689-86f0-51c1-8339-f42dbc0db768'::uuid, 'd48a0b75-e9c1-5be5-a169-417a5ecde74f'::uuid, 'gambhirananda', 'english', 'But that action is said to be born of rajas which is done by one desirous of results or by one who is egotistical, and which is highly strenuous.'),
('9520a45c-fb04-57d7-b2b5-21e4fb41454a'::uuid, 'd48a0b75-e9c1-5be5-a169-417a5ecde74f'::uuid, 'sivananda', 'english', 'But that action which is done by one longing for the fulfillment of desires or gain with egotism or with much effort is declared to be Rajasic (passionate).'),
('722d7371-7cec-5672-9178-70d741b51200'::uuid, '21b88f31-ea7f-5c7c-8b6f-cbfd5616dc2f'::uuid, 'gambhirananda', 'english', 'That action is said to be born of tamas which is undertaken out of delusion, without consideration of its consequences, loss, harm, and ability.'),
('8ab65935-9f57-5fb4-b815-fdeabf8c0de9'::uuid, '21b88f31-ea7f-5c7c-8b6f-cbfd5616dc2f'::uuid, 'sivananda', 'english', 'That action which is undertaken from delusion, without regard for the consequences, loss, injury, and one''s own ability, is declared to be Tamasic (dark).'),
('22f0a1f2-8634-5fd0-81c6-299c4f0226cb'::uuid, '1dd67c1b-b285-5adf-be0b-240c4bac7a15'::uuid, 'gambhirananda', 'english', '[Ast. introduces this verse with ''Idanim kartrbhedah ucyate, Now is being stated the distinctions among the agents.''-Tr.] The agent who is free from attachment [Attachment to results or the idea of agentship.], not egotistical, endowed with fortitude and diligence, and unperturbed by success and failure is said to be possessed of sattva.'),
('1702c16e-3897-5eda-8ae8-b11406a36007'::uuid, '1dd67c1b-b285-5adf-be0b-240c4bac7a15'::uuid, 'sivananda', 'english', 'An agent who is free from attachment, non-egoistic, endowed with firmness and enthusiasm, and unaffected by success or failure, is considered to be of a Sattvic (pure) nature.'),
('0d0be0a5-a0b5-5dd3-afb1-4f75ac7ecb38'::uuid, 'c632a076-86a6-5a8e-9ab8-1b1b682d9b4e'::uuid, 'gambhirananda', 'english', 'The agent who has attachment, who is desirous of the results of actions, covetous, cruel by nature, unclean, and subject to joy and sorrow, is declared to be possessed of rajas.'),
('2e48ed85-69c3-57e9-baa9-9cb4aa27e8c4'::uuid, 'c632a076-86a6-5a8e-9ab8-1b1b682d9b4e'::uuid, 'sivananda', 'english', 'Passionate, desiring to obtain the reward of their actions, greedy, cruel, impure, moved by joy and sorrow, such an agent is said to be Rajasic.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('fb25c9f6-91e8-5e1b-b1ab-23ad3835c69f'::uuid, '968836c8-3bb6-5dda-8e97-aacfe50c8d30'::uuid, 'gambhirananda', 'english', 'The agent who is unsteady, naive, inflexible, deceitful, wicked, lazy, sullen, and procrastinating is said to be possessed of tamas.'),
('1243d837-67ce-5583-8bf4-6a7e14f76d8a'::uuid, '968836c8-3bb6-5dda-8e97-aacfe50c8d30'::uuid, 'sivananda', 'english', 'Unsteady, vulgar, inflexible, deceitful, malicious, lazy, despondent, and procrastinating—such an agent is called Tamasic.'),
('3dc52beb-6b00-5777-8917-fe1fcb6abe09'::uuid, '1fbe4cf7-949f-55c4-ba49-584f5f481750'::uuid, 'gambhirananda', 'english', 'O Dhananjaya, listen to the classification of the intellect and fortitude, which is threefold according to the gunas, while it is being stated in detail and separately.'),
('d37ab11f-e2dc-51ae-9fa2-94f7036bbb23'::uuid, '1fbe4cf7-949f-55c4-ba49-584f5f481750'::uuid, 'sivananda', 'english', 'Hear thou the threefold division of intellect and firmness, according to the Gunas, as I declare them fully and distinctly, O Arjuna.'),
('a6f8fc52-b5b4-5163-a2ce-5691023d956c'::uuid, '56d4dbf4-5ea5-53ed-a27a-064a66f1fc69'::uuid, 'gambhirananda', 'english', 'O Partha, that intellect is born of sattva which understands action and withdrawal, duty and what is not duty, the sources of fear and fearlessness, as well as bondage and freedom.'),
('b66bbd94-02ff-52e9-88a9-b2eb2567a6d0'::uuid, '56d4dbf4-5ea5-53ed-a27a-064a66f1fc69'::uuid, 'sivananda', 'english', 'The intellect which knows the path of work and renunciation, what should be done and what should not be done, fear and fearlessness, bondage and liberation—that intellect is Sattvic (pure), O Arjuna.'),
('d3e48138-e5ac-5b18-98e7-a88f26333e22'::uuid, '6680c056-bada-5e2d-9459-cfba23c08dbb'::uuid, 'gambhirananda', 'english', 'O Partha, that intellect is born of rajas with which one wrongly understands virtue and vice, as well as what ought to be done and ought not to be done.'),
('3b3abc22-4cd3-5d1c-bc64-5cf522562ac3'::uuid, '6680c056-bada-5e2d-9459-cfba23c08dbb'::uuid, 'sivananda', 'english', 'That by which one wrongly understands dharma and adharma, and also what ought to be done and what ought not to be done—that intellect, O Arjuna, is rajasic (passionate).'),
('dffdc534-6ba9-57ea-8ff4-92af0e125b9a'::uuid, '75a336b0-bcec-54b0-8fcd-335627321b79'::uuid, 'gambhirananda', 'english', 'O Partha, that intellect is born of tamas which, being covered by darkness, considers vice as virtue, and indeed perceives all things contrary to what they are.'),
('0c103131-6e63-5f7b-a8e7-0c8f91b981c9'::uuid, '75a336b0-bcec-54b0-8fcd-335627321b79'::uuid, 'sivananda', 'english', 'That intellect, O Arjuna, which is enveloped in darkness and sees Adharma as Dharma and all things perverted, is Tamasic (dark).'),
('9811d9ef-59eb-528a-b279-364fc0b3d3c1'::uuid, 'f23dc957-9bd3-52f8-90b8-1a5b565f186a'::uuid, 'gambhirananda', 'english', 'O Partha, the firmness that is unfailing through concentration, with which one restrains the functions of the mind, vital forces, and the organs—that firmness is born of sattva.'),
('5cd44017-6c58-5315-ac4f-1b19e3edc9eb'::uuid, 'f23dc957-9bd3-52f8-90b8-1a5b565f186a'::uuid, 'sivananda', 'english', 'The unwavering firmness, through which Yoga restrains the functions of the mind, life-force, and senses—that firmness, O Arjuna, is Sattvic (pure).'),
('fbc731fd-bc58-51ec-9ea6-a00a57f4edd0'::uuid, 'cf8d5e88-c9aa-5a74-ba41-1c700eac559b'::uuid, 'gambhirananda', 'english', 'But, O Partha, the steadfastness with which one holds on to righteousness, covetable things, and wealth, desiring their fruits as the occasion for each arises, that steadfastness is born of rajas.'),
('c522ae9e-8aa9-53ac-a734-cb5d40adf563'::uuid, 'cf8d5e88-c9aa-5a74-ba41-1c700eac559b'::uuid, 'sivananda', 'english', 'But that, O Arjuna, by which one holds fast to Dharma (duty), enjoyment of pleasures, and earning of wealth, on account of attachment and desire for reward—that firmness, O Arjuna, is Rajasic (passionate).'),
('289f0c4c-6bd3-598e-b661-f7ea02436276'::uuid, '9591795e-51c1-5ac2-a198-08924f2fa35a'::uuid, 'gambhirananda', 'english', 'That firmness is considered to be born of tamas, due to which a person with a corrupt intellect does not give up sleep, fear, sorrow, despondency, as well as sensuality.'),
('d0dc7c5a-26dd-5bad-bdc2-336770c61b9e'::uuid, '9591795e-51c1-5ac2-a198-08924f2fa35a'::uuid, 'sivananda', 'english', 'That firmness, O Arjuna, by which a stupid man does not abandon sleep, fear, grief, despair, and conceit, is Tamasic.'),
('2959773f-e448-52c0-a4fd-0b459ea67afe'::uuid, '46180403-2b37-5256-9739-a04c939c1b28'::uuid, 'gambhirananda', 'english', 'Now hear from Me, O scion of the Bharata dynasty, as regards the three kinds of joy: That in which one delights due to habit, and certainly attains the cessation of sorrows; [S. and S.S. take the second line of this verse along with the next verse referring to sattvika happiness.-Tr.]'),
('43664545-e958-5481-a4c8-33b3b2dae44b'::uuid, '46180403-2b37-5256-9739-a04c939c1b28'::uuid, 'sivananda', 'english', 'And now, O Arjuna, hear from Me of the threefold pleasure, in which one rejoices through practice and surely comes to the end of pain.'),
('a09ffec2-a56d-52bd-8c92-e42a8cd21cbe'::uuid, 'bc9f3394-35bf-5ed6-9f81-e441fa926f6b'::uuid, 'gambhirananda', 'english', 'That which is like poison in the beginning, but is likened to nectar in the end, and which arises from the purity of one''s intellect—that joy is spoken of as born of sattva.'),
('739bdb2a-d742-59dd-bdf1-4084a8327d14'::uuid, 'bc9f3394-35bf-5ed6-9f81-e441fa926f6b'::uuid, 'sivananda', 'english', 'That which is like poison at first but in the end like nectar—that happiness is declared to be sattvic, born of the purity of one''s own mind due to self-realization.'),
('9ae6dddf-1140-5415-872e-a9f39aaec4d5'::uuid, '976ca21b-f81d-51ce-a649-a656dc745aaf'::uuid, 'gambhirananda', 'english', 'That joy is referred to as born of rajas, which, arising from the contact of the organs and their objects, is like nectar in the beginning but like poison in the end.'),
('d1bb4313-3341-57d0-9188-06bbae2f8687'::uuid, '976ca21b-f81d-51ce-a649-a656dc745aaf'::uuid, 'sivananda', 'english', 'That happiness which arises from the contact of the senses with the objects, which is initially like nectar but eventually like poison, is said to be Rajasic.'),
('8f90ce8b-5767-50a7-84dc-bedd9067fce6'::uuid, '92a79653-6524-5093-9dbe-a013de3578df'::uuid, 'gambhirananda', 'english', 'That joy is said to be born of tamas, which, both in the beginning and in the end, is delusive to oneself and arises from sleep, laziness, and inadvertence.'),
('ef21446e-5d6c-53c4-88cc-0e611bc788f4'::uuid, '92a79653-6524-5093-9dbe-a013de3578df'::uuid, 'sivananda', 'english', 'That happiness which at first, as well as in the end, deludes the self, and which arises from sleep, indolence, and heedlessness—that is declared to be Tamasic.'),
('a8b0024a-af73-5b20-8adb-cc6fe8cf2a62'::uuid, '3ae8dc19-4f88-56ac-82f3-dcf3ea8ba9b7'::uuid, 'gambhirananda', 'english', 'There is no entity in the world, nor among the gods in heaven, that can be free from these three gunas born of Nature.'),
('b8fff987-b58d-5094-a930-d0fbf4840265'::uuid, '3ae8dc19-4f88-56ac-82f3-dcf3ea8ba9b7'::uuid, 'sivananda', 'english', 'There is no being on earth or in heaven among the gods that is liberated from the three qualities born of Nature.'),
('b9315fa4-0529-552e-b3c1-e51c907e3a23'::uuid, 'dc23c870-abc6-5e76-8a3b-5eb10e09e429'::uuid, 'gambhirananda', 'english', 'O scorcher of enemies, the duties of the Brahmanas, Ksatriyas, Vaisyas, and Sudras have been fully classified according to the gunas born from Nature.'),
('d5b445fa-a041-54b9-89e7-1d6c5d657aaf'::uuid, 'dc23c870-abc6-5e76-8a3b-5eb10e09e429'::uuid, 'sivananda', 'english', 'Of Brahmanas, Kshatriyas, Vaisyas, and Sudras, O Arjuna, the duties are distributed according to the qualities born of their own nature.'),
('f395402d-b366-5ddd-80fe-0bcea3544659'::uuid, 'b3f9f47d-db42-5460-a0ee-1baa0a80f39d'::uuid, 'gambhirananda', 'english', 'The natural duties of the Brahmanas are the control of the internal and external organs, austerity, purity, forgiveness, straightforwardness, knowledge, as well as wisdom [Knowledge refers to the understanding of subjects presented by the scriptures; wisdom means making them matters of one''s own experience.], and faith.'),
('ce5f374c-1bd3-5ec5-9cb4-8c0d0296aea9'::uuid, 'b3f9f47d-db42-5460-a0ee-1baa0a80f39d'::uuid, 'sivananda', 'english', 'Serenity, self-restraint, austerity, purity, forgiveness, and uprightness, as well as knowledge, realization, and belief in God, are the duties of Brahmanas, born of their own nature.'),
('136b749c-d0d4-5c50-bd73-a0be9e3106b4'::uuid, '58f17d45-2394-5c64-8e01-61b485ed87c9'::uuid, 'gambhirananda', 'english', 'The natural duties of the Ksatriyas are heroism, boldness, fortitude, capability, and not retreating from battle, generosity, and lordliness.'),
('3ded35c8-0bb8-57ba-9c9c-f42150356908'::uuid, '58f17d45-2394-5c64-8e01-61b485ed87c9'::uuid, 'sivananda', 'english', 'Prowess, splendor, firmness, dexterity, and not fleeing from battle, generosity, and lordliness are the duties of the Kshatriyas, born of their own nature.'),
('ac351cf5-3b04-59cf-a45d-13d3cef71ed0'::uuid, '3e2bb158-ffd0-5d7b-94c2-f3fbd1d22157'::uuid, 'gambhirananda', 'english', 'The natural duties of the Vaisyas are agriculture, cattle-rearing, and trading. The natural duty of the Sudras, too, is in the form of service.'),
('8496c9d1-e315-51a8-8b17-4f875262aea6'::uuid, '3e2bb158-ffd0-5d7b-94c2-f3fbd1d22157'::uuid, 'sivananda', 'english', 'Agriculture, cattle-rearing, and trade are the duties of the Vaisya (merchant), born of their own nature; and service is the duty of the Sudra (servant-class), born of their own nature.'),
('3c058eee-8bf4-5909-be4e-31ee15380afb'::uuid, 'c4915d7c-f98b-5b88-9570-1155cc7fb70f'::uuid, 'gambhirananda', 'english', 'Being devoted to his own duty, one attains complete success. Hear how one devoted to their own duty achieves success.'),
('34e71d5d-e087-5a34-ac53-a74c5da423a2'::uuid, 'c4915d7c-f98b-5b88-9570-1155cc7fb70f'::uuid, 'sivananda', 'english', 'Each person devoted to their own duty attains perfection. How they attain perfection while being engaged in their own duty, hear now.'),
('93ae1b3f-8617-5f34-94f0-f9503043eda6'::uuid, 'ba536cf9-9317-5d24-910e-d44f8adc9da1'::uuid, 'gambhirananda', 'english', 'A human being achieves success by adoring, through his own duties, Him from whom is the origin of creatures and by whom all this is pervaded.'),
('f6d93c9d-03f4-58ad-b45e-5466423f1f4a'::uuid, 'ba536cf9-9317-5d24-910e-d44f8adc9da1'::uuid, 'sivananda', 'english', 'He from whom all the beings have evolved and by whom all this is pervaded, worshipping Him with his own duty, one attains perfection.'),
('44130658-7a5c-5603-9cd9-0ad5551eaa60'::uuid, 'ad717ff9-d2ea-5c9f-981a-db7901a4eaae'::uuid, 'gambhirananda', 'english', 'One''s own duty, though defective, is superior to another''s duty well performed. By performing a duty according to one''s own nature, one does not incur sin.'),
('00755660-7950-504b-87ee-1a3a14d7651a'::uuid, 'ad717ff9-d2ea-5c9f-981a-db7901a4eaae'::uuid, 'sivananda', 'english', 'Better is one''s own duty, even if it is destitute of merits, than the duty of another well performed. He who does the duty ordained by his own nature incurs no sin.'),
('67500a8a-0c05-56ff-93e2-45a1bab642c9'::uuid, '03d1a633-ac3e-5dfd-8b5b-2fc9a2d30c38'::uuid, 'gambhirananda', 'english', 'O son of Kunti, one should not give up the duty to which one is born, even though it be imperfect. For all undertakings are surrounded by evil, as fire is with smoke.'),
('78f85a9f-0ba3-5af0-8eb7-75d2e4240d47'::uuid, '03d1a633-ac3e-5dfd-8b5b-2fc9a2d30c38'::uuid, 'sivananda', 'english', 'One should not, O Arjuna, abandon the duty to which one is born, though it may be faulty; for, all undertakings are enveloped by evil, just as fire is by smoke.'),
('8fe36bee-f6a2-5cb9-b74a-2617eda8930e'::uuid, '0b64c096-e168-54ad-b107-571e2fd83aee'::uuid, 'gambhirananda', 'english', 'He whose intellect remains unattached to everything, who has conquered his internal organs and is desireless, attains through monasticism the supreme perfection consisting of the state of one free from duties.'),
('65851f17-6446-580f-b711-71f246c90a06'::uuid, '0b64c096-e168-54ad-b107-571e2fd83aee'::uuid, 'sivananda', 'english', 'He whose intellect is unattached everywhere, who has subdued his self, from whom desire has fled, he attains the supreme state of freedom from action through renunciation.'),
('c5e1c334-8cfa-5b67-92ed-38e2a00bd56a'::uuid, 'fb03c842-cec5-57c7-ae6e-b51554e201c8'::uuid, 'gambhirananda', 'english', 'Understand for certain from Me, in brief indeed, O son of Kunti, that process by which one who has achieved success attains Brahman, which is the supreme consummation of knowledge.'),
('a9aaccbc-7c02-5073-ae87-e107e14611de'::uuid, 'fb03c842-cec5-57c7-ae6e-b51554e201c8'::uuid, 'sivananda', 'english', 'Learn from Me, O Arjuna, in brief how one who has attained perfection reaches Brahman—the Eternal, that supreme state of knowledge.'),
('28a3dc49-5dbe-5a51-9bf6-fd4d15b67f6f'::uuid, '48032393-d926-543e-8576-b517b228ccc3'::uuid, 'gambhirananda', 'english', 'Endowed with a pure intellect and controlling oneself with fortitude, one should reject the objects beginning from sound [sound, touch, form, color, taste, and smell - Tr.] and eliminate attachment and hatred.'),
('3ee2f98f-d852-5243-ad38-46b28b5354da'::uuid, '48032393-d926-543e-8576-b517b228ccc3'::uuid, 'sivananda', 'english', 'Endowed with a pure intellect, controlling the self through firmness, relinquishing sound and other objects and abandoning attraction and hatred.'),
('96eb2300-2552-5d9c-b251-5a58ce358a6e'::uuid, 'd026c93b-cc7b-555b-8751-d933ebdb6b54'::uuid, 'gambhirananda', 'english', 'One who resorts to solitude, eats sparingly, has control over their speech, body, and mind, for whom meditation and concentration are ever the highest duty, and who is possessed of dispassion;'),
('ddc63674-b401-5e42-8161-3a0f09b04680'::uuid, 'd026c93b-cc7b-555b-8751-d933ebdb6b54'::uuid, 'sivananda', 'english', 'Dwelling in solitude, eating sparingly, with speech, body, and mind subdued, always engaged in meditation and concentration, and resorting to dispassion.'),
('b5bad8c0-7b89-54cb-abdd-bfbff05bf1e5'::uuid, 'c66eded3-fe89-504d-a33e-0bc722b8c32e'::uuid, 'gambhirananda', 'english', 'Having discarded egotism, force, pride, desire, anger, and superfluous possessions, and being free from the idea of possession and serene, that person is fit for becoming Brahman.'),
('fef8feac-beeb-5375-a83f-79247d06d623'::uuid, 'c66eded3-fe89-504d-a33e-0bc722b8c32e'::uuid, 'sivananda', 'english', 'Having abandoned egoism, strength, arrogance, desire, anger, and covetousness, and being free from the notion of ''mine'' and peaceful, he is fit for becoming Brahman.'),
('f82c1aba-7f3b-55c6-9f03-5f4d160d2ba7'::uuid, '0bc23035-867c-5f09-a058-26486df3c47d'::uuid, 'gambhirananda', 'english', 'One who has become Brahman and has attained the blissful Self does not grieve nor desire. Becoming the same towards all beings, he attains supreme devotion to Me.'),
('181f6e6b-f964-5612-b10b-68085ee677c1'::uuid, '0bc23035-867c-5f09-a058-26486df3c47d'::uuid, 'sivananda', 'english', 'Becoming Brahman, serene in the Self, he neither grieves nor desires; he is the same to all beings, and obtains supreme devotion to Me.'),
('f3ec5dc4-6754-5ec0-bb6b-ac05ababf681'::uuid, '1859b3b0-f11c-5156-a147-1d8e7e65f05a'::uuid, 'gambhirananda', 'english', 'Through devotion, he knows Me in reality, as to what and who I am. Then, having known Me truly, he enters into Me immediately afterward.'),
('b8b56b59-ffa8-5449-b462-67a152a168ac'::uuid, '1859b3b0-f11c-5156-a147-1d8e7e65f05a'::uuid, 'sivananda', 'english', 'By devotion, he knows Me in truth, who and what I am; then, having known Me in truth, he immediately enters into the Supreme.'),
('2175e2aa-458b-5ce8-8683-1fcc5b075e87'::uuid, '6cb2b09a-1dd6-5e8c-8fe8-e0cd16687f3d'::uuid, 'gambhirananda', 'english', 'Ever engaging in all actions, one to whom I am the refuge, attains the eternal, immutable state through my grace.'),
('4b0d52c3-ce26-57ab-89cf-08014fdde55d'::uuid, '6cb2b09a-1dd6-5e8c-8fe8-e0cd16687f3d'::uuid, 'sivananda', 'english', 'Having taken refuge in Me and doing all actions, by My grace he obtains the eternal, indestructible state of being.'),
('feac160e-4921-5ca1-8c49-6864d446116d'::uuid, '31a3a9f0-a75d-5b36-8f42-12ccbe43c915'::uuid, 'gambhirananda', 'english', 'Mentally surrendering all actions to Me and accepting Me as the supreme, keep your mind ever fixed on Me by resorting to the concentration of your intellect.'),
('a033ae31-3d48-5931-a1a4-77d78b7330eb'::uuid, '31a3a9f0-a75d-5b36-8f42-12ccbe43c915'::uuid, 'sivananda', 'english', 'Mentally renouncing all actions in Me, having Me as the highest goal, and resorting to the yoga of discrimination, do thou ever fix thy mind on Me.'),
('1824e0a2-8566-58d1-86fe-30c755d8794d'::uuid, 'a880de33-b6ec-5514-b87f-ed0a6ebda995'::uuid, 'gambhirananda', 'english', 'Having your mind fixed on Me, you will cross over all difficulties by My grace. If, however, you do not listen out of egotism, you will be destroyed.'),
('c3aeffbc-6b2a-590c-9a4c-84583ba76cdd'::uuid, 'a880de33-b6ec-5514-b87f-ed0a6ebda995'::uuid, 'sivananda', 'english', 'Fixing your mind on Me, you shall, by My grace, overcome all obstacles; but if you will not hear Me due to egoism, you shall perish.'),
('b8c02131-631a-527f-9098-cf3ec4146b1c'::uuid, '6292110c-df66-5538-a07f-4d41c3089dc1'::uuid, 'gambhirananda', 'english', 'Though you think ''I shall not fight'', relying on egotism, this determination of yours is vain. Your nature will impel you!'),
('b5fcca37-c5aa-5583-987e-7c1782a79b86'::uuid, '6292110c-df66-5538-a07f-4d41c3089dc1'::uuid, 'sivananda', 'english', 'If, filled with egoism, thou thinkest, "I will not fight," then thy resolve is vain; nature will compel thee.'),
('7497a196-4fc0-5899-b40d-15a09e5fc631'::uuid, 'b45448ce-f5b2-5652-8138-6282c3bb5366'::uuid, 'gambhirananda', 'english', 'Being bound by your own duty, born of nature, O son of Kunti, you will, being helpless, verily do that which you do not wish to do, owing to indiscretion.'),
('9e00700e-a8b7-5533-88d8-f4246175ef42'::uuid, 'b45448ce-f5b2-5652-8138-6282c3bb5366'::uuid, 'sivananda', 'english', 'O Arjuna, bound by your own Karma (action) born of your own nature, that which from delusion you wish not to do, even that you shall do helplessly.'),
('3fae89b1-d3ae-5d53-894d-99d2a09c5d42'::uuid, '87f3e1b1-5a5d-5c16-834b-afe93999beaa'::uuid, 'gambhirananda', 'english', 'O Arjuna, the Lord resides in the region of the hearts of all creatures, revolving through Maya all the creatures as though mounted on a machine!'),
('609dcf66-6427-5f2d-a87c-ac2ec7d2363a'::uuid, '87f3e1b1-5a5d-5c16-834b-afe93999beaa'::uuid, 'sivananda', 'english', 'The Lord dwells in the hearts of all beings, O Arjuna, causing all beings, by His illusory power, to revolve as if mounted on a machine.'),
('fcda5cbd-1c6d-57b3-b40c-febe7af6d21f'::uuid, 'f0152c09-3827-5ad6-bc79-50ce2f80afc8'::uuid, 'gambhirananda', 'english', 'Take refuge in Him alone with your whole being, O scion of the Bharata dynasty. Through His grace, you will attain supreme peace and the eternal abode.'),
('7421c461-505b-5daa-a5e7-8a374c54bf6d'::uuid, 'f0152c09-3827-5ad6-bc79-50ce2f80afc8'::uuid, 'sivananda', 'english', 'Fly to Him for refuge with all your being, O Arjuna; by His grace you will obtain supreme peace and the eternal abode.'),
('9ce46f58-97c6-503e-b0df-ec283483522d'::uuid, 'e063c739-2aa6-5e73-80fa-1feeff5aa04e'::uuid, 'gambhirananda', 'english', 'To you I have imparted this knowledge, which is more secret than any secret. Ponder over this as a whole and do as you like.'),
('a2f8bb71-ebc2-5bfb-83e9-02757ed46969'::uuid, 'e063c739-2aa6-5e73-80fa-1feeff5aa04e'::uuid, 'sivananda', 'english', 'Thus, wisdom more secret than secrecy itself has been declared to you by me. Reflect on it fully, then act as you wish.'),
('15b3b08a-4ce4-5b52-b4e4-685c0376d124'::uuid, 'b733a82a-53e5-5059-98a4-c4cfbe336026'::uuid, 'gambhirananda', 'english', 'Listen again to My highest utterance, which is the most profound of all. Since you are ever dear to Me, I shall speak what is beneficial to you.'),
('1d3a60e9-3826-506d-beb0-7c6dc3ab7c17'::uuid, 'b733a82a-53e5-5059-98a4-c4cfbe336026'::uuid, 'sivananda', 'english', 'Hear again My supreme word, most secret of all; for you are dearly beloved of Me, I will tell you what is good.'),
('119c0207-3865-573b-878c-e2abd8367ae6'::uuid, 'c65e783d-5615-590a-9499-b901df609df1'::uuid, 'gambhirananda', 'english', 'Fix your mind on Me, be devoted to Me, offer sacrifices to Me, and bow down to Me. Thus, you will come to Me alone. I promise you this truth, for you are dear to Me.'),
('a6064d5b-0aef-5463-b9ae-5f9c4529d066'::uuid, 'c65e783d-5615-590a-9499-b901df609df1'::uuid, 'sivananda', 'english', 'Fix your mind on Me, be devoted to Me, sacrifice to Me, bow down to Me. You will come to Me; I truly promise you this, for you are dear to Me.'),
('396f62be-b500-5d56-85ff-7d684795a8f4'::uuid, '9e52590f-0112-5726-87b1-e059dd963fcc'::uuid, 'gambhirananda', 'english', 'Abandon all forms of rites and duties, and take refuge in Me alone. I will free you from all sins; do not grieve.'),
('d480abd8-40ce-5ed7-b21b-bc395a212935'::uuid, '9e52590f-0112-5726-87b1-e059dd963fcc'::uuid, 'sivananda', 'english', 'Abandon all duties and take refuge in Me alone; I will liberate you from all sins; do not grieve.'),
('d336625b-f527-5ff4-b6d1-974616ed1385'::uuid, 'c7923de5-b237-5145-88be-87f1b7093152'::uuid, 'gambhirananda', 'english', 'This (that I have taught) should never be taught to one who is devoid of austerities, one who is not a devotee, one who does not render service, or one who cavils at Me.'),
('ed84eb63-83dc-5704-979f-739d61ccd940'::uuid, 'c7923de5-b237-5145-88be-87f1b7093152'::uuid, 'sivananda', 'english', 'Never speak this to one who is devoid of austerities or devotion, who does not render service, who does not desire to listen, or who cavils at Me.'),
('7bb318de-dd62-549f-a695-794301b76ae6'::uuid, '69092e4b-fb5f-5804-947c-a0c303835bf3'::uuid, 'gambhirananda', 'english', 'He who, entertaining supreme devotion to Me, speaks of this highest secret to My devotees, will without doubt reach Me alone.'),
('7923dcd5-de90-5c17-8861-90193cac58fc'::uuid, '69092e4b-fb5f-5804-947c-a0c303835bf3'::uuid, 'sivananda', 'english', 'He who, with supreme devotion to Me, teaches this supreme secret to My devotees, shall undoubtedly come to Me.'),
('ba9c5a00-30dc-53f5-a7f3-ee08b2580a69'::uuid, '2c6a75de-f720-5cac-97e5-83d42c9470e8'::uuid, 'gambhirananda', 'english', 'And compared to him, no other human is better at accomplishing what is dear to Me. Furthermore, there will be no one else in the world dearer to Me than him.'),
('58355263-3ecc-51e2-99c0-8762148d6b78'::uuid, '2c6a75de-f720-5cac-97e5-83d42c9470e8'::uuid, 'sivananda', 'english', 'There is no one among men who does service dearer to Me, nor shall there be anyone on earth dearer to Me than him.'),
('3ae1c484-3ece-5d49-9de2-66afa33c803d'::uuid, '4cb138d6-2512-5845-85da-5256ca34410f'::uuid, 'gambhirananda', 'english', 'And he who will study this sacred conversation between us two, which is conducive to virtue, by him I shall be adored through the Sacrifice of Knowledge. This is My judgment.'),
('2af23736-e804-57a9-b30d-2de1061c2800'::uuid, '4cb138d6-2512-5845-85da-5256ca34410f'::uuid, 'sivananda', 'english', 'And he who studies this sacred dialogue of ours, by him I shall have been worshipped through the sacrifice of wisdom; such is my conviction.'),
('4695928b-79ae-5e07-a0a2-c66a4ddd9d72'::uuid, '78434cc0-151d-5dbf-9d2f-ac34b26bf80e'::uuid, 'gambhirananda', 'english', 'Any man who, being reverent and free from caviling, listens to this (teaching) with reverence, he too, becoming free, shall attain the blessed worlds of those who perform virtuous deeds.'),
('79ad1dac-ee40-562c-aace-1eab7db8c151'::uuid, '78434cc0-151d-5dbf-9d2f-ac34b26bf80e'::uuid, 'sivananda', 'english', 'Also, the man who hears this, full of faith and free from malice, shall attain to the happy worlds of those of righteous deeds, and be liberated.'),
('8d7a9f97-111c-59f4-994e-86bbc673c2d3'::uuid, '7c2f1705-8a5f-534c-a3bd-95ae0f240cde'::uuid, 'gambhirananda', 'english', 'O Partha, have you listened to this with a one-pointed mind? O Dhananjaya, has your delusion caused by ignorance been dispelled?'),
('d1fd648d-0bd5-5e57-8a71-8356cffb04f5'::uuid, '7c2f1705-8a5f-534c-a3bd-95ae0f240cde'::uuid, 'sivananda', 'english', 'Has this been heard, O Arjuna, with one-pointed focus? Has the delusion of your ignorance been destroyed, O Dhananjaya?'),
('7d4d9bdb-d574-52dd-8691-a87237f588fd'::uuid, '5cbd4e23-1643-5c6b-8ad3-5a615d962817'::uuid, 'gambhirananda', 'english', 'Arjuna said, "O Acyuta, my delusion has been destroyed and my memory has been regained through Your grace. I stand with my doubt removed; I shall follow Your instructions."'),
('551deb6a-d14d-5b9a-86f2-9189c768e17b'::uuid, '5cbd4e23-1643-5c6b-8ad3-5a615d962817'::uuid, 'sivananda', 'english', 'Arjuna said, "My delusion has been destroyed, for I have gained my knowledge (memory) through Your grace, O Krishna. I am now free from doubts. I will act according to Your word."'),
('0ef29311-c1f1-5ca8-99ae-9c2db0172ce4'::uuid, '11f0e294-f1f8-56f2-939e-303e76c52135'::uuid, 'gambhirananda', 'english', 'Sanjaya said, "I thus heard this conversation between Vasudeva and the great-souled Partha, which is unique and makes one''s hair stand on end."'),
('0d594834-696e-5f38-b625-832a71f2d260'::uuid, '11f0e294-f1f8-56f2-939e-303e76c52135'::uuid, 'sivananda', 'english', 'Sanjaya said, Thus, I have heard this wonderful dialogue between Krishna and the high-souled Arjuna, which causes one''s hair to stand on end.'),
('857552e9-bc79-5390-9253-3bd414c61e83'::uuid, 'bd06a7ef-88c5-5695-a6f4-7bc372b3388f'::uuid, 'gambhirananda', 'english', 'Through the favor of Vyasa, I heard this secret concerning the supreme Yoga from Krishna, the Lord of Yogas, while He Himself was speaking!'),
('22367905-2a30-5dc9-abe7-c3a95810647a'::uuid, 'bd06a7ef-88c5-5695-a6f4-7bc372b3388f'::uuid, 'sivananda', 'english', 'Through the grace of Vyasa, I have heard this supreme and most secret Yoga, directly from Krishna, the Lord of Yoga, Himself declaring it.'),
('4eb3348a-7c55-5c9d-b28a-9810b0739bf6'::uuid, '043cccf4-4335-55b2-86d5-52b75086d7b4'::uuid, 'gambhirananda', 'english', 'And, O King, while repeatedly remembering this unique, sacred dialogue between Kesava and Arjuna, I rejoice every moment.'),
('4e140790-ff03-5570-a907-77843ceac57b'::uuid, '043cccf4-4335-55b2-86d5-52b75086d7b4'::uuid, 'sivananda', 'english', 'O King, remembering this wonderful and holy dialogue between Krishna and Arjuna, I continually rejoice.'),
('df5930db-8623-55a6-8bae-978b94cfb0e2'::uuid, '0a116bc7-c286-56e5-a807-fa6f4677db42'::uuid, 'gambhirananda', 'english', 'O King, repeatedly recollecting that greatly extraordinary form of Hari, I am struck with wonder and rejoice again and again.'),
('e757b932-a1d9-523f-ae63-6e9b9e2969f7'::uuid, '0a116bc7-c286-56e5-a807-fa6f4677db42'::uuid, 'sivananda', 'english', 'And, remembering again and again that most wonderful form of Hari, I am filled with great wonder, O King; and I rejoice again and again.')
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('e62a03e0-0bb2-57b4-90f2-037cbd5e643f'::uuid, 'eeb1dc40-a63a-5262-817b-3c4e81cf483c'::uuid, 'gambhirananda', 'english', 'Where there is Krishna, the Lord of yogas, and where there is Partha, the wielder of the bow, there is fortune, victory, prosperity, and unfailing prudence. Such is my conviction.'),
('8bed875a-9c1f-51d7-9521-63495d260d91'::uuid, 'eeb1dc40-a63a-5262-817b-3c4e81cf483c'::uuid, 'sivananda', 'english', 'Wherever Krishna, the Lord of Yoga, is; and wherever Arjuna, the wielder of the bow, is; there is prosperity, victory, happiness, and a firm policy; this is my conviction.')
